      res.setHeader('Set-Cookie', `${ESTIMATOR_COOKIE}=${cookieVal}; Path=/; Max-Age=${maxAge}; SameSite=Lax`);
      res.json({ role });
    } catch (err) {
      res.status(500).json({ error: 'Server error' });
    }
  })

