app.get('/mix-calculator', async (req, res) => {
    res.setHeader('Cache-Control', 'no-cache, no-store, must-revalidate');
    res.setHeader('Pragma', 'no-cache');
    res.setHeader('Expires', '0');
    const root = process.env.NODE_ENV === 'production'
      ? path.join(process.cwd(), 'dist', 'public')
      : path.join(process.cwd(), 'client', 'public');

    // Estimator admin cookie → full access, no injection needed.
    const estCookieVal = parseCookie(req.headers.cookie, ESTIMATOR_COOKIE);
    const estRole = verifyRoleCookie(estCookieVal);
    if (estRole === 'admin') {
      return res.sendFile('mix-calculator.html', { root });
    }

    // Check main-app session regardless of whether an estimator manager cookie
    // exists — the session may grant a higher role (e.g. create/edit → 'admin')
    // that would otherwise be blocked by a stale manager cookie.
    let mainAppRole: 'admin' | 'manager' | null = null;
    try {
      const sess = await lookupSessionFromCookie(req.headers.cookie);
      if (sess.kind === 'ok') {
        const matrix = await loadUserPermissionsMatrix(sess.user.id);
        const mp = matrix['mix_calculator'];
        const canAccess = sess.user.isAdmin || mp?.view || mp?.create || mp?.edit;
        if (canAccess) {
          mainAppRole = (sess.user.isAdmin || mp?.create || mp?.edit) ? 'admin' : 'manager';
        }
      }
    } catch {
      // ignore — fall through to estimator cookie check
    }

    // Effective role = highest privilege between main-app session and estimator cookie.
    const effectiveRole: 'admin' | 'manager' | null =
      mainAppRole === 'admin' ? 'admin'
      : estRole === 'manager' ? 'manager'
      : mainAppRole;

    if (!effectiveRole) {
      // Not authenticated via either route — redirect to estimator login.
      const returnTo = encodeURIComponent(req.originalUrl || '/mix-calculator');
      return res.redirect(302, `/estimator-login?returnTo=${returnTo}`);
    }

    // Inject window.__serverRole when the main-app session provides access OR
    // when it upgrades the role above the estimator cookie (manager → admin).
    const needsInjection = !estRole || (mainAppRole === 'admin' && estRole === 'manager');
    if (needsInjection) {
      const htmlPath = path.join(root, 'mix-calculator.html');
      let html = fs.readFileSync(htmlPath, 'utf-8');
      html = html.replace(
        '<script>\n(function(){',
        `<script>window.__serverRole='${effectiveRole}';</script>\n<script>\n(function(){`
      );
      return res.send(html);
    }

    // Estimator manager cookie with no higher main-app role — serve as-is.
    return res.sendFile('mix-calculator.html', { root });
  })

app.get("/api/dprs/labour-contractors", async (req, res) => {
    try {
      if (!req.authUser) return res.status(401).json({ error: "not_authenticated" });
      if (!req.authUser.isAdmin && !req.authUser.isOwner &&
          !["view", "create", "edit"].some(action => (req.authPermissions?.site_dprs as any)?.[action])) {
        return res.status(403).json({ message: "Access denied" });
      }
      const site = typeof req.query.site === "string" ? req.query.site.trim() : "";
      if (!site) return res.status(400).json({ message: "site is required" });
      if (!await assertTripSiteAccess(req, res, site)) return;
      const result = await db.execute(sql`
        SELECT trim(l.contractor) AS contractor
        FROM labour_logs l JOIN dprs d ON d.id = l.dpr_id
        WHERE lower(trim(d.site)) = lower(${site})
          AND NOT coalesce(d.is_deleted, false)
          AND NOT coalesce(d.is_cancelled, false)
          AND NOT coalesce(d.is_superseded, false)
          AND nullif(trim(l.contractor), '') IS NOT NULL
        GROUP BY trim(l.contractor)
        ORDER BY max(d.date) DESC, max(d.id) DESC, trim(l.contractor) ASC
      `);
      res.json(result.rows.map(row => row.contractor));
    } catch (err) {
      console.error("Labour contractor suggestions failed:", err);
      res.status(500).json({ message: "Failed to load contractor names" });
    }
  })

app.get("/api/dprs/with-details", async (req, res) => {
    const t0 = Date.now();
    try {
      const dateFrom = req.query.dateFrom as string | undefined;
      const dateTo   = req.query.dateTo   as string | undefined;
      const permittedSiteNames = await getPermittedSiteNames(req);
      let dprs = await storage.getDprsWithDetails({ dateFrom, dateTo });
      if (permittedSiteNames !== null) {
        // Compare base site names — edited/copied DPRs carry a provenance
        // suffix in `site` and must stay visible to site-restricted users.
        dprs = dprs.filter((d) => siteMatchesPermitted(d.site, permittedSiteNames));
      }
      const activeDrafts = dprs.filter(d => d.dprStatus === "draft" && !d.isDeleted && !d.isCancelled && !d.isSuperseded);
      const boqItemIds = Array.from(new Set(
        dprs.flatMap((dpr) =>
          (Array.isArray(dpr.progress) ? dpr.progress : [])
            .map((entry) => entry.boqItemId)
            .filter((id): id is number => id != null),
        ),
      ));
      // Extend the existing BOQ lookup for all authorized drafts, not one
      // request per DPR or project. Other BOQ references must also resolve.
      const readinessItemIds = activeDrafts.flatMap(dpr => collectDprBoqItemIds({
        progress: dpr.progress, equipment: dpr.equipment, labour: dpr.labour, structureItems: dpr.structureItems,
      }));
      const allBoqItemIds = Array.from(new Set([...boqItemIds, ...readinessItemIds]));
      const linkedBoqItems = allBoqItemIds.length > 0
        ? await db.select({
            id: boqItems.id,
            boqProjectId: boqItems.boqProjectId,
            unit: boqItems.unit,
            displayName: boqItems.displayName,
            itemName: boqItems.itemName,
            description: boqItems.description,
            mappingStatus: boqItems.mappingStatus,
            snlShortLabel: snlItems.shortLabel,
            snlMappedBy: snlBoqMappings.mappedBy,
            snlMappingIsAuto: snlBoqMappings.isAutoMapped,
            snlConfidence: snlBoqMappings.confidenceScore,
          })
            .from(boqItems)
            .leftJoin(snlBoqMappings, eq(snlBoqMappings.boqItemId, boqItems.id))
            .leftJoin(snlItems, eq(snlItems.id, snlBoqMappings.snlItemId))
            .where(drizzleInArray(boqItems.id, allBoqItemIds))
        : [];
      const draftProjectIds = Array.from(new Set(activeDrafts.map(d => d.boqProjectId).filter((id): id is number => id != null)));
      const draftProjects = draftProjectIds.length ? await db.select({
        id: boqProjectsTable.id, siteName: sitesTable.name,
      }).from(boqProjectsTable)
        .leftJoin(sitesTable, eq(sitesTable.id, boqProjectsTable.siteId))
        .where(drizzleInArray(boqProjectsTable.id, draftProjectIds)) : [];
      const readinessItemsById = new Map(linkedBoqItems.map(item => [item.id, item]));
      const readinessProjectsById = new Map(draftProjects.map(project => [project.id, project]));
      const activeDraftIds = new Set(activeDrafts.map(d => d.id));
      const boqItemById = new Map(linkedBoqItems.map((item) => [item.id, {
        id: item.id,
        displayName: item.displayName,
        itemName: item.itemName,
        description: item.description,
        mappingStatus: item.mappingStatus,
        snlShortLabel: item.snlShortLabel,
        snlMappedBy: item.snlMappedBy,
        snlMappingIsAuto: item.snlMappingIsAuto,
        snlConfidence: item.snlConfidence,
        canonicalDisplayName: trustedCanonicalBoqName(item) || null,
      }]));
      const response = dprs.map((dpr) => ({
        ...dpr,
        ...(activeDraftIds.has(dpr.id) ? {
          draftReadiness: evaluateSavedDraftReadiness(dpr, readinessItemsById, readinessProjectsById),
        } : {}),
        progress: dpr.progress.map((entry) => ({
          ...entry,
          boqItem: entry.boqItemId != null ? boqItemById.get(entry.boqItemId) ?? null : null,
        })),
      }));
      const dur = Date.now() - t0;
      if (dur > 200 || process.env.NODE_ENV !== "production") {
        const range = dateFrom ? ` [${dateFrom}→${dateTo ?? "∞"}]` : " [all]";
        console.log(`[perf] GET /api/dprs/with-details${range} → ${dprs.length} DPRs in ${dur}ms`);
      }
      res.json(response);
    } catch (err) {
      console.error("GET /api/dprs/with-details failed:", err);
      res.status(500).json({ message: "Failed to fetch DPRs with details" });
    }
  })

