app.post("/api/attachments", async (req, res) => {
    try {
      if (!req.authUser) return res.status(401).json({ message: "not_authenticated" });
      const parsed = insertAttachmentSchema.parse(req.body);
      if (!(attachmentModuleTypes as readonly string[]).includes(parsed.moduleType)) {
        return res.status(400).json({ message: `Invalid moduleType. Must be one of: ${attachmentModuleTypes.join(", ")}` });
      }
      // Diesel purchase evidence changes the purchase record's audit trail.
      // Stores inventory visibility is intentionally not sufficient to mutate it.
      if (parsed.moduleType === "diesel_purchase" && !assertEditEither(req, res, "site_diesel", "diesel_req_raise")) return;
      if (parsed.moduleType === "equipment_breakdown") {
        if (!assertCreateOrEdit(req, res, "plant_equipment")) return;
        if (!(await assertMaintenanceRecordAccess(req, res, parsed.linkedRecordId, true))) return;
      }
      if (!parsed.objectPath.startsWith("/objects/")) {
        return res.status(400).json({ message: "objectPath must reference an uploaded object" });
      }
      const ALLOWED_MIME_PREFIXES = ["image/", "application/pdf"];
      if (parsed.mimeType && !ALLOWED_MIME_PREFIXES.some((p) => parsed.mimeType!.startsWith(p))) {
        return res.status(400).json({ message: "Only image or PDF attachments are allowed" });
      }
      const MAX_FILE_SIZE = 15 * 1024 * 1024; // 15MB
      if (parsed.fileSize && parsed.fileSize > MAX_FILE_SIZE) {
        return res.status(400).json({ message: "File is too large. Maximum size is 15MB." });
      }
      // Batch 06C: per-activity photo cap — a dpr_progress attachment linked
      // to an activity row (progressEntryKey) may never be the 4th for that
      // row. Server-side backstop; the client blocks staging past capacity.
      if (parsed.moduleType === "dpr_progress" && parsed.progressEntryKey) {
        const existing = await storage.getAttachments(parsed.moduleType, parsed.linkedRecordId);
        const forEntry = existing.filter((a: any) => a.progressEntryKey === parsed.progressEntryKey).length;
        if (forEntry >= MAX_ACTIVITY_PHOTOS) {
          return res.status(400).json({ message: "Maximum 3 photos allowed for this activity." });
        }
      }
      // Evidence uploads may be retried after an ambiguous network response.
      // Do not create a second attachment row for the same canonical breakdown
      // and storage object.
      if (parsed.moduleType === "equipment_breakdown") {
        const existing = await storage.getAttachments(parsed.moduleType, parsed.linkedRecordId);
        const duplicate = existing.find((attachment: any) => attachment.objectPath === parsed.objectPath);
        if (duplicate) return res.status(200).json(duplicate);
      }
      const record = await storage.createAttachment({ ...parsed, uploadedBy: req.authUser.id });
      res.status(201).json(record);
    } catch (err: any) {
      if (err?.name === "ZodError") return res.status(400).json({ message: "Invalid data", errors: err.errors });
      res.status(500).json({ message: "Failed to save attachment" });
    }
  })

app.delete("/api/attachments/:id", async (req, res) => {
    try {
      if (!req.authUser) return res.status(401).json({ message: "not_authenticated" });
      const id = Number(req.params.id);
      const attachment = await storage.getAttachment(id);
      if (!attachment) return res.status(404).json({ message: "Attachment not found" });
      // Evidence removal uses the underlying module's explicitly delegated Delete.
      let allowed = false;
      switch (attachment.moduleType) {
        case "diesel_purchase": allowed = assertDeleteEither(req, res, "site_diesel", "diesel_req_raise"); break;
        case "dpr_progress": case "dpr_material": allowed = assertDelete(req, res, "site_dprs"); break;
        case "material_receipt": case "hmp_rmc_stock_receipt": allowed = assertDelete(req, res, "plant_materials"); break;
        case "site_purchase": case "site_material_trip": allowed = assertDelete(req, res, "site_materials"); break;
        case "irn": allowed = assertDelete(req, res, "irn_raise"); break;
        case "pi": case "pi_purchaser_action": allowed = assertDelete(req, res, "purchase_indents_raise"); break;
        case "store_grn": allowed = assertDelete(req, res, "stores_inventory"); break;
        case "vendor_bill": allowed = assertDelete(req, res, "vendor_bills_raise"); break;
        case "plant_production": allowed = assertDelete(req, res, "plant_production"); break;
        case "equipment_breakdown": case "equipment_maintenance": case "equipment_fuel_proof":
          allowed = assertDelete(req, res, "plant_equipment"); break;
        case "quality_test": allowed = assertDelete(req, res, "rmc_cube_tests"); break;
        default: return res.status(403).json({ error: "unmapped_attachment_permission" });
      }
      if (!allowed) return;
      if (attachment.moduleType === "equipment_breakdown") {
        if (!(await assertMaintenanceRecordAccess(req, res, attachment.linkedRecordId, true))) return;
      }
      const deleted = await storage.deleteAttachment(id);
      if (!deleted) return res.status(404).json({ message: "Attachment not found" });
      res.status(204).send();
    } catch (err) {
      if (err instanceof AttachmentReferenceError) {
        return res.status(409).json({ message: err.message, code: "ATTACHMENT_REFERENCED" });
      }
      res.status(500).json({ message: "Failed to delete attachment" });
    }
  })

