app.get("/api/dprs/chainage-overlap-context", async (req, res) => {
    try {
      if (!assertCreate(req, res, "site_dprs")) return;
      const itemIds = String(req.query.boqItemIds ?? "")
        .split(",").map((s) => Number(s.trim())).filter((n) => Number.isFinite(n) && n > 0);
      const excludeDprId = req.query.excludeDprId != null && String(req.query.excludeDprId).trim() !== ""
        ? Number(req.query.excludeDprId) : null;
      if (itemIds.length === 0) return res.json({ entries: [] });
      if (itemIds.length > 200) return res.status(400).json({ message: "Too many BOQ items" });
      // Site-access security: restricted users may only read progress for
      // projects whose site is permitted (same rule as the Progress Report).
      const permittedSiteNames = await getPermittedSiteNames(req);
      if (permittedSiteNames !== null) {
        const items = await Promise.all(itemIds.map((id) => storage.getBoqItem(id)));
        const projectIds = new Set<number>();
        for (const item of items as any[]) {
          if (item?.boqProjectId != null) projectIds.add(Number(item.boqProjectId));
        }
        const sites = await storage.getSites();
        const projects = await Promise.all(Array.from(projectIds).map((pid) => storage.getBoqProject(pid)));
        for (const project of projects) {
          const projectSite = project?.siteId != null ? sites.find((s) => s.id === project.siteId)?.name ?? null : null;
          if (projectSite == null || !siteMatchesPermitted(projectSite, permittedSiteNames)) {
            return res.status(403).json({ message: "Access denied for this site" });
          }
        }
      }
      const entries = await storage.getSubmittedChainageEntries(itemIds, excludeDprId);
      res.json({ entries });
    } catch (err) {
      console.error("GET /api/dprs/chainage-overlap-context:", err);
      res.status(500).json({ message: "Failed to load overlap context" });
    }
  })

app.patch("/api/progress-entries/:id/overlap-resolution", requireAuth, async (req, res) => {
    try {
      if (!assertEdit(req, res, "site_dprs")) return;
      const id = Number(req.params.id);
      if (!Number.isFinite(id) || id <= 0) {
        return res.status(400).json({ message: "Invalid progress entry id" });
      }

      // ── Strict payload validation ──────────────────────────────────────────
      // Exactly one of the two shapes must be present; no extra keys from the
      // other shape are tolerated (e.g. sending chainageOverrideReason along
      // with isIncidental:true is rejected as ambiguous).
      const body = req.body ?? {};
      if (typeof body !== "object" || Array.isArray(body)) {
        return res.status(400).json({ message: "Payload must be a JSON object" });
      }
      const bodyKeys = Object.keys(body);
      const hasOverrideReason =
        typeof body.chainageOverrideReason === "string" &&
        body.chainageOverrideReason.trim() !== "";
      const hasOverrideKey =
        Object.prototype.hasOwnProperty.call(body, "chainageOverrideReason");
      const hasIncidentalKey =
        Object.prototype.hasOwnProperty.call(body, "isIncidental");
      const hasLayerKey =
        Object.prototype.hasOwnProperty.call(body, "layerNo");
      const shapeCount =
        (hasIncidentalKey ? 1 : 0) + (hasOverrideKey ? 1 : 0) + (hasLayerKey ? 1 : 0);
      if (shapeCount > 1) {
        return res.status(400).json({
          message: "Payload must be exactly one shape — one of { isIncidental: true, incidentalDescription }, { chainageOverrideReason }, or { layerNo } — not more than one",
        });
      }
      if (shapeCount === 0) {
        return res.status(400).json({
          message: "Provide exactly one of: { isIncidental: true, incidentalDescription: '<non-empty>' }, { chainageOverrideReason: '<non-empty>' }, or { layerNo: <positive integer> }",
        });
      }

      // Shape A: incidental — isIncidental must be true (not false/missing).
      if (hasIncidentalKey) {
        if (body.isIncidental !== true) {
          return res.status(400).json({
            message: "isIncidental must be true in the incidental shape",
          });
        }
        const desc =
          typeof body.incidentalDescription === "string"
            ? body.incidentalDescription.trim()
            : "";
        if (!desc) {
          return res.status(400).json({
            message: "incidentalDescription is required and must be non-empty when isIncidental is true",
          });
        }
        const allowedKeys = new Set(["isIncidental", "incidentalDescription"]);
        if (bodyKeys.length !== 2 || bodyKeys.some((key) => !allowedKeys.has(key))) {
          return res.status(400).json({
            message: "Incidental payload must contain exactly isIncidental and incidentalDescription",
          });
        }
      }

      // Shape B: override reason — must be a non-blank string.
      if (hasOverrideKey) {
        if (!hasOverrideReason) {
          return res.status(400).json({
            message: "chainageOverrideReason must be a non-empty string",
          });
        }
        if (bodyKeys.length !== 1 || bodyKeys[0] !== "chainageOverrideReason") {
          return res.status(400).json({
            message: "Separately Payable payload must contain exactly chainageOverrideReason",
          });
        }
      }

      // Shape C: layer correction — layerNo must be a positive integer. This
      // direct historical-correction flow never clears the layer to null.
      if (hasLayerKey) {
        const rawLayer = body.layerNo;
        if (
          typeof rawLayer !== "number" ||
          !Number.isInteger(rawLayer) ||
          rawLayer <= 0
        ) {
          return res.status(400).json({
            message: "layerNo must be a positive integer",
          });
        }
        if (bodyKeys.length !== 1 || bodyKeys[0] !== "layerNo") {
          return res.status(400).json({
            message: "Layer correction payload must contain exactly layerNo",
          });
        }
      }

      // ── Load entry + parent DPR header ────────────────────────────────────
      const found = await storage.getProgressEntryWithDpr(id);
      if (!found) {
        return res.status(404).json({ message: "Progress entry not found" });
      }
      const { entry, dprSite, dprIsCancelled, dprIsDeleted, dprIsSuperseded } = found;

      // ── DPR editability guard (matches DPR edit/version route semantics) ──
      if (dprIsDeleted) {
        return res.status(409).json({ message: "The parent DPR has been deleted and cannot be modified" });
      }
      if (dprIsCancelled) {
        return res.status(409).json({ message: "The parent DPR is cancelled and cannot be modified" });
      }
      if (dprIsSuperseded) {
        return res.status(409).json({ message: "The parent DPR has been superseded by a newer version and cannot be modified" });
      }

      // ── Site-access authorization ──────────────────────────────────────────
      const permittedSiteNames = await getPermittedSiteNames(req);
      if (
        permittedSiteNames !== null &&
        !siteMatchesPermitted(dprSite, permittedSiteNames)
      ) {
        return res.status(403).json({ message: "Access denied for this site" });
      }

      // ── Audit actor (shared across all shapes) ─────────────────────────────
      const actor = currentUserName(req);
      const actorId = req.authUser?.id ?? null;
      const actorRole = req.authUser
        ? (req.authUser.isOwner ? "owner" : req.authUser.isAdmin ? "admin" : "manager")
        : null;

      // ── Shape C: direct layer correction (layer_no only) ───────────────────
      // Only progress_entries.layer_no is updated; no classification is touched
      // and no layer is inferred. Canonical overlap recomputation then decides
      // whether the pair remains an overlap.
      if (hasLayerKey) {
        const newLayer = body.layerNo as number;
        const oldLayer = entry.layerNo ?? null;

        // ── Capability boundary (same as DPR forms) ──────────────────────────
        // Allow correction when:
        //   (a) the BOQ item is layer-capable per isLayerCapableItem, OR
        //   (b) the entry already has a non-null layerNo (historical correction
        //       stays permitted even when BOQ metadata is incomplete).
        // Reject when neither applies — a row with no BOQ item AND null layer
        // cannot be reliably assigned a layer number here.
        const boqItemForLayer = entry.boqItemId != null
          ? await storage.getBoqItem(entry.boqItemId)
          : null;
        const itemIsCapable = isLayerCapableItem(boqItemForLayer as any);
        const hasExistingLayer = oldLayer != null;
        if (!itemIsCapable && !hasExistingLayer) {
          return res.status(422).json({
            message:
              "This progress entry belongs to a BOQ item that is not layer-capable, " +
              "and no layer number has been previously recorded. " +
              "Layer correction is only available for layer-capable items (e.g. WMM, GSB, embankment) " +
              "or entries that already carry a layer number.",
          });
        }

        const updatedEntry = await storage.updateProgressEntryLayer(id, newLayer);
        if (!updatedEntry) {
          return res.status(404).json({ message: "Progress entry not found" });
        }
        await storage.logAudit({
          module: "progress_entries",
          transactionId: id,
          action: "overlap_resolution",
          userId: actorId,
          userName: actor,
          userRole: actorRole,
          oldValues: { layerNo: oldLayer },
          newValues: { layerNo: updatedEntry.layerNo ?? null },
          reason: `Layer correction: ${oldLayer ?? "not recorded"} → ${newLayer}`,
        });
        return res.json(updatedEntry);
      }

      // ── Build strictly-shaped resolution input (Shapes A/B) ────────────────
      type ClassificationFields =
        | { isIncidental: true; incidentalDescription: string }
        | { chainageOverrideReason: string };
      const classificationFields: ClassificationFields = hasIncidentalKey
        ? { isIncidental: true, incidentalDescription: (body.incidentalDescription as string).trim() }
        : { chainageOverrideReason: (body.chainageOverrideReason as string).trim() };

      // ── Snapshot old values for audit trail ───────────────────────────────
      const oldValues = {
        isIncidental: entry.isIncidental ?? false,
        incidentalDescription: entry.incidentalDescription ?? null,
        chainageOverrideReason: entry.chainageOverrideReason ?? null,
      };

      const updated = await storage.updateProgressEntryClassification(id, classificationFields);
      if (!updated) {
        return res.status(404).json({ message: "Progress entry not found" });
      }
      const newValues = {
        isIncidental: updated.isIncidental ?? false,
        incidentalDescription: updated.incidentalDescription ?? null,
        chainageOverrideReason: updated.chainageOverrideReason ?? null,
      };

      // ── Audit log ─────────────────────────────────────────────────────────
      const reason = hasIncidentalKey
        ? `Marked incidental: ${(classificationFields as { isIncidental: true; incidentalDescription: string }).incidentalDescription}`
        : `Overlap override reason: ${(classificationFields as { chainageOverrideReason: string }).chainageOverrideReason}`;
      await storage.logAudit({
        module: "progress_entries",
        transactionId: id,
        action: "overlap_resolution",
        userId: actorId,
        userName: actor,
        userRole: actorRole,
        oldValues,
        newValues,
        reason,
      });

      res.json(updated);
    } catch (err) {
      console.error("PATCH /api/progress-entries/:id/overlap-resolution:", err);
      res.status(500).json({ message: "Failed to update progress entry classification" });
    }
  })

