app.post("/api/dprs/:id/version", async (req, res) => {
    try {
      const originalId = Number(req.params.id);

      // A new DPR version is a create-shaped action, but it requires edit
      // rights on the parent record too. Gate on edit (the stricter of the
      // two) since revising a DPR is logically an edit.
      if (!assertEdit(req, res, "site_dprs")) return;

      // Permission System v2: check site access BEFORE parsing body so a
      // restricted user cannot probe other sites even with a malformed payload.
      const versionOriginal = await storage.getDpr(originalId);
      if (!versionOriginal) {
        return res.status(404).json({ message: "DPR not found" });
      }
      {
        const permittedSiteNames = await getPermittedSiteNames(req);
        if (permittedSiteNames !== null && !siteMatchesPermitted(versionOriginal.site, permittedSiteNames)) {
          return res.status(403).json({ message: "Access denied for this site" });
        }
      }
      if (versionOriginal.dprStatus === "draft") {
        return res.status(409).json({
          code: "DPR_DRAFT_MUTATION_NOT_ALLOWED",
          message: "A draft DPR cannot be versioned. Edit, save, or submit the draft instead.",
        });
      }
      if ((versionOriginal as any).isSuperseded) {
        return res.status(409).json({
          code: "DPR_ALREADY_SUPERSEDED",
          message: "This DPR has already been superseded by a newer version.",
        });
      }

      let input = versionSchema.parse(req.body);
      {
        const savedProjectId = versionOriginal.boqProjectId != null
          ? Number(versionOriginal.boqProjectId)
          : null;
        const payloadProjectId = (input.data as any).boqProjectId != null
          ? Number((input.data as any).boqProjectId)
          : null;
        if (savedProjectId == null && payloadProjectId != null) {
          const projectRecoveryAllowed = await automaticNullProjectRecovery(versionOriginal, input.data);
          const hasBoqReferences =
            hasDprBoqReferences(input.data)
            || hasPreservedDprBoqReferences(versionOriginal, input.data);
          if (!projectRecoveryAllowed && hasBoqReferences) {
            // Keep the route-level response deterministic for an evidence
            // bearing request. Storage repeats item/project validation inside
            // its transaction and rejects foreign or missing item ids.
            return res.status(400).json({
              code: "DPR_PROJECT_MISMATCH",
              message: "A DPR version's BOQ references must belong to its same-site project.",
              savedProjectId,
              payloadProjectId,
            });
          }
          if (!projectRecoveryAllowed) {
            // A saved null with no evidence remains null; a guessed positive
            // header must never create a project pin by itself.
            input = {
              ...input,
              data: { ...input.data, boqProjectId: null },
            };
          }
        }
      }
      // Capture the target scope before any async validation. Storage locks the
      // same target and compares this token in its version transaction, so a
      // scope correction committed while programme/geometry/overlap checks run
      // cannot be silently accepted with a freshly fetched token.
      const scopeVersionToken = (input.data as any).boqProjectId != null
        ? await storage.getProjectScopeVersionToken(Number((input.data as any).boqProjectId))
        : null;
      // SiteEdit deliberately sends editable activity fields rather than
      // exposing server-owned review/link facts as controls. Preserve those
      // facts in the version payload before validation so programme approval,
      // scope overrides, and link-review history survive the row replacement.
      const originalProgress = Array.isArray((versionOriginal as any).progress)
        ? (versionOriginal as any).progress
        : [];
      const progressSourceResolution = Array.isArray((input.data as any).progress)
        ? resolveDprProgressSources((input.data as any).progress, originalProgress)
        : { ok: true as const, sources: [] };
      if (!progressSourceResolution.ok) {
        return res.status(400).json({
          code: "DPR_PROGRESS_IDENTITY_INVALID",
          message: progressSourceResolution.message,
        });
      }
      if (Array.isArray((input.data as any).progress)) {
        (input.data as any).progress = (input.data as any).progress.map((row: any, index: number) => {
          const source = progressSourceResolution.sources[index];
          const relevantFactsChanged = !!source && dprProgressReviewFactsChanged(source, row);
          const preservedSource = source && !relevantFactsChanged ? source : undefined;
          return {
            ...row,
            // These are server-owned facts. Never accept a forged incoming
            // approval/warning/actor value; restore the exact source row's
            // facts only when the validated identity and relevant work facts
            // still match. A changed chainage/link resets stale approval.
            linkReviewRequired: (preservedSource as any)?.linkReviewRequired ?? false,
            chainageReviewStatus: (preservedSource as any)?.chainageReviewStatus ?? null,
            scopeWarningType: (preservedSource as any)?.scopeWarningType ?? null,
            scopeOverrideReason: (preservedSource as any)?.scopeOverrideReason ?? null,
            scopeOverrideBy: (preservedSource as any)?.scopeOverrideBy ?? null,
            scopeOverrideAt: (preservedSource as any)?.scopeOverrideAt ?? null,
            lengthOverrideReason: row.lengthOverrideReason ?? null,
          };
        });
      }
      const authenticatedIsAdmin = req.authUser?.isAdmin === true;
      const geometryError = await validateVersionProgressGeometry(input.data, {
        allowLengthOverride: authenticatedIsAdmin,
        allowUomOverride: authenticatedIsAdmin,
        sourceProgress: Array.isArray(versionOriginal.progress) ? versionOriginal.progress : [],
      });
      if (geometryError) {
        return res.status(400).json({
          code: "DPR_GEOMETRY_INVALID",
          message: geometryError,
        });
      }
      const lifecycleIdentityConflict = equipmentLifecycleIdentityConflict(
        Array.isArray(versionOriginal.equipment) ? versionOriginal.equipment : [],
        Array.isArray((input.data as any).equipment) ? (input.data as any).equipment : [],
      );
      if (lifecycleIdentityConflict != null) {
        return res.status(409).json({
          message: "The linked equipment and dispatch identity are immutable. Keep the original equipment and plant usage IDs unchanged.",
          error: "EQUIPMENT_LIFECYCLE_ID_IMMUTABLE",
          equipmentUsageId: lifecycleIdentityConflict,
        });
      }
      const adminOnlyLinkedFieldConflict = linkedEquipmentAdminOnlyFieldConflict(
        Array.isArray(versionOriginal.equipment) ? versionOriginal.equipment : [],
        Array.isArray((input.data as any).equipment) ? (input.data as any).equipment : [],
      );
      if (adminOnlyLinkedFieldConflict != null && !authenticatedIsAdmin) {
        return res.status(403).json({
          message: "Opening meter, start time, diesel, and diesel source on a dispatched equipment segment can only be corrected by an administrator.",
          error: "LINKED_EQUIPMENT_ADMIN_EDIT_REQUIRED",
          equipmentUsageId: adminOnlyLinkedFieldConflict,
        });
      }
      const unownedLinkedConflicts = await unownedLinkedEquipmentConflicts(
        Array.isArray(versionOriginal.equipment) ? versionOriginal.equipment : [],
        Array.isArray((input.data as any).equipment) ? (input.data as any).equipment : [],
      );
      if (unownedLinkedConflicts.length > 0 && !authenticatedIsAdmin) {
        return res.status(409).json({
          message: "This linked equipment usage is historical and has no editable canonical owner. Its source facts cannot be changed in a DPR version.",
          error: "EQUIPMENT_USAGE_IMMUTABLE",
          equipmentUsageId: unownedLinkedConflicts[0],
        });
      }
      const movedUsageConflict = await movedEquipmentVersionConflict(
        Array.isArray(versionOriginal.equipment) ? versionOriginal.equipment : [],
        Array.isArray((input.data as any).equipment) ? (input.data as any).equipment : [],
        authenticatedIsAdmin,
      );
      if (movedUsageConflict != null) {
        return res.status(409).json({
          message: "This equipment segment has already moved onward and is immutable. Keep it unchanged in this DPR version.",
          error: "MOVED_EQUIPMENT_SEGMENT_IMMUTABLE",
          equipmentUsageId: movedUsageConflict,
        });
      }
      /*
       * Version validation is intentionally narrower than fresh create/draft/
       * submit validation.  SiteEdit sends a replacement array, so compare
       * each row with the already-resolved source identity before invoking the
       * three validators.  In particular, do not let a legacy untouched row
       * fail because today's rules are stricter than the rules in force when
       * that historical row was submitted.
       *
       * Keep the row objects themselves (rather than cloning them into JSON)
       * so validator mutations for changed/new rows — calculated quantity
       * source and chainage review status — still reach createVersionDpr.
       * Unchanged rows are not passed to a validator at all and therefore
       * cannot be mutated by one.
       */
      const versionProgress = Array.isArray((input.data as any).progress)
        ? (input.data as any).progress
        : [];
      const changedProgressIndexes = new Set<number>();
      versionProgress.forEach((row: any, index: number) => {
        const source = progressSourceResolution.ok
          ? progressSourceResolution.sources[index]
          : undefined;
        if (!source || dprProgressValidationFactsChanged(source as any, row as any)) {
          changedProgressIndexes.add(index);
        }
      });
      const changedProgress = versionProgress.filter((_row: any, index: number) =>
        changedProgressIndexes.has(index)
      );
      const programmeContextChanged = dprProgressProgrammeContextChanged(
        versionOriginal as any,
        input.data as any,
      );

      // 030A Part F: programme-bar link validation applies to edits too.
      // The BOQ-project header is part of this validator's context; when it
      // changes, every current row is relevant even if its row facts match.
      const linkError = await validateProgressProgrammeLinks(
        programmeContextChanged
          ? { ...(input.data as any), progress: versionProgress }
          : { ...(input.data as any), progress: changedProgress },
      );
      if (linkError) return res.status(400).json({ message: linkError, code: "PROGRAMME_LINK_INVALID" });
      const qtySourceError = await validateProgressQuantitySources({
        ...(input.data as any),
        progress: changedProgress,
      });
      if (qtySourceError) return res.status(400).json({ message: qtySourceError, code: "QUANTITY_SOURCE_INVALID" });
      const materialOutcomeError = await validateProgressMaterialOutcomes({
        ...(input.data as any),
        progress: changedProgress,
      });
      if (materialOutcomeError) return res.status(400).json({ message: materialOutcomeError, code: "MATERIAL_OUTCOME_INVALID" });
      // The version actor is an authenticated identity, not a client
      // assertion. In particular, a user with ordinary edit rights must not
      // be able to submit `editedBy: "admin"` and unlock admin-only
      // corrections. Keep the engineer completion workflow, but derive it
      // from the authenticated role as well.
      const authenticatedRole = String((req.authUser as any)?.role ?? "").toLowerCase();
      const authenticatedIsEngineer =
        authenticatedRole === "engineer" || (req.authUser as any)?.isFieldEngineer === true;
      const editedBy = authenticatedIsAdmin
        ? "admin"
        : authenticatedIsEngineer
          ? "engineer"
          : "manager";

      if (editedBy === "engineer") {
        const equipment = Array.isArray(versionOriginal.equipment) ? versionOriginal.equipment : [];
        const hasPendingClosing = equipment.some((e: any) =>
          e.machine && e.openingReading != null && e.closingReading == null
        );
        if (!hasPendingClosing) {
          return res.status(403).json({ message: "Engineer completion only allowed for DPRs with pending closing entries" });
        }
      }

      // Batch 06B: versioning creates a new SUBMITTED DPR — it must pass the
      // same chainage-overlap recheck as create/submit, or the guard could be
      // bypassed by editing. The original is excluded (it gets superseded).
      {
        const overlapIssues = await evaluateChainageOverlapIssues(
          input.data,
          originalId,
          Array.isArray(versionOriginal.progress) ? versionOriginal.progress : [],
        );
        if (overlapIssues.length > 0) {
          return res.status(422).json({
            message: "DPR is not ready to submit",
            code: "DPR_NOT_READY",
            mandatory: overlapIssues,
            advisories: [],
          });
        }
      }
      const newVersion = await storage.createVersionDpr(
        originalId,
        input.data,
        editedBy,
        input.clientTimestamp,
        {
          userId: req.authUser?.id ?? null,
          userName: req.authUser ? currentUserName(req) : input.data.engineer,
          closedAt: new Date(),
          allowMovedSourceReuse: true,
          allowMovedSourceCorrection: authenticatedIsAdmin,
          allowUnownedLinkedCorrectionIds: authenticatedIsAdmin ? unownedLinkedConflicts : [],
        },
        scopeVersionToken,
      );

      const actor = currentUserName(req);
      await storage.createNotification({
        type: "info",
        title: "DPR Updated",
        message: `DPR for ${input.data.site} (${input.data.date}) was edited by ${actor}`,
        isRead: 0,
      });
      sendPushToSection("site_dprs", "DPR Updated", `${actor} edited DPR for ${input.data.site} (${input.data.date})`, "/site-reports").catch(() => {});

      res.status(201).json(newVersion);
    } catch (err) {
      if ((err as any)?.code === "DPR_DRAFT_MUTATION_NOT_ALLOWED") {
        return res.status(409).json({ code: (err as any).code, message: (err as any).message });
      }
      if ((err as any)?.code === "DPR_ALREADY_SUPERSEDED") {
        return res.status(409).json({ code: (err as any).code, message: (err as any).message });
      }
      if ((err as any)?.code === "SCOPE_CHANGED_DURING_PLANNING") {
        return res.status(409).json({ code: (err as any).code, message: (err as any).message });
      }
      if ((err as any)?.code === "DPR_PROJECT_MISMATCH") {
        return res.status(400).json({
          code: "DPR_PROJECT_MISMATCH",
          message: (err as any).message,
        });
      }
      if (err instanceof InvalidDieselSourceError) return res.status(400).json({ code: err.code, field: err.field, message: err.message });
      if (err instanceof z.ZodError) {
        return res.status(400).json({
          message: err.errors[0].message,
          field: err.errors[0].path.join('.'),
        });
      }
      if (handleInsufficientPlantStock(err, res)) return;
      if (err instanceof CutFillInsufficientAvailabilityError) return res.status(409).json({ code: err.code, message: err.message, availableQty: err.availableQty, alreadyUsedQty: err.alreadyUsedQty });
      if (err instanceof CutFillValidationError) return res.status(422).json({ code: err.code, message: err.message });
      if (handleEquipmentActivityAllocationError(err, res)) return;
      if (handleEquipmentLifecycleConflict(err, res)) return;
      res.status(500).json({ message: "Failed to create version" });
    }
  })

app.post("/api/dprs/:id/clone", async (req, res) => {
    try {
      if (!assertEdit(req, res, "site_dprs")) return;
      const id = Number(req.params.id);
      const input = cloneSchema.parse(req.body);
      const editedBy = input.editedBy || (req.authUser?.isAdmin ? "admin" : "manager");

      // Permission System v2: check site access before cloning
      const cloneSource = await storage.getDpr(id);
      if (!cloneSource) {
        return res.status(404).json({ message: "Original DPR not found" });
      }
      {
        const permittedSiteNames = await getPermittedSiteNames(req);
        if (permittedSiteNames !== null && !siteMatchesPermitted(cloneSource.site, permittedSiteNames)) {
          return res.status(403).json({ message: "Access denied for this site" });
        }
      }
      if (cloneSource.dprStatus === "draft") {
        return res.status(409).json({
          code: "DPR_DRAFT_MUTATION_NOT_ALLOWED",
          message: "A draft DPR cannot be cloned. Edit, save, or submit the draft instead.",
        });
      }

      const cloned = await storage.cloneDpr(id, editedBy, input.clientTimestamp, req.authUser?.id ?? null);
      if (!cloned) {
        return res.status(404).json({ message: "Original DPR not found" });
      }

      const actor = currentUserName(req);
      await storage.createNotification({
        type: "success",
        title: "DPR Cloned",
        message: `DPR cloned for ${cloned.site} (${cloned.date}) by ${actor}`,
        isRead: 0,
      });
      sendPushToSection("site_dprs", "DPR Cloned", `${cloned.site} - ${cloned.date}`, "/site-reports").catch(() => {});

      res.status(201).json(cloned);
    } catch (err) {
      if ((err as any)?.code === "DPR_DRAFT_MUTATION_NOT_ALLOWED") {
        return res.status(409).json({ code: (err as any).code, message: (err as any).message });
      }
      if (err instanceof InvalidDieselSourceError) return res.status(400).json({ code: err.code, field: err.field, message: err.message });
      if (err instanceof z.ZodError) {
        return res.status(400).json({
          message: err.errors[0].message,
          field: err.errors[0].path.join('.'),
        });
      }
      if (handleInsufficientPlantStock(err, res)) return;
      if (handleEquipmentActivityAllocationError(err, res)) return;
      res.status(500).json({ message: "Failed to clone DPR" });
    }
  })

