app.post("/api/stores/grns", async (req, res) => {
    try {
      if (!assertCreate(req, res, "stores_inventory")) return;
      const { grn, items, grnCategory } = req.body;
      if (!grn || !items || !Array.isArray(items)) {
        return res.status(400).json({ error: "grn and items are required" });
      }

      // Server-side over-receipt guard: reject if any line would exceed its approved qty.
      // For manually-created GRNs (Batch 17): items may omit indentItemId — only items
      // that DO carry indentItemId are subject to the over-receipt guard. When indentItemId
      // is provided, validate it actually belongs to the referenced indent.
      if (grn.indentRef) {
        const linkedWithId = (items as any[]).filter(it => it.indentItemId != null);
        if (linkedWithId.length > 0) {
          // Validate that every provided indentItemId actually belongs to this indent
          const validIndentItemIds = await storage.getIndentItemIdsForIndentNo(grn.indentRef);
          if (validIndentItemIds.size > 0) {
            const foreignIds = linkedWithId.filter(it => !validIndentItemIds.has(Number(it.indentItemId)));
            if (foreignIds.length > 0) {
              return res.status(400).json({ error: "One or more indentItemId values do not belong to the referenced indent" });
            }
          }
        }
      }
      const linkedItems = (items as any[]).filter(it => it.indentItemId != null);
      if (linkedItems.length > 0) {
        const violations = await storage.checkGrnOverReceipt(
          linkedItems.map(it => ({ indentItemId: Number(it.indentItemId), qty: parseFloat(it.qty) || 0 }))
        );
        if (violations.length > 0) {
          return res.status(422).json({ error: "Over-receipt blocked", details: violations });
        }
      }

      const result = await storage.createStoreGrn(grn, items, grnCategory || undefined);
      sendPushToSection("stores_inventory", "GRN Created", `${result.grnNo ?? "GRN"} — ${grn.supplierName ?? "Supplier"}`, "/stores").catch(() => {});
      res.status(201).json(result);
    } catch (err) {
      console.error("POST /api/stores/grns:", err);
      res.status(500).json({ error: "Failed to create GRN" });
    }
  })

app.patch("/api/stores/grns/:id", async (req, res) => {
    try {
      if (!assertEdit(req, res, "stores_inventory")) return;
      const id = parseInt(req.params.id);
      const existing = await storage.getStoreGrn(id);
      if (!existing) return res.status(404).json({ error: "GRN not found" });
      if (existing.isCancelled) return res.status(409).json({ error: "Cannot edit a cancelled GRN" });

      const { acceptanceStatus, acceptanceRemarks, status, indentRef, overrideReason, itemAcceptance } = req.body;
      const updateData: Parameters<typeof storage.updateStoreGrn>[1] = {};

      if (acceptanceStatus !== undefined) {
        if (!["accepted", "partial", "rejected"].includes(acceptanceStatus)) {
          return res.status(400).json({ error: "Invalid acceptanceStatus value" });
        }
        updateData.acceptanceStatus = acceptanceStatus;
        updateData.acceptanceRemarks = acceptanceRemarks ?? null;
      }
      if (status !== undefined) {
        if (!["draft", "finalized"].includes(status)) {
          return res.status(400).json({ error: "Invalid status value" });
        }
        // Separation-of-duties check: the person who auto-created this GRN (the purchaser)
        // cannot finalize it — that must be done by someone in Stores.
        if (status === "finalized" && (existing as any).createdByUserId && req.authUser) {
          const isSelf = req.authUser.id === (existing as any).createdByUserId;
          if (isSelf) {
            if (!req.authUser.isAdmin) {
              return res.status(409).json({
                error: "Separation of duties: the purchaser who raised this GRN cannot finalize it. Ask a Stores/Admin user to finalize.",
                code: "SELF_FINALIZE_BLOCKED",
              });
            }
            // Admin override — require an explicit reason
            if (!overrideReason || typeof overrideReason !== "string" || !overrideReason.trim()) {
              return res.status(409).json({
                error: "Admin override required: provide an overrideReason to bypass separation-of-duties.",
                code: "OVERRIDE_REASON_REQUIRED",
              });
            }
            updateData.selfApprovalOverrideReason = overrideReason.trim();
            updateData.selfApprovalOverriddenBy = req.authUser.id;
            updateData.selfApprovalOverriddenAt = new Date();
          }
        }
        updateData.status = status;
      }
      if (indentRef !== undefined) {
        updateData.indentRef = indentRef ?? null;
      }

      if (Object.keys(updateData).length === 0 && (!itemAcceptance || itemAcceptance.length === 0)) {
        return res.status(400).json({ error: "No valid fields to update" });
      }
      const result = await storage.updateStoreGrn(id, updateData, itemAcceptance ?? undefined);
      if (!result) return res.status(404).json({ error: "GRN not found" });

      // Write audit log when a GRN is finalised (including admin override path)
      if (updateData.status === "finalized" && req.authUser) {
        try {
          await storage.logAudit({
            module: "store_grn",
            transactionId: id,
            action: updateData.selfApprovalOverrideReason ? "finalize_override" : "finalize",
            userId: req.authUser.id,
            userName: req.authUser.fullName ?? `User #${req.authUser.id}`,
            userRole: (req.authUser as any).role ?? null,
            reason: updateData.selfApprovalOverrideReason
              ? `Admin override — ${updateData.selfApprovalOverrideReason}`
              : null,
            stockImpact: `GRN ${result.grnNumber} finalised — items added to stock.`,
          });
        } catch (auditErr) {
          console.error("PATCH /api/stores/grns/:id: audit log write failed (non-fatal):", auditErr);
        }
      }

      res.json(result);
    } catch (err) {
      console.error("PATCH /api/stores/grns/:id:", err);
      res.status(500).json({ error: "Failed to update GRN" });
    }
  })

