app.get("/api/reports/progress/export", async (req, res) => {
    if (!assertExport(req, res, "site_dprs")) return;
    try {
      if (!assertView(req, res, "site_dprs")) return;
      const projectId = parseInt(req.query.projectId as string);
      if (!Number.isFinite(projectId)) return res.status(400).json({ error: "projectId is required" });
      const report = await assembleProgressReport(req, projectId, (req.query.site as string) || undefined);
      if (report === "forbidden") return res.status(403).json({ error: "forbidden" });
      if (!report) return res.status(404).json({ error: "Project not found" });
      const from = (req.query.from as string) || report.defaultFromDate || "1900-01-01";
      const to = (req.query.to as string) || new Date().toISOString().slice(0, 10);

      const summaryRows: any[][] = [
        ["Progress Report — RA-style DPR Rollup"],
        ["Project", report.project.name],
        ["Site", (req.query.site as string) || "All Sites"],
        ["Period", `${from} to ${to}`],
        ["Generated", new Date().toISOString().slice(0, 10)],
        [],
        ["Sl.", "BOQ Item", "UoM", "BOQ Qty", "Previous", "This Period", "Cumulative", "Balance", "% Complete", "DPR Count"],
      ];
      const detailRows: any[][] = [
        ["Date", "Item", "Side", "From", "To", "L", "W", "T", "Measured Qty", "Measured UoM", "BOQ Qty", "BOQ UoM", "Cumulative", "DPR No.", "Prepared By", "Remarks", "Possible Overlap", "Incidental (no BOQ credit)"],
      ];
      let sl = 0;
      for (const it of report.items) {
        const abstract = computeItemAbstract(it.entries, it.boqItem, from, to);
        sl++;
        summaryRows.push([
          sl,
          boqItemDisplayName(it.boqItem),
          it.boqItem.unit,
          abstract.contractQty,
          abstract.previousQty != null ? round3(abstract.previousQty) : "INCOMPLETE — unresolved BOQ credit",
          abstract.thisPeriodQty != null ? round3(abstract.thisPeriodQty) : "INCOMPLETE — unresolved BOQ credit",
          abstract.cumulativeQty != null ? round3(abstract.cumulativeQty) : "INCOMPLETE — unresolved BOQ credit",
          abstract.cumulativeQty == null
            ? "INCOMPLETE — unresolved BOQ credit"
            : abstract.balanceQty != null ? round3(abstract.balanceQty) : "",
          abstract.cumulativeQty == null
            ? "INCOMPLETE — unresolved BOQ credit"
            : abstract.pctComplete != null ? Number(abstract.pctComplete.toFixed(1)) : "",
          abstract.dprCount,
        ]);
        for (const e of it.entries) {
          if (e.dprDate < from || e.dprDate > to) continue;
          detailRows.push([
            e.dprDate,
            boqItemDisplayName(it.boqItem),
            e.side ?? "",
            e.chainageFrom ?? "",
            e.chainageTo ?? "",
            e.length ?? "",
            e.width ?? "",
            e.thickness ?? "",
            e.quantity ?? "",
            e.uom ?? "",
            e.boqCreditQty != null ? round4(e.boqCreditQty) : "INCOMPLETE — unresolved BOQ credit",
            it.boqItem.unit,
            e.runningCumulative != null ? round4(e.runningCumulative) : "INCOMPLETE — unresolved BOQ credit",
            `DPR-${e.dprId}`,
            e.engineer ?? "",
            [e.location, e.remarks, e.reviewFlag, ...e.conversionWarnings].filter(Boolean).join(" | "),
            e.overlaps.length ? e.overlaps.map((o) => `DPR-${o.withDprId}`).join(", ") : "",
            (e as any).isIncidental ? `Yes${(e as any).incidentalDescription ? ` — ${(e as any).incidentalDescription}` : ""}` : "",
          ]);
        }
      }
      const wb = xlsx.utils.book_new();
      const ws1 = xlsx.utils.aoa_to_sheet(summaryRows);
      ws1["!cols"] = [{ wch: 5 }, { wch: 45 }, { wch: 8 }, { wch: 14 }, { wch: 12 }, { wch: 12 }, { wch: 12 }, { wch: 12 }, { wch: 10 }, { wch: 10 }];
      const ws2 = xlsx.utils.aoa_to_sheet(detailRows);
      ws2["!cols"] = [{ wch: 11 }, { wch: 40 }, { wch: 10 }, { wch: 8 }, { wch: 8 }, { wch: 7 }, { wch: 7 }, { wch: 7 }, { wch: 12 }, { wch: 10 }, { wch: 12 }, { wch: 8 }, { wch: 14 }, { wch: 10 }, { wch: 16 }, { wch: 30 }, { wch: 16 }, { wch: 24 }];
      xlsx.utils.book_append_sheet(wb, ws1, "Summary");
      xlsx.utils.book_append_sheet(wb, ws2, "Measurement Details");
      const buf = xlsx.write(wb, { type: "buffer", bookType: "xlsx" });
      res.setHeader("Content-Type", "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet");
      res.setHeader("Content-Disposition", `attachment; filename="progress-report-${from}-to-${to}.xlsx"`);
      res.send(buf);
    } catch (err) {
      console.error("GET /api/reports/progress/export:", err);
      res.status(500).json({ error: "Failed to export progress report" });
    }
  })

