app.get("/api/boq/projects/:id/bom", async (req, res) => {
    try {
      if (!assertView(req, res, "work_programme_review")) return;
      const projectId = parseInt(req.params.id);
      const [{ items, bars, project, expandedItems, excludedCount }, projectArrangementsRaw, projectBarAllocations] = await Promise.all([
        computeProjectBom(projectId),
        storage.getEarthworkArrangements(projectId), // Instruction 025: client demand calc needs these
        storage.getArrangementProgrammeAllocationsForProject(projectId), // Instruction 026: bar-level phasing
      ]);
      // Instruction 026 §9: attach bar allocations so client + engine can phase per bar.
      const allocsByArrangement = new Map<number, Array<{ programmeBarId: number; boqItemId: number; qty: number }>>();
      for (const al of projectBarAllocations) {
        if (!allocsByArrangement.has(al.arrangementId)) allocsByArrangement.set(al.arrangementId, []);
        allocsByArrangement.get(al.arrangementId)!.push({ programmeBarId: al.programmeBarId, boqItemId: al.boqItemId, qty: Number(al.allocatedQty) || 0 });
      }
      const projectArrangements = projectArrangementsRaw.map(a => ({ ...a, programmeAllocations: allocsByArrangement.get(a.id) ?? [] }));
      const barItemIds = new Set(bars.map(b => b.boqItemId));
      const hasRecipes = expandedItems.some(it => it.materials.length > 0 || it.equipment.length > 0 || it.labour.length > 0);
      console.log(`[BOM] project=${projectId} items=${items.length} bars=${bars.length} hasRecipes=${hasRecipes} excluded=${excludedCount}`);
      res.json({
        items: expandedItems,
        bars,
        earthworkArrangements: projectArrangements,
        roadLengthKm: project?.roadLengthKm ?? 0,
        unprogrammedItemIds: items.filter(it => !barItemIds.has(it.id)).map(it => it.id),
        hasBars: bars.length > 0,
        hasItems: items.length > 0,
        hasRecipes,
        _excludedCount: excludedCount,
      });
    } catch (err) {
      console.error("GET /api/boq/projects/:id/bom:", err);
      res.status(500).json({ error: "Failed to fetch BOM data" });
    }
  })

app.get("/api/boq/projects/:id/shortage-check", async (req, res) => {
    try {
      if (!assertView(req, res, "work_programme_review")) return;
      const projectId = parseInt(req.params.id);
      const project = await storage.getBoqProject(projectId);
      if (!project) return res.status(404).json({ error: "Project not found" });

      // ── Horizon: server-authoritative — client sends mode + optional customDate ─
      const horizonModeParam = (req.query.horizonMode as string | undefined) ?? "current_month";
      const customDateParam = req.query.customDate as string | undefined;

      const [{ expandedItems, bars }, allStockBalances, allMaterialsRaw, allIndents, allIrns, materialMappings, allEarthworkArrangementsRaw, allBarAllocations] = await Promise.all([
        computeProjectBom(projectId),
        storage.getStockBalances(),
        storage.getAllPlantMaterials(),          // active + inactive — partitioned below
        storage.getPurchaseIndents(),
        storage.getInternalRequisitions(),
        storage.getMaterialMappings(projectId),
        storage.getEarthworkArrangements(projectId), // Instruction 023
        storage.getArrangementProgrammeAllocationsForProject(projectId), // Instruction 026
      ]);
      // Instruction 026 §9: attach programme-bar allocations for bar-level phasing.
      const allocsByArrId = new Map<number, Array<{ programmeBarId: number; boqItemId: number; qty: number }>>();
      for (const al of allBarAllocations) {
        if (!allocsByArrId.has(al.arrangementId)) allocsByArrId.set(al.arrangementId, []);
        allocsByArrId.get(al.arrangementId)!.push({ programmeBarId: al.programmeBarId, boqItemId: al.boqItemId, qty: Number(al.allocatedQty) || 0 });
      }
      const allEarthworkArrangements = allEarthworkArrangementsRaw.map(a => ({ ...a, programmeAllocations: allocsByArrId.get(a.id) ?? [] }));
      // Cut-to-fill by contract: BOQ item id → description lookup for detecting
      // rows whose earthwork is contractually sourced from roadway excavation.
      const boqItemDescById = new Map<number, string>();
      // PROCUREMENT CORRECTION Part D: id → operational SHORT NAME for the
      // "BOQ Work Item(s)" column. Priority: saved itemName → shared
      // short-name fallback → (client falls back to description last).
      const boqItemShortNameById = new Map<number, string>();
      for (const it of expandedItems as Array<{ id: number; description?: string | null; itemName?: string | null; itemCode?: string | null }>) {
        boqItemDescById.set(it.id, String(it.description ?? ""));
        const short = (it.itemName && String(it.itemName).trim()) || sharedShortItemName(it.description ?? "");
        boqItemShortNameById.set(it.id, short || String(it.description ?? ""));
      }
      // Cut-to-fill: batch-load current qty of any linked excavation BOQ items so
      // arrangement summaries can report cut-available vs fill-required.
      const excavationSourceIds = [...new Set(
        allEarthworkArrangements
          .map(a => (a as any).sourceExcavationBoqItemId as number | null)
          .filter((id): id is number => id != null)
      )];
      const cutQtyByBoqItemId = new Map<number, number>();
      if (excavationSourceIds.length > 0) {
        const cutRows = await db.select({ id: boqItems.id, currentQty: boqItems.currentQty })
          .from(boqItems).where(drizzleInArray(boqItems.id, excavationSourceIds));
        for (const r of cutRows) cutQtyByBoqItemId.set(r.id, Number(r.currentQty ?? 0));
      }

      // Partition: active only for resolution maps and stock lookup; inactive for diagnostics
      const allMaterials = allMaterialsRaw.filter(m => m.isActive === 1);
      const inactiveMaterials = allMaterialsRaw.filter(m => m.isActive !== 1);

      // Instruction 021: preload all active UOM conversion profiles, grouped by materialId
      const allConvProfiles = await storage.getAllMaterialUomConversions();
      const convProfilesByMaterialId = new Map<number, typeof allConvProfiles>();
      for (const p of allConvProfiles) {
        const arr = convProfilesByMaterialId.get(p.materialId) ?? [];
        arr.push(p);
        convProfilesByMaterialId.set(p.materialId, arr);
      }

      // ── materialId → HLC stock (partyId IS NULL) and elsewhere stock ────────
      // v2: keyed by materialId, NOT by name string.
      const hlcStockById = new Map<number, number>();      // partyId IS NULL
      const elsewhereStockById = new Map<number, number>(); // partyId IS NOT NULL
      for (const sb of allStockBalances) {
        if (!sb.materialId) continue;
        // Instruction 020 §7: parse as Number — numeric columns may arrive as strings via pg driver
        const bal = Number(sb.balance ?? 0);
        if (sb.partyId == null) {
          hlcStockById.set(sb.materialId, (hlcStockById.get(sb.materialId) ?? 0) + bal);
        } else {
          elsewhereStockById.set(sb.materialId, (elsewhereStockById.get(sb.materialId) ?? 0) + bal);
        }
      }

      // ── Confirmed incoming purchase — only ORDERED / PURCHASED items ─────────
      // Rule: orderedQty > 0 (set by placeOrderIndent) OR purchaseStatus ∈ {ORDERED, PURCHASED}
      // AND outstanding unreceived balance > 0. Keyed by item.materialId.
      const COMMITTED_PI_STATUSES = new Set(["ordered", "purchased"]); // lowercase
      const confirmedPiById = new Map<number, number>();
      for (const pi of allIndents) {
        if (pi.status === "rejected" || pi.status === "closed" || pi.status === "cancelled") continue;
        for (const item of pi.items ?? []) {
          const mid = (item as any).materialId as number | undefined | null;
          if (!mid) continue;
          const statusLc = (item.purchaseStatus ?? "").toLowerCase();
          // Instruction 020 §7: parse all quantities as Number — DB numeric columns may arrive as strings
          const ordQty = (item as any).orderedQty != null ? Number((item as any).orderedQty) : null;
          const isCommitted = COMMITTED_PI_STATUSES.has(statusLc) || (ordQty != null && ordQty > 0);
          if (!isCommitted) continue;
          const purchased = Number((item as any).totalPurchasedQty ?? 0);
          const committed = (ordQty ?? Number(item.approvedQty ?? item.qty ?? 0)) - purchased;
          if (committed <= 0) continue;
          confirmedPiById.set(mid, (confirmedPiById.get(mid) ?? 0) + committed);
        }
      }

      // ── Material master lookups ──────────────────────────────────────────────
      const materialIdByName = new Map<string, number>();
      for (const mat of allMaterials) {
        materialIdByName.set(mat.name.trim().toLowerCase(), mat.id);
      }

      // ── Instruction 019B §3: collision-aware alias/name resolution maps ─────────
      // Map.set() silently overwrites — we detect collisions instead.
      // resolvedAliasToId: normalized key → materialId  (exactly 1 candidate)
      // ambiguousByKey:    normalized key → candidates  (2+ candidates, cannot auto-resolve)
      type MatCandidate = { id: number; name: string; category: string | null; defaultUom: string | null };
      const keyToCandidates = new Map<string, MatCandidate[]>();
      for (const mat of allMaterials) {
        const aliasesRaw: string[] = (() => {
          try { return JSON.parse(mat.aliases ?? "[]"); } catch { return []; }
        })();
        const keys = new Set<string>([
          normalizeMaterialLabel(mat.name),
          ...aliasesRaw.map(a => normalizeMaterialLabel(a)).filter(Boolean),
        ]);
        for (const key of keys) {
          if (!key) continue;
          if (!keyToCandidates.has(key)) keyToCandidates.set(key, []);
          const cands = keyToCandidates.get(key)!;
          if (!cands.some(c => c.id === mat.id)) {
            cands.push({ id: mat.id, name: mat.name, category: mat.category ?? null, defaultUom: mat.defaultUom ?? null });
          }
        }
      }
      const resolvedAliasToId = new Map<string, number>();
      const ambiguousByKey = new Map<string, MatCandidate[]>();
      for (const [key, candidates] of keyToCandidates) {
        if (candidates.length === 1) resolvedAliasToId.set(key, candidates[0].id);
        else                          ambiguousByKey.set(key, candidates);
      }

      // ── Inactive material diagnostic map (Instruction 020 §1) ────────────────
      // Distinguishes "inactive_material" from "no_match" when auto-resolution fails.
      const inactiveKeyToName = new Map<string, string>();
      for (const mat of inactiveMaterials) {
        const normKey = normalizeMaterialLabel(mat.name);
        if (normKey) inactiveKeyToName.set(normKey, mat.name);
        const aliasesRaw: string[] = (() => { try { return JSON.parse(mat.aliases ?? "[]"); } catch { return []; } })();
        for (const alias of aliasesRaw) {
          const aKey = normalizeMaterialLabel(alias);
          if (aKey && !inactiveKeyToName.has(aKey)) inactiveKeyToName.set(aKey, mat.name);
        }
      }

      // ── Confirmed internal incoming — stores_verified IRN items with balance ─
      // Primary key: item.materialId (canonical FK). Name fallback ONLY when materialId is null.
      const confirmedIrnById = new Map<number, number>();
      for (const irn of allIrns) {
        if (irn.status !== "stores_verified") continue;
        for (const item of irn.items ?? []) {
          if (item.itemStatus !== "partially_issued" && item.itemStatus !== "pending") continue;
          const balance = (item.procureQty ?? item.qty) - (item.actualIssuedQty ?? 0);
          if (balance <= 0) continue;
          const directMid = (item as any).materialId as number | null | undefined;
          if (directMid) {
            // Canonical path: materialId present on item — use directly
            confirmedIrnById.set(directMid, (confirmedIrnById.get(directMid) ?? 0) + balance);
          } else {
            // Fallback: resolve by name (for legacy IRN items without materialId)
            const key = item.material?.trim().toLowerCase() ?? "";
            if (key) {
              const mid = materialIdByName.get(key);
              if (mid) confirmedIrnById.set(mid, (confirmedIrnById.get(mid) ?? 0) + balance);
            }
          }
        }
      }

      // ── Mapping table: BOM label → materialId + full mapping for conversion lookup ─
      // Project-specific mapping wins over global (null boqProjectId) mapping.
      const labelToMaterialId = new Map<string, number>();
      const labelToMapping = new Map<string, typeof materialMappings[0]>();
      // Load globals first (lower priority)
      for (const m of materialMappings) {
        if (m.boqProjectId == null) {
          labelToMaterialId.set(m.materialLabel, m.materialId);
          labelToMapping.set(m.materialLabel, m);
        }
      }
      // Project-specific overrides (higher priority — overwrite globals)
      for (const m of materialMappings) {
        if (m.boqProjectId != null) {
          labelToMaterialId.set(m.materialLabel, m.materialId);
          labelToMapping.set(m.materialLabel, m);
        }
      }

      // ── (a) Demand calculation ────────────────────────────────────────────────
      const demand = expandedItems.length && bars.length
        // Instruction 025: active execution arrangements reduce HLC demand
        ? calculateBomDemand(expandedItems as any, bars, project.totalMonths ?? 12, { arrangements: allEarthworkArrangements as any })
        : { materials: [], equipment: [], labour: [] };

      // ── (b) Collect all programme-month indexes ───────────────────────────────
      const allProgrammeMonths = demand.materials.flatMap(r => Object.keys(r.monthlyQty).map(Number));

      // ── (c) maxProgrammeMonth — must be declared before currentMonth ──────────
      // Fallback to project.totalMonths to avoid the circular dependency that
      // would occur if we used currentMonth as fallback (it isn't declared yet).
      const maxProgrammeMonth = allProgrammeMonths.length
        ? Math.max(...allProgrammeMonths)
        : (project.totalMonths ?? 12);

      // ── (d-e) Current project month ───────────────────────────────────────────
      // Returns 0 before programme start, contained bucket during, maxProgrammeMonth after.
      // No Math.max(1, ...) — before-start must yield 0 (Instruction 019A §2).
      const pStartDate = project.startDate ?? null;
      let currentMonth = 0;
      if (pStartDate) {
        const rawCurrent = dateToMonthIndex(new Date(), pStartDate);
        currentMonth = dateToMonthBucket(rawCurrent, maxProgrammeMonth);
      }

      // Helper: format a Date as YYYY-MM-DD ISO date string
      const toISODate = (d: Date): string => d.toISOString().split("T")[0];
      // Helper: end of programme month N = start of month N+1 minus 1 day
      const endOfProgMonth = (idx: number): string | null => {
        if (!pStartDate) return null;
        const startOfNext = monthIndexToDate(idx + 1, pStartDate);
        return toISODate(new Date(startOfNext.getTime() - 86_400_000));
      };

      type ResolvedHorizon = { horizonMonthIndex: number; resolvedHorizonDate: string | null };
      const resolveHorizon = (): ResolvedHorizon => {
        const mode = horizonModeParam as string;
        if (!pStartDate) {
          // No start date — always entire programme
          return { horizonMonthIndex: maxProgrammeMonth, resolvedHorizonDate: null };
        }
        switch (mode) {
          case "current_month": {
            const idx = Math.min(currentMonth, maxProgrammeMonth);
            return { horizonMonthIndex: idx, resolvedHorizonDate: endOfProgMonth(idx) };
          }
          case "next_30_days": {
            const cutoff = new Date(Date.now() + 30 * 24 * 60 * 60 * 1000);
            const rawIdx = dateToMonthIndex(cutoff, pStartDate);
            const idx = dateToMonthBucket(rawIdx, maxProgrammeMonth);
            return { horizonMonthIndex: idx, resolvedHorizonDate: toISODate(cutoff) };
          }
          case "next_programme_month": {
            const idx = Math.min(currentMonth + 1, maxProgrammeMonth);
            return { horizonMonthIndex: idx, resolvedHorizonDate: endOfProgMonth(idx) };
          }
          case "custom": {
            if (customDateParam) {
              const cutoff = new Date(customDateParam);
              const rawIdx = dateToMonthIndex(cutoff, pStartDate);
              const idx = dateToMonthBucket(rawIdx, maxProgrammeMonth);
              return { horizonMonthIndex: idx, resolvedHorizonDate: customDateParam };
            }
            // No custom date provided — fall through to entire_programme
            return { horizonMonthIndex: maxProgrammeMonth, resolvedHorizonDate: null };
          }
          case "entire_programme":
          default:
            return { horizonMonthIndex: maxProgrammeMonth, resolvedHorizonDate: null };
        }
      };

      const { horizonMonthIndex, resolvedHorizonDate } = resolveHorizon();

      // ── Build shortage rows (019B §4 + §7) ───────────────────────────────────
      const shortageRows = demand.materials.map(matRow => {
        // Resolve canonical materialId — strict precedence (019B §4):
        // 1. Saved BOQ-material mapping (project-specific > global)
        // 2. Exact approved alias or exact normalized canonical name (collision-aware)
        // No substring / loose auto-resolution.
        const labelKey = matRow.materialName.trim().toLowerCase();
        const normLabel = normalizeMaterialLabel(matRow.materialName);

        const savedMapping = labelToMapping.get(matRow.materialName) ?? labelToMapping.get(labelKey);
        const mappedId: number | null = savedMapping?.materialId ?? null;

        // Auto-resolve by exact alias or normalized name (only when no saved mapping)
        const rawAliasOrNameMatchId: number | null = mappedId == null
          ? (resolvedAliasToId.get(normLabel) ?? materialIdByName.get(labelKey) ?? null)
          : null;

        // ── Instruction 021 §1: UOM compatibility check for auto-resolved material ─
        // Material identity is preserved even when UOM conversion is not yet configured.
        // uomIncompatible = true only sets resolutionReason → "uom_incompatible" →
        // procurementStatus → "uom_resolution_required"; it no longer suppresses materialId.
        let aliasOrNameMatchId: number | null = rawAliasOrNameMatchId;
        let uomIncompatible = false;
        let autoConvFactor: number = 1;
        let autoConvMode: string | null = null;
        let autoConvBasis: string | null = null;
        let autoConvProfileId: number | null = null;
        let resolutionDiagnostic: { inactiveMaterialName?: string; bomUom?: string; masterUom?: string | null; materialName?: string; message?: string; action?: string } = {};

        if (rawAliasOrNameMatchId != null && matRow.uom) {
          const candidateMat = allMaterials.find(m => m.id === rawAliasOrNameMatchId);
          if (candidateMat) {
            const matProfiles = convProfilesByMaterialId.get(rawAliasOrNameMatchId) ?? [];
            const uomCheck = checkMappingUomCompatibility(matRow.uom, candidateMat, matProfiles);
            if (!uomCheck.compatible) {
              uomIncompatible = true;
              // 021: Do NOT suppress aliasOrNameMatchId — material identity still resolves.
              // The "uom_resolution_required" procurementStatus will block stock comparison.
              resolutionDiagnostic = {
                bomUom: matRow.uom,
                masterUom: candidateMat.defaultUom ?? null,
                materialName: candidateMat.name,
              };
            } else {
              autoConvFactor = uomCheck.conversionFactor ?? 1;
              autoConvMode = uomCheck.mode;
              autoConvBasis = uomCheck.basis;
              autoConvProfileId = uomCheck.conversionProfileId ?? null;
            }
          }
        }

        // Ambiguity — only when no saved mapping, no alias/name match, and not UOM-blocked
        const ambiguousCandidates: MatCandidate[] | null =
          (mappedId == null && aliasOrNameMatchId == null && !uomIncompatible)
            ? (ambiguousByKey.get(normLabel) ?? null)
            : null;
        const materialMappingAmbiguous = ambiguousCandidates != null && ambiguousCandidates.length > 0;

        const resolvedId: number | null = mappedId ?? aliasOrNameMatchId ?? null;
        // Unresolved: no saved mapping, alias/name blocked (UOM or not found), or ambiguous
        const materialMappingUnresolved = resolvedId == null;

        // ── Resolution reason (Instruction 020 §1) ──────────────────────────────
        let resolutionReason: ResolutionReason;
        if (mappedId != null) {
          resolutionReason = "saved_mapping";
        } else if (uomIncompatible) {
          resolutionReason = "uom_incompatible";
        } else if (aliasOrNameMatchId != null) {
          resolutionReason = "alias_resolved";
        } else if (materialMappingAmbiguous) {
          resolutionReason = "ambiguous";
        } else {
          // Distinguish inactive_material from no_match for targeted UI guidance
          const inactiveName = inactiveKeyToName.get(normLabel) ?? inactiveKeyToName.get(labelKey) ?? null;
          if (inactiveName) {
            resolutionReason = "inactive_material";
            resolutionDiagnostic = { inactiveMaterialName: inactiveName };
          } else {
            resolutionReason = "no_match";
            resolutionDiagnostic = { message: "No canonical material match was found.", action: "Review Material Master" };
          }
        }

        // ── 021 §12-13: Conversion factor and planning-UOM normalization ──────
        // Precedence: (1) saved mapping factor, (2) auto-resolved profile/bulk-density factor.
        // Factor meaning: 1 BOQ unit × convFactor = 1 stock unit  (e.g. 1 Cum × 2.20 = 2.20 MT).
        // Approach: keep demand in planning/BOQ UOM; convert stock DOWN to planning UOM (÷ factor).
        // This shows shortfall in the user's BOQ unit; add procurementEquivalentQty for stock UOM.
        const convFactor: number = savedMapping?.conversionFactorUsed ?? autoConvFactor;
        const convMode: string | null = savedMapping?.conversionMode ?? autoConvMode;
        const convSourceUom: string | null = savedMapping?.sourceUom ?? (convFactor !== 1 ? matRow.uom : null);
        const convProfileId: number | null = (savedMapping as any)?.conversionProfileId ?? autoConvProfileId;
        const resolvedMat = resolvedId != null ? allMaterials.find(m => m.id === resolvedId) : null;
        const canonicalUom: string | null = resolvedMat?.defaultUom ?? null;
        let conversionBasis: string | null = autoConvBasis ?? null;
        if (convFactor !== 1 && convSourceUom && canonicalUom && !conversionBasis) {
          conversionBasis = convMode === "bulk_density"
            ? `Bulk density: 1 ${convSourceUom} = ${convFactor} ${canonicalUom}`
            : `1 ${convSourceUom} = ${convFactor} ${canonicalUom}`;
        }

        // Demand stays in BOQ/planning UOM (no scaling).
        const scaledMatRow = matRow;

        // Stock is stored in canonical/stock UOM; divide by convFactor to get planning UOM coverage.
        // When uomIncompatible and no conversion found (uomBlocked), zero out stock so we don't
        // compare incompatible units (the UOM-resolution-required status will be shown instead).
        const uomBlocked = uomIncompatible && convFactor === 1;
        const invFactor = convFactor !== 1 ? 1 / convFactor : 1;
        const hlcRecordedStock = resolvedId != null && !uomBlocked
          ? Math.round((hlcStockById.get(resolvedId) ?? 0) * invFactor * 1000) / 1000
          : 0;
        const stockWithOtherParties = resolvedId != null && !uomBlocked
          ? Math.round((elsewhereStockById.get(resolvedId) ?? 0) * invFactor * 1000) / 1000
          : 0;
        const confirmedIncomingPurchase = resolvedId != null && !uomBlocked
          ? Math.round((confirmedPiById.get(resolvedId) ?? 0) * invFactor * 1000) / 1000
          : 0;
        const confirmedInternalIncoming = resolvedId != null && !uomBlocked
          ? Math.round((confirmedIrnById.get(resolvedId) ?? 0) * invFactor * 1000) / 1000
          : 0;
        const stockMatched = resolvedId != null && (hlcRecordedStock > 0 || stockWithOtherParties > 0);

        // sourceBoqItemId: non-null only when all breakdown entries trace to a single BOQ item
        const distinctBoqItemIds: number[] = [...new Set<number>(
          ((matRow as any).breakdown as Array<{ boqItemId?: number | null }> ?? [])
            .map(bd => bd.boqItemId)
            .filter((id): id is number => id != null)
        )];
        const sourceBoqItemId = distinctBoqItemIds.length === 1 ? distinctBoqItemIds[0] : null;
        const matProgrammingStatus = (matRow as any).programmingStatus as
          | "fully_programmed" | "partly_programmed" | "not_programmed" | undefined;
        const hasProgrammeBars = matProgrammingStatus !== "not_programmed";

        // Instruction 023: earthwork bulk detection from BOM row flag
        const isEarthworkBulkRequirement = !!(matRow as any).isEarthworkBulkRequirement;
        // Instruction 028A: category-generic arrangement marker stamped by the engine
        // (bituminous rows whose source items carry EFFECTIVE bituminous arrangements),
        // OR any non-cancelled bituminous arrangement on a source item — proposed
        // (draft/submitted/returned) arrangements must surface context in Procurement
        // even though they have no demand effect yet.
        const isBituminousArrangedRow = (matRow as any).arrangementWorkCategory === "bituminous"
          || (!(matRow as any).isEarthworkBulkRequirement && allEarthworkArrangements.some(a => {
            if (a.status === "cancelled" || a.status === "rejected") return false;
            if ((a as any).workCategory !== "bituminous") return false;
            if (a.boqItemId != null && distinctBoqItemIds.includes(a.boqItemId)) return true;
            const allocs = a.boqItemAllocations as Array<{ boqItemId: number }> | null;
            return Array.isArray(allocs) && allocs.some(al => distinctBoqItemIds.includes(al.boqItemId));
          }));
        const hasArrangementContext = isEarthworkBulkRequirement || isBituminousArrangedRow;
        // 028A §3/§7: company-retained fraction from engine's split — forwarded, never recalculated.
        const rowArrHlcQty = (matRow as any).arrangementHlcQty as number | undefined;
        const arrangementCompanyFraction = isBituminousArrangedRow && rowArrHlcQty != null && matRow.totalQty > 0
          ? Math.max(0, Math.min(1, rowArrHlcQty / matRow.totalQty))
          : undefined;

        // Cut-to-fill by contract: any source BOQ item whose description ties the
        // earthwork to roadway excavation (never borrow) → UI pre-selects the cut source.
        const contractCutToFill = isEarthworkBulkRequirement && distinctBoqItemIds.some(id =>
          isContractCutToFillDescription(boqItemDescById.get(id)),
        );

        const enrichedMatRow = { ...scaledMatRow, materialId: resolvedId, sourceBoqItemId };
        const shortageRow = computeShortageRow(
          enrichedMatRow,
          hlcRecordedStock,
          stockMatched,
          confirmedIncomingPurchase,
          currentMonth,
          stockWithOtherParties,
          {
            horizonMonthIndex,
            projectStartDate: project.startDate ?? null,
            hlcRecordedStock,
            stockWithOtherParties,
            confirmedIncomingPurchase,
            confirmedInternalIncoming,
            isProgrammed: hasProgrammeBars,
            materialMappingUnresolved,
            programmingStatus: matProgrammingStatus,
            programmedTotalDemand: (scaledMatRow as any).programmedTotalDemand as number | undefined,
            unprogrammedDemand: (scaledMatRow as any).unprogrammedDemand as number | undefined,
            sourceBoqItemIds: distinctBoqItemIds,
            resolutionReason,  // Instruction 020 §3: drives procurementStatus in planningEngine
            isEarthworkBulkRequirement, // Instruction 023
            requiresClassification: !!(matRow as any).requiresClassification, // Instruction 024
            ...(arrangementCompanyFraction != null ? { arrangementCompanyFraction } : {}), // 028A §3
          },
        );

        // Instruction 023/024: attach arrangement summaries for earthwork rows.
        // Use ALL distinctBoqItemIds (not just sourceBoqItemId) so multi-source rows
        // (e.g. Embankment Reach 1 + Reach 2 + Shoulder → "Earth / Borrow Soil") also
        // show their arrangements.
        let earthworkArrangementSummaries: import("@shared/planningEngine").EarthworkArrangementSummary[] | undefined;
        if (hasArrangementContext && distinctBoqItemIds.length > 0) {
          const rawArrs = allEarthworkArrangements.filter(a => {
            if (a.status === "cancelled") return false;
            // Single-BOQ arrangement
            if (a.boqItemId != null && distinctBoqItemIds.includes(a.boqItemId)) return true;
            // Multi-BOQ arrangement (boqItemAllocations JSONB)
            const allocs = a.boqItemAllocations as Array<{ boqItemId: number; qty: number }> | null;
            if (Array.isArray(allocs) && allocs.some(al => distinctBoqItemIds.includes(al.boqItemId))) return true;
            return false;
          });
          earthworkArrangementSummaries = rawArrs.map(a => {
            const allocQty = Number(a.allocatedQty ?? 0);
            const rate = a.agreedRate != null ? Number(a.agreedRate) : null;
            return {
              id: a.id,
              arrangementType: a.arrangementType,
              status: a.status,
              agencyName: a.agencyName ?? null,
              allocatedQty: allocQty,
              uom: a.uom,
              agreedRate: rate,
              tripRates: a.tripRates ?? null,
              billingTerms: a.billingTerms ?? null,
              estimatedValue: rate != null ? Math.round(allocQty * rate) : null,
              plannedDailyOutput: a.plannedDailyOutput != null ? Number(a.plannedDailyOutput) : null,
              mobilisationDate: (a as any).mobilisationDate ?? null,
              plannedStartDate: a.plannedStartDate ?? null,
              actualStartDate: (a as any).actualStartDate ?? null,
              targetCompletionDate: a.targetCompletionDate ?? null,
              reachLabel: a.reachLabel ?? null,
              components: (a.components as Record<string, string> | null) ?? null,
              completedQty: 0,      // progress loaded lazily by detail route
              recentDailyOutput: 0,
              lastEntryDate: null,
              daysSinceLastEntry: null,
              boqItemAllocations: (a.boqItemAllocations as Array<{ boqItemId: number; qty: number }> | null) ?? null,
              boqItemId: a.boqItemId ?? null,
              sourceExcavationBoqItemId: (a as any).sourceExcavationBoqItemId ?? null,
              cutAvailableQty: (a as any).sourceExcavationBoqItemId != null
                ? (cutQtyByBoqItemId.get((a as any).sourceExcavationBoqItemId) ?? null)
                : null,
              // Instruction 026: bar linkage state for Work Programme / Procurement display
              programmeAllocations: (a as any).programmeAllocations ?? [],
              barLinkedQty: ((a as any).programmeAllocations ?? []).reduce((s: number, al: any) => s + (Number(al.qty) || 0), 0),
              pendingRevision: (a as any).pendingRevision ?? null,
            };
          });
        }

        // Instruction 026 §15: timing source — bar-level programme vs legacy BOQ-level.
        let arrangementTimingSource: "bar_level" | "boq_level_legacy" | undefined;
        if (hasArrangementContext && earthworkArrangementSummaries?.length) {
          const activeArrs = earthworkArrangementSummaries.filter(a =>
            ["approved", "mobilisation_pending", "in_progress", "on_hold"].includes(String(a.status)));
          if (activeArrs.length > 0) {
            const anyLegacy = activeArrs.some(a => {
              const linked = (a as any).barLinkedQty ?? 0;
              return Number(a.allocatedQty) - linked > 0.001;
            });
            arrangementTimingSource = anyLegacy ? "boq_level_legacy" : "bar_level";
          }
        }

        // 021 §13: procurement equivalent — shortfall in stock/canonical UOM (e.g. MT)
        // = planning shortfall × convFactor. Shown alongside planning shortfall in UI.
        const procurementEquivalentQty = convFactor !== 1 && !uomBlocked
          ? Math.round(shortageRow.actionableShortfall * convFactor * 1000) / 1000
          : null;
        const procurementEquivalentUom = convFactor !== 1 && !uomBlocked ? canonicalUom : null;

        return {
          ...shortageRow,
          // PROCUREMENT CORRECTION Part D/E: contributing BOQ items resolved to
          // short names. Per-item contributed quantities are NOT invented —
          // only ids + names until the engine provides a real breakdown.
          sourceBoqItems: distinctBoqItemIds.map(id => ({
            id,
            name: boqItemShortNameById.get(id) ?? `BOQ #${id}`,
          })),
          ...(materialMappingAmbiguous ? { materialMappingAmbiguous: true, ambiguousCandidates } : {}),
          resolvedVia: mappedId ? "mapping" as const : (aliasOrNameMatchId ? "alias" as const : null),
          ...(conversionBasis ? { conversionBasis, canonicalUom, conversionProfileId: convProfileId } : {}),
          ...(procurementEquivalentQty != null ? { procurementEquivalentQty, procurementEquivalentUom } : {}),
          ...(Object.keys(resolutionDiagnostic).length > 0 ? { resolutionDiagnostic } : {}),
          // Instruction 023/024: earthwork arrangement context
          // isEarthworkBulkRequirement = arrangement flow (already classified as earthwork).
          // requiresClassification    = classification flow (gravel/moorum not yet routed).
          // Both need earthworkBoqItemId/earthworkSourceBoqItemIds so EarthworkControl can
          // find the BOQ item to classify or manage arrangements.
          ...(isEarthworkBulkRequirement ? {
            earthworkBoqItemId: sourceBoqItemId,  // null for multi-source rows (use sourceBoqItemIds)
            earthworkSourceBoqItemIds: distinctBoqItemIds,  // always present for earthwork rows
            earthworkArrangements: earthworkArrangementSummaries ?? [],
            ...(contractCutToFill ? { contractCutToFill: true } : {}),
            // Instruction 025 §12: physical vs outsourced vs HLC split for the row
            ...((matRow as any).arrangementOutsourcedQty != null ? {
              arrangementOutsourcedQty: (matRow as any).arrangementOutsourcedQty,
              arrangementHlcQty: (matRow as any).arrangementHlcQty,
            } : {}),
            // Instruction 026 §15: whether exclusion timing follows the programme bars
            ...(arrangementTimingSource ? { arrangementTimingSource } : {}),
          } : {}),
          // Instruction 028A §14: category-generic arrangement fields. Earthwork rows keep
          // every legacy field above untouched; bituminous rows get the same context under
          // generic names so Procurement can present execution effects without guessing.
          ...(hasArrangementContext ? {
            workCategory: isBituminousArrangedRow ? "bituminous" as const : "earthwork" as const,
            executionArrangements: earthworkArrangementSummaries ?? [],
            arrangementSourceBoqItemIds: distinctBoqItemIds,
            ...(arrangementTimingSource ? { arrangementTimingSource } : {}),
            ...((matRow as any).arrangementOutsourcedQty != null ? {
              arrangementAgencyQty: (matRow as any).arrangementOutsourcedQty,
              arrangementCompanyQty: (matRow as any).arrangementHlcQty,
              // legacy aliases retained for existing consumers
              arrangementOutsourcedQty: (matRow as any).arrangementOutsourcedQty,
              arrangementHlcQty: (matRow as any).arrangementHlcQty,
            } : {}),
            // Row-scoped mapping warnings (project-level list stays on the response root)
            rowMappingWarnings: ((demand as any).mappingWarnings ?? []).filter(
              (w: any) => distinctBoqItemIds.includes(w.boqItemId),
            ),
          } : {}),
          ...(shortageRow.requiresClassification && !isEarthworkBulkRequirement && distinctBoqItemIds.length > 0 ? {
            // Classification-required rows are gravel/moorum (isEarthworkBulkRequirement = false),
            // so the earthwork block above did not fire. Attach BOQ item identity here so
            // EarthworkControl can invoke the bulk-classification endpoint.
            earthworkBoqItemId: distinctBoqItemIds.length === 1 ? distinctBoqItemIds[0] : null,
            earthworkSourceBoqItemIds: distinctBoqItemIds,
          } : {}),
        };
      });

      // Sort: unresolved/ambiguous first, then by actionableShortfall desc, then totalDemand desc
      shortageRows.sort((a, b) => {
        const aTop = (a as any).materialMappingUnresolved || (a as any).materialMappingAmbiguous;
        const bTop = (b as any).materialMappingUnresolved || (b as any).materialMappingAmbiguous;
        if (aTop !== bTop) return aTop ? -1 : 1;
        return (b.actionableShortfall - a.actionableShortfall) || (b.totalDemand - a.totalDemand);
      });

      // Instruction 019C §2: derive programme relation from actual dates, not clamped
      // currentMonth (which cannot distinguish "in last month" from "after programme end").
      // pStartDate and maxProgrammeMonth are already defined above; no horizon math touched.
      let programmeRelation: "before_start" | "within_programme" | "after_end" = "within_programme";
      if (pStartDate) {
        const today = new Date();
        const progStart = new Date(pStartDate);
        // Programme end = first day of the month AFTER the last programme month.
        // e.g. starts Jan 1, maxProgrammeMonth=6 → end = Jul 1 → Jun 30 is within_programme.
        const progEnd = new Date(progStart);
        progEnd.setMonth(progEnd.getMonth() + maxProgrammeMonth);
        if (today < progStart) {
          programmeRelation = "before_start";
        } else if (today >= progEnd) {
          programmeRelation = "after_end";
        }
        // else: within_programme (default, covers today in the final month)
      }

      res.json({
        projectId,
        projectName: project.name,
        projectStartDate: project.startDate ?? null,
        rows: shortageRows,
        hasBars: bars.length > 0,
        hasRecipes: expandedItems.some(it => it.materials.length > 0),
        currentMonth,
        horizonMonthIndex,
        maxProgrammeMonth,
        selectedHorizonMode: horizonModeParam,
        resolvedHorizonDate,
        resolvedProgrammeMonthIndex: horizonMonthIndex,
        programmeRelation,
        // Instruction 025 §13: why demand numbers changed (arrangement exclusions)
        demandAdjustments: (demand as any).demandAdjustments ?? [],
        arrangementOverlaps: (demand as any).arrangementOverlaps ?? [],
        // Instruction 028 §22: non-company components with no recipe resource to exclude
        mappingWarnings: (demand as any).mappingWarnings ?? [],
      });
    } catch (err) {
      console.error("GET /api/boq/projects/:id/shortage-check:", err);
      // Return a structured, safe error — no stack traces or secrets exposed to the client.
      const detail = err instanceof Error ? err.message : String(err);
      res.status(500).json({ error: "Failed to compute shortage check", detail });
    }
  })

