app.put("/api/boq/projects/:id/cut-fill-reconciliation/activation", async (req, res) => {
    const projectId = Number(req.params.id);
    if (!await assertCutFillProjectAccess(req, res, projectId, true)) return;
    const activationDate = req.body?.activationDate;
    if (activationDate != null && (typeof activationDate !== "string" || !/^\d{4}-\d{2}-\d{2}$/.test(activationDate))) {
      return res.status(400).json({ message: "activationDate must be YYYY-MM-DD or null." });
    }
    await db.update(boqProjectsTable).set({ cutFillReconciliationActivatedOn: activationDate ?? null })
      .where(eq(boqProjectsTable.id, projectId));
    await (storage as any).logAudit({ module: "cut_fill_reconciliation", transactionId: projectId, action: "activation_updated", userId: req.authUser?.id, userName: currentUserName(req), newValues: { activationDate: activationDate ?? null } });
    res.json({ activationDate: activationDate ?? null });
  })

app.put("/api/boq/projects/:id/cut-fill-opening-balances/:sourceBoqItemId", async (req, res) => {
    const projectId = Number(req.params.id), sourceBoqItemId = Number(req.params.sourceBoqItemId), quantity = Number(req.body?.quantity);
    if (!await assertCutFillProjectAccess(req, res, projectId, true)) return;
    if (!Number.isInteger(sourceBoqItemId) || sourceBoqItemId <= 0 || !Number.isFinite(quantity) || quantity < 0) {
      return res.status(400).json({ message: "A source BOQ item and non-negative quantity are required." });
    }
    const [sourceItem] = await db.select({ description: boqItems.description, unit: boqItems.unit })
      .from(boqItems).where(and(eq(boqItems.id, sourceBoqItemId), eq(boqItems.boqProjectId, projectId)));
    if (!sourceItem || classifyWorkType(sourceItem.description ?? "", sourceItem.unit ?? "") !== "roadway_excavation") {
      return res.status(400).json({ message: "Opening balance source must be a roadway excavation BOQ item in this project." });
    }
    const result = await db.execute(sql`
      INSERT INTO cut_fill_opening_balances (boq_project_id, source_excavation_boq_item_id, quantity, uom, remarks, confirmed_by_user_id, updated_at)
      VALUES (${projectId}, ${sourceBoqItemId}, ${quantity}, 'CUM', ${typeof req.body?.remarks === "string" ? req.body.remarks.trim() : null}, ${req.authUser?.id ?? null}, NOW())
      ON CONFLICT (boq_project_id, source_excavation_boq_item_id)
      DO UPDATE SET quantity = EXCLUDED.quantity, remarks = EXCLUDED.remarks, confirmed_by_user_id = EXCLUDED.confirmed_by_user_id, confirmed_at = NOW(), updated_at = NOW()
      RETURNING *
    `);
    await (storage as any).logAudit({ module: "cut_fill_opening_balance", transactionId: sourceBoqItemId, action: "upsert", userId: req.authUser?.id, userName: currentUserName(req), newValues: result.rows[0] });
    res.json(result.rows[0]);
  })

app.get("/api/boq/projects/:id/cut-fill-sources", async (req, res) => {
    const projectId = Number(req.params.id);
    if (!await assertCutFillProjectAccess(req, res, projectId)) return;
    const rows = await db.execute(sql`
      SELECT p.id, p.entry_key AS "entryKey", p.boq_item_id AS "boqItemId", p.activity, p.uom,
        b.description AS "sourceItemDescription", p.reusable_qty AS "reusableQty", d.date,
        COALESCE((SELECT SUM(c.quantity) FROM cut_fill_consumptions c JOIN progress_entries fp ON fp.id = c.fill_progress_entry_id JOIN dprs fd ON fd.id = fp.dpr_id
          WHERE c.source_progress_entry_id = p.id AND fd.dpr_status = 'submitted' AND COALESCE(fd.is_superseded,false)=false AND COALESCE(fd.is_deleted,false)=false AND COALESCE(fd.is_cancelled,false)=false),0) AS "consumedQty"
      FROM progress_entries p JOIN dprs d ON d.id = p.dpr_id JOIN boq_items b ON b.id = p.boq_item_id JOIN boq_projects bp ON bp.id = d.boq_project_id
      WHERE d.boq_project_id = ${projectId} AND d.dpr_status = 'submitted' AND COALESCE(d.is_superseded,false)=false AND COALESCE(d.is_deleted,false)=false AND COALESCE(d.is_cancelled,false)=false
        AND bp.cut_fill_reconciliation_activated_on IS NOT NULL AND d.date >= bp.cut_fill_reconciliation_activated_on
        AND p.material_outcome IS NOT NULL
      ORDER BY d.date, p.id
    `);
    res.json({ sources: (rows.rows as any[]).map(r => ({ ...r, availableQty: Math.max(0, Number(r.reusableQty ?? 0) - Number(r.consumedQty ?? 0)) })) });
  })

app.post("/api/boq/projects/:id/earthwork-arrangements", async (req, res) => {
    try {
      if (!assertAuthed(req, res)) return;
      if (!assertEdit(req, res, "work_programme")) return;

      // ── Schema readiness guard ────────────────────────────────────────────
      if (!earthworkSchemaReady) {
        return res.status(503).json({
          error: "EARTHWORK_SCHEMA_NOT_READY",
          message: "Earthwork database setup has not completed yet. Please wait a moment and retry.",
        });
      }

      const projectId = parseInt(req.params.id);
      const user = (req as any).authUser ?? (req as any).user;
      const body = req.body ?? {};
      const tripRatesResult = arrangementTripRatesSchema.safeParse(body.tripRates ?? null);
      const termsResult = arrangementBillingTermsSchema.nullable().safeParse(body.billingTerms ?? null);
      if (!termsResult.success) return res.status(400).json({ error: "INVALID_BILLING_TERMS", message: termsResult.error.issues[0].message });
      if (!tripRatesResult.success) return res.status(400).json({
        error: "INVALID_TRIP_RATES", message: tripRatesResult.error.issues[0].message,
      });
      // Capture the scope read before any arrangement validation. The create
      // transaction rechecks this token after taking the project mutex, so a
      // correction committed while this request was validating cannot result
      // in a stale arrangement insert.
      const scopeVersionToken = await storage.getProjectScopeVersionToken(projectId);

      const { materialLabel, arrangementType } = body;
      // saveIntent: "draft" = Save Draft; "submit" = Submit for Approval (single request, no second PATCH)
      const saveIntent: "draft" | "submit" = body.saveIntent === "submit" ? "submit" : "draft";
      // boqItemAllocations supersedes boqItemId for multi-source arrangements
      const boqItemAllocationsRaw = body.boqItemAllocations as Array<{ boqItemId: number; qty: number }> | undefined;
      const singleBoqItemId: number | null = body.boqItemId ? Number(body.boqItemId) : null;

      // ── Typed validation ──────────────────────────────────────────────────
      if (!materialLabel || !String(materialLabel).trim()) {
        return res.status(400).json({ error: "VALIDATION_FAILED", message: "materialLabel is required." });
      }

      const allocatedQtyNum = Number(body.allocatedQty);
      if (body.allocatedQty == null || isNaN(allocatedQtyNum) || allocatedQtyNum <= 0) {
        return res.status(400).json({
          error: "INVALID_ALLOCATED_QUANTITY",
          message: "Allocated quantity must be a positive number.",
        });
      }

      // Date format guard (YYYY-MM-DD or null)
      const dateRe = /^\d{4}-\d{2}-\d{2}$/;
      const plannedStart = body.plannedStartDate ?? null;
      const targetEnd = body.targetCompletionDate ?? null;
      if (plannedStart && !dateRe.test(plannedStart))
        return res.status(400).json({ error: "INVALID_DATE_RANGE", message: "plannedStartDate must be YYYY-MM-DD" });
      if (targetEnd && !dateRe.test(targetEnd))
        return res.status(400).json({ error: "INVALID_DATE_RANGE", message: "targetCompletionDate must be YYYY-MM-DD" });
      if (plannedStart && targetEnd && targetEnd < plannedStart)
        return res.status(400).json({ error: "INVALID_DATE_RANGE", message: "targetCompletionDate cannot precede plannedStartDate" });

      // ── Instruction 031 B3: authoritative Scope linkage (validated first —
      // a reach-linked arrangement is exempt from the raw-chainage guard below,
      // because its internal no-scope/withdrawn intervals are clipped by the
      // eligibility engine instead of blocking the whole selection).
      const scopeCheckResult = await validateArrangementScopeSegments(projectId, body.scopeSegmentIds);
      if (!scopeCheckResult.ok) return res.status(scopeCheckResult.status).json(scopeCheckResult.body);
      const scopeSegmentIdsValue = scopeCheckResult.ids;

      // ── Instruction 032 Part M (light): block arrangements over permanently
      // excluded / withdrawn scope, unless the record is historical (the
      // arrangement's chainage predates the withdrawal's effective date via
      // evaluateDprScope's date gate). Temporary blocks do NOT block — the
      // arrangement may be preparation for after the block lifts.
      if (scopeSegmentIdsValue == null) {
        const arrChF = body.chainageFrom != null ? Number(body.chainageFrom) : null;
        const arrChT = body.chainageTo != null ? Number(body.chainageTo) : null;
        if (arrChF != null && arrChT != null && Number.isFinite(arrChF) && Number.isFinite(arrChT) && arrChT > arrChF) {
          const rawSegs = await storage.getProjectScopeSegments(projectId);
          const segs: ScopeSegmentLike[] = (rawSegs as any[]).map(x => ({
            id: x.id, segmentType: x.segmentType, chainageFrom: Number(x.chainageFrom), chainageTo: Number(x.chainageTo),
            side: x.side, status: x.status, applicability: x.applicability,
            categoryIds: safeIdList(x.categoryIds),
            itemIds: safeIdList(x.itemIds),
            effectiveFrom: x.effectiveFrom, effectiveTo: x.effectiveTo, label: x.label, reason: x.reason,
          }));
          if (segs.some(s => s.segmentType === "working_reach" && (s.status ?? "confirmed") === "confirmed")) {
            const arrItemId = singleBoqItemId ?? ((Array.isArray(boqItemAllocationsRaw) && boqItemAllocationsRaw[0]?.boqItemId) || null);
            const arrItem: any = arrItemId ? await storage.getBoqItem(Number(arrItemId)) : null;
            const scopeCheck = evaluateDprScope(segs, {
              boqItemId: arrItemId != null ? Number(arrItemId) : null,
              categoryId: arrItem?.categoryId ?? null,
              isLinear: true,
              side: body.side ?? null,
              chainageFromKm: arrChF,
              chainageToKm: arrChT,
              dprDate: plannedStart ?? null,
            });
            if (scopeCheck.status === "no_scope" || scopeCheck.status === "withdrawn") {
              return res.status(422).json({
                error: "SCOPE_BLOCKED",
                message: `This chainage is outside the project's executable scope (${scopeCheck.status === "withdrawn" ? "withdrawn" : "no scope"}). ${scopeCheck.message ?? ""}`.trim(),
              });
            }
          }
        }
      }

      // Submit-specific validation — arrangement type must be confirmed before submitting
      if (saveIntent === "submit" && (!arrangementType || arrangementType === "not_decided")) {
        return res.status(400).json({
          error: "SUBMIT_VALIDATION_FAILED",
          message: "Arrangement type must be selected before submitting for approval. 'Not Decided' is only valid for drafts.",
        });
      }

      // ── Instruction 028 §35 — category validation ─────────────────────────
      const workCategory: string = body.workCategory ?? "earthwork";
      if (!isValidWorkCategory(workCategory)) {
        return res.status(400).json({ error: "INVALID_WORK_CATEGORY", message: `Unsupported work category '${workCategory}'. Supported: earthwork, bituminous.` });
      }
      if (arrangementType && arrangementType !== "not_decided" && !isArrangementTypeAllowed(workCategory, arrangementType)) {
        return res.status(400).json({ error: "INVALID_ARRANGEMENT_TYPE", message: `Arrangement type '${arrangementType}' is not valid for ${workCategory} works.` });
      }
      const badKeys = invalidComponentKeys(workCategory, body.components ?? null);
      if (badKeys.length > 0) {
        return res.status(400).json({ error: "INVALID_COMPONENT_KEYS", message: `Component keys not allowed for ${workCategory}: ${badKeys.join(", ")}` });
      }
      const bituminousItemType = body.bituminousItemType ?? null;
      if (bituminousItemType != null && !isValidBituminousItemType(bituminousItemType)) {
        return res.status(400).json({ error: "INVALID_BITUMINOUS_ITEM_TYPE", message: `Unknown bituminous item type '${bituminousItemType}'.` });
      }
      if (workCategory !== "bituminous" && bituminousItemType != null) {
        return res.status(400).json({ error: "INVALID_BITUMINOUS_ITEM_TYPE", message: "bituminousItemType applies only to bituminous arrangements." });
      }
      // 028A §13 (Part D safe fallback): Shared responsibility is not yet carried through
      // demand proration, so NEW Shared components are blocked outright — a stored split
      // would silently behave as 100% company-retained. Existing stored records are preserved.
      if (body.components && typeof body.components === "object") {
        const sharedKeys = Object.entries(body.components as Record<string, string>).filter(([, v]) => v === "shared").map(([k]) => k);
        if (sharedKeys.length > 0) {
          return res.status(400).json({ error: "SHARED_NOT_AVAILABLE", message: `Shared responsibility percentage entry is not yet available (component${sharedKeys.length > 1 ? "s" : ""} '${sharedKeys.join("', '")}'). Choose Company, Agency or Client for now.` });
        }
      }

      // Agency required for outsourced types (category-driven)
      const needsAgency = workCategory === "bituminous"
        ? (getCategoryDescriptor("bituminous").outsourcedTypes.has(arrangementType) || arrangementType === "partly_outsourced")
        : ["fully_outsourced_composite","vendor_material_delivered","hlc_source_outsourced_execution","partly_outsourced"].includes(arrangementType);
      if (needsAgency && !body.agencyName?.trim()) {
        return res.status(400).json({ error: "AGENCY_REQUIRED", message: "Agency / Vendor name is required for outsourced arrangements." });
      }

      // ── Instruction 028 §35 — category eligibility vs linked BOQ item(s) ──
      // A bituminous arrangement may only be raised against items that resolve
      // to the bituminous category (auto-detected or manual override); and an
      // earthwork arrangement must never target a bituminous-classified item.
      {
        const sourceItemIds: number[] = boqItemAllocationsRaw && Array.isArray(boqItemAllocationsRaw)
          ? boqItemAllocationsRaw.filter(a => a.boqItemId && Number(a.qty) > 0).map(a => Number(a.boqItemId))
          : (singleBoqItemId ? [singleBoqItemId] : []);
        for (const itemId of sourceItemIds) {
          const [srcItem] = await db.select({
            description: boqItems.description, unit: boqItems.unit,
            itemWorkCategory: boqItems.workCategory,
            bulkMaterialClassification: boqItems.bulkMaterialClassification,
          }).from(boqItems).where(eq(boqItems.id, itemId));
          if (!srcItem) continue; // existence is validated by the allocation guard below
          const resolved = executionArrangementCategoryForItem({
            description: srcItem.description ?? "", unit: srcItem.unit ?? "",
            workCategory: srcItem.itemWorkCategory,
            bulkMaterialClassification: srcItem.bulkMaterialClassification,
          } as any);
          if (workCategory === "bituminous" && resolved !== "bituminous") {
            return res.status(400).json({
              error: "CATEGORY_ITEM_MISMATCH",
              message: `BOQ item ${itemId} is not classified as bituminous — a bituminous arrangement cannot be raised against it. Use the manual classification override if the auto-detection is wrong.`,
            });
          }
          if (workCategory === "earthwork" && resolved === "bituminous") {
            return res.status(400).json({
              error: "CATEGORY_ITEM_MISMATCH",
              message: `BOQ item ${itemId} is classified as bituminous — raise a bituminous arrangement instead of an earthwork one.`,
            });
          }
        }
      }

      // ── Linkage guard: every arrangement must be tied to a BOQ source ─────
      // An arrangement with no boqItemId and no boqItemAllocations is an orphan —
      // it bypasses the per-item over-allocation guard and becomes unattributable.
      const hasMultiSource = boqItemAllocationsRaw && Array.isArray(boqItemAllocationsRaw)
        && boqItemAllocationsRaw.some(a => a.boqItemId && Number(a.qty) > 0);
      const hasSingleSource = !!singleBoqItemId;
      if (!hasSingleSource && !hasMultiSource) {
        return res.status(400).json({
          error: "BOQ_SOURCE_REQUIRED",
          message: "An earthwork arrangement must be linked to at least one BOQ item. Provide boqItemId or a non-empty boqItemAllocations array.",
        });
      }
      if (hasSingleSource && hasMultiSource) {
        return res.status(400).json({
          error: "AMBIGUOUS_BOQ_SOURCE",
          message: "Provide either boqItemId (single-source) or boqItemAllocations (multi-source), not both.",
        });
      }

      // ── Multi-BOQ over-allocation guard ───────────────────────────────────
      const effectiveAllocations: Array<{ boqItemId: number; qty: number }> = [];

      if (boqItemAllocationsRaw && Array.isArray(boqItemAllocationsRaw) && boqItemAllocationsRaw.length > 0) {
        // Multi-source: validate each source individually
        // Uses getAllocatedQtyForBoqItem which checks BOTH direct (boq_item_id) and
        // JSONB split (boq_item_allocations) allocations — prevents double-counting.
        for (const alloc of boqItemAllocationsRaw) {
          if (!alloc.boqItemId || Number(alloc.qty) <= 0) continue;
          const [boqItem] = await db.select({ currentQty: boqItems.currentQty, description: boqItems.description })
            .from(boqItems).where(eq(boqItems.id, Number(alloc.boqItemId)));
          if (!boqItem) {
            return res.status(400).json({ error: "BOQ_ITEM_NOT_FOUND", message: `BOQ item ${alloc.boqItemId} not found.` });
          }
          const alreadyAllocated = await storage.getAllocatedQtyForBoqItem(projectId, Number(alloc.boqItemId));
          const boqQty = Number(boqItem.currentQty ?? 0);
          if (alreadyAllocated + Number(alloc.qty) > boqQty + 0.001) {
            return res.status(400).json({
              error: "ALLOCATION_EXCEEDS_REMAINING_QUANTITY",
              message: `Allocation for "${boqItem.description}" (${(alreadyAllocated + Number(alloc.qty)).toFixed(2)} CUM) would exceed BOQ quantity (${boqQty} CUM). Already allocated: ${alreadyAllocated.toFixed(2)} CUM across all arrangements.`,
            });
          }
          effectiveAllocations.push({ boqItemId: Number(alloc.boqItemId), qty: Number(alloc.qty) });
        }

        // ── Allocation total must match allocatedQty for multi-source ──────
        const allocSum = effectiveAllocations.reduce((s, a) => s + a.qty, 0);
        if (Math.abs(allocSum - allocatedQtyNum) > 0.01) {
          return res.status(400).json({
            error: "ALLOCATION_TOTAL_MISMATCH",
            message: `allocatedQty (${allocatedQtyNum}) must equal the sum of boqItemAllocations (${allocSum.toFixed(2)} CUM). Please correct the per-source split.`,
          });
        }
      } else if (singleBoqItemId) {
        // Single-source: also use getAllocatedQtyForBoqItem to catch cross-allocation leakage
        const [boqItem] = await db.select({ currentQty: boqItems.currentQty, description: boqItems.description })
          .from(boqItems).where(eq(boqItems.id, singleBoqItemId));
        if (boqItem) {
          const alreadyAllocated = await storage.getAllocatedQtyForBoqItem(projectId, singleBoqItemId);
          const boqQty = Number(boqItem.currentQty ?? 0);
          if (alreadyAllocated + allocatedQtyNum > boqQty + 0.001) {
            return res.status(400).json({
              error: "ALLOCATION_EXCEEDS_REMAINING_QUANTITY",
              message: `Allocated quantity (${(alreadyAllocated + allocatedQtyNum).toFixed(2)} CUM) would exceed BOQ quantity (${boqQty} CUM). Already allocated: ${alreadyAllocated.toFixed(2)} CUM.`,
            });
          }
        }
        effectiveAllocations.push({ boqItemId: singleBoqItemId, qty: allocatedQtyNum });
      }

      const primaryBoqItemId = effectiveAllocations.length === 1
        ? effectiveAllocations[0].boqItemId
        : (effectiveAllocations.length > 1 ? null : singleBoqItemId);
      const reuseSourceCheck = await validateReusedExcavationSource(
        projectId,
        arrangementType ?? "not_decided",
        body.sourceExcavationBoqItemId,
        effectiveAllocations.map((allocation) => allocation.boqItemId),
      );
      if (!reuseSourceCheck.ok) {
        return res.status(reuseSourceCheck.status).json(reuseSourceCheck.body);
      }

      // Determine final status from saveIntent
      const finalStatus = saveIntent === "submit" ? "submitted" : "draft";
      const submittedAtValue = saveIntent === "submit" ? new Date() : null;

      const row = await storage.createEarthworkArrangement({
        boqProjectId: projectId,
        boqItemId: primaryBoqItemId,
        boqItemAllocations: effectiveAllocations.length > 1 ? effectiveAllocations : null,
        materialLabel: String(materialLabel).trim(),
        workCategory,
        bituminousItemType: workCategory === "bituminous" ? bituminousItemType : null,
        arrangementType: arrangementType ?? "not_decided",
        status: finalStatus,
        submittedAt: submittedAtValue,
        allocatedQty: allocatedQtyNum,
        uom: body.uom ?? "CUM",
        agencyName: body.agencyName?.trim() || null,
        workDescription: body.workDescription?.trim() || null,
        reachLabel: body.reachLabel?.trim() || null,
        chainageFrom: body.chainageFrom != null ? Number(body.chainageFrom) : null,
        chainageTo: body.chainageTo != null ? Number(body.chainageTo) : null,
        scopeSegmentIds: scopeSegmentIdsValue,
        tripRates: tripRatesResult.data,
        billingTerms: termsResult.data,
        agreedRate: body.agreedRate != null ? Number(body.agreedRate) : null,
        borrowSource: body.borrowSource?.trim() || null,
        avgLeadKm: body.avgLeadKm != null ? Number(body.avgLeadKm) : null,
        mobilisationDate: body.mobilisationDate ?? null,
        plannedStartDate: plannedStart,
        targetCompletionDate: targetEnd,
        plannedDailyOutput: body.plannedDailyOutput != null ? Number(body.plannedDailyOutput) : null,
        workingHoursPerShift: body.workingHoursPerShift != null ? Number(body.workingHoursPerShift) : null,
        numExcavators: body.numExcavators != null ? Number(body.numExcavators) : null,
        excavatorType: body.excavatorType?.trim() || null,
        numTippers: body.numTippers != null ? Number(body.numTippers) : null,
        tipperCapacityCum: body.tipperCapacityCum != null ? Number(body.tipperCapacityCum) : null,
        dieselResponsibility: body.dieselResponsibility ?? null,
        components: body.components ?? null,
        inclusions: body.inclusions?.trim() || null,
        exclusions: body.exclusions?.trim() || null,
        notes: body.notes?.trim() || null,
        sourceExcavationBoqItemId: reuseSourceCheck.sourceId,
        preparedByUserId: user?.id ?? null,
      }, scopeVersionToken);

      await (storage as any).logAudit({ userName: user?.fullName ?? "Unknown", userRole: user?.role ?? null,
        module: "earthwork_arrangements",
        transactionId: Number(row.id),
        action: "create",
        userId: user?.id ?? null,
        newValues: row,
      }).catch(() => {});

      res.status(201).json(row);
    } catch (err: any) {
      console.error("POST /api/boq/projects/:id/earthwork-arrangements:", err);
      const errMsg = String(err?.message ?? "");
      if (err?.code === "SCOPE_CHANGED_DURING_PLANNING"
        || (ScopeChangedDuringPlanningError && err instanceof ScopeChangedDuringPlanningError)) {
        return res.status(409).json({
          code: "SCOPE_CHANGED_DURING_PLANNING",
          message: err.message,
        });
      }
      // Schema errors — return actionable column/table name
      if (errMsg.includes("relation") || errMsg.includes("does not exist") || errMsg.includes("column")) {
        const colMatch = errMsg.match(/column "([^"]+)"/);
        const tableMatch = errMsg.match(/relation "([^"]+)"/);
        const detail = colMatch
          ? `Missing column: ${colMatch[1]}.`
          : tableMatch ? `Missing table: ${tableMatch[1]}.`
          : "Schema check needed.";
        return res.status(503).json({
          error: "EARTHWORK_SCHEMA_NOT_READY",
          message: `Earthwork database setup is incomplete. ${detail} The server will retry setup on next restart.`,
        });
      }
      // Unknown error — log with correlation ID; do not blame required fields
      const correlationId = Date.now().toString(36) + Math.random().toString(36).slice(2, 6);
      console.error(`[earthwork-save-error:${correlationId}]`, err);
      res.status(500).json({
        error: "ARRANGEMENT_SAVE_FAILED",
        message: `An unexpected error occurred while saving the arrangement. (ref: ${correlationId})`,
      });
    }
  })

app.get("/api/earthwork-arrangements/:id", async (req, res) => {
    try {
      if (!assertAuthed(req, res)) return;
      const id = parseInt(req.params.id);
      const arr = await storage.getEarthworkArrangementById(id);
      if (!arr) return res.status(404).json({ error: "Arrangement not found" });
      const progress = await (storage as any).getArrangementProgress(id);
      res.json({ ...arr, progress });
    } catch (err) {
      console.error("GET /api/earthwork-arrangements/:id:", err);
      res.status(500).json({ error: "Failed to fetch arrangement" });
    }
  })

app.get("/api/earthwork-arrangements/:id/execution-evidence", async (req, res) => {
    try {
      if (!assertAuthed(req, res) || !assertViewEither(req, res, "work_programme", "work_programme_review")) return;
      const id = Number(req.params.id);
      if (!Number.isInteger(id) || id <= 0) return res.status(400).json({ message: "A valid arrangement id is required" });
      const arrangement = await storage.getEarthworkArrangementById(id);
      if (!arrangement) return res.status(404).json({ message: "Arrangement not found" });
      if (!(await assertOutcomeProjectScope(req, res, arrangement.boqProjectId))) return;
      const bars = await storage.getArrangementExecutionEvidence(id);
      res.json({
        arrangementId: arrangement.id,
        boqProjectId: arrangement.boqProjectId,
        evidence: bars,
        // This endpoint exposes evidence only; status events and billing retain
        // their existing, separate semantics.
      });
    } catch (err) {
      console.error("GET /api/earthwork-arrangements/:id/execution-evidence:", err);
      res.status(500).json({ message: "Failed to load arrangement execution evidence" });
    }
  })

app.patch("/api/earthwork-arrangements/:id", async (req, res) => {
    try {
      if (!assertAuthed(req, res)) return;
      if (!assertEdit(req, res, "work_programme")) return;

      // ── Schema readiness guard ────────────────────────────────────────────
      if (!earthworkSchemaReady) {
        return res.status(503).json({
          error: "EARTHWORK_SCHEMA_NOT_READY",
          message: "Earthwork database setup has not completed yet. Please wait a moment and retry.",
        });
      }

      const id = parseInt(req.params.id);
      const user = (req as any).authUser ?? (req as any).user;
      const body = req.body ?? {};
      const now = new Date().toISOString();

      const allowedFields = [
        "arrangementType", "agencyName", "workDescription", "reachLabel",
        "chainageFrom", "chainageTo", "allocatedQty", "uom", "agreedRate",
        "tripRates",
        "billingTerms",
        "borrowSource", "avgLeadKm",
        "mobilisationDate", "plannedStartDate", "actualStartDate", "targetCompletionDate",
        "plannedDailyOutput", "workingHoursPerShift", "numExcavators", "excavatorType",
        "numTippers", "tipperCapacityCum", "dieselResponsibility", "components",
        "inclusions", "exclusions", "notes", "status",
        "rejectionReason", "cancellationReason", "onHoldReason",
        "boqItemAllocations", "sourceExcavationBoqItemId",
        "bituminousItemType",
        "scopeSegmentIds", // Instruction 031 B3
      ];
      const patch: Record<string, unknown> = {};
      for (const field of allowedFields) {
        if (field in body) patch[field] = body[field];
      }

      if ("tripRates" in patch) {
        const result = arrangementTripRatesSchema.safeParse(patch.tripRates);
        if (!result.success) return res.status(400).json({
          error: "INVALID_TRIP_RATES", message: result.error.issues[0].message,
        });
        patch.tripRates = result.data;
      }
      if ("billingTerms" in patch) {
        const result = arrangementBillingTermsSchema.nullable().safeParse(patch.billingTerms);
        if (!result.success) return res.status(400).json({ error: "INVALID_BILLING_TERMS", message: result.error.issues[0].message });
        patch.billingTerms = result.data;
      }

      // Numeric coercion
      for (const f of ["allocatedQty","agreedRate","avgLeadKm","plannedDailyOutput","chainageFrom","chainageTo","numExcavators","numTippers","tipperCapacityCum","workingHoursPerShift","sourceExcavationBoqItemId"]) {
        if (f in patch && patch[f] != null) patch[f] = Number(patch[f]);
      }

      const current = await storage.getEarthworkArrangementById(id);
      if (!current) return res.status(404).json({ error: "Arrangement not found" });
      const requestedStatus = typeof patch.status === "string" ? patch.status : null;
      const statusChanged = requestedStatus != null && requestedStatus !== current.status;
      const currentStatusDateRecorded = hasRecordedArrangementStatusChange(
        (current as any).revisionHistory,
        current.status,
      );
      const confirmExistingStatus = body.confirmExistingStatus === true
        && current.status === "cancelled"
        && requestedStatus === current.status
        && !currentStatusDateRecorded;
      if (body.confirmExistingStatus === true && !confirmExistingStatus) {
        return res.status(409).json({
          error: "STATUS_CONFIRMATION_NOT_ALLOWED",
          message: currentStatusDateRecorded
            ? "This cancelled arrangement already has a confirmed effective date."
            : "Historical effective-date confirmation is only available for an existing cancelled arrangement.",
        });
      }
      if ((statusChanged || confirmExistingStatus) && !isValidArrangementEffectiveDate(body.effectiveFrom)) {
        return res.status(400).json({
          error: "STATUS_EFFECTIVE_FROM_REQUIRED",
          message: "Choose the date from which this arrangement status became effective.",
        });
      }
      if (statusChanged && typeof body.statusReason === "string") {
        if (requestedStatus === "cancelled") patch.cancellationReason = body.statusReason.trim() || null;
        if (requestedStatus === "rejected") patch.rejectionReason = body.statusReason.trim() || null;
        if (requestedStatus === "on_hold") patch.onHoldReason = body.statusReason.trim() || null;
      }
      if (confirmExistingStatus) {
        if (!assertOutcomeManagerAuthority(req, res)) return;
        const confirmed: any = await db.transaction(async (tx) => {
          const [row] = await tx.select().from(earthworkArrangementsTable)
            .where(eq(earthworkArrangementsTable.id, id)).for("update");
          if (!row) return null;
          if (hasRecordedArrangementStatusChange((row as any).revisionHistory, "cancelled")) {
            return { alreadyConfirmed: true };
          }
          const revisionHistory = appendArrangementStatusChange((row as any).revisionHistory, {
            previousStatus: row.status,
            status: row.status,
            effectiveFrom: body.effectiveFrom,
            recordedAt: now,
            changedBy: user?.id ?? null,
            reason: typeof body.statusReason === "string"
              ? body.statusReason
              : (row.cancellationReason ?? row.rejectionReason ?? row.onHoldReason ?? null),
          });
          const [updatedRow] = await tx.update(earthworkArrangementsTable)
            .set({ revisionHistory } as any)
            .where(eq(earthworkArrangementsTable.id, id))
            .returning();
          return { updatedRow };
        });
        if (!confirmed) return res.status(404).json({ error: "Arrangement not found" });
        if (confirmed.alreadyConfirmed) {
          return res.status(409).json({
            error: "STATUS_CONFIRMATION_NOT_ALLOWED",
            message: "This cancelled arrangement already has a confirmed effective date.",
          });
        }
        await (storage as any).logAudit({
          userName: user?.fullName ?? "Unknown", userRole: user?.role ?? null,
          module: "earthwork_arrangements", transactionId: Number(id),
          action: "status_effective_date_confirmed", userId: user?.id ?? null,
          newValues: { status: current.status, effectiveFrom: body.effectiveFrom },
        }).catch(() => {});
        return res.json(confirmed.updatedRow);
      }
      const nextArrangementType = patch.arrangementType ?? current.arrangementType;
      const nextSourceId = "sourceExcavationBoqItemId" in patch
        ? patch.sourceExcavationBoqItemId
        : current.sourceExcavationBoqItemId;
      const nextAllocations = "boqItemAllocations" in patch
        ? patch.boqItemAllocations
        : current.boqItemAllocations;
      const destinationBoqItemIds = "boqItemAllocations" in patch
        ? (Array.isArray(nextAllocations)
          ? (nextAllocations as Array<{ boqItemId?: number | null }>)
              .map((allocation) => Number(allocation?.boqItemId))
              .filter(Number.isFinite)
          : [])
        : current.boqItemId != null ? [current.boqItemId] : Array.isArray(nextAllocations)
          ? (nextAllocations as any[]).map(x => Number(x?.boqItemId)).filter(Number.isFinite) : [];
      const relationshipChanged = "arrangementType" in patch || "sourceExcavationBoqItemId" in patch || "boqItemAllocations" in patch;
      if (relationshipChanged) {
        const reuseSourceCheck = await validateReusedExcavationSource(
          current.boqProjectId, nextArrangementType, nextSourceId, destinationBoqItemIds,
        );
        if (!reuseSourceCheck.ok) return res.status(reuseSourceCheck.status).json(reuseSourceCheck.body);
        patch.sourceExcavationBoqItemId = reuseSourceCheck.sourceId;
      }

      // ── Instruction 031 B3: validate + normalise Scope linkage on edit ────
      if ("scopeSegmentIds" in patch) {
        const scopeCheckResult = await validateArrangementScopeSegments(current.boqProjectId, patch.scopeSegmentIds);
        if (!scopeCheckResult.ok) return res.status(scopeCheckResult.status).json(scopeCheckResult.body);
        patch.scopeSegmentIds = scopeCheckResult.ids;
      }

      // ── Instruction 028 §35 — category validation on PATCH ────────────────
      const rowCategory: string = (current as any).workCategory ?? "earthwork"; // old rows = earthwork during transition
      if ("workCategory" in body && body.workCategory !== rowCategory) {
        return res.status(400).json({ error: "INVALID_WORK_CATEGORY", message: "workCategory cannot be changed on an existing arrangement." });
      }
      if (typeof patch.arrangementType === "string" && patch.arrangementType !== "not_decided"
          && !isArrangementTypeAllowed(rowCategory, patch.arrangementType)) {
        return res.status(400).json({ error: "INVALID_ARRANGEMENT_TYPE", message: `Arrangement type '${patch.arrangementType}' is not valid for ${rowCategory} works.` });
      }
      if (patch.components) {
        const badKeysPatch = invalidComponentKeys(rowCategory, patch.components as Record<string, unknown>);
        if (badKeysPatch.length > 0) {
          return res.status(400).json({ error: "INVALID_COMPONENT_KEYS", message: `Component keys not allowed for ${rowCategory}: ${badKeysPatch.join(", ")}` });
        }
      }
      if ("bituminousItemType" in patch && patch.bituminousItemType != null) {
        if (rowCategory !== "bituminous" || !isValidBituminousItemType(patch.bituminousItemType)) {
          return res.status(400).json({ error: "INVALID_BITUMINOUS_ITEM_TYPE", message: "Invalid bituminous item type for this arrangement." });
        }
      }
      // 028A §13 (Part D safe fallback) — same rule as POST, but NEVER blocks a record
      // that already stored a Shared component (preserved as-is; engine retains company-side).
      if (patch.components && typeof patch.components === "object") {
        const currentComponents = ((current as any).components ?? {}) as Record<string, string>;
        const newSharedKeys = Object.entries(patch.components as Record<string, string>)
          .filter(([k, v]) => v === "shared" && currentComponents[k] !== "shared")
          .map(([k]) => k);
        if (newSharedKeys.length > 0) {
          return res.status(400).json({ error: "SHARED_NOT_AVAILABLE", message: `Shared responsibility percentage entry is not yet available (component${newSharedKeys.length > 1 ? "s" : ""} '${newSharedKeys.join("', '")}'). Choose Company, Agency or Client for now.` });
        }
      }

      // ── Instruction 026 §17 + 027 Parts E/F/H: controlled editing of operational arrangements ──
      const OPERATIONAL = new Set(["approved", "mobilisation_pending", "in_progress", "on_hold"]);
      /** pendingRevision shape (027): { fields, reason, proposedByUserId, proposedAt }. Legacy (026): flat field map. */
      const readPending = (p: any): { fields: Record<string, unknown>; reason?: string; proposedByUserId?: number | null; proposedAt?: string } | null =>
        p == null ? null : (p.fields && typeof p.fields === "object" ? p : { fields: p });

      // Fully terminal arrangements are not editable at all (§28 ARRANGEMENT_NOT_EDITABLE)
      if ((current.status === "cancelled" || current.status === "rejected") && !body.revisionAction) {
        const changesAnything = Object.keys(patch).some(f =>
          JSON.stringify((patch as any)[f] ?? null) !== JSON.stringify((current as any)[f] ?? null));
        if (changesAnything) {
          return res.status(409).json({ error: "ARRANGEMENT_NOT_EDITABLE", message: `A ${current.status} arrangement cannot be edited. Create a new arrangement instead.` });
        }
      }

      // ── Status-transition hardening (027 review): no demotion bypass ────────
      // An operational arrangement's status may only move along the operational
      // workflow — never back to draft/submitted/returned, which would strip the
      // controlled-edit guard and allow silent material overwrites.
      if (OPERATIONAL.has(current.status) && "status" in patch && patch.status !== current.status) {
        const ALLOWED_TRANSITIONS: Record<string, Set<string>> = {
          approved: new Set(["mobilisation_pending", "in_progress", "on_hold", "cancelled"]),
          mobilisation_pending: new Set(["in_progress", "on_hold", "cancelled"]),
          in_progress: new Set(["on_hold", "completed", "cancelled"]),
          on_hold: new Set(["in_progress", "cancelled"]),
        };
        if (!ALLOWED_TRANSITIONS[current.status]?.has(String(patch.status))) {
          return res.status(409).json({
            error: "INVALID_STATUS_TRANSITION",
            message: `An arrangement in status "${current.status}" cannot move to "${patch.status}". Operational arrangements cannot be demoted — use a controlled revision for material changes.`,
          });
        }
      }

      /**
       * Validate material/commercial fields as they WOULD become effective
       * (merged over current). Mirrors the POST/PATCH linkage guards so that
       * revision approval / apply-now cannot make invalid scope effective.
       */
      const checkMaterialGuards = async (fields: Record<string, unknown>): Promise<{ status: number; body: unknown } | null> => {
        const merged: any = { ...current, ...fields };
        const qty = Number(merged.allocatedQty ?? 0);
        if (!(qty > 0)) return { status: 400, body: { error: "INVALID_QUANTITY", message: "allocatedQty must be greater than zero." } };
        const allocs = merged.boqItemAllocations as Array<{ boqItemId: number; qty: number }> | null;
        const hasMulti = Array.isArray(allocs) && allocs.some(a => a.boqItemId && Number(a.qty) > 0);
        const singleId = merged.boqItemId ? Number(merged.boqItemId) : null;
        if (!hasMulti && !singleId) {
          return { status: 400, body: { error: "BOQ_SOURCE_REQUIRED", message: "An earthwork arrangement must retain a BOQ linkage." } };
        }
        if (hasMulti) {
          const sum = allocs!.filter(a => a.boqItemId && Number(a.qty) > 0).reduce((s, a) => s + Number(a.qty), 0);
          if (Math.abs(sum - qty) > 0.01) {
            return { status: 400, body: { error: "ALLOCATION_TOTAL_MISMATCH", message: `allocatedQty (${qty}) must equal the sum of boqItemAllocations (${sum.toFixed(2)} CUM).` } };
          }
          for (const alloc of allocs!) {
            if (!alloc.boqItemId || Number(alloc.qty) <= 0) continue;
            const [boqItem] = await db.select({ currentQty: boqItems.currentQty, description: boqItems.description })
              .from(boqItems).where(eq(boqItems.id, Number(alloc.boqItemId)));
            if (!boqItem) return { status: 400, body: { error: "BOQ_ITEM_NOT_FOUND", message: `BOQ item ${alloc.boqItemId} not found.` } };
            const totalAllocated = await storage.getAllocatedQtyForBoqItem(current.boqProjectId, Number(alloc.boqItemId));
            const ownExisting = (Array.isArray(current.boqItemAllocations)
              ? (current.boqItemAllocations as Array<{ boqItemId: number; qty: number }>).find(a => Number(a.boqItemId) === Number(alloc.boqItemId))?.qty ?? 0
              : (Number(current.boqItemId) === Number(alloc.boqItemId) ? Number(current.allocatedQty ?? 0) : 0));
            if (totalAllocated - Number(ownExisting) + Number(alloc.qty) > Number(boqItem.currentQty ?? 0) + 0.001) {
              return { status: 400, body: { error: "ALLOCATION_EXCEEDS_REMAINING_QUANTITY", message: `Change would over-allocate "${boqItem.description}".` } };
            }
          }
        } else if (singleId && ("allocatedQty" in fields || "boqItemId" in fields)) {
          const [boqItem] = await db.select({ currentQty: boqItems.currentQty, description: boqItems.description })
            .from(boqItems).where(eq(boqItems.id, singleId));
          if (!boqItem) return { status: 400, body: { error: "BOQ_ITEM_NOT_FOUND", message: `BOQ item ${singleId} not found.` } };
          const totalAllocated = await storage.getAllocatedQtyForBoqItem(current.boqProjectId, singleId);
          const ownExisting = Number(current.boqItemId) === singleId ? Number(current.allocatedQty ?? 0) : 0;
          if (totalAllocated - ownExisting + qty > Number(boqItem.currentQty ?? 0) + 0.001) {
            return { status: 400, body: { error: "ALLOCATION_EXCEEDS_REMAINING_QUANTITY", message: `Change would over-allocate "${boqItem.description}".` } };
          }
        }
        // 026 bar links: effective quantity cannot drop below what is already linked to programme bars.
        if ("allocatedQty" in fields) {
          const linked = (await db.select().from(earthworkArrangementProgrammeAllocations)
            .where(eq(earthworkArrangementProgrammeAllocations.arrangementId, id)))
            .reduce((s, a) => s + Number(a.allocatedQty), 0);
          if (qty + 0.001 < linked) {
            return { status: 409, body: { error: "ALLOCATION_BELOW_BAR_LINKED", message: `allocatedQty (${qty}) cannot be below the ${linked.toFixed(2)} CUM already linked to programme stretches. Unlink stretches first.` } };
          }
        }
        return null;
      };

      // ── Revision decision actions: approve / reject / discard (§20) ─────────
      if (body.revisionAction === "approve" || body.revisionAction === "discard" || body.revisionAction === "reject") {
        // approve/reject are approver-only decisions (§22). discard is allowed
        // for the proposer (withdrawing their own proposal) or an approver.
        const pendingPeek = readPending((current as any).pendingRevision);
        if (!pendingPeek) return res.status(404).json({ error: "REVISION_NOT_FOUND", message: "This arrangement has no pending revision." });
        const isProposerDiscard = body.revisionAction === "discard" && pendingPeek.proposedByUserId != null && pendingPeek.proposedByUserId === user?.id;
        if (!isProposerDiscard && !assertApprove(req, res, "work_programme")) return;

        // Row-locked transaction: serialize against concurrent proposals/decisions.
        const result: any = await db.transaction(async (tx) => {
          const [row] = await tx.select().from(earthworkArrangementsTable)
            .where(eq(earthworkArrangementsTable.id, id)).for("update");
          if (!row) return { status: 404, body: { error: "ARRANGEMENT_NOT_FOUND", message: "Arrangement not found." } };
          const pendingWrap = readPending((row as any).pendingRevision);
          if (!pendingWrap) return { status: 404, body: { error: "REVISION_NOT_FOUND", message: "This arrangement has no pending revision." } };
          if (!OPERATIONAL.has(row.status) && row.status !== "completed") {
            return { status: 409, body: { error: "REVISION_NOT_APPROVABLE", message: `Revisions can only be decided on operational arrangements (current status: ${row.status}).` } };
          }
          const history = Array.isArray((row as any).revisionHistory) ? [...(row as any).revisionHistory] : [];
          if (body.revisionAction === "discard" || body.revisionAction === "reject") {
            // §20: rejected/discarded proposals stay auditable; effective values unchanged.
            history.push({
              type: "material", outcome: body.revisionAction === "reject" ? "rejected" : "discarded",
              changes: pendingWrap.fields, reason: pendingWrap.reason ?? null,
              proposedByUserId: pendingWrap.proposedByUserId ?? null, proposedAt: pendingWrap.proposedAt ?? null,
              decidedByUserId: user?.id ?? null, decidedAt: now,
            });
            const [updated0] = await tx.update(earthworkArrangementsTable)
              .set({ pendingRevision: null, revisionHistory: history } as any)
              .where(eq(earthworkArrangementsTable.id, id)).returning();
            return { status: 200, body: updated0, audit: { action: `revision_${body.revisionAction === "reject" ? "rejected" : "discarded"}`, oldValues: pendingWrap.fields } };
          }
          // Approve: re-validate the fields as they would become effective before applying.
          const guardErr = await checkMaterialGuards(pendingWrap.fields);
          if (guardErr) return guardErr;
          const previous: Record<string, unknown> = {};
          for (const k of Object.keys(pendingWrap.fields)) previous[k] = (row as any)[k] ?? null;
          history.push({
            type: "material", outcome: "approved", version: history.filter((h: any) => h.outcome === "approved").length + 1,
            previous, changes: pendingWrap.fields, reason: pendingWrap.reason ?? null,
            proposedByUserId: pendingWrap.proposedByUserId ?? null, proposedAt: pendingWrap.proposedAt ?? null,
            approvedByUserId: user?.id ?? null, approvedAt: now, effectiveFrom: now,
          });
          const [updated1] = await tx.update(earthworkArrangementsTable)
            .set({ ...(pendingWrap.fields as any), pendingRevision: null, revisionHistory: history } as any)
            .where(eq(earthworkArrangementsTable.id, id)).returning();
          return { status: 200, body: updated1, audit: { action: "revision_approved", oldValues: previous, newValues: pendingWrap.fields } };
        });
        if (result.audit) {
          await (storage as any).logAudit({ userName: user?.fullName ?? "Unknown", userRole: user?.role ?? null, module: "earthwork_arrangements", transactionId: Number(id), userId: user?.id ?? null, ...result.audit }).catch(() => {});
        }
        // Instruction 030: an APPROVED revision can raise quantity / change the
        // BOQ split or chainage — re-run the idempotent auto-sync so newly
        // available approved quantity reaches the programme bars immediately.
        if (result.status === 200 && body.revisionAction === "approve" && AUTO_SYNC_STATUSES.has(String((result.body as any)?.status ?? ""))) {
          await runArrangementAutoSync(id, user, "revision_approved");
        }
        return res.status(result.status).json(result.body);
      }

      if (OPERATIONAL.has(current.status)) {
        const cls = classifyArrangementEdit(current as any, body);

        // ── Material/commercial changes (§18–19, §21, §25) ───────────────────
        if (cls.material.length > 0) {
          const materialChanges: Record<string, unknown> = {};
          for (const f of cls.material) materialChanges[f] = body[f];

          // Instruction 031: operational fields submitted ALONGSIDE material
          // changes must not be silently dropped — they are applied immediately
          // (same semantics as a pure operational edit) while the material part
          // follows the revision flow. Collected here, merged into the update tx.
          const sideOperational: Record<string, unknown> = {};
          const sideOperationalOld: Record<string, unknown> = {};
          for (const f of cls.operational) {
            // Use the VALIDATED/normalised patch value when present (e.g.
            // scopeSegmentIds deduped + coerced to numbers) — never the raw body.
            sideOperational[f] = f in patch ? (patch as any)[f] : (body[f] ?? null);
            sideOperationalOld[f] = (current as any)[f] ?? null;
          }
          const hasSideOperational = cls.operational.length > 0;
          const sideOpHistoryEntry = hasSideOperational ? {
            type: "operational", outcome: "applied", previous: sideOperationalOld,
            changes: sideOperational,
            reason: body.editReason ? String(body.editReason) : (body.revisionReason ? String(body.revisionReason) : null),
            changedByUserId: user?.id ?? null, changedAt: now,
          } : null;

          if (body.saveIntent === "apply_now") {
            // §21 Admin Edit and Apply Now — approver-only, reason mandatory, versioned.
            if (!assertApprove(req, res, "work_programme")) return;
            if (!body.editReason || !String(body.editReason).trim()) {
              return res.status(400).json({ error: "ADMIN_APPLY_REASON_REQUIRED", message: "A reason is mandatory for Edit and Apply Now." });
            }
            const guardErr = await checkMaterialGuards(materialChanges);
            if (guardErr) return res.status(guardErr.status).json(guardErr.body);
            const result: any = await db.transaction(async (tx) => {
              const [row] = await tx.select().from(earthworkArrangementsTable)
                .where(eq(earthworkArrangementsTable.id, id)).for("update");
              if (!row) return { status: 404, body: { error: "ARRANGEMENT_NOT_FOUND", message: "Arrangement not found." } };
              const previous: Record<string, unknown> = {};
              for (const k of Object.keys(materialChanges)) previous[k] = (row as any)[k] ?? null;
              const history = Array.isArray((row as any).revisionHistory) ? [...(row as any).revisionHistory] : [];
              history.push({
                type: "material", outcome: "approved", appliedNow: true,
                version: history.filter((h: any) => h.outcome === "approved").length + 1,
                previous, changes: materialChanges, reason: String(body.editReason),
                proposedByUserId: user?.id ?? null, proposedAt: now,
                approvedByUserId: user?.id ?? null, approvedAt: now, effectiveFrom: now,
              });
              if (sideOpHistoryEntry) history.push(sideOpHistoryEntry);
              const [applied] = await tx.update(earthworkArrangementsTable)
                .set({ ...(materialChanges as any), ...(sideOperational as any), revisionHistory: history } as any)
                .where(eq(earthworkArrangementsTable.id, id)).returning();
              return { status: 200, body: { ...applied, appliedNow: true }, previous };
            });
            if (result.status === 200) {
              await (storage as any).logAudit({ userName: user?.fullName ?? "Unknown", userRole: user?.role ?? null, module: "earthwork_arrangements", transactionId: Number(id), action: "revision_applied_now", userId: user?.id ?? null, oldValues: result.previous, newValues: materialChanges }).catch(() => {});
              // Instruction 030: Edit-and-Apply-Now changes effective qty/split/
              // chainage on an operational arrangement — re-sync bar allocations.
              if (AUTO_SYNC_STATUSES.has(String((result.body as any)?.status ?? ""))) {
                await runArrangementAutoSync(id, user, "revision_applied_now");
              }
            }
            return res.status(result.status).json(result.body);
          }

          if (body.saveIntent !== "revise") {
            return res.status(409).json({
              error: "MATERIAL_CHANGE_REQUIRES_REVISION",
              message: "This arrangement is operational. Changes to agency, quantity, rate, scope or responsibility require a controlled revision (submit as a revision for approval).",
              fields: cls.material,
            });
          }
          if (!body.revisionReason || !String(body.revisionReason).trim()) {
            return res.status(400).json({ error: "REVISION_REASON_REQUIRED", message: "Please give a short reason for this revision." });
          }
          // Validate at proposal time too — reject obviously invalid proposals early.
          const guardErrP = await checkMaterialGuards(materialChanges);
          if (guardErrP) return res.status(guardErrP.status).json(guardErrP.body);
          // Store the proposal WITHOUT applying it — old approved values keep driving
          // demand (§19, §27). Row-locked so concurrent proposals cannot overwrite.
          const result: any = await db.transaction(async (tx) => {
            const [row] = await tx.select().from(earthworkArrangementsTable)
              .where(eq(earthworkArrangementsTable.id, id)).for("update");
            if (!row) return { status: 404, body: { error: "ARRANGEMENT_NOT_FOUND", message: "Arrangement not found." } };
            if (readPending((row as any).pendingRevision)) {
              return { status: 409, body: { error: "REVISION_ALREADY_PENDING", message: "A revision is already pending on this arrangement. Approve, reject or discard it first." } };
            }
            const pendingRevision = { fields: materialChanges, reason: String(body.revisionReason), proposedByUserId: user?.id ?? null, proposedAt: now };
            const historyOp = Array.isArray((row as any).revisionHistory) ? [...(row as any).revisionHistory] : [];
            if (sideOpHistoryEntry) historyOp.push(sideOpHistoryEntry);
            const [updated2] = await tx.update(earthworkArrangementsTable)
              .set({ pendingRevision, ...(sideOperational as any), ...(sideOpHistoryEntry ? { revisionHistory: historyOp } : {}) } as any)
              .where(eq(earthworkArrangementsTable.id, id)).returning();
            return { status: 200, body: { ...updated2, revisionPending: true } };
          });
          if (result.status === 200) {
            await (storage as any).logAudit({ userName: user?.fullName ?? "Unknown", userRole: user?.role ?? null, module: "earthwork_arrangements", transactionId: Number(id), action: "revision_proposed", userId: user?.id ?? null, newValues: materialChanges }).catch(() => {});
            // Instruction 031: an operational scope-link change applied alongside
            // the revision proposal takes effect immediately — reconcile bars now.
            if (hasSideOperational && ("scopeSegmentIds" in sideOperational || "reachLabel" in sideOperational || "chainageFrom" in sideOperational || "chainageTo" in sideOperational)
              && AUTO_SYNC_STATUSES.has(String((result.body as any)?.status ?? ""))) {
              await runArrangementAutoSync(id, user, "scope_changed");
            }
          }
          return res.status(result.status).json(result.body);
        }

        // ── Operational edits (§17): immediate, audited, reason for dates/output ──
        if (cls.operational.length > 0) {
          if (cls.reasonRequired && (!body.editReason || !String(body.editReason).trim())) {
            return res.status(400).json({ error: "REVISION_REASON_REQUIRED", message: "Please give a short reason for changing planned dates or output.", fields: cls.operational.filter(f => ["mobilisationDate","plannedStartDate","targetCompletionDate","plannedDailyOutput"].includes(f)) });
          }
          const oldValues: Record<string, unknown> = {};
          const newValues: Record<string, unknown> = {};
          for (const f of cls.operational) { oldValues[f] = (current as any)[f] ?? null; newValues[f] = body[f] ?? null; }
          const history = Array.isArray((current as any).revisionHistory) ? [...(current as any).revisionHistory] : [];
          history.push({ type: "operational", outcome: "applied", previous: oldValues, changes: newValues, reason: body.editReason ? String(body.editReason) : null, changedByUserId: user?.id ?? null, changedAt: now });
          patch.revisionHistory = history;
          await (storage as any).logAudit({ userName: user?.fullName ?? "Unknown", userRole: user?.role ?? null, module: "earthwork_arrangements", transactionId: Number(id), action: "operational_edit", userId: user?.id ?? null, oldValues, newValues }).catch(() => {});
          // fall through: patch is applied below like any normal update
        }
      }

      // ── Linkage/over-allocation guard on PATCH (mirrors POST guard) ────────
      // Only apply when the patch mutates BOQ linkage or quantity fields.
      const patchChangesLinkage = "boqItemId" in body || "boqItemAllocations" in body || "allocatedQty" in body;
      if (patchChangesLinkage) {

        const newAllocsRaw = patch.boqItemAllocations as Array<{ boqItemId: number; qty: number }> | undefined;
        const newSingleId = "boqItemId" in body ? (body.boqItemId ? Number(body.boqItemId) : null) : Number(current.boqItemId ?? 0) || null;
        const newAllocQty = "allocatedQty" in patch ? Number(patch.allocatedQty) : Number(current.allocatedQty ?? 0);

        const hasMultiSource = newAllocsRaw != null && Array.isArray(newAllocsRaw)
          && newAllocsRaw.some(a => a.boqItemId && Number(a.qty) > 0);
        const hasSingleSource = !!newSingleId;

        // No-source rejection: mirrors POST guard — PATCH cannot leave an arrangement orphaned.
        // This fires when boqItemAllocations is patched to [] (or all qty=0) while boqItemId is null.
        if (!hasSingleSource && !hasMultiSource) {
          return res.status(400).json({
            error: "BOQ_SOURCE_REQUIRED",
            message: "An earthwork arrangement must retain a BOQ linkage. Provide boqItemId or a non-empty boqItemAllocations array.",
          });
        }

        // Exclusivity check (only when both explicitly provided in this PATCH)
        if ("boqItemId" in body && "boqItemAllocations" in body && hasSingleSource && hasMultiSource) {
          return res.status(400).json({
            error: "AMBIGUOUS_BOQ_SOURCE",
            message: "Provide either boqItemId (single-source) or boqItemAllocations (multi-source), not both.",
          });
        }

        // ── Allocation total must match allocatedQty for multi-source (mirrors POST) ──
        if (hasMultiSource && newAllocsRaw) {
          const allocSum = newAllocsRaw
            .filter(a => a.boqItemId && Number(a.qty) > 0)
            .reduce((s, a) => s + Number(a.qty), 0);
          if (Math.abs(allocSum - newAllocQty) > 0.01) {
            return res.status(400).json({
              error: "ALLOCATION_TOTAL_MISMATCH",
              message: `allocatedQty (${newAllocQty}) must equal the sum of boqItemAllocations (${allocSum.toFixed(2)} CUM). Please correct the per-source split.`,
            });
          }
        }

        // Over-allocation check per source when quantity or allocations change
        const projectIdForArrangement = current.boqProjectId;
        if (hasMultiSource && newAllocsRaw) {
          for (const alloc of newAllocsRaw) {
            if (!alloc.boqItemId || Number(alloc.qty) <= 0) continue;
            const [boqItem] = await db.select({ currentQty: boqItems.currentQty, description: boqItems.description })
              .from(boqItems).where(eq(boqItems.id, Number(alloc.boqItemId)));
            if (!boqItem) return res.status(400).json({ error: "BOQ_ITEM_NOT_FOUND", message: `BOQ item ${alloc.boqItemId} not found.` });
            // Subtract this arrangement's own existing contribution before checking
            const totalAllocated = await storage.getAllocatedQtyForBoqItem(projectIdForArrangement, Number(alloc.boqItemId));
            const ownExisting = (Array.isArray(current.boqItemAllocations)
              ? (current.boqItemAllocations as Array<{ boqItemId: number; qty: number }>)
                  .find(a => Number(a.boqItemId) === Number(alloc.boqItemId))?.qty ?? 0
              : 0);
            const netAllocated = totalAllocated - Number(ownExisting);
            if (netAllocated + Number(alloc.qty) > Number(boqItem.currentQty ?? 0) + 0.001) {
              return res.status(400).json({
                error: "ALLOCATION_EXCEEDS_REMAINING_QUANTITY",
                message: `Edit would over-allocate "${boqItem.description}": ${(netAllocated + Number(alloc.qty)).toFixed(2)} CUM > ${boqItem.currentQty} CUM BOQ.`,
              });
            }
          }
        } else if (hasSingleSource && newSingleId && "allocatedQty" in patch) {
          const [boqItem] = await db.select({ currentQty: boqItems.currentQty, description: boqItems.description })
            .from(boqItems).where(eq(boqItems.id, newSingleId));
          if (boqItem) {
            const totalAllocated = await storage.getAllocatedQtyForBoqItem(projectIdForArrangement, newSingleId);
            const ownExisting = Number(current.boqItemId) === newSingleId ? Number(current.allocatedQty ?? 0) : 0;
            const netAllocated = totalAllocated - ownExisting;
            if (netAllocated + newAllocQty > Number(boqItem.currentQty ?? 0) + 0.001) {
              return res.status(400).json({
                error: "ALLOCATION_EXCEEDS_REMAINING_QUANTITY",
                message: `Edit would over-allocate "${boqItem.description}": ${(netAllocated + newAllocQty).toFixed(2)} CUM > ${boqItem.currentQty} CUM BOQ.`,
              });
            }
          }
        }
      }
      // ── End of linkage/over-allocation guard ──────────────────────────────

      // Status transition — set timestamps
      const newStatus = patch.status as string | undefined;
      // Timestamp columns require Date objects (drizzle PgTimestamp), not ISO strings.
      if (newStatus === "submitted") patch.submittedAt = new Date();
      if (newStatus === "approved") { patch.approvedByUserId = user?.id ?? null; patch.approvedAt = new Date(); }
      if (newStatus === "returned") patch.returnedAt = new Date();
      if (newStatus === "completed") patch.completedAt = new Date();
      if (newStatus === "in_progress" && !body.actualStartDate) patch.actualStartDate = now.split("T")[0];
      if (statusChanged) {
        const statusReason = typeof body.statusReason === "string"
          ? body.statusReason
          : newStatus === "cancelled" ? patch.cancellationReason
          : newStatus === "rejected" ? patch.rejectionReason
          : newStatus === "on_hold" ? patch.onHoldReason
          : null;
        patch.revisionHistory = appendArrangementStatusChange(
          patch.revisionHistory ?? (current as any).revisionHistory,
          {
            previousStatus: current.status,
            status: newStatus!,
            effectiveFrom: body.effectiveFrom,
            recordedAt: now,
            changedBy: user?.id ?? null,
            reason: typeof statusReason === "string" ? statusReason : null,
          },
        );
      }

      const updated = await storage.updateEarthworkArrangement(id, patch as any);
      if (!updated) return res.status(404).json({ error: "Arrangement not found" });

      // ── Instruction 030 Part A: auto-allocate to overlapping bars ──────────
      // Never blocks the update itself; failures only log. Idempotent —
      // existing (manual) allocations are preserved, only the unassigned
      // remainder is distributed to bars overlapping the arrangement's chainage.
      // Triggers: ANY transition into an operational status (approved,
      // mobilisation_pending, in_progress, on_hold), and any change to the
      // arrangement's quantity, BOQ split or chainage while it is operational.
      const enteredOperational = !!newStatus && AUTO_SYNC_STATUSES.has(newStatus) && newStatus !== current.status;
      const scopeChanged = patchChangesLinkage || "chainageFrom" in body || "chainageTo" in body || "scopeSegmentIds" in body;
      if (AUTO_SYNC_STATUSES.has(String(updated.status)) && (enteredOperational || scopeChanged)) {
        await runArrangementAutoSync(id, user, enteredOperational ? `status_${newStatus}` : "scope_changed");
      }

      await (storage as any).logAudit({ userName: user?.fullName ?? "Unknown", userRole: user?.role ?? null,
        module: "earthwork_arrangements",
        transactionId: Number(id),
        action: newStatus ? `status_${newStatus}` : "update",
        userId: user?.id ?? null,
        newValues: patch,
      }).catch(() => {});

      res.json(updated);
    } catch (err: any) {
      console.error("PATCH /api/earthwork-arrangements/:id:", err);
      const errMsg = String(err?.message ?? "");
      if (errMsg.includes("relation") || errMsg.includes("does not exist") || errMsg.includes("column")) {
        const colMatch = errMsg.match(/column "([^"]+)"/);
        const detail = colMatch ? `Missing column: ${colMatch[1]}.` : "Schema check needed.";
        return res.status(503).json({
          error: "EARTHWORK_SCHEMA_NOT_READY",
          message: `Earthwork database setup is incomplete. ${detail}`,
        });
      }
      const correlationId = Date.now().toString(36) + Math.random().toString(36).slice(2, 6);
      console.error(`[earthwork-update-error:${correlationId}]`, err);
      res.status(500).json({
        error: "ARRANGEMENT_UPDATE_FAILED",
        message: `An unexpected error occurred while updating the arrangement. (ref: ${correlationId})`,
      });
    }
  })

app.delete("/api/earthwork-arrangements/:id", async (req, res) => {
    try {
      if (!assertAuthed(req, res)) return;
      if (!assertDelete(req, res, "work_programme")) return;
      const id = parseInt(req.params.id);
      const user = (req as any).authUser ?? (req as any).user;
      const { reason, effectiveFrom } = req.body ?? {};
      if (!isValidArrangementEffectiveDate(effectiveFrom)) {
        return res.status(400).json({
          error: "STATUS_EFFECTIVE_FROM_REQUIRED",
          message: "Choose the date from which this cancellation became effective.",
        });
      }
      const recordedAt = new Date().toISOString();
      const result: any = await db.transaction(async (tx) => {
        const [row] = await tx.select().from(earthworkArrangementsTable)
          .where(eq(earthworkArrangementsTable.id, id)).for("update");
        if (!row) return { status: 404, body: { error: "Arrangement not found" } };
        if (row.status === "cancelled") {
          return { status: 409, body: { error: "ARRANGEMENT_ALREADY_CANCELLED", message: "This arrangement is already cancelled. Confirm its historical effective date from the arrangement register if needed." } };
        }
        if (row.status === "rejected" || row.status === "completed") {
          return { status: 409, body: { error: "INVALID_STATUS_TRANSITION", message: `An arrangement in status "${row.status}" cannot be cancelled.` } };
        }
        const revisionHistory = appendArrangementStatusChange((row as any).revisionHistory, {
          previousStatus: row.status,
          status: "cancelled",
          effectiveFrom,
          recordedAt,
          changedBy: user?.id ?? null,
          reason: typeof reason === "string" ? reason : null,
        });
        const [updatedRow] = await tx.update(earthworkArrangementsTable).set({
          status: "cancelled",
          cancellationReason: reason?.trim() || null,
          revisionHistory,
        } as any).where(eq(earthworkArrangementsTable.id, id)).returning();
        return { status: 200, body: updatedRow };
      });
      if (result.status !== 200) return res.status(result.status).json(result.body);

      await (storage as any).logAudit({ userName: user?.fullName ?? "Unknown", userRole: user?.role ?? null,
        module: "earthwork_arrangements",
        transactionId: Number(id),
        action: "cancel",
        userId: user?.id ?? null,
        newValues: { status: "cancelled", reason, effectiveFrom },
      }).catch(() => {});

      res.json({ ok: true });
    } catch (err) {
      console.error("DELETE /api/earthwork-arrangements/:id:", err);
      res.status(500).json({ error: "Failed to cancel earthwork arrangement" });
    }
  })

app.get("/api/boq/projects/:id/arrangement-programme-allocations", async (req, res) => {
    try {
      if (!assertViewEither(req, res, "work_programme", "work_programme_review")) return;
