app.post("/api/boq/projects/:id/auto-sequence", async (req, res) => {
    try {
      if (!assertEdit(req, res, "work_programme")) return;
      const projectId = parseInt(req.params.id);
      // Scope is read below and then used to compute every generated bar.
      // Carry this token into each write so a correction cannot be silently
      // followed by writes computed from the old scope.
      const scopeVersionToken = await storage.getProjectScopeVersionToken(projectId);
      const { generateSequencedProgramme } = await import("@shared/programmeSequencer");
      const { calculateAutoDurationFull } = await import("@shared/planningEngine");

      const [items, project, , existingBars] = await Promise.all([
        storage.getBoqItemsWithRecipes(projectId),
        storage.getBoqProject(projectId),
        storage.getBoqProgramSettings(projectId),
        storage.getWorkProgramBars(projectId),
      ]);

      const workingHrs  = (project as any)?.workingHoursPerDay  ?? 8;
      const workingDays = (project as any)?.workingDaysPerMonth ?? 26;
      const totalMonths = (project as any)?.totalMonths         ?? 18;
      const projChFrom  = (project as any)?.chainageFrom        ?? 0;
      const projChTo    = (project as any)?.chainageTo          ?? null;
      // Prefer chainage-derived length if both endpoints are set
      const roadLengthKm = projChTo != null
        ? Math.max(0, projChTo - projChFrom)
        : (project as any)?.roadLengthKm ?? 0;
      const requestedFronts = Math.floor(Number(req.body?.fronts) || 0);
      const fronts = requestedFronts >= 1
        ? requestedFronts
        : Math.min(5, Math.max(2, Math.ceil((roadLengthKm || 24) / 12)));
      const _stagger = Number(req.body?.staggerMonths);
      const staggerMonths = !isNaN(_stagger) ? Math.max(0, _stagger) : 1;
      const _lag = Number(req.body?.lagMonths);
      const lagMonths = !isNaN(_lag) ? Math.max(0, _lag) : 0.25;
      const _strGroups = parseInt(req.body?.structureGroups);
      const structureGroups = _strGroups >= 1 ? _strGroups : fronts;
      const _brgGroups = parseInt(req.body?.bridgeGroups);
      const bridgeGroups = _brgGroups >= 1 ? _brgGroups : fronts;
      // Structure-front auto-splitting ("Struct. Front N" / "Bridge Grp N" bars) is disabled
      // by default — it produces incorrect results for projects that use per-location structure
      // bars imported from a schedule.
      // New clients send `disableStructureFronts: true` directly; legacy clients sent
      // `enableStructureFronts: false` (inverted). Prefer the explicit field; fall back to the
      // legacy inversion so older saved programme-settings still restore correctly.
      const disableStructureFronts = req.body?.disableStructureFronts !== undefined
        ? Boolean(req.body.disableStructureFronts)
        : req.body?.enableStructureFronts !== true;

      // dryRun=true: classify items and return diagnostics WITHOUT touching bars or DB.
      const dryRun = req.body?.dryRun === true;
      // A real auto-sequence rewrites/deletes existing schedule bars and creates
      // replacements. It is a direct schedule writer, never a revision bypass.
      if (!dryRun && sendDirectScheduleMutationBlock(
        res,
        await directScheduleMutationBlock(projectId, existingBars as any[]),
      )) return;

      // ── Instruction 029 Part A/C: real user-entered stretch rows ─────────────
      // stretches: [{ label?, chainageFrom, chainageTo, priority, manualQtyFraction? }]
      // Overlaps and malformed rows BLOCK (400); gaps are returned as warnings.
      const { validateStretches } = await import("@shared/programmeSequencer");
      const rawStretches = Array.isArray(req.body?.stretches) ? req.body.stretches : null;
      const stretches = rawStretches && rawStretches.length > 0
        ? rawStretches.map((s: any, i: number) => ({
            label: typeof s?.label === "string" && s.label.trim() ? s.label.trim().slice(0, 60) : null,
            chainageFrom: Number(s?.chainageFrom),
            chainageTo: Number(s?.chainageTo),
            priority: Number(s?.priority ?? i + 1),
            manualQtyFraction: s?.manualQtyFraction != null && Number(s.manualQtyFraction) > 0
              ? Math.min(1, Number(s.manualQtyFraction))
              : null,
            // 030A — optional per-stretch side, validated; invalid values → null
            side: isBarSide(s?.side) ? s.side : null,
            // 029B — front label + display-only order tiebreaker
            front: typeof s?.front === "string" && s.front.trim() ? s.front.trim().slice(0, 60) : null,
            executionOrder: Number.isFinite(Number(s?.executionOrder)) && Number(s.executionOrder) >= 1
              ? Math.floor(Number(s.executionOrder))
              : null,
            // 029C — optional planned width (m) for the width-matched LHS/RHS split
            plannedWidthM: Number.isFinite(Number(s?.plannedWidthM)) && Number(s.plannedWidthM) > 0
              ? Number(s.plannedWidthM)
              : null,
          }))
        : null;
      let stretchGaps: Array<{ from: number; to: number }> = [];
      if (stretches) {
        const v = validateStretches(stretches, projChFrom, projChTo);
        if (v.errors.length > 0 || v.overlaps.length > 0) {
          return res.status(400).json({
            error: "STRETCH_VALIDATION_FAILED",
            message: [
              ...v.errors,
              ...v.overlaps.map(o =>
                `${o.aLabel} and ${o.bLabel} overlap between Km ${o.overlapFrom} and Km ${o.overlapTo}`),
            ].join("; "),
            validationErrors: v.errors,
            overlaps: v.overlaps,
          });
        }
        stretchGaps = v.gaps;
      }

      // ── Instruction 032 Part I: eligible-scope coverage for allocation ──────
      // Confirmed scope segments drive per-item clipping: bars only over
      // eligible coverage, blocked coverage unprogrammed, excluded/withdrawn
      // coverage receives nothing. When the project has no confirmed working
      // reaches, scope setup is not in use → legacy allocation unchanged.
      const scopeSegmentsRaw = await storage.getProjectScopeSegments(projectId);
      const scopeSegs: ScopeSegmentLike[] = (scopeSegmentsRaw as any[]).map(s => ({
        id: s.id, segmentType: s.segmentType, chainageFrom: Number(s.chainageFrom), chainageTo: Number(s.chainageTo),
        side: s.side, status: s.status, applicability: s.applicability,
        categoryIds: safeIdList(s.categoryIds),
        itemIds: safeIdList(s.itemIds),
        effectiveFrom: s.effectiveFrom, effectiveTo: s.effectiveTo, label: s.label, reason: s.reason,
      }));
      const scopeActive = scopeSegs.some(s => s.segmentType === "working_reach" && (s.status ?? "confirmed") === "confirmed")
        && scopeSegs.some(s => s.segmentType !== "working_reach" || true); // reaches alone still define eligible coverage
      // Date semantics for PLANNING (not DPRs): onDate is deliberately null →
      // every recorded withdrawal applies (never programme withdrawn scope,
      // even if its effective date is in the future) and every un-released
      // temporary block stays blocked (blocked qty remains unprogrammed until
      // the block is released and the programme regenerated). Conservative by
      // design — a programme should never promise work on doubtful coverage.
      const scopeItemCache = new Map<number, ReturnType<typeof resolveEligibleScope>>();
      const scopeForItem = (boqItemId: number) => {
        let r = scopeItemCache.get(boqItemId);
        if (!r) {
          const it: any = (items as any[]).find(x => x.id === boqItemId);
          r = resolveEligibleScope(scopeSegs, {
            boqItemId,
            categoryId: it?.categoryId ?? null,
            isLinear: true, // scopeCoverage is only consulted for pavement-track (linear) bars
            onDate: null,
          });
          scopeItemCache.set(boqItemId, r);
        }
        return r;
      };

      // Persist sequence options so the UI can pre-populate the dialog next time.
      // Skipped in dry-run mode so the diagnostic call doesn't mutate saved settings.
      // 029C: DEFERRED until after the overallocation guard — a blocked run must
      // leave project state completely untouched.
      const sequenceSettings = {
        sequenceOptions: {
          fronts: requestedFronts >= 1 ? fronts : null,
          staggerMonths,
          lagMonths,
          structureGroups: _strGroups >= 1 ? structureGroups : null,
          bridgeGroups: _brgGroups >= 1 ? bridgeGroups : null,
          enableStructureFronts: !disableStructureFronts,
          stretches: stretches ?? null, // Instruction 029 — restore the stretch table next open
          // Scope-load provenance: fingerprint of the confirmed Project Scope
          // at the moment the stretches were loaded from it. Lets the dialog
          // warn "scope has changed since these stretches were loaded" — no
          // silent regeneration, ever. null = stretches not scope-loaded.
          scopeFingerprint: typeof req.body?.scopeFingerprint === "string" && req.body.scopeFingerprint
            ? String(req.body.scopeFingerprint).slice(0, 4000)
            : null,
        },
      } as any;

      // Non-destructive rerun: only remove previously auto-generated bars so that
      // any bars the planner manually placed (source = "manual") are preserved.
      // The reach-label fallback catches legacy bars created before the source column existed.
      const AUTO_LABEL_RE = /^(Full Length|Structures|Bridges|Reach \d+|Struct\. Front \d+|Bridge Grp \d+)$/;

      // When structure fronts are disabled, pre-delete auto-sequence bars that belong to
      // structure-type BOQ items NOW — outside the "no bars" safety guard — so that old
      // linear bars don't persist for items that already have imported structure_location bars.
      // Dry-run skips all deletions so the DB remains untouched.
      // 029C: deletion itself is DEFERRED until after the overallocation guard —
      // only the candidate list is computed here.
      const structurePreDeleteIds: number[] = [];
      if (disableStructureFronts) {
        // Items with at least one structure_import bar are implicitly structure-planned
        // even if planningWorkType was never set manually.
        const structureImportIds = new Set(
          (existingBars as any[])
            .filter((b) => b.source === "structure_import")
            .map((b) => b.boqItemId),
        );
        const structureItemIds = new Set([
          ...(items as any[])
            .filter((it) => isStructureOrLocationScheduledItem(it, { hasStructureImportBar: structureImportIds.has(it.id) }))
            .map((it) => it.id),
          ...structureImportIds,
        ]);
        if (structureItemIds.size > 0) {
          const structureAutoBars = (existingBars as any[]).filter(
            (b) => structureItemIds.has(b.boqItemId) &&
                   (b.source === "auto-sequence" || b.source === "auto_generate" || !b.source ||
                    (b.source === "manual" && AUTO_LABEL_RE.test(b.reachLabel ?? ""))),
          );
          structurePreDeleteIds.push(...structureAutoBars.map((b: any) => b.id));
        }
      }

      // Derive structure-import item IDs for the seqItems filter below.
      // We recompute here (outside the if-block) so it's always available.
      const _structureImportIds = new Set(
        (existingBars as any[])
          .filter((b) => b.source === "structure_import")
          .map((b) => b.boqItemId),
      );

      // Build sequencer input — when structure fronts are disabled, exclude structure-type
      // items entirely so the sequencer only schedules road/linear work. Their bars were
      // already pre-deleted above; any imported structure_location bars are untouched.
      // skippedItems captures every excluded item with a human-readable reason so the UI
      // can surface a useful actionable message rather than a bare count.
      const skippedItems: { id: number; description: string; reason: string }[] = [];

      const seqItems = (items as any[])
        .filter((it) => {
          if (it.includedInPlanning === false) {
            skippedItems.push({ id: it.id, description: ((it.description ?? "") as string).slice(0, 80), reason: "Excluded from planning (non-construction item)" });
            return false;
          }
          if ((it.currentQty ?? 0) <= 0) {
            skippedItems.push({ id: it.id, description: ((it.description ?? "") as string).slice(0, 80), reason: "Missing quantity — currentQty is 0" });
            return false;
          }
          if (
            disableStructureFronts &&
            isStructureOrLocationScheduledItem(it, { hasStructureImportBar: _structureImportIds.has(it.id) })
          ) {
            skippedItems.push({ id: it.id, description: ((it.description ?? "") as string).slice(0, 80), reason: "Structure/point-location item — bars imported from structure schedule" });
            return false;
          }
          return true;
        })
        .map((it) => {
          const equipment = ((it.equipment ?? []) as any[]).map((e) => ({
            name: e.equipmentName,
            outputUnit: e.outputUnit ?? null,
            outputTheoretical: e.outputTheoretical ?? null,
            outputEfficiency: e.outputEfficiency ?? null,
            standardOutputs: e.standardOutputs ?? null,
            // Item-specific hrs/BOQ-unit rate — last-resort output source so contractor/custom
            // equipment or SDB equipment used for a unit the master doesn't define still
            // contributes to the bottleneck instead of silently dropping out.
            qtyPerBoqUnit: e.qtyPerBoqUnit != null ? Number(e.qtyPerBoqUnit) : null,
            count: e.count ?? 1,
          }));
          const dur = calculateAutoDurationFull(
            it.currentQty ?? 0,
            it.canonicalUnit ?? it.unit ?? "",
            equipment,
            workingHrs,
            workingDays,
            null,
            null,
          );
          return {
            boqItemId: it.id,
            description: it.description ?? "",
            unit: it.canonicalUnit ?? it.unit ?? "",
            totalQty: it.currentQty ?? 0,
            fullDurationMonths: dur.months > 0 ? dur.months : 1,
            // Pass stored planningWorkType so user-overridden classifications are respected
            planningWorkType: (it.planningWorkType === "road" || it.planningWorkType === "structure")
              ? it.planningWorkType as "road" | "structure"
              : undefined,
            // Pass workCategory so the sequencer can use it as a fallback classifier
            // when classifyWorkType cannot match description+unit (e.g. "1 Cum" units).
            workCategory: it.workCategory ?? null,
            // 029C — layerConfig classification drives the automatic category
            // allocation rule (earthwork estimate / MT proportional / pavement).
            layerType: (it.layerConfig as any)?.layerType ?? null,
            // Shoulder sequencing — planner-confirmed layer class (remembered on regen).
            shoulderLayerClass: (it as any).shoulderLayerClass ?? null,
          };
        });

      const {
        bars,
        unclassifiedItemIds,
        unclassifiedItems: seqUnclassifiedItems,
        diagnostics: seqDiagnostics,
        scopeSummary: seqScopeSummary,
      } = generateSequencedProgramme(seqItems, {
        fronts,
        totalMonths,
        roadLengthKm,
        chainageStartKm: projChFrom,
        staggerMonths,
        lagMonths,
        structureGroups,
        bridgeGroups,
        disableStructureFronts,
        ...(stretches ? { stretches } : {}), // Instruction 029 — real stretch table
        // Instruction 032 — clip road bars to each item's eligible executable scope
        ...(scopeActive ? {
          scopeCoverage: (boqItemId: number, stretch: { chainageFrom: number; chainageTo: number; side?: string | null }) => {
            const scope = scopeForItem(boqItemId);
            if (!scope.hasWorkingReaches) return null;
            const cov = coverageForStretch(scope, stretch);
            // No restriction hit within this stretch → legacy path for the stretch
            // ONLY if the whole stretch is executable (eligible == stretch coverage
            // with no excluded/blocked/withdrawn portions).
            return cov;
          },
        } : {}),
      });

      // ── Instruction 029 Part D: regeneration PLAN (computed for dry-run AND real run) ──
      // Never silently destroy bars linked to real work: allocation rows cascade-delete
      // with their bar, so linked bars are reconciled in place (id preserved) or blocked.
      // Instruction 030A extends the same protection to DPR progress entries that
      // reference a bar via progress_entries.programmeBarId — those bars are also
      // reconciled in place or blocked, never silently deleted.
      const AUTO_MATCH = (b: any) =>
        isAutoSequenceManagedBar({
          source: b.source,
          revisionHistory: b.revisionHistory,
          legacyAutoLabel: AUTO_LABEL_RE.test(b.reachLabel ?? ""),
        });
      const regenAutoBars = (existingBars as any[]).filter(AUTO_MATCH);
      const regenAllocRows = await storage.getArrangementProgrammeAllocationsForProject(projectId);
      const allocsByBarId = new Map<number, any[]>();
      for (const al of (regenAllocRows as any[])) {
        if (!allocsByBarId.has(al.programmeBarId)) allocsByBarId.set(al.programmeBarId, []);
        allocsByBarId.get(al.programmeBarId)!.push(al);
      }
      // 030A: DPR-linked bars (any submitted or draft progress link) are protected too.
      const regenProgressLinks = await storage.getProgressLinksForProject(projectId);
      const dprLinksByBarId = new Map<number, { submittedCount: number; draftCount: number }>();
      for (const pl of regenProgressLinks) {
        if (pl.submittedCount > 0 || pl.draftCount > 0) {
          dprLinksByBarId.set(pl.programmeBarId, { submittedCount: pl.submittedCount, draftCount: pl.draftCount });
        }
      }
      const chOverlap = (a: any, b: any) => {
        const af = Number(a.chainageFrom), at = Number(a.chainageTo);
        const bf = Number(b.chainageFrom), bt = Number(b.chainageTo);
        if (![af, at, bf, bt].every(Number.isFinite)) return 0;
        return Math.max(0, Math.min(at, bt) - Math.max(af, bf));
      };
      const reconcilePlan: Array<{ barId: number; newBarIdx: number; reachLabel: string | null }> = [];
      const blockedBars: Array<{ barId: number; boqItemId: number; reachLabel: string | null; arrangementIds: number[]; dprProgressCount?: number }> = [];
      {
        const consumed = new Set<number>();
        for (const b of regenAutoBars) {
          const linkedAllocs = allocsByBarId.get(b.id);
          const dprLink = dprLinksByBarId.get(b.id);
          const isProtected = (linkedAllocs && linkedAllocs.length > 0) || !!dprLink;
          if (!isProtected) continue; // unprotected — normal delete path
          let bestIdx = -1, bestOv = 0;
          bars.forEach((nb, idx) => {
            if (consumed.has(idx) || nb.boqItemId !== b.boqItemId) return;
            const ov = chOverlap(nb, b);
            if (ov > bestOv) { bestOv = ov; bestIdx = idx; }
          });
          if (bestIdx >= 0 && bestOv > 0.0005) {
            consumed.add(bestIdx);
            reconcilePlan.push({ barId: b.id, newBarIdx: bestIdx, reachLabel: bars[bestIdx].reachLabel });
          } else {
            blockedBars.push({
              barId: b.id,
              boqItemId: b.boqItemId,
              reachLabel: b.reachLabel ?? null,
              arrangementIds: Array.from(new Set((linkedAllocs ?? []).map((al: any) => al.arrangementId))),
              ...(dprLink ? { dprProgressCount: dprLink.submittedCount + dprLink.draftCount } : {}),
            });
          }
        }
      }
      const consumedNewBars = new Set(reconcilePlan.map(p => p.newBarIdx));

      // ── 029C Part C #16c: a manually overridden quantity on a reconciled bar
      // is never silently overwritten by the automatic calculation — the bar
      // keeps its quantity and the conflict is surfaced.
      const regenBarById = new Map((regenAutoBars as any[]).map((b: any) => [b.id, b]));
      const qtyConflicts: Array<{ barId: number; boqItemId: number; reachLabel: string | null; keptQty: number; autoQty: number }> = [];
      for (const p of reconcilePlan) {
        const ex = regenBarById.get(p.barId);
        if (ex?.isQtyOverride) {
          qtyConflicts.push({
            barId: p.barId, boqItemId: ex.boqItemId, reachLabel: ex.reachLabel ?? null,
            keptQty: Number(ex.plannedQty ?? 0), autoQty: Number(bars[p.newBarIdx].plannedQty ?? 0),
          });
        }
      }
      const qtyConflictBarIds = new Set(qtyConflicts.map(c => c.barId));

      // ── 029C Part D/F: allocation preview + overallocation guard ────────────
      // Effective planned qty per item after this run = new/reconciled bars
      // (manual-override reconciles keep their existing qty) + blocked bars
      // kept unchanged + untouched manual bars.
      const itemByIdAlloc = new Map((items as any[]).map((it: any) => [it.id, it]));
      const blockedIdSet = new Set(blockedBars.map(b => b.barId));
      const reconcileByNewIdx = new Map(reconcilePlan.map(p => [p.newBarIdx, p.barId]));
      const allocTotals = new Map<number, number>();
      const allocRows = new Map<number, Array<Record<string, unknown>>>();
      const addAlloc = (itemId: number, qty: number, row?: Record<string, unknown>) => {
        allocTotals.set(itemId, (allocTotals.get(itemId) ?? 0) + qty);
        if (row) {
          if (!allocRows.has(itemId)) allocRows.set(itemId, []);
          allocRows.get(itemId)!.push(row);
        }
      };
      bars.forEach((b: any, idx: number) => {
        const reconciledBarId = reconcileByNewIdx.get(idx);
        const keepsOverride = reconciledBarId != null && qtyConflictBarIds.has(reconciledBarId);
        const qty = keepsOverride ? Number(regenBarById.get(reconciledBarId)?.plannedQty ?? 0) : Number(b.plannedQty ?? 0);
        addAlloc(b.boqItemId, qty, {
          reachLabel: b.reachLabel, side: b.side ?? null, qty: +qty.toFixed(3),
          rule: keepsOverride ? "manual-override-kept" : (b.allocationRule ?? "pavement"),
          note: b.allocationNote ?? null,
        });
      });
      for (const b of regenAutoBars as any[]) {
        if (blockedIdSet.has(b.id)) {
          addAlloc(b.boqItemId, Number(b.plannedQty ?? 0), {
            reachLabel: b.reachLabel ?? null, side: b.side ?? null,
            qty: +Number(b.plannedQty ?? 0).toFixed(3), rule: "kept-blocked", note: null,
          });
        }
      }
      for (const b of existingBars as any[]) {
        if (!AUTO_MATCH(b)) addAlloc(b.boqItemId, Number(b.plannedQty ?? 0)); // untouched manual bars count toward totals
      }
      const allocationPreview: Array<Record<string, unknown>> = [];
      const overallocatedItems: Array<{ boqItemId: number; description: string; boqQty: number; planned: number; excess: number }> = [];
      const uniqueItemIds = Array.from(allocTotals.keys());
      for (const itemId of uniqueItemIds) {
        const it = itemByIdAlloc.get(itemId);
        if (!it) continue;
        const boqQty = Number(it.currentQty ?? 0);
        const total = allocTotals.get(itemId) ?? 0;
        const tolerance = Math.max(0.5, boqQty * 0.001);
        const over = total - boqQty;
        if (over > tolerance) {
          overallocatedItems.push({
            boqItemId: itemId, description: ((it.description ?? "") as string).slice(0, 100),
            boqQty, planned: +total.toFixed(3), excess: +over.toFixed(3),
          });
        }
        // Instruction 032 — scope figures for this item (when scope is active).
        const sc = seqScopeSummary?.[itemId];
        allocationPreview.push({
          boqItemId: itemId,
          description: ((it.displayName ?? it.description ?? "") as string).slice(0, 100),
          unit: it.canonicalUnit ?? it.unit ?? "",
          boqQty,
          totalAllocated: +total.toFixed(3),
          unallocated: +Math.max(0, boqQty - total).toFixed(3),
          overallocated: +Math.max(0, over).toFixed(3),
          programmedPct: boqQty > 0 ? +Math.min(100, (total / boqQty) * 100).toFixed(1) : null,
          rows: allocRows.get(itemId) ?? [],
          ...(sc ? {
            scope: {
              eligibleSideLenKm: sc.eligibleSideLenKm,
              blockedSideLenKm: sc.blockedSideLenKm,
              excludedSideLenKm: sc.excludedSideLenKm,
              withdrawnSideLenKm: sc.withdrawnSideLenKm,
              blockedQty: sc.blockedQty,          // in balance, NOT programmed
              fullyExcluded: sc.fullyExcluded,
            },
          } : {}),
        });
      }

      // 029C Part D: block persistence when any item overshoots its BOQ quantity
      // beyond tolerance — unless an explicit override with reason is supplied.
      const overrideReason = typeof req.body?.overallocationOverrideReason === "string"
        ? req.body.overallocationOverrideReason.trim()
        : "";
      if (!dryRun && overallocatedItems.length > 0 && !overrideReason) {
        return res.status(400).json({
          error: "OVERALLOCATION_BLOCKED",
          message: `Planned quantity exceeds the BOQ quantity for ${overallocatedItems.length} item(s). Reduce the allocation or provide an explicit override reason.`,
          overallocatedItems,
          allocationPreview,
        });
      }
      if (!dryRun && overallocatedItems.length > 0 && overrideReason) {
        const authUser = (req as any).authUser;
        await storage.logAudit({
          module: "work_programme",
          transactionId: projectId,
          action: "overallocation_override",
          userId: authUser?.id ?? null,
          userName: authUser?.name ?? authUser?.username ?? "unknown",
          userRole: authUser?.role ?? null,
          reason: overrideReason,
          newValues: { overallocatedItems },
        } as any).catch((e: any) => console.error("auto-sequence overallocation audit:", e?.message ?? e));
      }

      // 029C: deferred mutations — only run once the overallocation guard has
      // passed (or been explicitly overridden), so a blocked run changes nothing.
      const regenSummary = {
        toRecreate: regenAutoBars.length - reconcilePlan.length - blockedBars.length,
        preservedUpdated: reconcilePlan.length,
        blocked: blockedBars,
        newBars: bars.length,
        stretchGaps, // Instruction 029 Part C — non-blocking gap warnings
        // 029C — compact quantity preview + conflicts, shown before confirm
        allocationPreview,
        overallocatedItems,
        qtyConflicts,
        // Instruction 032 — scope basis of this run (null = scope not in use)
        scopeApplied: scopeActive,
        scopeSummary: seqScopeSummary ?? null,
      };

      // ── Dry-run: return per-item classification trace without touching bars or DB ──
      if (dryRun) {
        // Per-reach scope breakdown for the review panel: gross chainage vs
        // eligible portions vs excluded/blocked/withdrawn side-lengths.
        // Item-agnostic (all-linear applicability) — it shows what the corridor
        // itself permits; item-specific exclusions still apply during allocation.
        let stretchScope: any[] | null = null;
        if (scopeActive && stretches) {
          const generalScope = resolveEligibleScope(scopeSegs, {
            boqItemId: null, categoryId: null, isLinear: true, onDate: null,
          });
          if (generalScope.hasWorkingReaches) {
            stretchScope = stretches.map((st: any, i: number) => {
              const cov = coverageForStretch(generalScope, st);
              return {
                label: st.label ?? `Stretch ${i + 1}`,
                chainageFrom: st.chainageFrom,
                chainageTo: st.chainageTo,
                side: st.side ?? null,
                eligibleRanges: cov.subRanges.map(r => ({ from: r.from, to: r.to })),
                eligibleSideLenKm: cov.eligibleSideLenKm,
                blockedSideLenKm: cov.blockedSideLenKm,     // temporary blocks — withheld, not removed
                excludedSideLenKm: cov.excludedSideLenKm,   // no-scope
                withdrawnSideLenKm: cov.withdrawnSideLenKm,
                contractualSideLenKm: cov.contractualSideLenKm, // qty basis = eligible + blocked
              };
            });
          }
        }
        const itemById = new Map((items as any[]).map((it: any) => [it.id, it]));
        const diagItems = seqDiagnostics.map((d) => {
          const raw = itemById.get(d.boqItemId);
          return {
            id: d.boqItemId,
            itemCode: raw?.itemCode ?? null,
            description: d.description,          // full BOQ description — what classification receives
            shortName: raw?.itemName ?? raw?.displayName ?? null,  // display-only, never used for classification
            rawUnit: raw?.unit ?? d.unit,         // unit as stored in DB
            canonicalUnit: raw?.canonicalUnit ?? d.unit,  // normalised unit passed to sequencer
            workCategory: d.workCategory,         // saved category on BOQ item
            planningWorkType: d.planningWorkType ?? null,  // user-overridden work type (if any)
            resolvedWorkType: d.resolvedWorkType,  // what resolveWorkType() returned
            track: d.track,                        // "pavement" | "structure" | "bridge" | "other"
            stage: d.wouldHaveBar ? d.stage : null,
            wouldHaveBar: d.wouldHaveBar,
            skipReason: d.skipReason ?? null,
          };
        });
        return res.json({
          dryRun: true,
          fieldAudit: {
            note: "Classification always reads item.description (full BOQ text). item_name/itemName/shortName is display-only.",
            classificationField: "description",
            shortNameField: "itemName (display label only — Gantt rows, DPR selectors, BOM breakdown)",
          },
          projectId,
          fronts,
          totalMonths,
          roadLengthKm,
          skippedBeforeSequencer: skippedItems,
          sequencerItems: diagItems,
          wouldCreateBars: bars.length,
          unclassifiedCount: unclassifiedItemIds.length,
          // Instruction 029 Part D — pre-regeneration summary for explicit confirmation
          regenSummary: { ...regenSummary, stretchScope },
        });
      }

      // SAFETY: never wipe the existing programme unless we actually built new bars.
      if (!bars.length) {
        return res.status(422).json({
          error: `No bars generated (items with qty: ${seqItems.length}, fronts: ${fronts}). ` +
                 `Your existing programme was left untouched. Make sure BOQ items have a current quantity > 0.`,
          itemsConsidered: seqItems.length,
          fronts,
          unclassifiedItemIds,
        });
      }

      // Build the full new set first; only then replace the old bars.  The
      // arrays are handed to one storage transaction below, which holds the
      // project mutex across settings, deletes, updates, and inserts.
      const programmeUpdates: Array<{ id: number; data: any }> = [];
      const programmeDeleteIds = new Set<number>(structurePreDeleteIds);
      const programmeInserts: any[] = [];
      let created = 0;
      const insertErrors: string[] = [];
      // ── Instruction 029 Part D: APPLY the regeneration plan computed above ──
      // 1. Reconcile protected bars in place (id + arrangement links preserved).
      for (const p of reconcilePlan) {
        const nb = bars[p.newBarIdx];
        // 029C #16c: bars with a manual quantity override keep their quantity —
        // the automatic calculation never silently overwrites it (surfaced in
        // regenSummary.qtyConflicts instead).
        const keepQty = qtyConflictBarIds.has(p.barId);
        const projectStartDate = (project as any)?.startDate ?? null;
        const calendarSchedule = projectStartDate ? {
          startDate: (() => {
            const d = monthIndexToDateCal(nb.startMonth, projectStartDate);
            return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
          })(),
          endDate: (() => {
            const d = displayFinishDateCal(nb.endMonth, projectStartDate, nb.startMonth);
            return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
          })(),
        } : {};
        programmeUpdates.push({ id: p.barId, data: {
          reachLabel: nb.reachLabel,
          chainageFrom: nb.chainageFrom,
          chainageTo: nb.chainageTo,
          startMonth: nb.startMonth,
          endMonth: nb.endMonth,
          ...calendarSchedule,
          ...(keepQty ? {} : { plannedQty: nb.plannedQty, isQtyOverride: nb.isQtyOverride }),
          isDurationOverride: nb.isDurationOverride,
          source: "auto-sequence",
          ...(nb.sequenceOrder != null ? { sequenceOrder: nb.sequenceOrder } : {}),
          // 030A: carry the stretch side onto reconciled bars — but never wipe an
          // explicitly-set side back to null just because the stretch omitted it.
          ...((nb as any).side != null ? { side: (nb as any).side } : {}),
          // 029B: front + display order carry the same never-wipe rule.
          ...((nb as any).executionFront != null ? { executionFront: (nb as any).executionFront } : {}),
          ...((nb as any).executionOrder != null ? { executionOrder: (nb as any).executionOrder } : {}),
        } as any });
      }
      // 2. Delete only unprotected matched bars (blocked bars stay untouched).
      const protectedIds = new Set([
        ...reconcilePlan.map(p => p.barId),
        ...blockedBars.map(p => p.barId),
      ]);
      for (const b of regenAutoBars) {
        if (protectedIds.has(b.id)) continue; // preserved in place or blocked — never delete
        programmeDeleteIds.add(b.id);
      }
      // 3. Insert the remaining new bars. (`created` counts INSERTS only —
      // reconciled bars are reported separately as regenSummary.preservedUpdated.)
      for (let i = 0; i < bars.length; i++) {
        if (consumedNewBars.has(i)) continue; // applied as in-place update, not an insert
        // 029C: allocationRule/allocationNote are preview-only fields, not DB columns.
        const { allocationRule: _ar, allocationNote: _an, ...b } = bars[i] as any;
        programmeInserts.push({ ...b, boqProjectId: projectId } as any);
      }

      const mutation = await storage.applyWorkProgrammeMutation(
        projectId,
        {
          settings: sequenceSettings,
          needsReviewItemIds: unclassifiedItemIds,
          deleteBarIds: Array.from(programmeDeleteIds),
          updates: programmeUpdates,
          inserts: programmeInserts,
        },
        scopeVersionToken,
      );
      created = programmeInserts.length;
      const deletedCount = Number(mutation?.deleted ?? 0);
      // Use the sequencer's rich unclassified-item records.
      // Each record already has: boqItemId, description, workCategory, unit,
      // resolvedWorkType, skipReason — built inside generateSequencedProgramme.
      const unclassifiedItems = seqUnclassifiedItems.map((u) => {
        skippedItems.push({
          id: u.boqItemId,
          description: u.description.slice(0, 80),
          reason: u.skipReason,
        });
        return {
          id: u.boqItemId,
          description: u.description.slice(0, 120),
          workCategory: u.workCategory,
          unit: u.unit,
          resolvedWorkType: u.resolvedWorkType,
          skipReason: u.skipReason,
        };
      });

      res.json({
        success: true,
        fronts,
        totalMonths,
        // Total bars now representing the programme = fresh inserts + in-place reconciles.
        bars: created + reconcilePlan.length,
        itemsConsidered: seqItems.length,
        unclassifiedCount: unclassifiedItemIds.length,
        unclassifiedItemIds,
        unclassifiedItems,
        // skippedItems lists every item that did NOT get a bar, with an actionable reason:
        //   "Excluded from planning"    — includedInPlanning=false (non-construction charge items)
        //   "Missing quantity"          — currentQty=0 or null
        //   "Structure/point-location"  — structure schedule items excluded from linear sequencer
        //   "Work type unresolved"      — no recipe match; needs workCategory in BOQ Item Review
        skippedItems,
        skippedCount: skippedItems.length,
        errorCount: insertErrors.length,
        sampleError: insertErrors[0] ?? null,
        // Instruction 029: what actually happened to protected bars + gap warnings.
        // inserted/deleted are the real DB operations; preservedUpdated bars kept their ids.
        regenSummary: { ...regenSummary, inserted: created, deleted: deletedCount },
      });
    } catch (err: any) {
      console.error("auto-sequence:", err);
      if (err?.code === "SCOPE_CHANGED_DURING_PLANNING" || (ScopeChangedDuringPlanningError && err instanceof ScopeChangedDuringPlanningError)) {
        return res.status(409).json({ code: "SCOPE_CHANGED_DURING_PLANNING", message: err.message });
      }
      res.status(500).json({ error: `Failed to auto-sequence programme: ${err?.message ?? String(err)}` });
    }
  })

app.post("/api/boq/projects/:id/parse-structure-schedule", structureUpload.single("file"), async (req, res) => {
    try {
      if (!assertEdit(req, res, "work_programme")) return;
      if (!req.file) return res.status(400).json({ error: "No file uploaded. Send an Excel file in the 'file' field." });
      const projectId = parseInt(req.params.id);

      const allItems = await storage.getBoqItems(projectId) as any[];
      const itemByCode = new Map(allItems.map((it: any) => [String(it.itemCode ?? "").trim().toLowerCase(), it]));
      const itemByCodeSubItem = new Map<string, any>();
      for (const it of allItems) {
        if ((it as any).boqSubItem) {
          const k = `${String((it as any).itemCode ?? "").trim().toLowerCase()}::${String((it as any).boqSubItem ?? "").trim().toLowerCase()}`;
          itemByCodeSubItem.set(k, it);
        }
      }

      // Server-side XLSX parsing
      const { read, utils } = await import("xlsx");
      const wb = read(req.file.buffer, { type: "buffer", cellDates: true });

      // ── Sheet detection ────────────────────────────────────────────────────────
      // Preferred: matrix-format sheets (one column per structure, BOQ items as rows).
      // Fallback: legacy flat format — one row per structure×item, sheet named
      // "Structure_Schedule_Import".
      // Frozen 4-sheet Structure Schedule Import format (V1 planning boundary):
      // only these exact sheet names are recognised as structure/location schedules.
      const MATRIX_SHEETS = [
        "Culverts", "Drains_Retaining_Walls", "Minor_Bridges", "Major_Bridges",
      ];
      const LEGACY_SHEET = "Structure_Schedule_Import";

      const presentMatrixSheets = MATRIX_SHEETS.filter(s => wb.SheetNames.includes(s));
      const hasLegacySheet = wb.SheetNames.includes(LEGACY_SHEET);

      if (!presentMatrixSheets.length && !hasLegacySheet) {
        return res.status(422).json({
          error: "No recognised structure schedule sheet found in this workbook.",
          availableSheets: wb.SheetNames,
          hint: `Use the frozen Structure Schedule Import format with sheet(s) named: ${MATRIX_SHEETS.join(", ")} — ` +
                `or the legacy flat format with a sheet named "${LEGACY_SHEET}".`,
        });
      }

      // ── Shared BOQ matcher (used by both parsers) ──────────────────────────────
      function matchBoqItem(boqCode: string, boqSubItem: string, boqDesc: string): any {
        let found: any = null;
        if (boqCode && boqSubItem) {
          const k = `${boqCode.trim().toLowerCase()}::${boqSubItem.trim().toLowerCase()}`;
          found = itemByCodeSubItem.get(k) ?? null;
        }
        if (!found && boqCode) {
          found = itemByCode.get(boqCode.trim().toLowerCase()) ?? null;
          if (!found) {
            const stripped = boqCode.replace(/^0+/, "").trim().toLowerCase();
            found = allItems.find((it: any) =>
              String(it.itemCode ?? "").replace(/^0+/, "").trim().toLowerCase() === stripped
            ) ?? null;
          }
        }
        if (!found && boqDesc) {
          const needle = boqDesc.toLowerCase().slice(0, 40);
          found = allItems.find((it: any) =>
            (it.description ?? "").toLowerCase().includes(needle)
          ) ?? null;
        }
        return found;
      }

      // BC / wearing-coat quantities against pipe culverts are unusual — warn.
      const BC_PATTERN = /wearing\s*coat|bc\s+over|bituminous\s+concrete\s+over|bc\s+on\s+slab/i;
      const PIPE_CULVERT_PATTERN = /pipe\s+culvert|np[23]\s+pipe|rcc\s+pipe/i;

      // ── Matrix-format parser ───────────────────────────────────────────────────
      // Sheet layout:
      //   Row 1  (header):      BOQ Code | BOQ Sub Item | BOQ Description | UOM | <structId1> | <structId2> …
      //   Row 2  (meta):        Structure Type | | | | <type1> | <type2> …
      //   Row 3  (meta):        Chainage From  | | | | <from1> | <from2> …
      //   Row 4  (meta):        Chainage To    | | | | <to1>   | <to2>   … (optional for point items)
      //   Rows 5+ (data):       <code> | <sub> | <desc> | <uom> | <qty1> | <qty2> …
      //   Empty qty cells → skip that structure×item combination.
      //
      // Chainage is NEVER silently defaulted to 0: a structure column with no
      // resolvable "Chainage From" value is left with chainageFromKm = null and
      // every row for that column is flagged chainageMissing = true, which the
      // write path turns into needsReview = true instead of a fabricated 0.00 km.
      // Point items (e.g. dissipation chambers) may omit "Chainage To" entirely —
      // chainageToKm then falls back to chainageFromKm for that column.

      function parseMatrixSheet(sheetName: string): { rows: any[]; warnings: string[] } {
        const ws = wb.Sheets[sheetName];
        const raw: any[][] = utils.sheet_to_json(ws, { header: 1, defval: "", raw: false }) as any[][];
        if (!raw.length) return { rows: [], warnings: [`Sheet "${sheetName}" is empty — skipped.`] };

        const localWarnings: string[] = [];

        // Find the header row: first row whose col-0 looks like "BOQ Code"
        let hdrIdx = raw.findIndex(r =>
          /boq.?code|item.?code/i.test(String(r[0] ?? "").trim()),
        );
        if (hdrIdx < 0) hdrIdx = 0; // assume first row

        const hdrRow = raw[hdrIdx];
        // Structure IDs from col 4 onward
        const structIds: string[] = [];
        for (let c = 4; c < hdrRow.length; c++) {
          structIds.push(String(hdrRow[c] ?? "").trim());
        }
        const structCount = structIds.filter(Boolean).length;
        if (!structCount) {
          localWarnings.push(`Sheet "${sheetName}": no structure columns found after column D — skipped.`);
          return { rows: [], warnings: localWarnings };
        }

        // Read metadata rows (Structure Type, Chainage From, Chainage To) immediately
        // after the header. Header text is normalized (lowercased, non-alphanumeric
        // stripped) before matching so variants like "Chainage (Km)" or "Chainage in Km"
        // are still recognized — same approach as normHeader() in the legacy parser
        // below. See shared/structureImportLabels.ts for the matching logic + tests.
        const structTypes: string[] = new Array(structIds.length).fill("");
        const chainageFromKm: (number | null)[] = new Array(structIds.length).fill(null);
        const chainageToKm: (number | null)[]   = new Array(structIds.length).fill(null);
        let dataStart = hdrIdx + 1;
        let foundStructureTypeRow = false;
        let foundChainageFromRow = false;
        let foundChainageToRow = false;

        for (let ri = hdrIdx + 1; ri < Math.min(hdrIdx + 7, raw.length); ri++) {
          const c0Raw = String(raw[ri][0] ?? "");
          if (isStructureTypeLabel(c0Raw)) {
            foundStructureTypeRow = true;
            for (let c = 4; c < raw[ri].length; c++) {
              if (c - 4 < structIds.length) structTypes[c - 4] = String(raw[ri][c] ?? "").trim();
            }
            dataStart = Math.max(dataStart, ri + 1);
          } else if (isChainageToLabel(c0Raw)) {
            // Checked before isChainageFromLabel() since "Chainage To" is more specific
            // and isChainageFromLabel() would otherwise never see it (mutually exclusive
            // prefixes, but keep the more specific check first for clarity/safety).
            foundChainageToRow = true;
            for (let c = 4; c < raw[ri].length; c++) {
              if (c - 4 < structIds.length) {
                const cellStr = String(raw[ri][c] ?? "").trim();
                if (cellStr) {
                  const v = parseFloat(cellStr.replace(/,/g, ""));
                  chainageToKm[c - 4] = isNaN(v) ? null : v;
                }
              }
            }
            dataStart = Math.max(dataStart, ri + 1);
          } else if (isChainageFromLabel(c0Raw)) {
            foundChainageFromRow = true;
            for (let c = 4; c < raw[ri].length; c++) {
              if (c - 4 < structIds.length) {
                const cellStr = String(raw[ri][c] ?? "").trim();
                if (cellStr) {
                  const v = parseFloat(cellStr.replace(/,/g, ""));
                  chainageFromKm[c - 4] = isNaN(v) ? null : v;
                }
              }
            }
            dataStart = Math.max(dataStart, ri + 1);
          }
        }
        if (!foundStructureTypeRow) {
          localWarnings.push(`Sheet "${sheetName}": no "Structure Type" row found in the first 6 rows after the header — structure types were left blank for all columns.`);
        }
        if (!foundChainageFromRow) {
          localWarnings.push(`Sheet "${sheetName}": no "Chainage From" row found in the first 6 rows after the header — chainage was NOT imported (left blank, not defaulted to 0) and every row was marked for review.`);
        }
        // Point items (e.g. dissipation chambers) are allowed to omit "Chainage To" —
        // fall back to chainageFrom for that column instead of warning per-column.
        for (let i = 0; i < structIds.length; i++) {
          if (chainageToKm[i] == null) chainageToKm[i] = chainageFromKm[i];
        }

        const outRows: any[] = [];
        const missingChainageStructIds = new Set<string>();

        for (let ri = dataStart; ri < raw.length; ri++) {
          const row = raw[ri];
          const boqCode = String(row[0] ?? "").trim();
          const boqSubItem = String(row[1] ?? "").trim();
          const boqDesc    = String(row[2] ?? "").trim();
          const uom        = String(row[3] ?? "").trim();

          // Skip blank / metadata rows
          if (!boqCode && !boqDesc) continue;
          // Skip if col-0 looks like a metadata marker
          if (/^(structure[\s_]?type|chainage|remarks|total|sub-total)/i.test(boqCode)) continue;

          const boqItem = matchBoqItem(boqCode, boqSubItem, boqDesc);

          for (let c = 4; c < row.length; c++) {
            const colIdx = c - 4;
            const structId = structIds[colIdx];
            if (!structId) continue;

            const cellStr = String(row[c] ?? "").trim();
            if (!cellStr) continue;
            const qty = parseFloat(cellStr.replace(/,/g, ""));
            if (isNaN(qty) || qty <= 0) continue;

            const structType = structTypes[colIdx] ?? "";
            const chFrom = chainageFromKm[colIdx];
            const chTo = chainageToKm[colIdx];
            const chainageMissing = chFrom == null;
            if (chainageMissing) missingChainageStructIds.add(structId);

            // BC / wearing-coat against pipe culverts — warn but allow
            if (BC_PATTERN.test(boqDesc) && PIPE_CULVERT_PATTERN.test(structType)) {
              localWarnings.push(
                `Sheet "${sheetName}" row ${ri + 1}, ${structId} (${structType}): ` +
                `"${boqDesc}" qty ${qty} — BC/wearing coat is unusual for pipe culverts.`,
              );
            }

            outRows.push({
              rowIdx: ri + 2,
              structureId:  structId,
              structureType: structType,
              chainageFromKm: chFrom,
              chainageToKm: chTo,
              chainageMissing,
              boqItemCode:  boqCode,
              boqSubItem,
              boqExcelRow:  ri + 2,
              boqDescription: boqDesc,
              plannedQty:   qty,
              uom,
              startDate:    "",
              durationDays: 0,
              remarks:      "",
              boqItemId:    boqItem?.id ?? null,
              matchStatus:  boqItem ? "matched" : "unmatched",
              matchedItemCode: boqItem?.itemCode ?? null,
              matchedDescription: boqItem?.description?.slice(0, 80) ?? null,
              sheetName,
            });
          }
        }

        if (missingChainageStructIds.size) {
          localWarnings.push(
            `Sheet "${sheetName}": no chainage found for structure(s) ${Array.from(missingChainageStructIds).join(", ")} — ` +
            `imported with blank chainage (not defaulted to 0) and marked "needs review".`,
          );
        }

        return { rows: outRows, warnings: localWarnings };
      }

      // ── Legacy flat-format parser ──────────────────────────────────────────────
      // Columns: structure_id | structure_type | chainage_km | boq_item_code |
      //          boq_sub_item | planned_qty | uom | start_date | duration_days | remarks
      function parseLegacySheet(): { rows: any[]; warnings: string[] } {
        const ws = wb.Sheets[LEGACY_SHEET];
        const json = utils.sheet_to_json<Record<string, unknown>>(ws, { defval: "", raw: false });
        if (!json.length) return { rows: [], warnings: [`Sheet "${LEGACY_SHEET}" is empty.`] };

        // Normalize a header name for comparison: lowercase and strip everything
        // but letters/digits. This makes "start_date", "start date", "Start Date"
        // and camelCase "startDate" all match the same alias.
        function normHeader(s: string): string {
          return s.trim().toLowerCase().replace(/[^a-z0-9]/g, "");
        }
        function colStr(row: Record<string, unknown>, ...aliases: string[]): string {
          for (const alias of aliases) {
            const target = normHeader(alias);
            const key = Object.keys(row).find(k => normHeader(k) === target);
            if (key) return String(row[key] ?? "");
          }
          return "";
        }
        function colNum(row: Record<string, unknown>, ...aliases: string[]): number {
          const v = parseFloat(colStr(row, ...aliases).replace(/,/g, ""));
          return isNaN(v) ? 0 : v;
        }
        // Converts an Excel serial date number (days since 1899-12-30, with the
        // well-known 1900 leap-year bug) to an ISO "YYYY-MM-DD" string.
        function excelSerialToIso(serial: number): string {
          const ms = Math.round((serial - 25569) * 86400 * 1000);
          return new Date(ms).toISOString().slice(0, 10);
        }
        function colDate(row: Record<string, unknown>, ...aliases: string[]): string {
          const v = colStr(row, ...aliases).trim();
          if (!v) return "";
          if (/^\d{4}-\d{2}-\d{2}/.test(v)) return v.slice(0, 10);
          // Plain numeric value → Excel serial date (only plausible date range).
          if (/^\d+(\.\d+)?$/.test(v)) {
            const serial = Number(v);
            if (serial > 20000 && serial < 80000) return excelSerialToIso(serial);
          }
          const parts = v.split(/[\/-]/);
          if (parts.length === 3) {
            const [a, b, c] = parts.map(Number);
            if (c > 31) return `${c}-${String(b).padStart(2, "0")}-${String(a).padStart(2, "0")}`;
            if (a > 31) return `${a}-${String(b).padStart(2, "0")}-${String(c).padStart(2, "0")}`;
          }
          return "";
        }

        const outRows = json
          .map((row, i) => {
            const structureId    = colStr(row, "structure_id", "structure_name", "structure id");
            const boqItemCode    = colStr(row, "boq_item_code", "item_code", "item code", "boq item code");
            const boqSubItem     = colStr(row, "boq_sub_item", "sub_item", "sub item");
            const boqDescription = colStr(row, "boq_description", "description", "item description");
            const boqExcelRowRaw = Math.round(colNum(row, "boq_excel_row", "excel_row"));
            const boqExcelRow    = boqExcelRowRaw || (i + 2);
            const boqItem        = matchBoqItem(boqItemCode, boqSubItem, boqDescription);
            return {
              rowIdx: i + 2,
              structureId,
              structureType:      colStr(row, "structure_type", "type"),
              chainageKm:         colNum(row, "chainage_km", "chainage", "ch_km"),
              boqItemCode,
              boqSubItem,
              boqExcelRow,
              boqDescription,
              plannedQty:         colNum(row, "planned_qty", "quantity", "qty"),
              uom:                colStr(row, "uom", "unit"),
              startDate:          colDate(row, "start_date", "start date"),
              durationDays:       Math.round(colNum(row, "duration_days", "duration", "duration (days)")),
              remarks:            colStr(row, "remarks", "notes"),
              boqItemId:          boqItem?.id ?? null,
              matchStatus:        boqItem ? "matched" : "unmatched",
              matchedItemCode:    boqItem?.itemCode ?? null,
              matchedDescription: boqItem?.description?.slice(0, 80) ?? null,
              sheetName:          LEGACY_SHEET,
            };
          })
          .filter(r => r.structureId || r.boqDescription || r.plannedQty > 0);

        return { rows: outRows, warnings: [] };
      }

      // ── Run the appropriate parser(s) ──────────────────────────────────────────
      let allRows: any[] = [];
      const allParseWarnings: string[] = [];
      const parsedSheetNames: string[] = [];

      if (presentMatrixSheets.length) {
        for (const sn of presentMatrixSheets) {
          const { rows: sheetRows, warnings: sheetWarnings } = parseMatrixSheet(sn);
          allRows = allRows.concat(sheetRows);
          allParseWarnings.push(...sheetWarnings);
          if (sheetRows.length) parsedSheetNames.push(sn);
        }
      } else {
        const { rows: legRows, warnings: legWarnings } = parseLegacySheet();
        allRows = legRows;
        allParseWarnings.push(...legWarnings);
        parsedSheetNames.push(LEGACY_SHEET);
      }

      if (!allRows.length) {
        return res.status(422).json({
          error: "No data rows could be read from the uploaded file.",
          warnings: allParseWarnings,
          hint: "Check that BOQ item rows have numeric quantity values in the structure columns.",
        });
      }

      res.json({
        sheetNames: parsedSheetNames,
        rows: allRows,
        totalRows: allRows.length,
        warnings: allParseWarnings,
      });
    } catch (err: any) {
      console.error("POST /api/boq/projects/:id/parse-structure-schedule:", err);
      res.status(500).json({ error: `Failed to parse structure schedule: ${err?.message ?? String(err)}` });
    }
  })

app.post("/api/boq/projects/:id/auto-sequence-structures", async (req, res) => {
    try {
      if (!assertEdit(req, res, "work_programme")) return;
      const projectId = parseInt(req.params.id);
      const scope: "unscheduled" | "all" = req.body?.scope === "all" ? "all" : "unscheduled";
      const scopeVersionToken = await storage.getProjectScopeVersionToken(projectId);
      const existingBars = await storage.getWorkProgramBars(projectId);
      if (sendDirectScheduleMutationBlock(
        res,
        await directScheduleMutationBlock(projectId, existingBars as any[]),
      )) return;
      const summary = await runStructureAutoSequence(projectId, { scope, scopeVersionToken });
      res.json(summary);
    } catch (err: any) {
      console.error("auto-sequence-structures:", err);
      if (err instanceof DirectScheduleMutationBlockedError) {
        return res.status(err.block.status).json({ error: err.block.error, message: err.block.message });
      }
      if (err?.code === "SCOPE_CHANGED_DURING_PLANNING" || (ScopeChangedDuringPlanningError && err instanceof ScopeChangedDuringPlanningError)) {
        return res.status(409).json({ code: "SCOPE_CHANGED_DURING_PLANNING", message: err.message });
      }
      res.status(500).json({ error: `Failed to auto-sequence structures: ${err?.message ?? String(err)}` });
    }
  })

app.post("/api/boq/projects/:id/import-structure", async (req, res) => {
    try {
      if (!assertEdit(req, res, "work_programme")) return;
      const projectId = parseInt(req.params.id);
      // Capture before item/settings reads. Bar deletes and inserts recheck
      // this token while holding the project mutex.
      const scopeVersionToken = await storage.getProjectScopeVersionToken(projectId);
      const { rows, mode = "append", onMissingDates } = req.body as {
        rows: Array<{
          structureId: string;
          structureType: string;
          chainageKm?: number;
          chainageFromKm?: number | null;
          chainageToKm?: number | null;
          chainageMissing?: boolean;
          boqItemCode?: string;
          boqSubItem?: string;
          boqExcelRow?: number;
          boqDescription?: string;
          plannedQty: number;
          uom?: string;
          startDate?: string;    // ISO date "YYYY-MM-DD"
          durationDays?: number;
          remarks?: string;
          // matched BOQ item (resolved by frontend preview)
          boqItemId?: number;
        }>;
        mode?: "append" | "replace";
        // How to handle rows with no usable start date. When omitted and such
        // rows exist, the route returns a 409 asking the client to decide.
        onMissingDates?: "unscheduled" | "auto_sequence" | "cancel";
      };

      if (!Array.isArray(rows) || rows.length === 0) {
        return res.status(400).json({ error: "rows array is required and must not be empty" });
      }

      // Pre-scan for rows with no valid, parseable start date. Quantities are
      // always imported as-is (source of truth) — this only decides how such
      // rows get placed on the Gantt.
      const isValidIsoDate = (s?: string) => !!s && /^\d{4}-\d{2}-\d{2}/.test(s);
      const rowsMissingDates = rows.filter(r => r.plannedQty > 0 && !isValidIsoDate(r.startDate)).length;
      if (rowsMissingDates > 0 && !onMissingDates) {
        return res.status(409).json({
          requiresDecision: true,
          missingDateRows: rowsMissingDates,
          totalRows: rows.length,
          message: `${rowsMissingDates} of ${rows.length} row(s) have no valid start date. Choose how to place them.`,
        });
      }
      if (onMissingDates === "cancel") {
        return res.status(200).json({ cancelled: true, created: 0, skipped: 0 });
      }

      // Load all BOQ items for fallback matching
      const allItems = await storage.getBoqItems(projectId) as any[];
      const itemById = new Map(allItems.map((it: any) => [it.id, it]));
      const itemByCode = new Map(allItems.map((it: any) => [String(it.itemCode ?? "").trim().toLowerCase(), it]));

      const results: { row: number; status: "created" | "skipped"; structureId?: string; reason?: string }[] = [];
      let created = 0;
      let skipped = 0;
      let unmatchedBoqRows = 0;
      let uomMismatchRows = 0;
      let missingDateRows = 0;
      const warnings: string[] = [];
      const importInserts: any[] = [];
      // Track imported qty per BOQ item for over-planned detection
      const importedQtyByItemId = new Map<number, number>();
      const createdBarIds: number[] = [];

      const project = await storage.getBoqProject(projectId) as any;
      const pSettings = await storage.getBoqProgramSettings(projectId) as any;
      const projectStartDate: string | null = pSettings?.projectStartDate ?? null;
      const totalMonths: number = project?.totalMonths ?? 18;
      const workingDays: number = pSettings?.workingDaysPerMonth ?? 25;
      // Project chainage bounds for range validation (null = skip)
      const projChFrom: number | null = project?.chainageFrom ?? null;
      const projChTo: number | null = project?.chainageTo ?? null;

      // Build a secondary lookup: (itemCode:subItem) composite key for when subItem is provided
      const itemByCodeSubItem = new Map<string, any>();
      for (const it of allItems) {
        if ((it as any).boqSubItem) {
          const compositeKey = `${String((it as any).itemCode ?? "").trim().toLowerCase()}::${String((it as any).boqSubItem ?? "").trim().toLowerCase()}`;
          itemByCodeSubItem.set(compositeKey, it);
        }
      }

      for (let i = 0; i < rows.length; i++) {
        const r = rows[i];

        // Validation: skip rows with no meaningful quantity
        if (!r.plannedQty || r.plannedQty <= 0) {
          results.push({ row: i + 1, status: "skipped", structureId: r.structureId, reason: "plannedQty must be > 0" });
          skipped++;
          continue;
        }

        // Unified chainage: new matrix rows carry chainageFromKm/chainageToKm/chainageMissing;
        // legacy flat-sheet rows only carry a single chainageKm — treat that as both
        // from and to (point value) for backward compatibility. Missing chainage is
        // NEVER defaulted to 0 — it stays null and the row is marked needsReview below.
        const rowChainageFrom: number | null = r.chainageFromKm ?? r.chainageKm ?? null;
        const rowChainageTo: number | null = r.chainageToKm ?? r.chainageKm ?? rowChainageFrom;
        const rowChainageMissing: boolean = r.chainageMissing === true || rowChainageFrom == null;

        // Chainage range validation (soft warning, not a skip)
        if (projChFrom != null && projChTo != null && rowChainageFrom != null) {
          if (rowChainageFrom < projChFrom - 0.1 || rowChainageFrom > projChTo + 0.1) {
            warnings.push(`Row ${i + 1} (${r.structureId}): chainage ${rowChainageFrom} km is outside project range ${projChFrom}–${projChTo} km`);
          }
        }
        if (rowChainageMissing) {
          warnings.push(`Row ${i + 1} (${r.structureId ?? "?"}): no chainage found — imported with blank chainage (not defaulted to 0) and marked "needs review".`);
        }

        // Resolve BOQ item — 4-level priority matching the parse endpoint:
        // P0 → boqItemId (pre-matched by parse endpoint, fastest path)
        // P1 → boq_excel_row + boq_item_code + boq_sub_item
        //       (uses boqItems.excelRow stored from BOQ Excel import; exact P1 when available)
        // P2 → boq_item_code + boq_sub_item composite exact
        // P3 → boq_item_code exact / leading-zero stripped
        // P4 → boq_description partial (first 40 chars, last resort)
        let boqItem: any = null;
        if (r.boqItemId && itemById.has(r.boqItemId)) {
          boqItem = itemById.get(r.boqItemId);
        } else if (r.boqExcelRow && r.boqItemCode) {
          boqItem = allItems.find((it: any) =>
            it.excelRow === r.boqExcelRow &&
            String(it.itemCode ?? "").trim().toLowerCase() === String(r.boqItemCode).trim().toLowerCase() &&
            (!r.boqSubItem || String(it.boqSubItem ?? "").trim().toLowerCase() === String(r.boqSubItem).trim().toLowerCase())
          ) ?? null;
        }
        if (!boqItem && r.boqItemCode && r.boqSubItem) {
          const compositeKey = `${String(r.boqItemCode).trim().toLowerCase()}::${String(r.boqSubItem).trim().toLowerCase()}`;
          boqItem = itemByCodeSubItem.get(compositeKey) ?? null;
        }
        if (!boqItem && r.boqItemCode) {
          boqItem = itemByCode.get(String(r.boqItemCode).trim().toLowerCase()) ?? null;
          if (!boqItem) {
            // fuzzy: strip leading zeros / spaces
            const stripped = String(r.boqItemCode).replace(/^0+/, "").trim().toLowerCase();
            boqItem = allItems.find((it: any) =>
              String(it.itemCode ?? "").replace(/^0+/, "").trim().toLowerCase() === stripped
            ) ?? null;
          }
        }
        if (!boqItem && r.boqDescription) {
          // last-resort: closest description match (first 40 chars)
          const needle = r.boqDescription.toLowerCase();
          boqItem = allItems.find((it: any) =>
            (it.description ?? "").toLowerCase().includes(needle.slice(0, 40))
          ) ?? null;
        }

        if (!boqItem) {
          results.push({ row: i + 1, status: "skipped", structureId: r.structureId, reason: `No BOQ item matched (code: ${r.boqItemCode ?? "—"})` });
          skipped++;
          unmatchedBoqRows++;
          continue;
        }

        // UOM compatibility warning (soft — don't skip, but flag)
        if (r.uom && boqItem.unit && r.uom.toLowerCase() !== boqItem.unit.toLowerCase()) {
          warnings.push(`Row ${i + 1} (${r.structureId}): UOM mismatch — sheet "${r.uom}" vs BOQ item "${boqItem.unit}"`);
          uomMismatchRows++;
        }
        // Accumulate imported qty per BOQ item for over-planned detection
        importedQtyByItemId.set(boqItem.id, (importedQtyByItemId.get(boqItem.id) ?? 0) + (r.plannedQty ?? 0));

        // Compute startMonth / endMonth from startDate + durationDays.
        // Missing or unparseable start_date is never silently defaulted to Month 1 —
        // the row is imported with its planned quantity intact but marked unscheduled
        // (placeholder position) so it can be placed by "Auto-sequence" instead.
        let startMonth = 1;
        let endMonth   = 1.1;
        const hasValidDate = r.startDate && /^\d{4}-\d{2}-\d{2}/.test(r.startDate);
        let scheduled = true;
        if (!hasValidDate) {
          missingDateRows++;
          scheduled = false;
          warnings.push(`Row ${i + 1} (${r.structureId ?? "?"}): no valid start_date — imported as unscheduled. Use "Auto-sequence imported structure bars" to place it.`);
        }
        if (hasValidDate && projectStartDate) {
          try {
            const pStart = new Date(projectStartDate);
            const sDate  = new Date(r.startDate!);
            const diffMs = sDate.getTime() - pStart.getTime();
            const diffDays = diffMs / 86400000;
            startMonth = Math.max(1, 1 + diffDays / workingDays);
            const durMonths = r.durationDays ? r.durationDays / workingDays : 1;
            endMonth = startMonth + durMonths;
            if (endMonth > totalMonths) endMonth = totalMonths;
            if (endMonth <= startMonth) endMonth = startMonth + 0.1;
            startMonth = +startMonth.toFixed(3);
            endMonth   = +endMonth.toFixed(3);
          } catch (dateErr) {
            scheduled = false;
            warnings.push(`Row ${i + 1} (${r.structureId ?? "?"}): could not parse start_date "${r.startDate}" — imported as unscheduled.`);
          }
        }

        const endDate = r.startDate && r.durationDays
          ? (() => {
              const d = new Date(r.startDate);
              d.setDate(d.getDate() + r.durationDays);
              return d.toISOString().slice(0, 10);
            })()
          : null;

        importInserts.push({
            boqProjectId: projectId,
            boqItemId: boqItem.id,
            reachLabel: r.structureId,
            chainageFrom: rowChainageFrom,
            chainageTo: rowChainageTo,
            startMonth,
            endMonth,
            startDate: r.startDate ?? null,
            endDate,
            plannedQty: r.plannedQty ?? 0,
            source: "structure_import",
            planningMode: "structure_location",
            scheduled,
            durationSource: scheduled ? "imported" : null,
            needsReview: !scheduled || rowChainageMissing,
            structureId: r.structureId,
            structureLocType: r.structureType,
            structureChainageKm: rowChainageFrom,
            relativeChainageKm: (rowChainageFrom != null && project?.chainageFrom != null)
              ? Math.round((rowChainageFrom - project.chainageFrom) * 1000) / 1000
              : null,
            durationDays: r.durationDays ?? null,
            boqSubItem: r.boqSubItem ?? null,
            boqExcelRow: r.boqExcelRow ?? null,
            notes: r.remarks ?? null,
          } as any);
        created++;
        results.push({ row: i + 1, status: "created", structureId: r.structureId });
      }

      // Replace/delete and every imported insert share one project-locked
      // transaction. A correction can therefore never observe the temporary
      // empty programme that existed when each bar was written separately.
      const importMutation = await storage.applyWorkProgrammeMutation(
        projectId,
        {
          deleteStructureLocationBars: mode === "replace",
          inserts: importInserts,
        },
        scopeVersionToken,
      );
      createdBarIds.push(...((importMutation as any)?.insertedBars ?? []).map((bar: any) => Number(bar.id)).filter(Number.isFinite));

      // If the client asked to auto-sequence unscheduled rows right away, do it
      // now for just the bars created in this import.
      let autoSequenceSummary: { updated: number; structures: number; fronts: number; needsReviewCount: number } | null = null;
      if (onMissingDates === "auto_sequence" && createdBarIds.length) {
        try {
          autoSequenceSummary = await runStructureAutoSequence(projectId, { barIds: createdBarIds, scopeVersionToken });
        } catch (e: any) {
          if (e?.code === "SCOPE_CHANGED_DURING_PLANNING" || (ScopeChangedDuringPlanningError && e instanceof ScopeChangedDuringPlanningError)) throw e;
          warnings.push(`Auto-sequence after import failed: ${e?.message ?? String(e)}`);
        }
      }

      // Detect over-planned BOQ items: sum of imported plannedQty > item.currentQty
      const overPlannedItems: Array<{ boqItemId: number; itemCode: string; description: string; currentQty: number; importedQty: number }> = [];
      for (const [itemId, importedQty] of importedQtyByItemId) {
        const it = itemById.get(itemId);
        if (it && it.currentQty != null && importedQty > it.currentQty * 1.05) {
          // Allow 5% tolerance before flagging
          overPlannedItems.push({
            boqItemId: itemId,
            itemCode: it.itemCode ?? "",
            description: (it.description ?? "").slice(0, 80),
            currentQty: it.currentQty,
            importedQty,
          });
        }
      }
      if (overPlannedItems.length) {
        warnings.push(`${overPlannedItems.length} BOQ item(s) have total imported quantity exceeding their BOQ quantity — check if all sub-items are correctly assigned.`);
      }

      res.status(201).json({
        created,
        skipped,
        total: rows.length,
        rowsRead: rows.length,
        rowsImported: created,
        rowsSkipped: skipped,
        unmatchedBoqRows,
        uomMismatchRows,
        missingDateRows,
        overPlannedItems,
        autoSequenceSummary,
        warnings: warnings.slice(0, 50), // cap at 50 to keep response small
        results,
      });
    } catch (err: any) {
      console.error("POST /api/boq/projects/:id/import-structure:", err);
      if (err?.code === "SCOPE_CHANGED_DURING_PLANNING" || (ScopeChangedDuringPlanningError && err instanceof ScopeChangedDuringPlanningError)) {
        return res.status(409).json({ code: "SCOPE_CHANGED_DURING_PLANNING", message: err.message });
      }
      res.status(500).json({ error: `Failed to import structure schedule: ${err?.message ?? String(err)}` });
    }
  })

