                                            </Select>
                                            {partyMatch == null && maxQty > 0.001 && (
                                              <p className="text-amber-600 font-semibold text-[12px] mt-0.5">⚠ Select party for plant stock</p>
                                            )}
                                          </>
                                        ) : (
