  // Batch 06E: app-level validation for the four nullable linkage IDs on a
  // site material trip (no DB FKs by design). Confirms each supplied ID
  // exists and is mutually compatible. Returns an error string or null.
  const validateTripLinkage = async (input: {
    boqProjectId?: number | null;
    boqItemId?: number | null;
    programmeBarId?: number | null;
    earthworkArrangementId?: number | null;
    site?: string | null;
    operationalDate?: string | null;
    allowHistoricalArrangementId?: number | null;
    requireProjectItemPair?: boolean;
  }): Promise<string | null> => {
    const { boqProjectId, boqItemId, programmeBarId, earthworkArrangementId, site, operationalDate, allowHistoricalArrangementId, requireProjectItemPair } = input;
    if (requireProjectItemPair && (boqProjectId == null || boqItemId == null)) {
      return "boqProjectId and boqItemId are required for a material trip";
    }
    if ((boqProjectId == null) !== (boqItemId == null)) {
      return "boqProjectId and boqItemId must be provided together";
    }
    if (boqProjectId != null) {
      const project = await storage.getBoqProject(boqProjectId);
      if (!project) return `BOQ project ${boqProjectId} not found`;
      if (site != null) {
        const sites = await storage.getSites();
        const projectSite = project.siteId != null ? sites.find((candidate) => candidate.id === project.siteId)?.name ?? null : null;
        // Compare in both directions so provenance suffixes use the same
        // canonical-site rules as the rest of the API, without allowing a
        // broad prefix match to cross sites.
        if (projectSite == null || !siteMatchesPermitted(site, [projectSite]) || !siteMatchesPermitted(projectSite, [site])) {
          return `BOQ project ${boqProjectId} does not belong to trip site ${site}`;
        }
      }
    }
    if (boqItemId != null) {
      const item = await storage.getBoqItem(boqItemId);
      if (!item) return `BOQ item ${boqItemId} not found`;
      if (boqProjectId != null && item.boqProjectId !== boqProjectId) {
        return `BOQ item ${boqItemId} does not belong to project ${boqProjectId}`;
      }
    }
    if (programmeBarId != null) {
      const bar = await storage.getWorkProgramBar(programmeBarId);
      if (!bar) return `Programme bar ${programmeBarId} not found`;
      if (boqProjectId != null && bar.boqProjectId !== boqProjectId) {
        return `Programme bar ${programmeBarId} does not belong to project ${boqProjectId}`;
      }
      if (boqItemId != null && bar.boqItemId !== boqItemId) {
        return `Programme bar ${programmeBarId} is not for BOQ item ${boqItemId}`;
      }
    }
    if (earthworkArrangementId != null) {
      const arrangement = await storage.getEarthworkArrangementById(earthworkArrangementId);
      if (!arrangement) return `Execution arrangement ${earthworkArrangementId} not found`;
      if (boqProjectId != null && arrangement.boqProjectId !== boqProjectId) {
        return `Arrangement ${earthworkArrangementId} does not belong to project ${boqProjectId}`;
      }
      if (
        earthworkArrangementId !== allowHistoricalArrangementId
        && tripArrangementLinkError(arrangement, operationalDate)
      ) {
        return tripArrangementLinkError(arrangement, operationalDate);
      }
      // Single-item arrangements must match the receipt's BOQ item; multi-item
      // arrangements (boqItemId null + jsonb allocations) are checked against
      // their allocation list when present.
      if (boqItemId != null && arrangement.boqItemId != null && arrangement.boqItemId !== boqItemId) {
        return `Arrangement ${earthworkArrangementId} is not for BOQ item ${boqItemId}`;
      }
      if (boqItemId != null && arrangement.boqItemId == null && Array.isArray(arrangement.boqItemAllocations) && (arrangement.boqItemAllocations as any[]).length > 0) {
        const ids = (arrangement.boqItemAllocations as any[]).map((a: any) => Number(a?.boqItemId)).filter((n) => Number.isFinite(n));
        if (ids.length > 0 && !ids.includes(boqItemId)) {
          return `Arrangement ${earthworkArrangementId} allocations do not include BOQ item ${boqItemId}`;
        }
      }
    }
    if (boqProjectId != null && boqItemId != null) {
      const itemArrangements = await storage.getEarthworkArrangementsForItem(boqProjectId, boqItemId);
      if (blocksExternalReceiptsForBoqItem(itemArrangements, boqItemId, operationalDate)) {
        return "This BOQ item's material comes from the Roadway Excavation cut-fill ledger and cannot accept an external material trip";
      }
    }
    return null;
  };

  // Create a new site material trip
  app.post("/api/site-material-trips", async (req, res) => {
    try {
      if (!assertCreate(req, res, "site_materials")) return;
      const input = insertSiteMaterialTripSchema.parse(req.body);
      if (input.materialSourceType === "own_source") {
        if (!input.materialSourceLabel?.trim()) return res.status(400).json({ message: "Enter the borrow area / source description." });
        input.materialSourceSupplier = null;
        input.materialSourceLabel = input.materialSourceLabel.trim();
      } else {
        input.materialSourceLabel = null;
      }
      if (!await assertTripSiteAccess(req, res, input.site)) return;
      // New receipts must declare their transport route.  The base insert
      // schema intentionally remains nullable because historical data and
      // PATCH payloads need to remain backward compatible.
      if (input.transportType !== "in_house" && input.transportType !== "agency_vendor") {
        return res.status(400).json({ message: "transportType must be in_house or agency_vendor" });
      }
      if (input.internalEquipmentId != null && input.transportType !== "in_house") {
        return res.status(400).json({ message: "internalEquipmentId is only allowed for in-house transport" });
      }
      const linkageError = await validateTripLinkage({ ...input, operationalDate: input.date, requireProjectItemPair: true });
      if (linkageError) return res.status(400).json({ message: linkageError });
      const trip = await storage.createSiteMaterialTrip(input);
      sendPushToSection("site_materials", "Site Material Trip Added", `${input.material || 'Material'} - ${input.site || ''}`, "/site-reports").catch(() => {});
      res.status(201).json(trip);
    } catch (err) {
      console.error("Error creating site material trip:", err);
      res.status(500).json({ message: "Failed to create site material trip" });
    }
  });

  // Update a site material trip
  app.patch("/api/site-material-trips/:id", async (req, res) => {
    try {
      if (!assertEdit(req, res, "site_materials")) return;
      const id = Number(req.params.id);
      const input = insertSiteMaterialTripSchema.partial().parse(req.body);
      const existing = await storage.getSiteMaterialTripById(id);
      if (!existing) return res.status(404).json({ message: "Site material trip not found" });
      if (!await assertTripSiteAccess(req, res, existing.site)) return;
      if (("materialSourceType" in input ? input.materialSourceType : existing.materialSourceType) === "own_source") {
        input.materialSourceSupplier = null;
      } else if ("materialSourceType" in input || "materialSourceLabel" in input) {
        input.materialSourceLabel = null;
      }
      if ("site" in input && !await assertTripSiteAccess(req, res, input.site)) return;
      if (input.transportType != null && input.transportType !== "in_house" && input.transportType !== "agency_vendor") {
        return res.status(400).json({ message: "transportType must be in_house or agency_vendor" });
      }
      // A transport-type correction away from in-house must not leave an
      // internal-master link attached to the same trip.
      if (input.transportType === "agency_vendor") input.internalEquipmentId = null;
      if (input.internalEquipmentId != null && input.transportType !== "in_house") {
        if ((input.transportType ?? existing.transportType) !== "in_house") {
          return res.status(400).json({ message: "internalEquipmentId is only allowed for in-house transport" });
        }
      }
      if ("boqProjectId" in input || "boqItemId" in input || "programmeBarId" in input || "earthworkArrangementId" in input || "site" in input) {
        // DPR-02: correcting an existing link is a normal deliberate edit.
        // Validate the complete resulting row atomically instead of requiring
        // an unsafe two-request "unlink, then relink" transition.
        const merged = mergeMaterialTripLinkage(existing, input);
        if (merged.boqProjectId != null || merged.boqItemId != null || merged.programmeBarId != null || merged.earthworkArrangementId != null) {
          const linkageError = await validateTripLinkage({
            ...merged,
            site: ("site" in input ? input.site : existing.site) ?? null,
            operationalDate: ("date" in input ? input.date : existing.date) ?? null,
            allowHistoricalArrangementId: existing.earthworkArrangementId,
            requireProjectItemPair: true,
          });
          if (linkageError) return res.status(400).json({ message: linkageError });
        }
      }
      const trip = await storage.updateSiteMaterialTrip(id, input, {
        userId: req.authUser!.id,
        userName: currentUserName(req),
        userRole: req.authUser!.isOwner ? "owner" : req.authUser!.isAdmin ? "admin" : "manager",
      });
      if (!trip) return res.status(404).json({ message: "Site material trip not found" });
      sendPushToSection("site_materials", "Site Material Trip Updated", `Trip #${id} updated`, "/site-reports").catch(() => {});
      res.json(trip);
    } catch (err) {
      console.error("Error updating site material trip:", err);
      res.status(500).json({ message: "Failed to update site material trip" });
    }
  });

