    try {
      if (!assertCreate(req, res, "site_dprs")) return;
      const itemIds = String(req.query.boqItemIds ?? "")
        .split(",").map((s) => Number(s.trim())).filter((n) => Number.isFinite(n) && n > 0);
      const excludeDprId = req.query.excludeDprId != null && String(req.query.excludeDprId).trim() !== ""
        ? Number(req.query.excludeDprId) : null;
      if (itemIds.length === 0) return res.json({ entries: [] });
      if (itemIds.length > 200) return res.status(400).json({ message: "Too many BOQ items" });
      // Site-access security: restricted users may only read progress for
      // projects whose site is permitted (same rule as the Progress Report).
      const permittedSiteNames = await getPermittedSiteNames(req);
      if (permittedSiteNames !== null) {
        const items = await Promise.all(itemIds.map((id) => storage.getBoqItem(id)));
        const projectIds = new Set<number>();
        for (const item of items as any[]) {
          if (item?.boqProjectId != null) projectIds.add(Number(item.boqProjectId));
        }
        const sites = await storage.getSites();
        const projects = await Promise.all(Array.from(projectIds).map((pid) => storage.getBoqProject(pid)));
        for (const project of projects) {
          const projectSite = project?.siteId != null ? sites.find((s) => s.id === project.siteId)?.name ?? null : null;
          if (projectSite == null || !siteMatchesPermitted(projectSite, permittedSiteNames)) {
            return res.status(403).json({ message: "Access denied for this site" });
          }
        }
      }
      const entries = await storage.getSubmittedChainageEntries(itemIds, excludeDprId);
      res.json({ entries });
    } catch (err) {
      console.error("GET /api/dprs/chainage-overlap-context:", err);
      res.status(500).json({ message: "Failed to load overlap context" });
    }
  });

  // Get single DPR details
  app.get(api.dprs.get.path, async (req, res) => {
    // Batch 06B: require DPR view permission — this endpoint returns full DPR
    // contents (and now backs the read-only overlap preview), so it must not
    // be readable by authenticated users without site_dprs access.
    if (!assertView(req, res, "site_dprs")) return;
    // Guard: a non-numeric id must 400, not crash the pg driver with NaN.
    const dprIdNum = Number(req.params.id);
    if (!Number.isInteger(dprIdNum) || dprIdNum <= 0) {
      return res.status(400).json({ message: "Invalid DPR id" });
    }
    const dpr = await storage.getDpr(dprIdNum);
    if (!dpr) {
      return res.status(404).json({ message: 'DPR not found' });
    }
    // Permission System v2: check that the requesting user can access this DPR's site
    const permittedSiteNames = await getPermittedSiteNames(req);
    if (permittedSiteNames !== null && !siteMatchesPermitted(dpr.site, permittedSiteNames)) {
      return res.status(403).json({ message: 'Access denied for this site' });
    }
    const progressIds = dpr.progress?.map(p => p.id) || [];
    const actPersonnel = progressIds.length > 0 ? await storage.getActivityPersonnel(progressIds) : [];
    const enrichedProgress = dpr.progress?.map(p => ({
      ...p,
      personnelIds: actPersonnel.filter(ap => ap.progressEntryId === p.id).map(ap => ap.personnelId),
    }));
    if ((dpr as any).dprStatus === "draft") {
      const snapshot = await db.transaction(async (tx) => {
        await tx.execute(sql`SELECT id FROM dprs WHERE id = ${dprIdNum} FOR SHARE`);
        return sectionSnapshot(await readSectionAggregate(tx, dprIdNum));
      });
      return res.json({ ...snapshot.dpr, sectionTokens: snapshot.sectionTokens, headerToken: snapshot.headerToken });
    }
    res.json({ ...dpr, progress: enrichedProgress });
  });

  // ── Instruction 030A Part F: server-side validation of DPR → programme-bar
  // links. Never rely on UI-only validation. Checks, per progress entry with a
  // programmeBarId: bar exists + belongs to the DPR's BOQ project, BOQ item
  // matches, side compatibility (planned LHS ⇒ DPR LHS, etc.), basic chainage
  // validity against the selected bar (containment unless a reasoned override),
  // and bar active/not superseded. Returns an error string or null.
  // Instruction 031: side/chainage rules now live in the shared module
  // (shared/dprProgrammeLink.ts) so both DPR screens and the server enforce the
  // exact same logic. `opts.draft` enables draft-lenient mode (Part B/F):
  // incomplete chainage or a missing out-of-range reason never strips a draft's
  // programmeBarId; structural errors (wrong project/item/side) still fail.
  // Side effect (Part G): rows whose chainage falls outside their linked bar
  // get chainageReviewStatus="review_required" stamped onto the input so they
  // are preserved but excluded from the bar's completed quantity until review.
  async function validateProgressProgrammeLinks(input: any, opts: { draft?: boolean } = {}): Promise<string | null> {
    const progress: any[] = Array.isArray(input?.progress) ? input.progress : [];
    // Batch 1: actual execution side is a mandatory core field for chainage-
    // based road work on FINAL submission (linked or not) — the UI enforces
    // this too, but the server must not be bypassable. Drafts stay lenient.
    if (!opts.draft) {
      for (const p of progress) {
        if (p?.noSiteWork || p == null) continue;
        const fromKm = p.chainageFromKm != null ? Number(p.chainageFromKm) : parseChainageKm(p.chainageFrom);
        const toKm = p.chainageToKm != null ? Number(p.chainageToKm) : parseChainageKm(p.chainageTo);
        const hasChainage = fromKm != null || toKm != null;
        if (hasChainage && !normalizeDprSideKey(p.side)) {
          return `Progress entry "${p.activity ?? ""}": the actual execution side (LHS / RHS / Both Sides / Full Width) is required for chainage-based work`;
        }
      }
    }
    const linked = progress.filter(p => p?.programmeBarId != null && !p?.noSiteWork);
    if (linked.length === 0) return null;
    const dprProjectId = input?.boqProjectId != null ? Number(input.boqProjectId) : null;
    for (const p of linked) {
      const bar = await storage.getWorkProgramBar?.(Number(p.programmeBarId));
      if (!bar) return `Progress entry "${p.activity ?? ""}": selected programme bar no longer exists`;
      if (dprProjectId != null && (bar as any).boqProjectId !== dprProjectId) {
        return `Progress entry "${p.activity ?? ""}": programme bar belongs to a different BOQ project`;
      }
      if ((bar as any).scheduled === false) {
        return `Progress entry "${p.activity ?? ""}": programme bar is not an active scheduled bar`;
      }
      if (p.boqItemId != null && (bar as any).boqItemId !== Number(p.boqItemId)) {
        return `Progress entry "${p.activity ?? ""}": BOQ item does not match the selected programme bar`;
      }
      const rowError = checkProgrammeLinkRow(p, bar as any, { draft: opts.draft });
      if (rowError) return rowError;
      // Part G: stamp review status (preserve an existing "approved").
      if (p.chainageReviewStatus !== "approved") {
        p.chainageReviewStatus = deriveChainageReviewStatus(p, bar as any);
      }
    }
    return null;
  }

  /**
   * Quantity-source verification (all progress rows, linked or not).
   * Never trusts a client-supplied "calculated" flag: recomputes the geometry
   * quantity from the submitted dimensions/chainage + the BOQ item's
   * measurement profile and compares within tolerance — the same
   * recompute-not-trust pattern as chainage containment and side checks.
   * Also stamps quantitySource="calculated" server-side when the row's
   * quantity genuinely matches the recomputed geometry value.
   */
  async function validateProgressQuantitySources(input: any, opts: { draft?: boolean } = {}): Promise<string | null> {
    const progress: any[] = Array.isArray(input?.progress) ? input.progress : [];
    for (const p of progress) {
      if (p?.noSiteWork || p?.quantity == null) continue;
      const boqItem = p.boqItemId != null ? await storage.getBoqItem(Number(p.boqItemId)) : null;
      const err = checkQuantitySourceRow(p, boqItem as any, { draft: opts.draft });
      if (err) return `Progress entry "${p.activity ?? ""}": ${err}`;
      // The server decides "calculated", not the client.
      const resolved = resolveQuantitySource(p, boqItem as any);
      if (resolved === "calculated") p.quantitySource = "calculated";
      else if (p.quantitySource === "calculated") p.quantitySource = null; // stale claim on draft — clear it
    }
    return null;
  }

  /** Outcome validation is intentionally separate from quantity/BOQ validation:
   * reusable material never changes the credited progress quantity. */
  async function validateProgressMaterialOutcomes(input: any, opts: { draft?: boolean } = {}): Promise<string | null> {
    const progress: any[] = Array.isArray(input?.progress) ? input.progress : [];
    for (const p of progress) {
      if (p?.noSiteWork) continue;
      const item = p?.boqItemId != null ? await storage.getBoqItem(Number(p.boqItemId)) : null;
      const isRoadwayExcavation = !!item
        && classifyWorkType((item as any).description ?? "", (item as any).unit ?? "") === "roadway_excavation";
      if (p?.materialOutcome != null || p?.reusableQty != null) {
        if (!isRoadwayExcavation) {
          return `Progress entry "${p?.activity ?? ""}": material outcome may only be recorded against roadway excavation.`;
        }
      }
      // Drafts preserve partial in-progress outcome controls. Strict tuple
      // validation happens only when the DPR is submitted or versioned.
      if (opts.draft) continue;
      if (!isRoadwayExcavation) continue;
       const issue = excavationMaterialOutcomeIssue(
         p?.quantity,
         p?.materialOutcome,
         p?.reusableQty,
         (item as any)?.unit,
       );
      if (issue) return `Progress entry "${p?.activity ?? ""}": ${issue}`;
    }
    return null;
  }

  /**
   * Instruction 032 Part N — lightweight scope validation for DPR progress rows.
   * Uses the shared eligible-scope service; adds NO new DPR steps. Rules:
   *  - executable scope → proceed normally
   *  - temporary block → warn; continuation requires a reason (drafts lenient)
   *  - permanent no-scope / withdrawn (on/after effective date) → block normal
   *    submission unless an authorised user (project_scope approve) overrides
   *    with a reason. Item/category exceptions respected via applicability.
   * Persists warning type / reason / user / timestamp on each affected row.
   * Projects with no confirmed working reaches are untouched (no behaviour change).
   */
  async function validateProgressScope(input: any, req: any, opts: { draft?: boolean } = {}): Promise<{ error: string; code: string } | null> {
    const progress: any[] = Array.isArray(input?.progress) ? input.progress : [];
    const rows = progress.filter(p => !p?.noSiteWork && p?.boqItemId != null && p?.chainageFromKm != null && p?.chainageToKm != null);
    if (rows.length === 0) return null;
    const segCache = new Map<number, ScopeSegmentLike[]>();
    const loadSegs = async (projectId: number): Promise<ScopeSegmentLike[]> => {
      let s = segCache.get(projectId);
      if (!s) {
        const raw = await storage.getProjectScopeSegments(projectId);
        s = (raw as any[]).map(x => ({
          id: x.id, segmentType: x.segmentType, chainageFrom: Number(x.chainageFrom), chainageTo: Number(x.chainageTo),
          side: x.side, status: x.status, applicability: x.applicability,
          categoryIds: safeIdList(x.categoryIds),
          itemIds: safeIdList(x.itemIds),
          effectiveFrom: x.effectiveFrom, effectiveTo: x.effectiveTo, label: x.label, reason: x.reason,
        }));
        segCache.set(projectId, s);
      }
      return s;
    };
    const authUser = req?.authUser;
    const canOverride = !!authUser && (authUser.isAdmin || authUser.isOwner ||
      (req.authPermissions?.project_scope?.approve === true));
    for (const p of rows) {
      const boqItem: any = await storage.getBoqItem(Number(p.boqItemId));
      if (!boqItem?.boqProjectId) continue;
      const segs = await loadSegs(Number(boqItem.boqProjectId));
      if (!segs.some(s => s.segmentType === "working_reach" && (s.status ?? "confirmed") === "confirmed")) continue;
      const isLinear = !isStructureOrLocationScheduledItem(boqItem, { hasStructureImportBar: false });
      const check = evaluateDprScope(segs, {
        boqItemId: Number(p.boqItemId),
        categoryId: boqItem.categoryId ?? null,
        isLinear,
        side: p.side ?? null,
        chainageFromKm: Number(p.chainageFromKm),
        chainageToKm: Number(p.chainageToKm),
        dprDate: input?.date ?? null,
      });
      const reason = typeof p.scopeOverrideReason === "string" && p.scopeOverrideReason.trim() ? p.scopeOverrideReason.trim() : null;
      if (check.status === "ok") {
        p.scopeWarningType = null;
        continue;
      }
      if (check.status === "temporary_block") {
        p.scopeWarningType = "temporary_block";
        if (!reason && !opts.draft) {
          return { error: `Progress entry "${p.activity ?? ""}": ${check.message} Provide a reason to continue.`, code: "SCOPE_TEMP_BLOCKED" };
        }
        if (reason) { p.scopeOverrideBy = authUser?.id ?? null; p.scopeOverrideAt = new Date(); }
        continue;
      }
      // no_scope / withdrawn — block pending authorised review (drafts may be saved with the flag)
      p.scopeWarningType = check.status;
      if (opts.draft) continue;
      if (!canOverride || !reason) {
        return {
          error: `Progress entry "${p.activity ?? ""}": ${check.message} Submission is blocked pending authorised review${canOverride ? " — provide an override reason" : ""}.`,
          code: "SCOPE_BLOCKED",
        };
      }
      p.scopeOverrideBy = authUser?.id ?? null;
      p.scopeOverrideAt = new Date();
    }
    return null;
  }

  /**
   * Batch 06B — server-side chainage-overlap recheck for Final Submit.
   * Uses the SAME neutral shared helper as Progress Report and the entry
   * screens (shared/chainageOverlap.ts). Checks BOTH:
   *  A. overlapping rows inside the submitted payload itself (same DPR);
   *  B. overlap with prior VALID submitted progress (canonical filter:
   *     submitted, not superseded, not cancelled, not deleted, chainage
   *     review not pending), excluding the DPR being submitted.
   * Overlap is never a hard block: a row with a chainageOverrideReason
   * passes. Rows without meaningful From/To km or without a BOQ item are
   * out of scope (structures/manual locations). Drafts never call this.
   * Returns Batch 04-shaped mandatory readiness issues.
   */
  async function evaluateChainageOverlapIssues(
    input: any,
    excludeDprId?: number | null,
    persistedProgress?: any[] | null,
  ): Promise<DprReadinessIssue[]> {
    const toCandidateChainageRows = (source: any): CandidateChainageRow[] => {
      const progress: any[] = Array.isArray(source?.progress) ? source.progress : [];
      return progress.map((p, i) => ({
        rowKey: i,
        boqItemId: p?.boqItemId != null ? Number(p.boqItemId) : null,
        side: p?.side ?? null,
        fromKm: p?.chainageFromKm != null ? Number(p.chainageFromKm) : parseChainageKm(p?.chainageFrom),
        toKm: p?.chainageToKm != null ? Number(p.chainageToKm) : parseChainageKm(p?.chainageTo),
        chainageOverrideReason: p?.chainageOverrideReason ?? null,
        label: p?.activity ?? null,
        noSiteWork: !!p?.noSiteWork,
        isIncidental: !!p?.isIncidental,
        layerNo: p?.layerNo != null && Number.isFinite(Number(p.layerNo)) ? Number(p.layerNo) : null,
      }));
    };
    const rows = toCandidateChainageRows(input);
    const itemIds = Array.from(new Set(rows.filter(isChainageGuardRow).map((r) => Number(r.boqItemId))));
    const priors = itemIds.length > 0 ? await storage.getSubmittedChainageEntries(itemIds, excludeDprId ?? null) : [];
    const exemptRowKeys = Array.isArray(persistedProgress)
      ? unchangedChainageRowKeys(rows, toCandidateChainageRows({ progress: persistedProgress }))
      : undefined;
    return chainageOverlapReadinessIssues(rows, priors, { exemptRowKeys })
      .map(({ section, label, message, rowKey }) => ({ section, label, message, rowKey }));
  }

  // ── 06X: PATCH /api/progress-entries/:id/overlap-resolution ─────────────────
  // Narrow classification-only patch for a single progress entry.
  //
  // Accepts EXACTLY ONE of two strictly-typed shapes (no extra fields):
  //   Shape A — incidental:       { isIncidental: true, incidentalDescription: "<non-empty>" }
  //   Shape B — override reason:  { chainageOverrideReason: "<non-empty>" }
  //
  // The two shapes are mutually exclusive — sending both keys, neither key,
  // or any unsupported field is a 400 error. Applying one resolution clears
  // the opposite classification so a row can never remain both Incidental and
  // Separately Payable.
  //
  // Guards (same semantics as DPR edit/version routes):
  //   - assertEdit(site_dprs) — edit permission required
  //   - site-access via getPermittedSiteNames
  //   - parent DPR must not be cancelled, deleted, or superseded
  //   - draft DPRs: classification patch is allowed (overlap review happens
  //     before final submit, which is when the gate fires)
  //
  // No whole-DPR readiness gate; no overlap gate. Those run on final submit.
  // Audit-logs with action "overlap_resolution".
  app.patch("/api/progress-entries/:id/overlap-resolution", requireAuth, async (req, res) => {
    try {
      if (!assertEdit(req, res, "site_dprs")) return;
      const id = Number(req.params.id);
      if (!Number.isFinite(id) || id <= 0) {
        return res.status(400).json({ message: "Invalid progress entry id" });
      }

      // ── Strict payload validation ──────────────────────────────────────────
      // Exactly one of the two shapes must be present; no extra keys from the
      // other shape are tolerated (e.g. sending chainageOverrideReason along
      // with isIncidental:true is rejected as ambiguous).
      const body = req.body ?? {};
      if (typeof body !== "object" || Array.isArray(body)) {
        return res.status(400).json({ message: "Payload must be a JSON object" });
      }
      const bodyKeys = Object.keys(body);
      const hasOverrideReason =
        typeof body.chainageOverrideReason === "string" &&
        body.chainageOverrideReason.trim() !== "";
      const hasOverrideKey =
        Object.prototype.hasOwnProperty.call(body, "chainageOverrideReason");
      const hasIncidentalKey =
        Object.prototype.hasOwnProperty.call(body, "isIncidental");
      const hasLayerKey =
        Object.prototype.hasOwnProperty.call(body, "layerNo");
      const shapeCount =
        (hasIncidentalKey ? 1 : 0) + (hasOverrideKey ? 1 : 0) + (hasLayerKey ? 1 : 0);
      if (shapeCount > 1) {
        return res.status(400).json({
          message: "Payload must be exactly one shape — one of { isIncidental: true, incidentalDescription }, { chainageOverrideReason }, or { layerNo } — not more than one",
        });
      }
      if (shapeCount === 0) {
        return res.status(400).json({
          message: "Provide exactly one of: { isIncidental: true, incidentalDescription: '<non-empty>' }, { chainageOverrideReason: '<non-empty>' }, or { layerNo: <positive integer> }",
        });
      }

      // Shape A: incidental — isIncidental must be true (not false/missing).
      if (hasIncidentalKey) {
        if (body.isIncidental !== true) {
          return res.status(400).json({
            message: "isIncidental must be true in the incidental shape",
          });
        }
        const desc =
          typeof body.incidentalDescription === "string"
            ? body.incidentalDescription.trim()
            : "";
        if (!desc) {
          return res.status(400).json({
            message: "incidentalDescription is required and must be non-empty when isIncidental is true",
          });
        }
        const allowedKeys = new Set(["isIncidental", "incidentalDescription"]);
        if (bodyKeys.length !== 2 || bodyKeys.some((key) => !allowedKeys.has(key))) {
          return res.status(400).json({
            message: "Incidental payload must contain exactly isIncidental and incidentalDescription",
          });
        }
      }

      // Shape B: override reason — must be a non-blank string.
      if (hasOverrideKey) {
        if (!hasOverrideReason) {
          return res.status(400).json({
            message: "chainageOverrideReason must be a non-empty string",
          });
        }
        if (bodyKeys.length !== 1 || bodyKeys[0] !== "chainageOverrideReason") {
          return res.status(400).json({
            message: "Separately Payable payload must contain exactly chainageOverrideReason",
          });
        }
      }

      // Shape C: layer correction — layerNo must be a positive integer. This
      // direct historical-correction flow never clears the layer to null.
      if (hasLayerKey) {
        const rawLayer = body.layerNo;
        if (
          typeof rawLayer !== "number" ||
          !Number.isInteger(rawLayer) ||
          rawLayer <= 0
        ) {
          return res.status(400).json({
            message: "layerNo must be a positive integer",
          });
        }
        if (bodyKeys.length !== 1 || bodyKeys[0] !== "layerNo") {
          return res.status(400).json({
            message: "Layer correction payload must contain exactly layerNo",
          });
        }
      }

      // ── Load entry + parent DPR header ────────────────────────────────────
      const found = await storage.getProgressEntryWithDpr(id);
      if (!found) {
        return res.status(404).json({ message: "Progress entry not found" });
      }
      const { entry, dprSite, dprIsCancelled, dprIsDeleted, dprIsSuperseded } = found;

      // ── DPR editability guard (matches DPR edit/version route semantics) ──
      if (dprIsDeleted) {
        return res.status(409).json({ message: "The parent DPR has been deleted and cannot be modified" });
      }
      if (dprIsCancelled) {
        return res.status(409).json({ message: "The parent DPR is cancelled and cannot be modified" });
      }
      if (dprIsSuperseded) {
        return res.status(409).json({ message: "The parent DPR has been superseded by a newer version and cannot be modified" });
      }

      // ── Site-access authorization ──────────────────────────────────────────
      const permittedSiteNames = await getPermittedSiteNames(req);
      if (
        permittedSiteNames !== null &&
        !siteMatchesPermitted(dprSite, permittedSiteNames)
      ) {
        return res.status(403).json({ message: "Access denied for this site" });
      }

      // ── Audit actor (shared across all shapes) ─────────────────────────────
      const actor = currentUserName(req);
      const actorId = req.authUser?.id ?? null;
      const actorRole = req.authUser
        ? (req.authUser.isOwner ? "owner" : req.authUser.isAdmin ? "admin" : "manager")
        : null;

      // ── Shape C: direct layer correction (layer_no only) ───────────────────
      // Only progress_entries.layer_no is updated; no classification is touched
      // and no layer is inferred. Canonical overlap recomputation then decides
      // whether the pair remains an overlap.
      if (hasLayerKey) {
        const newLayer = body.layerNo as number;
        const oldLayer = entry.layerNo ?? null;

        // ── Capability boundary (same as DPR forms) ──────────────────────────
        // Allow correction when:
        //   (a) the BOQ item is layer-capable per isLayerCapableItem, OR
        //   (b) the entry already has a non-null layerNo (historical correction
        //       stays permitted even when BOQ metadata is incomplete).
        // Reject when neither applies — a row with no BOQ item AND null layer
        // cannot be reliably assigned a layer number here.
        const boqItemForLayer = entry.boqItemId != null
          ? await storage.getBoqItem(entry.boqItemId)
          : null;
        const itemIsCapable = isLayerCapableItem(boqItemForLayer as any);
        const hasExistingLayer = oldLayer != null;
        if (!itemIsCapable && !hasExistingLayer) {
          return res.status(422).json({
            message:
              "This progress entry belongs to a BOQ item that is not layer-capable, " +
              "and no layer number has been previously recorded. " +
              "Layer correction is only available for layer-capable items (e.g. WMM, GSB, embankment) " +
              "or entries that already carry a layer number.",
          });
        }

        const updatedEntry = await storage.updateProgressEntryLayer(id, newLayer);
        if (!updatedEntry) {
          return res.status(404).json({ message: "Progress entry not found" });
        }
        await storage.logAudit({
          module: "progress_entries",
          transactionId: id,
          action: "overlap_resolution",
          userId: actorId,
          userName: actor,
          userRole: actorRole,
          oldValues: { layerNo: oldLayer },
          newValues: { layerNo: updatedEntry.layerNo ?? null },
          reason: `Layer correction: ${oldLayer ?? "not recorded"} → ${newLayer}`,
        });
        return res.json(updatedEntry);
      }

      // ── Build strictly-shaped resolution input (Shapes A/B) ────────────────
      type ClassificationFields =
        | { isIncidental: true; incidentalDescription: string }
        | { chainageOverrideReason: string };
      const classificationFields: ClassificationFields = hasIncidentalKey
        ? { isIncidental: true, incidentalDescription: (body.incidentalDescription as string).trim() }
        : { chainageOverrideReason: (body.chainageOverrideReason as string).trim() };

      // ── Snapshot old values for audit trail ───────────────────────────────
      const oldValues = {
        isIncidental: entry.isIncidental ?? false,
        incidentalDescription: entry.incidentalDescription ?? null,
        chainageOverrideReason: entry.chainageOverrideReason ?? null,
      };

      const updated = await storage.updateProgressEntryClassification(id, classificationFields);
      if (!updated) {
        return res.status(404).json({ message: "Progress entry not found" });
      }
      const newValues = {
        isIncidental: updated.isIncidental ?? false,
        incidentalDescription: updated.incidentalDescription ?? null,
        chainageOverrideReason: updated.chainageOverrideReason ?? null,
      };

      // ── Audit log ─────────────────────────────────────────────────────────
      const reason = hasIncidentalKey
        ? `Marked incidental: ${(classificationFields as { isIncidental: true; incidentalDescription: string }).incidentalDescription}`
        : `Overlap override reason: ${(classificationFields as { chainageOverrideReason: string }).chainageOverrideReason}`;
      await storage.logAudit({
        module: "progress_entries",
        transactionId: id,
        action: "overlap_resolution",
        userId: actorId,
        userName: actor,
        userRole: actorRole,
        oldValues,
        newValues,
        reason,
      });

      res.json(updated);
    } catch (err) {
      console.error("PATCH /api/progress-entries/:id/overlap-resolution:", err);
      res.status(500).json({ message: "Failed to update progress entry classification" });
    }
  });

  // Batch 06B — prior submitted chainage progress route is registered above
  // /api/dprs/:id; keep this marker as the overlap-resolution section boundary.

  // Create new DPR (draft or submitted)
  // 06M-B: shared 409 mapping for the diesel plant-stock sufficiency guard.
  // Fires whenever a DPR equipment log or Equipment Usage row would push the
  // recorded plant Diesel stock below zero. Returns the structured payload
  // the client dialogs render (required/available/shortage in litres).
  const handleInsufficientPlantStock = (err: unknown, res: any): boolean => {
    if (err instanceof InsufficientPlantStockError) {
      const material = err.payload.material.trim().toUpperCase();
      res.status(409).json({
        code: err.code,
        ...err.payload,
        message: `INSUFFICIENT ${material} IN PLANT STOCK — Required: ${err.payload.requestedQty} L, Available: ${err.payload.availableQty} L, Shortfall: ${err.payload.shortageQty} L. If purchased Diesel has already arrived, first enter its physical receipt under Material Receipt so it is added to Plant Stock.`,
      });
      return true;
    }
    return false;
  };
  const handleEquipmentLifecycleConflict = (err: unknown, res: any): boolean => {
    if (err instanceof EquipmentIncomingConflictError) {
      res.status(409).json({ code: err.code, message: err.message });
      return true;
    }
    return false;
  };

  const handleEquipmentActivityAllocationError = (err: unknown, res: Response): boolean => {
    if (!(err instanceof EquipmentActivityAllocationError)) return false;
    res.status(422).json({ code: err.code, message: err.message });
    return true;
  };

  /**
   * A legacy saved null is repaired only when the replacement will retain real
   * BOQ evidence: incoming rows or equipment children explicitly preserved by
   * the replacement. Cleared progress/labour/material/structure rows do not
   * count. The old confirmation flag is intentionally not consulted: client
   * confirmation is not proof that a project or an item is valid.
   * Storage repeats the evidence, item ownership, and site checks under the
   * project-before-DPR transaction lock.
   */
  const sameDprSiteName = (left: unknown, right: unknown): boolean => {
    const normalize = (value: unknown) => normalizeDprSiteName(
      typeof value === "string"
        ? value.replace(/ – (Edited by|Copy by) .+$/, "")
        : value,
    );
    const normalizedLeft = normalize(left);
    return normalizedLeft !== "" && normalizedLeft === normalize(right);
  };

  const automaticNullProjectRecovery = async (
    existing: any,
    input: any,
  ): Promise<boolean> => {
    const savedProjectId = existing?.boqProjectId != null ? Number(existing.boqProjectId) : null;
    const requestedProjectId = input?.boqProjectId != null ? Number(input.boqProjectId) : null;
    const sameDprSite = sameDprSiteName(existing?.site, input?.site);
    if (!isEvidenceBasedDprNullProjectRecovery({
      savedProjectId,
      requestedProjectId,
      sameSite: sameDprSite,
      hasBoqReferences: hasDprBoqReferences(input)
        || hasPreservedDprBoqReferences(existing, input),
    })) return false;
    const [project] = await db.select({
      siteId: boqProjectsTable.siteId,
      siteName: sitesTable.name,
    })
      .from(boqProjectsTable)
      .innerJoin(sitesTable, eq(boqProjectsTable.siteId, sitesTable.id))
      .where(eq(boqProjectsTable.id, requestedProjectId!))
      .limit(1);
    if (!project || !sameDprSiteName(project.siteName, input.site)) return false;
    const matchingSites = await db.select({
      id: sitesTable.id,
      name: sitesTable.name,
    }).from(sitesTable);
    const normalizedInputSite = normalizeDprSiteName(input.site);
    const normalizedMatches = matchingSites.filter((site) =>
      normalizeDprSiteName(site.name) === normalizedInputSite,
    );
    return normalizedMatches.length === 1
      && Number(normalizedMatches[0]?.id) === Number(project.siteId);
  };

  const sectionContextSchema = z.object({
    site: z.string().trim().min(1),
    date: z.string().regex(/^\d{4}-\d{2}-\d{2}$/),
    workType: z.enum(["road", "structure", "protective", "misc"]).default("road"),
    boqProjectId: z.number().int().positive().nullable().default(null),
  });
  const loadSectionSnapshot = async (id: number) => db.transaction(async (tx) => {
    await tx.execute(sql`SELECT id FROM dprs WHERE id = ${id} FOR SHARE`);
    const row = await readSectionAggregate(tx, id);
    return row ? sectionSnapshot(row) : undefined;
  });
  const sectionFailure = (err: any, res: Response) => {
    if (err instanceof z.ZodError) return res.status(400).json({ message: err.errors[0].message, field: err.errors[0].path.join(".") });
    if (err instanceof DprSectionConflict) return res.status(409).json({ message: err.message, code: err.code });
    if (handleInsufficientPlantStock(err, res) || handleEquipmentLifecycleConflict(err, res) || handleEquipmentActivityAllocationError(err, res)) return;
    if (err?.code === "SCOPE_CHANGED_DURING_PLANNING") return res.status(409).json({ code: err.code, message: err.message });
    if (err instanceof InvalidDieselSourceError || err instanceof CutFillValidationError || err instanceof DprProjectMismatchError) {
      return res.status(422).json({ code: err.code, message: err.message });
    }
    if (err instanceof CutFillInsufficientAvailabilityError) return res.status(409).json({ code: err.code, message: err.message });
    if (err?.status) return res.status(err.status).json({ code: err.code, message: err.message, mandatory: err.mandatory, advisories: err.advisories });
    console.error("[DPR section] save failed", dprSaveErrorMetadata(err));
    return res.status(500).json({ message: "Failed to save DPR section" });
  };
  const validateSectionAggregate = async (input: any, req: any, id: number, draft: boolean) => {
    const permitted = await getPermittedSiteNames(req);
    if (permitted !== null && !siteMatchesPermitted(input.site, permitted)) throw Object.assign(new Error("Access denied for this site"), { status: 403 });
    for (const [validator, code] of [
      [validateProgressProgrammeLinks, "PROGRAMME_LINK_INVALID"],
      [validateProgressQuantitySources, "QUANTITY_SOURCE_INVALID"],
      [validateProgressMaterialOutcomes, "MATERIAL_OUTCOME_INVALID"],
    ] as const) {
      const message = await validator(input, { draft });
      if (message) throw Object.assign(new Error(message), { code, status: 400 });
    }
    const scope = await validateProgressScope(input, req, { draft });
    if (scope) throw Object.assign(new Error(scope.error), { code: scope.code, status: 422 });
    if (!draft) {
      const readiness = evaluateDprSubmitReadiness(input);
      const mandatory = [...readiness.mandatory, ...await evaluateChainageOverlapIssues(input, id)];
      if (mandatory.length) throw Object.assign(new Error("DPR is not ready to submit"), {
        code: "DPR_NOT_READY", status: 422, mandatory, advisories: readiness.advisories,
      });
    }
  };
  app.post("/api/dpr-sections/resolve", async (req, res) => {
    try {
      if (!assertView(req, res, "site_dprs")) return;
      const context = normalizeDprSectionContext(sectionContextSchema.parse(req.body.context));
      const permitted = await getPermittedSiteNames(req);
      if (permitted !== null && !siteMatchesPermitted(context.site, permitted)) return res.status(403).json({ message: "Access denied for this site" });
      const candidates = await findSectionDrafts(db, context);
      if (!candidates.length) return res.json({ kind: "new" });
      if (candidates.length === 1) return res.json({ kind: "existing", snapshot: await loadSectionSnapshot(candidates[0].id) });
      return res.json({ kind: "choose", candidates: candidates.map((row: any) => ({
        id: row.id, site: row.site, date: row.date, workType: row.workType, boqProjectId: row.boqProjectId,
        engineer: row.engineer, lastEditedAt: row.lastEditedAt, createdAt: row.createdAt,
      })) });
    } catch (err) { sectionFailure(err, res); }
  });
  app.get("/api/dpr-sections/:id", async (req, res) => {
    try {
      if (!assertView(req, res, "site_dprs")) return;
      const id = z.coerce.number().int().positive().parse(req.params.id);
      const snapshot = await loadSectionSnapshot(id);
      if (!snapshot) return res.status(404).json({ message: "DPR not found" });
      const permitted = await getPermittedSiteNames(req);
      if (permitted !== null && !siteMatchesPermitted(snapshot.dpr.site, permitted)) return res.status(403).json({ message: "Access denied for this site" });
      return res.json(snapshot);
    } catch (err) { sectionFailure(err, res); }
  });
  app.put("/api/dpr-sections/:section", async (req, res) => {
    try {
      if (!assertCreate(req, res, "site_dprs")) return;
      const section = z.enum(DPR_SECTIONS).parse(req.params.section);
      const context = normalizeDprSectionContext(sectionContextSchema.parse(req.body.context));
      const dprId = z.number().int().positive().optional().parse(req.body.dprId);
      const data = z.record(z.unknown()).parse(req.body.data);
      const allowed = new Set([...DPR_SECTION_FIELDS[section], "engineer"]);
      if (Object.keys(data).some(key => !allowed.has(key))) return res.status(400).json({ message: "Payload contains fields owned by a different section" });
      if (!dprId) z.string().trim().min(1).parse(data.engineer);
      const permitted = await getPermittedSiteNames(req);
      if (permitted !== null && !siteMatchesPermitted(context.site, permitted)) return res.status(403).json({ message: "Access denied for this site" });
      if (dprId) {
        const existing = await storage.getDpr(dprId);
        if (!existing) return res.status(404).json({ message: "DPR not found" });
        if (permitted !== null && !siteMatchesPermitted(existing.site, permitted)) return res.status(403).json({ message: "Access denied for this site" });
      }
      const scopeToken = context.boqProjectId == null ? null : await storage.getProjectScopeVersionToken(context.boqProjectId);
      const snapshot = await saveDprSection(db, storage, {
        section, context, dprId, data, sectionToken: req.body.sectionToken, headerToken: req.body.headerToken,
        clientKey: z.string().min(16).max(128).optional().parse(req.body.clientKey),
        actorName: req.authUser?.fullName,
      }, req.authUser?.id ?? null, (input, id) => validateSectionAggregate(input, req, id, true), scopeToken);
      return res.json(snapshot);
    } catch (err) { sectionFailure(err, res); }
  });

  app.post(api.dprs.create.path, async (req, res) => {
    let requestedDprStatus: string | undefined;
    try {
      if (!assertCreate(req, res, "site_dprs")) return;
      const input = api.dprs.create.input.parse(req.body);
      requestedDprStatus = (input as any).dprStatus;
      const permittedSiteNames = await getPermittedSiteNames(req);
      if (permittedSiteNames !== null && !siteMatchesPermitted(input.site, permittedSiteNames)) {
        return res.status(403).json({ message: "Access denied for this site" });
      }
      // Draft creation participates in the same project mutex as scope
      // correction. The token turns a validation-then-write race into a
      // deterministic retry instead of allowing stale dependent links.
      const scopeVersionToken = (input as any).boqProjectId != null
        ? await storage.getProjectScopeVersionToken(Number((input as any).boqProjectId))
        : null;
      // 030A Part F: validate programme-bar links server-side (draft-lenient
      // when saving a draft — Instruction 031 Part B).
      const linkError = await validateProgressProgrammeLinks(input, { draft: (input as any).dprStatus === "draft" });
      if (linkError) return res.status(400).json({ message: linkError, code: "PROGRAMME_LINK_INVALID" });
      const qtySourceError = await validateProgressQuantitySources(input, { draft: (input as any).dprStatus === "draft" });
      if (qtySourceError) return res.status(400).json({ message: qtySourceError, code: "QUANTITY_SOURCE_INVALID" });
      const materialOutcomeError = await validateProgressMaterialOutcomes(input, { draft: (input as any).dprStatus === "draft" });
      if (materialOutcomeError) return res.status(400).json({ message: materialOutcomeError, code: "MATERIAL_OUTCOME_INVALID" });
      const scopeError = await validateProgressScope(input, req, { draft: (input as any).dprStatus === "draft" });
      if (scopeError) return res.status(422).json({ message: scopeError.error, code: scopeError.code });
      // Batch 04: shared submit-readiness gate. Drafts stay lenient; Final
      // Submit is rejected only for MANDATORY issues (advisories never block).
      if ((input as any).dprStatus !== "draft") {
        const readiness = evaluateDprSubmitReadiness(input as any);
        // Batch 06B: server-side chainage-overlap recheck (same-DPR + prior
        // submitted DPRs) — mandatory unless the row carries a reason.
        const overlapIssues = await evaluateChainageOverlapIssues(input, null);
        const mandatory = [...readiness.mandatory, ...overlapIssues];
        if (mandatory.length > 0) {
          return res.status(422).json({
            message: "DPR is not ready to submit",
            code: "DPR_NOT_READY",
            mandatory,
            advisories: readiness.advisories,
          });
        }
      }
      const createOptions = { reuseExistingDraft: req.query.resumeExisting === "1" };
      const dpr = await storage.createDpr(input, input.clientTimestamp, {
        userId: req.authUser?.id ?? null,
        userName: req.authUser ? currentUserName(req) : input.engineer,
        closedAt: new Date(),
      }, { ...createOptions, scopeVersionToken });
      const isDraft = (input as any).dprStatus === "draft";
      if (!isDraft) {
        await storage.createNotification({ type: "success", title: "New DPR Submitted", message: `${input.engineer || 'Engineer'} submitted DPR for ${input.site} (${input.date})`, isRead: 0 });
        sendPushToSection("site_dprs", "New DPR Submitted", `${input.engineer || 'Engineer'} - ${input.site} - ${input.date}`, "/site-reports").catch(() => {});
      }
      if (isDraft) {
        const snapshot = await loadSectionSnapshot(dpr.id);
        if (!snapshot) throw new DprSectionConflict("The created DPR is no longer available.");
        return res.status(201).json({ ...snapshot.dpr, headerToken: snapshot.headerToken, sectionTokens: snapshot.sectionTokens });
      }
      res.status(201).json(dpr);
    } catch (err) {
      if (err instanceof DprSectionConflict) return sectionFailure(err, res);
      if ((err as any)?.code === "SCOPE_CHANGED_DURING_SUBMIT" || (err as any)?.code === "SCOPE_CHANGED_DURING_PLANNING") {
        const code = requestedDprStatus === "draft"
          ? "SCOPE_CHANGED_DURING_PLANNING"
          : "SCOPE_CHANGED_DURING_SUBMIT";
        return res.status(409).json({ code, message: (err as any).message });
      }
      if ((err as any)?.code === "DPR_PROJECT_MISMATCH" || (DprProjectMismatchError && err instanceof DprProjectMismatchError)) {
        return res.status(400).json({
          code: "DPR_PROJECT_MISMATCH",
          message: (err as any).message,
          itemIds: (err as any).itemIds ?? [],
        });
      }
      if (err instanceof z.ZodError) {
        return res.status(400).json({
          message: err.errors[0].message,
          field: err.errors[0].path.join('.'),
        });
      }
      if (handleInsufficientPlantStock(err, res)) return;
      if (err instanceof InvalidDieselSourceError) return res.status(400).json({ code: err.code, field: err.field, message: err.message });
      if (err instanceof CutFillInsufficientAvailabilityError) return res.status(409).json({ code: err.code, message: err.message, availableQty: err.availableQty, alreadyUsedQty: err.alreadyUsedQty });
      if (err instanceof CutFillValidationError) return res.status(422).json({ code: err.code, message: err.message });
      if (handleEquipmentActivityAllocationError(err, res)) return;
      if (handleEquipmentLifecycleConflict(err, res)) return;
      res.status(500).json({ message: "Failed to create DPR" });
    }
  });

  // Update an existing draft DPR (engineer only; no notification/push/PIN)
  app.patch("/api/dprs/:id/draft", async (req, res) => {
    try {
      if (!assertCreate(req, res, "site_dprs")) return;
      const id = Number(req.params.id);
      const existing = await storage.getDpr(id);
      if (!existing) return res.status(404).json({ message: "DPR not found" });
      if ((existing as any).dprStatus !== "draft") return res.status(400).json({ message: "Only draft DPRs can be updated via this endpoint" });
      const permittedSiteNames = await getPermittedSiteNames(req);
      if (permittedSiteNames !== null && !siteMatchesPermitted(existing.site, permittedSiteNames)) {
        return res.status(403).json({ message: "Access denied for this site" });
      }
      const draftSnapshot = await loadSectionSnapshot(id);
      if (!draftSnapshot) return res.status(404).json({ message: "DPR not found" });
      assertSectionTokens(draftSnapshot, req.body);
      let input = createDprRequestSchema.parse(req.body);
      if (permittedSiteNames !== null && !siteMatchesPermitted(input.site, permittedSiteNames)) {
        return res.status(403).json({ message: "Access denied for this site" });
      }
      const savedProjectId = (existing as any).boqProjectId != null ? Number((existing as any).boqProjectId) : null;
      const payloadProjectId = (input as any).boqProjectId != null ? Number((input as any).boqProjectId) : null;
      const projectRecoveryAllowed = await automaticNullProjectRecovery(existing, input);
      if (savedProjectId !== payloadProjectId && !projectRecoveryAllowed) {
        // A project selected on a no-BOQ DPR is metadata only.  Guided
        // re-resolution can change that metadata between draft saves, but it
        // must never be allowed to move a DPR which contains real BOQ-linked
        // work.  Existing child refs are included because equipment
        // allocations/segments may be retained by the replacement write when
        // a compact PATCH omits those child arrays.
        const hasBoqReferences =
            hasDprBoqReferences(input) || hasPreservedDprBoqReferences(existing, input);
        if (savedProjectId == null && payloadProjectId != null && !sameDprSiteName(existing.site, input.site)) {
          return res.status(400).json({
            code: "DPR_PROJECT_RECOVERY_CONFIRMATION_REQUIRED",
            message: "A saved no-project DPR can only be recovered on its original site.",
          });
        }
        if (!hasBoqReferences) {
          // A saved null with no BOQ evidence remains intentionally null.
          // Canonicalizing here preserves storage's unconditional header
          // mismatch guard without allowing a client-side project guess.
          input = { ...input, boqProjectId: savedProjectId };
        } else {
          return res.status(400).json({
            code: "DPR_PROJECT_MISMATCH",
            message: "A draft DPR's BOQ project cannot change while it is being edited.",
            savedProjectId,
            payloadProjectId,
          });
        }
      }
      const scopeVersionToken = (input as any).boqProjectId != null
        ? await storage.getProjectScopeVersionToken(Number((input as any).boqProjectId))
        : null;
      const linkError = await validateProgressProgrammeLinks(input, { draft: true });
      if (linkError) return res.status(400).json({ message: linkError, code: "PROGRAMME_LINK_INVALID" });
      const qtySourceError = await validateProgressQuantitySources(input, { draft: true });
      if (qtySourceError) return res.status(400).json({ message: qtySourceError, code: "QUANTITY_SOURCE_INVALID" });
      const materialOutcomeError = await validateProgressMaterialOutcomes(input, { draft: true });
      if (materialOutcomeError) return res.status(400).json({ message: materialOutcomeError, code: "MATERIAL_OUTCOME_INVALID" });
      const scopeError = await validateProgressScope(input, req, { draft: true });
      if (scopeError) return res.status(422).json({ message: scopeError.error, code: scopeError.code });
      // storage.updateDraftDpr(id, input, req.authUser?.id ?? null)
      // (scopeVersionToken is the fourth argument for the project-mutex handoff)
      const updated = await storage.updateDraftDpr(id, input, req.authUser?.id ?? null, scopeVersionToken, projectRecoveryAllowed, {
        headerToken: req.body.headerToken, sectionTokens: req.body.sectionTokens,
      });
      if (!updated) return res.status(404).json({ message: "DPR not found or not a draft" });
      const savedSnapshot = await loadSectionSnapshot(id);
      if (!savedSnapshot) throw new DprSectionConflict("The saved DPR is no longer available. Reload before continuing.");
      res.json({
        ...savedSnapshot.dpr, sectionTokens: savedSnapshot.sectionTokens, headerToken: savedSnapshot.headerToken,
      });
    } catch (err) {
      if (err instanceof DprSectionConflict) return sectionFailure(err, res);
      if ((err as any)?.code === "SCOPE_CHANGED_DURING_PLANNING") {
        return res.status(409).json({ code: "SCOPE_CHANGED_DURING_PLANNING", message: (err as any).message });
      }
      if ((err as any)?.code === "DPR_PROJECT_MISMATCH" || (DprProjectMismatchError && err instanceof DprProjectMismatchError)) {
        return res.status(400).json({
          code: "DPR_PROJECT_MISMATCH",
          message: (err as any).message,
          savedProjectId: (err as any).savedProjectId,
          payloadProjectId: (err as any).payloadProjectId,
          itemIds: (err as any).itemIds ?? [],
        });
      }
      if (err instanceof InvalidDieselSourceError) return res.status(400).json({ code: err.code, field: err.field, message: err.message });
      if (err instanceof z.ZodError) return res.status(400).json({ message: err.errors[0].message, field: err.errors[0].path.join('.') });
      if (handleInsufficientPlantStock(err, res)) return;
      if (err instanceof CutFillInsufficientAvailabilityError) return res.status(409).json({ code: err.code, message: err.message, availableQty: err.availableQty, alreadyUsedQty: err.alreadyUsedQty });
      if (err instanceof CutFillValidationError) return res.status(422).json({ code: err.code, message: err.message });
      if (handleEquipmentActivityAllocationError(err, res)) return;
      console.error("[DPR draft save] Unexpected failure", {
        operation: "PATCH /api/dprs/:id/draft",
        dprId: Number.isSafeInteger(Number(req.params.id)) ? Number(req.params.id) : null,
        actorUserId: req.authUser?.id ?? null,
        ...dprSaveErrorMetadata(err),
      });
      res.status(500).json({ message: "Failed to update draft DPR" });
    }
  });

  // Submit a draft DPR (change to submitted, fire notification)
  app.post(["/api/dprs/:id/submit", "/api/dpr-sections/:id/submit"], async (req, res) => {
    try {
      if (!assertCreate(req, res, "site_dprs")) return;
      const id = Number(req.params.id);
      const existing = await storage.getDpr(id);
      if (!existing) return res.status(404).json({ message: "DPR not found" });
      if ((existing as any).dprStatus !== "draft") return res.status(400).json({ message: "Only draft DPRs can be submitted via this endpoint" });
      const permittedSiteNames = await getPermittedSiteNames(req);
      if (permittedSiteNames !== null && !siteMatchesPermitted(existing.site, permittedSiteNames)) {
        return res.status(403).json({ message: "Access denied for this site" });
      }
      const snapshot = await loadSectionSnapshot(id);
      if (!snapshot) return res.status(404).json({ message: "DPR not found" });
      assertSectionTokens(snapshot, req.body);
      // Both legacy and section submissions now finalize saved content only.
      // Unsaved form data must first be explicitly saved with its tokens.
      let input = createDprRequestSchema.parse(snapshot.dpr);
      if (permittedSiteNames !== null && !siteMatchesPermitted(input.site, permittedSiteNames)) {
        return res.status(403).json({ message: "Access denied for this site" });
      }
      const savedProjectId = (existing as any).boqProjectId != null ? Number((existing as any).boqProjectId) : null;
      const payloadProjectId = (input as any).boqProjectId != null ? Number((input as any).boqProjectId) : null;
      const projectRecoveryAllowed = await automaticNullProjectRecovery(existing, input);
      if (savedProjectId !== payloadProjectId && !projectRecoveryAllowed) {
        // Same narrow carve-out as draft PATCH: a no-BOQ DPR may carry a
        // newly re-resolved project header, but any real progress, equipment,
        // allocation/segment, structure, material, or labour BOQ reference
        // keeps the mismatch protection active.  Existing refs matter because
        // replacement storage can preserve omitted equipment children.
        const hasBoqReferences =
          hasDprBoqReferences(input) || hasPreservedDprBoqReferences(existing, input);
        if (savedProjectId == null && payloadProjectId != null && !sameDprSiteName(existing.site, input.site)) {
          return res.status(400).json({
            code: "DPR_PROJECT_RECOVERY_CONFIRMATION_REQUIRED",
            message: "A saved no-project DPR can only be recovered on its original site.",
          });
        }
        if (!hasBoqReferences) {
          input = { ...input, boqProjectId: savedProjectId };
        } else {
          return res.status(400).json({
            code: "DPR_PROJECT_MISMATCH",
            message: "A DPR's BOQ project cannot change when a draft is submitted.",
            savedProjectId,
            payloadProjectId,
          });
        }
      }
      // Scope correction and final submit use the BOQ project row as a
      // transaction mutex. Carry a token from validation into the submit
      // transaction so a correction committed in between is rejected and
      // revalidated rather than silently bypassing the corrected scope.
      const scopeVersionToken = (input as any).boqProjectId != null
        ? await storage.getProjectScopeVersionToken(Number((input as any).boqProjectId))
        : null;
      const linkError = await validateProgressProgrammeLinks(input);
      if (linkError) return res.status(400).json({ message: linkError, code: "PROGRAMME_LINK_INVALID" });
      const qtySourceError = await validateProgressQuantitySources(input);
      if (qtySourceError) return res.status(400).json({ message: qtySourceError, code: "QUANTITY_SOURCE_INVALID" });
      const materialOutcomeError = await validateProgressMaterialOutcomes(input);
      if (materialOutcomeError) return res.status(400).json({ message: materialOutcomeError, code: "MATERIAL_OUTCOME_INVALID" });
      const scopeError = await validateProgressScope(input, req, {});
      if (scopeError) return res.status(422).json({ message: scopeError.error, code: scopeError.code });
      // Batch 04: same shared submit-readiness gate as non-draft create.
      {
        const readiness = evaluateDprSubmitReadiness(input as any);
        // Batch 06B: chainage-overlap recheck against current DB state,
        // excluding the draft being submitted.
        const overlapIssues = await evaluateChainageOverlapIssues(input, id);
        const mandatory = [...readiness.mandatory, ...overlapIssues];
        if (mandatory.length > 0) {
          return res.status(422).json({
            message: "DPR is not ready to submit",
            code: "DPR_NOT_READY",
            mandatory,
            advisories: readiness.advisories,
          });
        }
      }
      const clientTimestamp = (req.body as any).clientTimestamp;
      const submitted = await storage.submitDraftDpr(id, input, clientTimestamp, {
        userId: req.authUser?.id ?? null,
        userName: req.authUser ? currentUserName(req) : input.engineer,
        closedAt: new Date(),
      }, scopeVersionToken, projectRecoveryAllowed, {
        headerToken: req.body.headerToken, sectionTokens: req.body.sectionTokens, stored: true,
        validate: async (aggregate: any, dprId: number) => {
          const validated = createDprRequestSchema.parse(aggregate);
          await validateSectionAggregate(validated, req, dprId, false);
          return validated;
        },
      });
      if (!submitted) return res.status(404).json({ message: "DPR not found or not a draft" });
      await storage.createNotification({ type: "success", title: "New DPR Submitted", message: `${submitted.engineer || 'Engineer'} submitted DPR for ${submitted.site} (${submitted.date})`, isRead: 0 });
      sendPushToSection("site_dprs", "New DPR Submitted", `${submitted.engineer || 'Engineer'} - ${submitted.site} - ${submitted.date}`, "/site-reports").catch(() => {});
      res.json(submitted);
    } catch (err) {
      if (err instanceof DprSectionConflict || (err as any)?.status) return sectionFailure(err, res);
      if ((err as any)?.code === "SCOPE_CHANGED_DURING_SUBMIT" || (err as any)?.code === "SCOPE_CHANGED_DURING_PLANNING") {
        return res.status(409).json({ code: "SCOPE_CHANGED_DURING_SUBMIT", message: (err as any).message });
      }
      if ((err as any)?.code === "DPR_PROJECT_MISMATCH" || (DprProjectMismatchError && err instanceof DprProjectMismatchError)) {
        return res.status(400).json({
          code: "DPR_PROJECT_MISMATCH",
          message: (err as any).message,
          savedProjectId: (err as any).savedProjectId,
          payloadProjectId: (err as any).payloadProjectId,
          itemIds: (err as any).itemIds ?? [],
        });
      }
      if (err instanceof InvalidDieselSourceError) return res.status(400).json({ code: err.code, field: err.field, message: err.message });
      if (err instanceof z.ZodError) return res.status(400).json({ message: err.errors[0].message, field: err.errors[0].path.join('.') });
      if (handleInsufficientPlantStock(err, res)) return;
      if (err instanceof CutFillInsufficientAvailabilityError) return res.status(409).json({ code: err.code, message: err.message, availableQty: err.availableQty, alreadyUsedQty: err.alreadyUsedQty });
      if (err instanceof CutFillValidationError) return res.status(422).json({ code: err.code, message: err.message });
      if (handleEquipmentActivityAllocationError(err, res)) return;
      if (handleEquipmentLifecycleConflict(err, res)) return;
      res.status(500).json({ message: "Failed to submit DPR" });
    }
  });

