  // Material Receipts
  // Linked diesel receipts must always point to this one stock material. Keeping
  // the lookup shared between create and correction paths prevents historical
  // links from being changed to another similarly named material.
  async function getCanonicalDieselMaterial() {
    const materials = await storage.getAllPlantMaterials();
    return ["DIESEL", "HSD"].map((name) =>
      materials.find((m) => m.isActive !== 0 && m.name.trim().toUpperCase() === name),
    ).find(Boolean);
  }

  const isDieselMaterialName = (name: string | null | undefined) =>
    /^(diesel|hsd)$/i.test((name ?? "").trim());

  const canRecordStandaloneDieselReceipt = (req: any) => !!(
    req.authUser?.isOwner ||
    req.authUser?.isAdmin ||
    req.authPermissions?.site_diesel?.edit ||
    req.authPermissions?.diesel_req_raise?.edit
  );

  async function validateDieselReceiptControl(
    req: any,
    input: Partial<import("@shared/schema").InsertMaterialReceipt>,
    existing?: import("@shared/schema").MaterialReceipt,
  ): Promise<{ status: number; body: any } | null> {
    const materialId = input.materialId ?? existing?.materialId;
    const material = (await storage.getAllPlantMaterials()).find((m) => m.id === materialId);
    if (!material) return { status: 400, body: { message: `Plant material #${materialId} not found` } };

    const diesel = isDieselMaterialName(material.name);
    const suppliedLink = Object.prototype.hasOwnProperty.call(input, "linkedDieselRequirementId");
    let effectiveLink = suppliedLink ? input.linkedDieselRequirementId : existing?.linkedDieselRequirementId;
    const isRegularising = existing?.linkedDieselRequirementId == null && effectiveLink != null;

    // A valid existing purchase link cannot be stripped or changed through a
    // receipt correction. An unlinked exception may, however, be regularised.
    if (existing?.linkedDieselRequirementId != null) {
      effectiveLink = existing.linkedDieselRequirementId;
    }

    if (!diesel) {
      if (effectiveLink != null) {
        return { status: 400, body: { code: "LINKED_DIESEL_MATERIAL_MISMATCH", message: "Only Diesel receipts can be linked to a Daily Diesel Requirement" } };
      }
      input.dieselExceptionReason = null;
      return null;
    }

    if (effectiveLink == null) {
      // Historical unlinked Diesel/HSD rows predate the exception field. An
      // ordinary correction must leave them distinguishable as legacy rows:
      // do not require a new reason and do not silently write one.
      if (existing && existing.linkedDieselRequirementId == null && existing.dieselExceptionReason == null) {
        input.dieselExceptionReason = null;
        return null;
      }
      if (!canRecordStandaloneDieselReceipt(req)) {
        return { status: 403, body: { code: "DIESEL_STANDALONE_NOT_AUTHORISED", message: "Diesel/HSD receipts must be linked to a purchased Daily Diesel Requirement. Only Owner/Admin/PM may record a standalone exception." } };
      }
      const reason = String(input.dieselExceptionReason ?? existing?.dieselExceptionReason ?? "").trim();
      if (!reason) {
        return { status: 400, body: { code: "DIESEL_EXCEPTION_REASON_REQUIRED", message: "A reason is required for an exceptional standalone Diesel/HSD receipt" } };
      }
      input.dieselExceptionReason = reason;
      return null;
    }

    // Linking a legacy or exceptional receipt is a deliberate stock-record
    // regularisation, not an ordinary plant-material correction.
    if (isRegularising && !canRecordStandaloneDieselReceipt(req)) {
      return { status: 403, body: { code: "DIESEL_REGULARISATION_NOT_AUTHORISED", message: "Only Owner/Admin/PM may link a standalone Diesel/HSD receipt to a Daily Diesel Requirement." } };
    }

    const linkedReq = await storage.getDieselRequirement(effectiveLink);
    if (!linkedReq || linkedReq.status !== "purchased" || !(linkedReq as any).qtyPurchased) {
      return { status: 400, body: { message: "Linked diesel requirement not found or not a completed purchase" } };
    }
    const canonicalDiesel = await getCanonicalDieselMaterial();
    if (!canonicalDiesel) {
      return { status: 400, body: { code: "CANONICAL_DIESEL_MATERIAL_NOT_CONFIGURED", message: "Linked diesel receipts require an active canonical DIESEL or HSD plant material" } };
    }
    if (material.id !== canonicalDiesel.id) {
      return { status: 400, body: { code: "LINKED_DIESEL_MATERIAL_MISMATCH", message: "Only Diesel receipts using the canonical diesel material can be linked to a diesel purchase" } };
    }
    const effectiveUom = input.uom ?? existing?.uom ?? "";
    if (effectiveUom.trim().toLowerCase() !== "liters") {
      return { status: 400, body: { code: "LINKED_DIESEL_UOM_INVALID", message: "Linked diesel receipts must use UOM Liters" } };
    }
    input.uom = "Liters";
    if (isRegularising || !existing) input.linkedDieselRequirementId = effectiveLink;
    else delete input.linkedDieselRequirementId;

    const linkedReceipts = (await storage.getDieselRequirementReceipts([effectiveLink]))
      .filter((r) => r.id !== existing?.id);
    const state = computeDieselReceiptState((linkedReq as any).qtyPurchased, linkedReceipts);
    const requestedQty = Number(input.quantity ?? existing?.quantity ?? 0);
    if (requestedQty > state.pendingQty + 0.001) {
      const excessQty = Math.round((requestedQty - state.pendingQty) * 1000) / 1000;
      return {
        status: 409,
        body: {
          code: "DIESEL_RECEIPT_EXCEEDS_REMAINING",
          message: `Diesel receipt quantity ${requestedQty} L exceeds the remaining purchased quantity ${state.pendingQty} L by ${excessQty} L`,
          requestedQty,
          remainingQty: state.pendingQty,
          excessQty,
          linkedDieselRequirementId: effectiveLink,
        },
      };
    }
    // Retain a historical exception reason after later regularisation.
    input.dieselExceptionReason = existing?.dieselExceptionReason ?? null;
    return null;
  }

  const handleDieselReceiptRemainingError = (err: unknown, res: any): boolean => {
    if (!(err instanceof DieselReceiptExceedsRemainingError)) return false;
    const p = err.payload;
    res.status(409).json({
      code: err.code,
      message: `Diesel receipt quantity ${p.requestedQty} L exceeds the remaining purchased quantity ${p.remainingQty} L by ${p.excessQty} L`,
      ...p,
    });
    return true;
  };

  const handleInvalidLinkedDieselRequirementError = (err: unknown, res: any): boolean => {
    if (!(err instanceof InvalidLinkedDieselRequirementError)) return false;
    res.status(400).json({
      code: err.code,
      message: err.message,
      linkedDieselRequirementId: err.requirementId,
    });
    return true;
  };

  app.get("/api/plant-module/material-receipts", async (req, res) => {
    try {
      const filters = {
        partyId: req.query.partyId ? Number(req.query.partyId) : undefined,
        dateFrom: req.query.dateFrom as string | undefined,
        dateTo: req.query.dateTo as string | undefined,
      };
      const receipts = await storage.getMaterialReceipts(filters);
      res.json(receipts);
    } catch (err) {
      res.status(500).json({ message: "Failed to fetch material receipts" });
    }
  });

  app.post("/api/plant-module/material-receipts", async (req, res) => {
    try {
      if (!assertCreate(req, res, "plant_materials")) return;
      const body = { ...req.body };
      if (typeof body.isPlantCommon === 'boolean') {
        body.isPlantCommon = body.isPlantCommon ? 1 : 0;
      }
      const input = insertMaterialReceiptSchema.parse(body);
      const dieselControlError = await validateDieselReceiptControl(req, input);
      if (dieselControlError) return res.status(dieselControlError.status).json(dieselControlError.body);
      // 06M-C: a purchase↔receipt link must point at a real PURCHASED Daily
      // Diesel Requirement and the receipt must be for the canonical Diesel
      // material — otherwise arbitrary receipts could inflate a purchase's
      // Received total and corrupt the audit chain.
      if (input.linkedDieselRequirementId != null) {
        const linkedReq = await storage.getDieselRequirement(input.linkedDieselRequirementId);
        if (!linkedReq || linkedReq.status !== "purchased" || !(linkedReq as any).qtyPurchased) {
          return res.status(400).json({ message: "Linked diesel requirement not found or not a completed purchase" });
        }
        // The link has one canonical stock material, rather than accepting any
        // material whose name happens to look like diesel. Prefer DIESEL over
        // HSD where both masters are active.
        const canonicalDiesel = await getCanonicalDieselMaterial();
        if (!canonicalDiesel) {
          return res.status(400).json({
            code: "CANONICAL_DIESEL_MATERIAL_NOT_CONFIGURED",
            message: "Linked diesel receipts require an active canonical DIESEL or HSD plant material",
          });
        }
        if (input.materialId !== canonicalDiesel.id) {
          return res.status(400).json({
            code: "LINKED_DIESEL_MATERIAL_MISMATCH",
            message: "Only Diesel receipts using the canonical diesel material can be linked to a diesel purchase",
          });
        }
        if (input.uom.trim().toLowerCase() !== "liters") {
          return res.status(400).json({
            code: "LINKED_DIESEL_UOM_INVALID",
            message: "Linked diesel receipts must use UOM Liters",
          });
        }
        // Persist one spelling so the stock ledger cannot split diesel balances
        // by user-entered casing.
        input.uom = "Liters";
      }
      const receipt = await storage.createMaterialReceipt(input);
      // A linked diesel receipt reuses qualifying purchase evidence rather than
      // duplicating files.  This is deliberately after successful receipt/stock
      // creation; a failed receipt can never acquire links.
      if ((receipt as any).linkedDieselRequirementId) {
        try {
          await storage.linkDieselPurchaseEvidenceToMaterialReceipt(
            (receipt as any).linkedDieselRequirementId,
            receipt.id,
            req.authUser!.id,
          );
        } catch (err) {
          // Receipt and stock creation have already committed. Do not report a
          // failed optional link as a failed receipt (and invite retry/duplicate
          // stock); historical read fallback still exposes the evidence.
          console.error("Failed to link diesel purchase evidence to receipt:", err);
        }
      }

      await storage.createNotification({
        type: "info",
        title: "Material Receipt Added",
        message: `New material receipt: ${receipt.quantity} ${receipt.uom} received on ${receipt.date}`,
        isRead: 0,
      });
      sendPushToSection("plant_materials", "Material Receipt", `${receipt.quantity} ${receipt.uom} received on ${receipt.date}`, "/plant").catch(() => {});

      // 06M-C: receipt linked to a Daily Diesel Purchase — recompute derived
      // Received/Pending and notify PM/site diesel visibility holders.
      if ((receipt as any).linkedDieselRequirementId) {
        try {
          const reqId = (receipt as any).linkedDieselRequirementId as number;
          const dieselReq = await storage.getDieselRequirement(reqId);
          if (dieselReq) {
            const linked = await storage.getDieselRequirementReceipts([reqId]);
            const state = computeDieselReceiptState((dieselReq as any).qtyPurchased, linked);
            const title = state.status === "fully_received" ? "DIESEL FULLY RECEIVED" : "DIESEL PARTLY RECEIVED";
            const body = `Purchased: ${state.purchasedQty} L · Received: ${state.receivedQty} L · Pending: ${state.pendingQty} L`;
            sendPushToSection("site_diesel", title, body, "/plant/diesel-requirements").catch(() => {});
          }
        } catch (e) {
          console.error("06M-C: failed to notify diesel receipt progress:", e);
        }
      }

      res.status(201).json(receipt);
    } catch (err: any) {
      if (err instanceof z.ZodError) return res.status(400).json({ message: "Invalid receipt data", errors: err.errors });
      if (handleDieselReceiptRemainingError(err, res)) return;
      if (handleInvalidLinkedDieselRequirementError(err, res)) return;
      if (handleInsufficientPlantStock(err, res)) return;
      console.error("Error creating material receipt:", err);
      res.status(500).json({ message: "Failed to create material receipt" });
    }
  });

  app.put("/api/plant-module/material-receipts/:id", async (req, res) => {
    try {
      if (!req.authUser) return res.status(401).json({ message: "not_authenticated" });
      const id = Number(req.params.id);
      const existing = await storage.getMaterialReceipt(id);
      if (!existing) return res.status(404).json({ message: "Receipt not found" });
      const { editPermissionRequestId, ...body } = req.body ?? {};
      const directEditor = !!(
        req.authUser!.isOwner ||
        req.authUser!.isAdmin ||
        req.authPermissions?.plant_materials?.edit
      );
      let approvedRequestId: number | null = null;
      if (existing.documentStatus === "submitted") {
        if (directEditor) {
          // A zero is intentional: it makes the direct-edit path explicit and
          // prevents a stale approved request from being silently ignored.
          if (editPermissionRequestId !== 0) {
            return res.status(400).json({
              code: "EDIT_PERMISSION_REQUEST_ID_REQUIRED",
              message: "Direct editors must send editPermissionRequestId=0 when correcting a submitted receipt",
            });
          }
        } else {
          if (!Number.isInteger(editPermissionRequestId) || editPermissionRequestId <= 0) {
            return res.status(403).json({
              code: "APPROVED_EDIT_PERMISSION_REQUIRED",
              message: "An active approved edit permission is required to correct this submitted receipt",
            });
          }
          const activePermission = await storage.checkActiveEditPermission(req.authUser!.id, "material_receipt", id);
          if (!activePermission || activePermission.id !== editPermissionRequestId) {
            return res.status(403).json({
              code: "APPROVED_EDIT_PERMISSION_REQUIRED",
              message: "The supplied edit permission is not active for this material receipt",
            });
          }
          approvedRequestId = activePermission.id;
        }
      } else if (!assertEdit(req, res, "plant_materials")) {
        return;
      }
      // 06M-D: a cancelled receipt is terminal — its stock was already reversed.
      // Editing it would re-apply stock on a record whose net effect must stay zero.
      if (existing.isCancelled) {
        return res.status(409).json({ code: "RECEIPT_ALREADY_CANCELLED", message: "This receipt is cancelled and cannot be edited. Its stock effect was already reversed. Create a new receipt instead." });
      }
      if (typeof body.isPlantCommon === 'boolean') {
        body.isPlantCommon = body.isPlantCommon ? 1 : 0;
      }
      const input = insertMaterialReceiptSchema.partial().parse(body);
      const dieselControlError = await validateDieselReceiptControl(req, input, existing);
      if (dieselControlError) return res.status(dieselControlError.status).json(dieselControlError.body);
      // A receipt already linked to a diesel purchase remains constrained during
      // correction. Validate effective values so a partial update cannot leave
      // an invalid historical material/UOM in place; supplying both canonical
      // values is the supported way to repair such a historical row.
      if (existing.linkedDieselRequirementId != null) {
        const canonicalDiesel = await getCanonicalDieselMaterial();
        if (!canonicalDiesel) {
          return res.status(400).json({
            code: "CANONICAL_DIESEL_MATERIAL_NOT_CONFIGURED",
            message: "Linked diesel receipts require an active canonical DIESEL or HSD plant material",
          });
        }
        const effectiveMaterialId = input.materialId ?? existing.materialId;
        const effectiveUom = input.uom ?? existing.uom;
        if (effectiveMaterialId !== canonicalDiesel.id) {
          return res.status(400).json({
            code: "LINKED_DIESEL_MATERIAL_MISMATCH",
            message: "Only Diesel receipts using the canonical diesel material can be linked to a diesel purchase",
          });
        }
        if (effectiveUom.trim().toLowerCase() !== "liters") {
          return res.status(400).json({
            code: "LINKED_DIESEL_UOM_INVALID",
            message: "Linked diesel receipts must use UOM Liters",
          });
        }
        if (input.uom !== undefined) input.uom = "Liters";
      }
      const updated = await storage.updateMaterialReceipt(id, input);
      if (!updated) return res.status(404).json({ message: "Receipt not found" });
      // Consumption is deliberately after the receipt update succeeds. A failed
      // validation/storage update must leave the approved correction available.
      if (approvedRequestId !== null) {
        await storage.consumeEditPermission(approvedRequestId);
      }
      await storage.logAudit({
        module: "material_receipts",
        transactionId: id,
        action: "edit",
        userId: req.authUser!.id,
        userName: currentUserName(req),
        userRole: req.authUser!.isOwner ? "owner" : req.authUser!.isAdmin ? "admin" : "manager",
        oldValues: existing,
        newValues: updated,
      });
      sendPushToSection("plant_materials", "Material Receipt Updated", `Receipt #${req.params.id} updated`, "/plant").catch(() => {});
      res.json(updated);
    } catch (err: any) {
      if (err instanceof z.ZodError) return res.status(400).json({ message: "Invalid receipt data", errors: err.errors });
      if (handleDieselReceiptRemainingError(err, res)) return;
      if (handleInvalidLinkedDieselRequirementError(err, res)) return;
      if (handleInsufficientPlantStock(err, res)) return;
      console.error("Error updating material receipt:", err);
      res.status(500).json({ message: "Failed to update material receipt" });
    }
  });

  // Final Submit: locks the receipt for normal-user edits once required
  // documents (challan/DC/invoice/receipt) are attached. Owner/Admin can
  // force-submit without a document for testing/edge cases (spec §H, §F).
  app.post("/api/plant-module/material-receipts/:id/final-submit", async (req, res) => {
    try {
      if (!assertEdit(req, res, "plant_materials")) return;
      const id = Number(req.params.id);
      const before = await storage.getMaterialReceipt(id);
      if (!before) return res.status(404).json({ message: "Receipt not found" });
      if (before.documentStatus === "submitted") return res.status(400).json({ message: "This receipt is already Final Submitted" });
      const isOwnerOrAdmin = !!(req.authUser!.isOwner || req.authUser!.isAdmin);
      if (!isOwnerOrAdmin) {
        const docs = await storage.getAttachments("material_receipt", id);
        const requiredTypes = ["bill", "challan", "dc", "invoice", "receipt"];
        const hasRequiredDoc = docs.some(d => requiredTypes.includes((d as any).docType));
        if (!hasRequiredDoc) {
          return res.status(400).json({ message: "Please upload the bill, challan, DC, invoice or receipt photo before Final Submit." });
        }
      }
      const updated = await storage.finalSubmitMaterialReceipt(id, req.authUser!.id);
      await storage.logAudit({
        module: "material_receipts",
        transactionId: id,
        action: "final_submit",
        userId: req.authUser!.id,
        userName: currentUserName(req),
        userRole: req.authUser!.isOwner ? "owner" : req.authUser!.isAdmin ? "admin" : "manager",
        oldValues: before,
        newValues: updated ?? null,
      });
      res.json(updated);
    } catch (err) {
      console.error("POST /api/plant-module/material-receipts/:id/final-submit:", err);
      res.status(500).json({ message: "Failed to final-submit receipt" });
    }
  });

  app.delete("/api/plant-module/material-receipts/:id", async (req, res) => {
    try {
      if (!assertAdmin(req, res)) return;
      const id = Number(req.params.id);
      const before = await storage.getMaterialReceipt(id);
      const deleted = await storage.deleteMaterialReceipt(id);
      if (!deleted) return res.status(404).json({ message: "Receipt not found" });
      await storage.logAudit({
        module: "material_receipts",
        transactionId: id,
        action: "delete",
        userId: req.authUser!.id,
        userName: currentUserName(req),
        userRole: req.authUser!.isOwner ? "owner" : req.authUser!.isAdmin ? "admin" : "manager",
        oldValues: before ?? null,
        // 06M-D: stock reversal happens inside the delete transaction (skipped
        // when the receipt was already cancelled — that reversal already ran).
        stockImpact: "Receipt deleted; stock effect reversed within the delete transaction (or previously at cancellation)",
      });
      sendPushToSection("plant_materials", "Material Receipt Deleted", `Receipt #${req.params.id} deleted`, "/plant").catch(() => {});
      res.status(204).send();
    } catch (err: any) {
      if (err?.code === "INSUFFICIENT_PLANT_STOCK") {
        const p = err.payload;
        return res.status(409).json({
          code: "RECEIPT_REVERSAL_STOCK_UNAVAILABLE",
          message: `CANNOT DELETE MATERIAL RECEIPT. Receipt Qty: ${p.requestedQty} — Current Available Stock: ${p.availableQty}. This receipt cannot be deleted because the stock required for reversal is no longer fully available. Please contact PM/Admin for reconciliation.`,
          ...p,
        });
      }
      res.status(500).json({ message: "Failed to delete material receipt" });
    }
  });

  // Cancel a material receipt (stock-affecting: flagged for reversal, not hard-deleted)
  app.post("/api/plant-module/material-receipts/:id/cancel", async (req, res) => {
    try {
      if (!assertDeleteOrCancel(req, res, "plant_materials")) return;
      const id = Number(req.params.id);
      const reason = String(req.body?.reason || "").trim();
      if (!reason) return res.status(400).json({ message: "Cancellation reason is required" });
      const before = await storage.getMaterialReceipt(id);
      if (!before) return res.status(404).json({ message: "Receipt not found" });
      const updated = await storage.cancelMaterialReceipt(id, req.authUser!.id, reason);
      await storage.logAudit({
        module: "material_receipts",
        transactionId: id,
        action: "cancel",
        userId: req.authUser!.id,
        userName: currentUserName(req),
        userRole: req.authUser!.isOwner ? "owner" : req.authUser!.isAdmin ? "admin" : "manager",
        oldValues: before,
        newValues: updated ?? null,
        reason,
        // 06M-D: reversal now happens automatically inside the cancellation transaction.
        stockImpact: "Receipt cancelled; stock reversed automatically via material_receipt_cancel_reversal ledger entry",
      });
      sendPushToSection("plant_materials", "Material Receipt Cancelled", `Receipt #${id} cancelled`, "/plant").catch(() => {});
      res.json(updated);
    } catch (err: any) {
      if (err?.code === "RECEIPT_ALREADY_CANCELLED") {
        return res.status(409).json({ code: err.code, message: "This receipt is already cancelled — its stock was already reversed." });
      }
      if (err?.code === "INSUFFICIENT_PLANT_STOCK") {
        const p = err.payload;
