      const id = Number(req.params.id);
      const equipmentId = Number(req.body?.equipmentId);
      if (!Number.isInteger(id) || id <= 0 || !Number.isInteger(equipmentId) || equipmentId <= 0) {
        return res.status(400).json({ message: "Valid log id and equipmentId are required" });
      }
      const context = await storage.getEquipmentPerformanceLogContext(id);
      if (!context) return res.status(404).json({ message: "Equipment log not found in an active project" });
      if (context.plantUsageId != null) {
        return res.status(409).json({ message: "Canonical-linked equipment logs cannot be reclassified" });
      }
      if (!await assertTripSiteAccess(req, res, context.site)) return;
      const updated = await storage.confirmEquipmentPerformanceLog(id, equipmentId, {
        userId: req.authUser?.id ?? null,
        userName: currentUserName(req),
        userRole: (req.authUser as any)?.role ?? null,
      });
      res.json(updated);
    } catch (err: any) {
      const message = err?.message ?? "Failed to confirm equipment identity";
      const status = /canonical-linked/i.test(message) ? 409 : /not found/i.test(message) ? 404 : 500;
      res.status(status).json({ message });
    }
  });

  // Equipment Usage
  app.get("/api/plant-module/equipment-usage", async (req, res) => {
    try {
      const filters = {
        equipmentId: req.query.equipmentId ? Number(req.query.equipmentId) : undefined,
        dateFrom: req.query.dateFrom as string | undefined,
        dateTo: req.query.dateTo as string | undefined,
      };
      const usage = await storage.getEquipmentUsage(filters);
      res.json(usage);
    } catch (err) {
      res.status(500).json({ message: "Failed to fetch equipment usage" });
    }
  });

  // Batch 6: open plant records for a given date + equipmentIds — used by SiteEntry to detect P&M-dispatched equipment
  // 06X: site param is required in both branches (no cross-site disclosure);
  //      permission guard runs in both branches; results filtered by
  //      destinationSite (normalised) so only records dispatched to the
  //      requesting site are returned.
  app.get("/api/plant-module/equipment-usage/open-today", requireAuth, async (req, res) => {
    try {
      const date = req.query.date as string;
      if (!date) return res.status(400).json({ message: "date is required" });
      const site = req.query.site as string | undefined;
      if (!site || !normaliseSiteLabel(site)) {
        return res.status(400).json({ message: "site is required" });
      }
      // Site-access authorization in both branches: a user may only discover
      // open usage for a site they are permitted to see.
      const permittedSiteNames = await getPermittedSiteNames(req);
      if (permittedSiteNames !== null && !siteMatchesPermitted(site, permittedSiteNames)) {
        return res.status(403).json({ message: "You do not have access to this site" });
      }
      const wanted = normaliseSiteLabel(site);
      const ids = req.query.equipmentIds;
      if (ids === undefined) {
        // Batch 05: omitted equipmentIds = open usage discovery for Guided DPR.
        // Discovery is SITE-SCOPED: filter strictly on destinationSite
        // (the authoritative dispatch-target field). Records without a
        // destinationSite were opened for plant-internal use and are not
        // surfaced here — the site field that counts is where the equipment
        // was sent, not where it lives.
        const all = await storage.getOpenEquipmentUsageForDate(date);
        return res.json(
          all.filter((u) =>
            ((u as any).destinationType == null || (u as any).destinationType === "site") &&
            normaliseSiteLabel((u as any).destinationSite) === wanted,
          ),
        );
      }
      const equipmentIds: number[] = Array.isArray(ids)
        ? (ids as string[]).map(Number).filter(Boolean)
        : [Number(ids)].filter(Boolean);
      const records = await storage.getOpenEquipmentUsageForDate(date, equipmentIds);
      // Filter strictly on destinationSite — this is the ownership field
      // for dispatched equipment. Records with no destinationSite (plant-
      // internal entries) are not returned to a DPR site context.
      res.json(
        records.filter((u) =>
          ((u as any).destinationType == null || (u as any).destinationType === "site") &&
          normaliseSiteLabel((u as any).destinationSite) === wanted,
        ),
      );
    } catch (err) {
      res.status(500).json({ message: "Failed to fetch open equipment records" });
    }
  });

  // Get previous diesel balance and closing reading for equipment (for new entry creation)
  app.get("/api/plant-module/equipment-usage/previous-balance/:equipmentId", async (req, res) => {
    try {
      const equipmentId = parseInt(req.params.equipmentId);
      const excludeId = req.query.excludeId ? parseInt(req.query.excludeId as string) : undefined;

      const usage = await storage.getEquipmentUsage({ equipmentId });
      // Usage is already sorted by date DESC, id DESC - so the first entry is the most recent

      // Filter out only the excluded entry (when editing)
      const filteredUsage = excludeId ? usage.filter(u => u.id !== excludeId) : usage;

      // Get the most recent entry for this equipment (includes same-day entries).
      // Prefer the operator's actual Diesel Balance in Tank dip; fall back to
      // closingDiesel when no dip was recorded.
      const last = filteredUsage.length > 0 ? filteredUsage[0] : null;
      const previousBalance = last
        ? (last.dieselBalanceInTank ?? last.closingDiesel ?? 0)
        : 0;
      const previousClosingReading = last ? last.closingReading || 0 : 0;
      res.json({ previousBalance, previousClosingReading });
    } catch (err) {
      res.status(500).json({ message: "Failed to fetch previous balance", previousBalance: 0, previousClosingReading: 0 });
    }
  });

  // INSTRUCTION 06Q — canonical latest-prior-closing endpoint (opening-reading
  // continuity). Strictly before `beforeDate` by default; `inclusive=1` means
  // on-or-before (used by the Plant module so a second same-day entry
  // continues from the day's earlier closing). Read-only; never creates or
  // duplicates Equipment Usage records; diesel previous-balance is untouched.
  app.get("/api/equipment/:equipmentId/latest-closing", requireAuth, async (req, res) => {
    try {
      const equipmentId = parseInt(req.params.equipmentId);
      const beforeDate = req.query.beforeDate as string | undefined;
      if (!equipmentId || !beforeDate || !/^\d{4}-\d{2}-\d{2}$/.test(beforeDate)) {
        return res.status(400).json({ message: "equipmentId and beforeDate (YYYY-MM-DD) are required" });
      }
      const inclusive = req.query.inclusive === "1" || req.query.inclusive === "true";
      const siteName = typeof req.query.site === "string" ? req.query.site.trim() : "";
      const unrestricted = !!(req.authUser?.isAdmin || req.authUser?.isOwner);
      if (siteName) {
        if (!assertView(req, res, "site_dprs")) return;
        if (!await assertTripSiteAccess(req, res, siteName)) return;
      } else if (!unrestricted && !req.authPermissions?.plant_equipment?.view) {
        return res.status(400).json({ message: "site is required for site equipment continuity" });
      }
      const excludeSource = req.query.excludeSource === "plant_usage" || req.query.excludeSource === "dpr_log"
        ? req.query.excludeSource : undefined;
      const excludeRecordId = req.query.excludeRecordId == null
        ? undefined : Number(req.query.excludeRecordId);
      if (
        (excludeSource && (!Number.isInteger(excludeRecordId) || Number(excludeRecordId) <= 0))
        || (!excludeSource && excludeRecordId !== undefined)
      ) {
        return res.status(400).json({ message: "excludeSource and a positive excludeRecordId must be supplied together" });
      }
      const permittedSiteNames = await getPermittedSiteNames(req);
      const resolved = await storage.resolveLatestPriorClosing(equipmentId, beforeDate, {
        inclusive,
        ...(siteName ? { siteName, permittedSiteNames } : {}),
        ...(excludeSource ? { excludeSource, excludeRecordId } : {}),
      });
      res.json(resolved ?? { closingReading: null, sourceDate: null, source: null });
    } catch (err) {
      res.status(500).json({ message: "Failed to resolve latest closing reading" });
    }
  });

  // Physical fuel-tank continuity is intentionally separate from calculated
  // diesel closings: only a submitted, live DPR's confirmed dip is eligible.
  app.get("/api/equipment/:equipmentId/latest-confirmed-diesel-tank", requireAuth, async (req, res) => {
    try {
      if (!assertView(req, res, "site_dprs")) return;
      const equipmentId = parseInt(req.params.equipmentId);
      const beforeDate = req.query.beforeDate as string | undefined;
      const siteName = typeof req.query.site === "string" ? req.query.site.trim() : "";
      if (!equipmentId || !beforeDate || !/^\d{4}-\d{2}-\d{2}$/.test(beforeDate) || !siteName) {
        return res.status(400).json({ message: "equipmentId, site, and beforeDate (YYYY-MM-DD) are required" });
      }
      if (!await assertTripSiteAccess(req, res, siteName)) return;
      const inclusive = req.query.inclusive === "1" || req.query.inclusive === "true";
      const permittedSiteNames = await getPermittedSiteNames(req);
      const resolved = await storage.resolveLatestConfirmedDieselTank(
        equipmentId, beforeDate, { siteName, permittedSiteNames }, { inclusive },
      );
      res.json(resolved ?? { dieselBalanceInTank: null, sourceDate: null, recordId: null });
    } catch (_) {
      res.status(500).json({ message: "Failed to resolve latest confirmed diesel tank" });
    }
  });

  // 06X: destinationSite is a Site-master identity, not arbitrary text.
  // Canonicalise casing on both create and update and enforce the same
  // destination-site access boundary used by DPR equipment discovery.
  async function canonicaliseEquipmentDestinationSite(
    req: any,
    res: any,
    rawBody: any,
    existingUsage?: { destinationSite?: string | null },
  ): Promise<Record<string, any> | undefined> {
    const body = { ...(rawBody ?? {}) };
    const hasIncomingDestination = Object.prototype.hasOwnProperty.call(body, "destinationSite");
    const existingDestination = normaliseSiteLabel(existingUsage?.destinationSite);
    const incomingDestinationIsBlank =
      hasIncomingDestination &&
      (body.destinationSite == null || String(body.destinationSite).trim() === "");

    // A dispatched record remains owned by its destination site throughout
    // its lifecycle. Omitting destinationSite on PUT therefore authorizes and
    // canonicalizes the persisted value; explicitly clearing it is rejected.
    if (existingDestination && incomingDestinationIsBlank) {
      res.status(400).json({
        message: "Destination site cannot be cleared from a dispatched equipment record",
      });
      return undefined;
    }

    const effectiveDestination = hasIncomingDestination
      ? body.destinationSite
      : existingUsage?.destinationSite;
    if (effectiveDestination == null || String(effectiveDestination).trim() === "") {
      // Explicit plant-internal path: records that never had a destination
      // remain plant-owned and are intentionally undiscoverable from DPRs.
      if (hasIncomingDestination) body.destinationSite = null;
      return body;
    }

    const siteRows = await storage.getSites();
    const permittedSiteNames = await getPermittedSiteNames(req);

    // Reassignment must not let a user "take" a dispatch from a site they
    // cannot access by supplying a new permitted destination. Authorize the
    // persisted owner first, then the effective destination.
    //
    // Legacy exception: records created before the registered-site dropdown
    // stored destinationSite as free text (e.g. "THAKKADPALLY"). Such values
    // cannot resolve to a Site Master row, which used to block ALL edits.
    // When the request explicitly supplies a NEW destination, the correction
    // is allowed — the new value is still validated against active Site
    // Master and permission-checked below. We never fuzzy-match or auto-fix
    // the legacy value; without an explicit replacement it stays an error.
    if (existingDestination) {
      const existingMatches = siteRows.filter(
        (site) => site.isActive === 1 && normaliseSiteLabel(site.name) === existingDestination,
      );
      const hasExplicitReplacement = hasIncomingDestination && !incomingDestinationIsBlank;
      if (existingMatches.length === 1) {
        if (
          permittedSiteNames !== null &&
          !siteMatchesPermitted(existingMatches[0].name, permittedSiteNames)
        ) {
          res.status(403).json({ message: "You do not have access to update this dispatched equipment record" });
          return undefined;
        }
      } else if (!hasExplicitReplacement) {
        res.status(400).json({
          message:
            "The saved destination site is not a registered Site. " +
            "Select a registered Destination Site from the list and save again.",
        });
        return undefined;
      }
      // else: unresolvable legacy destination + explicit new selection —
      // proceed; the requested destination is validated and authorized below.
    }

    const requested = normaliseSiteLabel(effectiveDestination);
    const activeMatches = siteRows.filter(
      (site) => site.isActive === 1 && normaliseSiteLabel(site.name) === requested,
    );
    if (activeMatches.length !== 1) {
      res.status(400).json({
        message: "Destination site must be one active registered Site — refresh the site list and select it again",
      });
      return undefined;
    }

    const canonicalSite = activeMatches[0].name;
    if (
      permittedSiteNames !== null &&
      !siteMatchesPermitted(canonicalSite, permittedSiteNames)
    ) {
      res.status(403).json({ message: "You do not have access to dispatch equipment to this site" });
      return undefined;
    }

    body.destinationSite = canonicalSite;
    return body;
  }

  /** 06Y movement destinations are identities, never user-entered locations. */
  async function canonicaliseMovementDestination(
    req: any, res: any, body: any,
  ): Promise<{ destinationType: "site" | "hmp" | "rmc"; destinationLabel: string } | undefined> {
    const destinationType = String(body?.destinationType ?? "").trim().toLowerCase();
    if (destinationType === "hmp" || destinationType === "rmc") {
      // Closed vocabulary: labels are intentionally not free text.
      return {
        destinationType,
        destinationLabel: destinationType === "hmp" ? "HMP PLANT" : "RMC PLANT",
      };
    }
    if (destinationType !== "site") {
      res.status(400).json({ message: "destinationType must be site, hmp, or rmc" });
      return undefined;
    }
    const wanted = normaliseSiteLabel(body?.destinationSite);
    const matches = (await storage.getSites()).filter(
      (site: any) => site.isActive === 1 && normaliseSiteLabel(site.name) === wanted,
    );
    if (matches.length !== 1) {
      res.status(400).json({ message: "Destination site must be one active registered Site" });
      return undefined;
    }
    const permitted = await getPermittedSiteNames(req);
    if (permitted !== null && !siteMatchesPermitted(matches[0].name, permitted)) {
      res.status(403).json({ message: "You do not have access to this destination site" });
      return undefined;
    }
    return { destinationType: "site", destinationLabel: matches[0].name };
  }

  // 06Y: close-and-create transfer. The closed source is never repurposed.
  app.post("/api/equipment-usage/:id/move", async (req, res) => {
    try {
      if (!assertEdit(req, res, "site_dprs")) return;
      const sourceId = Number(req.params.id);
      if (!Number.isInteger(sourceId) || sourceId <= 0) return res.status(400).json({ message: "Valid source usage id is required" });
      const source = await storage.getEquipmentUsageById(sourceId);
      if (!source) return res.status(404).json({ message: "Source equipment usage not found" });
      if ((source as any).destinationType !== "site") {
        return res.status(409).json({ message: "Only a completed Site equipment segment can be sent onward here" });
      }
      // A site-originated source is protected by its persisted site owner.
      const sourceSite = (source as any).destinationType === "site" || (source as any).destinationType == null
        ? ((source as any).destinationSite ?? (source as any).siteName) : null;
      const permitted = await getPermittedSiteNames(req);
      if (sourceSite && permitted !== null && !siteMatchesPermitted(sourceSite, permitted)) {
        return res.status(403).json({ message: "You do not have access to move equipment from this source site" });
      }
      const destination = await canonicaliseMovementDestination(req, res, req.body);
      if (!destination) return;
      const date = String(req.body?.successorDate ?? req.body?.date ?? "");
      if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) return res.status(400).json({ message: "Movement date (YYYY-MM-DD) is required" });
      const successor = await storage.createEquipmentUsageSuccessor(sourceId, {
        date,
        ...destination,
        shiftFrom: req.body?.shiftFrom ?? sourceSite ?? null,
        shiftTo: req.body?.shiftTo ?? destination.destinationLabel,
        openedByUserId: req.authUser?.id ?? null,
        openedByUserName: req.authUser ? currentUserName(req) : null,
        openedAt: new Date(),
      });
      res.status(201).json(successor);
    } catch (err: any) {
      const message = err?.message ?? "Failed to move equipment";
      const status = /closed|closing|date|successor|immutable/i.test(message) ? 409 : 500;
      res.status(status).json({ message });
    }
  });

  app.get("/api/equipment-usage/lifecycle", requireAuth, async (req, res) => {
    try {
      if (!assertView(req, res, "site_dprs")) return;
      const ids = String(req.query.ids ?? "")
        .split(",")
        .map(Number)
        .filter((id) => Number.isInteger(id) && id > 0)
        .slice(0, 100);
      if (ids.length === 0) return res.json([]);
      const sourceRows = await Promise.all(ids.map((id) => storage.getEquipmentUsageById(id)));
      if (sourceRows.some((row) => !row)) {
        return res.status(404).json({ message: "Equipment usage not found" });
      }
      const permitted = await getPermittedSiteNames(req);
      if (
        permitted !== null &&
        sourceRows.some((row: any) => {
          const sourceSite = row?.destinationType === "site"
            ? (row.destinationSite ?? row.siteName)
            : null;
          return sourceSite && !siteMatchesPermitted(sourceSite, permitted);
        })
      ) {
        return res.status(403).json({ message: "You do not have access to this equipment lifecycle" });
      }
      res.json(await storage.getEquipmentUsageLifecycle(ids));
    } catch (_) {
      res.status(500).json({ message: "Failed to fetch equipment lifecycle" });
    }
  });

  app.get("/api/plant-module/equipment-usage/incoming", async (req, res) => {
    try {
      if (!assertView(req, res, "plant_equipment")) return;
      const destinationType = String(req.query.destinationType ?? "").toLowerCase();
      if (destinationType !== "hmp" && destinationType !== "rmc") {
        return res.status(400).json({ message: "destinationType must be hmp or rmc" });
      }
      res.json(await storage.getOpenIncomingEquipmentUsage(destinationType));
    } catch (_) {
      res.status(500).json({ message: "Failed to fetch incoming equipment" });
    }
  });

  // Completes the same incoming row; it intentionally delegates diesel and
  // meter accounting to the existing update transaction.
  app.post("/api/plant-module/equipment-usage/:id/complete-incoming", async (req, res) => {
    try {
      if (!assertEdit(req, res, "plant_equipment")) return;
      const id = Number(req.params.id);
      const completion = req.body ?? {};
      const updated = await storage.completeIncomingEquipmentUsage(id, {
        entryType: completion.entryType ?? "time_meter",
        closingReading: completion.closingReading,
        startTime: completion.startTime,
        endTime: completion.endTime,
        openingDiesel: completion.openingDiesel,
        dieselIssued: completion.dieselIssued,
        dieselIncluded: completion.dieselIncluded,
        dieselSource: completion.dieselSource,
        fuelStation: completion.fuelStation,
        billNumber: completion.billNumber,
        amountPaid: completion.amountPaid,
        dieselBalanceInTank: completion.dieselBalanceInTank,
        dieselBalanceConfirmed: completion.dieselBalanceConfirmed,
        operator: completion.operator,
        task: completion.task,
        remarks: completion.remarks,
        closedByUserId: req.authUser?.id ?? null,
        closedByUserName: req.authUser ? currentUserName(req) : null,
        closedAt: new Date(),
      } as any);
      res.json(updated);
    } catch (err: any) {
      if (err instanceof EquipmentIncomingConflictError) {
        return res.status(409).json({ code: err.code, message: err.message });
      }
      if (err instanceof InvalidDieselSourceError) {
        return res.status(400).json({ code: err.code, field: err.field, message: err.message });
      }
      res.status(400).json({ message: err?.message ?? "Failed to complete incoming equipment" });
    }
  });

  app.post("/api/plant-module/equipment-usage", async (req, res) => {
    try {
      if (!assertCreate(req, res, "plant_equipment")) return;
      const input = await canonicaliseEquipmentDestinationSite(req, res, req.body);
      if (!input) return;
      const usage = await storage.createEquipmentUsage(input as any);
      const eqName = input.equipmentName || `Equipment #${input.equipmentId}`;
      sendPushToSection("plant_equipment", "Equipment Entry", `${eqName} - Opening: ${input.openingReading ?? 'N/A'}`, "/plant/equipment-usage").catch(() => {});
      res.status(201).json(usage);
    } catch (err) {
      console.error("POST /api/plant-module/equipment-usage:", err);
      if (handleInsufficientPlantStock(err, res)) return;
      if (err instanceof InvalidDieselSourceError) return res.status(400).json({ code: err.code, field: err.field, message: err.message });
      if (err instanceof z.ZodError) {
        return res.status(400).json({ message: err.errors[0]?.message ?? "Validation failed", field: err.errors[0]?.path?.join(".") });
      }
      const msg = (err as any)?.message ?? "";
      if (msg.includes("equipment") && msg.toLowerCase().includes("not found")) {
        return res.status(400).json({ message: "Equipment not found — verify the equipment selection and try again" });
      }
      res.status(500).json({ message: "Failed to create equipment usage — check opening reading and date, then retry" });
    }
  });

  app.put("/api/plant-module/equipment-usage/:id", async (req, res) => {
    try {
      const id = parseInt(req.params.id);
      if (!assertEdit(req, res, "plant_equipment")) return;
      const existing = await storage.getEquipmentUsageById(id);
      if (!existing) {
        return res.status(404).json({ message: "Equipment usage not found" });
      }
      const input = await canonicaliseEquipmentDestinationSite(req, res, req.body, existing);
      if (!input) return;
      const updated = await storage.updateEquipmentUsage(id, input);
      if (!updated) return res.status(404).json({ message: "Equipment usage not found" });
      const eqName = input.equipmentName || `Equipment #${input.equipmentId || id}`;
      sendPushToSection("plant_equipment", "Equipment Updated", `${eqName} - Closing: ${input.closingReading ?? 'N/A'}`, "/plant/equipment-usage").catch(() => {});
      res.json(updated);
    } catch (err) {
      console.error("PUT /api/plant-module/equipment-usage/:id:", err);
      console.error("[equipment-usage-update-diagnostic]", {
        message: err instanceof Error ? err.message : String(err),
        stack: err instanceof Error ? err.stack : undefined,
      });
      if (handleInsufficientPlantStock(err, res)) return;
      if (err instanceof InvalidDieselSourceError) return res.status(400).json({ code: err.code, field: err.field, message: err.message });
      if (err instanceof z.ZodError) {
        return res.status(400).json({ message: err.errors[0]?.message ?? "Validation failed", field: err.errors[0]?.path?.join(".") });
      }
      const msg = (err as any)?.message ?? "";
      if (msg.includes("closing") || msg.includes("reading")) {
        return res.status(400).json({ message: "Invalid closing reading — ensure it is greater than the opening reading and retry" });
      }
      res.status(500).json({ message: "Failed to update equipment usage — check the entry values and retry" });
    }
  });

  app.delete("/api/plant-module/equipment-usage/:id", async (req, res) => {
    try {
      if (!assertAdmin(req, res)) return;
      const id = parseInt(req.params.id);
      const deleted = await storage.deleteEquipmentUsage(id);
      if (!deleted) {
        return res.status(404).json({ message: "Equipment usage not found" });
      }
      sendPushToSection("plant_equipment", "Equipment Entry Deleted", `Equipment usage #${id} deleted`, "/plant/equipment-usage").catch(() => {});
      res.status(204).send();
    } catch (err) {
      if (err instanceof InvalidDieselSourceError) return res.status(400).json({ code: err.code, field: err.field, message: err.message });
      res.status(500).json({ message: "Failed to delete equipment usage" });
    }
  });

  // Distinct list of generator names for DG dropdowns. Falls back to canonical defaults if empty.
  // Returns active generators from the Equipment Master so the heating-session
  // and generator-log forms use the *same* names that appear on the Equipment
  // Usage screen. Falls back to historical generator-log names when the master
  // hasn't been populated yet.
  app.get("/api/plant-module/generators", async (_req, res) => {
    try {
      const all = await storage.getEquipmentMaster(false);
      const generators = all
        .filter((e: any) => (e.equipmentType || "").toLowerCase() === "generator")
        .map((e: any) => ({ id: e.id, name: e.name }));
      if (generators.length > 0) {
        generators.sort((a, b) => a.name.localeCompare(b.name));
        return res.json(generators);
      }
      // Legacy fallback — derive from past generator logs.
      const logs = await storage.getGeneratorLogs();
      const names = Array.from(
        new Set(
          logs
            .map((l: any) => (l.generatorName || "").toString().trim())
            .filter(Boolean)
        )
      );
      const merged = Array.from(new Set([...names, "600 KVA GENERATOR", "40-30 KVA GENERATOR"]));
      merged.sort();
      res.json(merged.map(n => ({ id: null, name: n })));
    } catch (err: any) {
      res.status(500).json({ message: err?.message || "Failed to list generators" });
    }
  });

  app.get("/api/plant-module/generator-logs", async (req, res) => {
    try {
      const filters = {
        dateFrom: req.query.dateFrom as string | undefined,
        dateTo: req.query.dateTo as string | undefined,
      };
      const logs = await storage.getGeneratorLogs(filters);
      res.json(logs);
    } catch (err) {
