      const irn = await storage.closeIrn(id, currentUserName(req));
      if (!irn) return res.status(404).json({ message: "IRN not found" });
      sendPushToSection("irn_view", "IRN Closed", `${irn.irnNo} marked as fulfilled`, "/irn").catch(() => {});
