  app.patch("/api/boq/scope-segments/:segId", async (req, res) => {
    try {
      if (!assertEdit(req, res, "project_scope")) return;
      const segId = parseInt(req.params.segId);
      let data: any;
      try { data = parseScopeSegmentBody(req.body); }
      catch (e: any) { return res.status(400).json({ error: e.message }); }
      const authUser = (req as any).authUser;
      const result = await storage.updateProjectScopeSegment(segId, data, authUser?.id ?? null);
      // Instruction 031: revising a CONFIRMED reach supersedes it — linked
      // arrangements lose that range now (stale auto rows stripped); when the
      // revision is confirmed, links are re-pointed and coverage redistributes.
      // A revised CONSTRAINT changes every linked reach's eligible clipping.
      if (result.revised) {
        if (result.segment.segmentType === "working_reach") {
          await reconcileArrangementsForScopeSegments([segId], authUser);
        } else {
          await reconcileLinkedArrangementsForProject(result.segment.boqProjectId, authUser);
        }
      }
      res.json({ ...result.segment, revised: result.revised });
    } catch (err: any) {
      const msg = String(err?.message ?? "");
      if (msg.startsWith("SEGMENT_")) return res.status(422).json({ error: msg });
      console.error("PATCH scope-segments:", err);
      res.status(500).json({ error: "Failed to update scope segment" });
    }
  });

  app.post("/api/boq/scope-segments/:segId/correct-initial", async (req, res) => {
    try {
      if (!assertAdmin(req, res)) return;
      const segId = Number(req.params.segId);
      if (!Number.isInteger(segId) || segId <= 0) return res.status(400).json({ error: "invalid_scope_segment_id" });
      const correctionReason = typeof req.body?.correctionReason === "string"
        ? req.body.correctionReason.trim()
        : "";
      if (!correctionReason) {
        return res.status(400).json({ error: "correction_reason_required", message: "A reason is required for an initial scope correction." });
      }
      if (correctionReason.length > 2000) {
        return res.status(400).json({ error: "correction_reason_too_long" });
      }
      let data: any;
      // Correction is a partial update: omitted optional fields must remain
      // untouched rather than being materialized as null.
      try { data = parseScopeSegmentBody(req.body, true); }
      catch (e: any) { return res.status(400).json({ error: e.message }); }
      const authUser = (req as any).authUser;
      const result = await storage.correctInitialScopeSegment(segId, data, correctionReason, {
        userId: authUser?.id ?? null,
        userName: currentUserName(req),
        userRole: authUser?.isOwner ? "owner" : authUser?.isAdmin ? "admin" : null,
      });
      return res.json({
        ...result.segment,
        correctedInPlace: true,
        before: result.before,
        affectedDrafts: result.affectedDrafts.map((draft: any) => ({
          ...draft,
          editUrl: draft.editUrl ?? `/site/edit/${draft.id}?draft`,
        })),
      });
    } catch (err: any) {
      if (err instanceof InitialScopeCorrectionBlockedError || err?.code === "INITIAL_SCOPE_CORRECTION_BLOCKED") {
        return res.status(409).json({
          error: "initial_scope_correction_blocked",
          code: "INITIAL_SCOPE_CORRECTION_BLOCKED",
          message: err.message,
          blockers: err.blockers ?? [],
          affectedDrafts: (err.affectedDrafts ?? []).map((draft: any) => ({
            ...draft,
            editUrl: draft.editUrl ?? `/site/edit/${draft.id}?draft`,
          })),
        });
      }
      const msg = String(err?.message ?? "");
      if (msg === "SEGMENT_NOT_FOUND" || msg === "PROJECT_NOT_FOUND") return res.status(404).json({ error: msg.toLowerCase() });
      if (msg === "CORRECTION_REASON_REQUIRED") return res.status(400).json({ error: "correction_reason_required" });
      console.error("POST initial scope correction:", err);
      return res.status(500).json({ error: "Failed to correct initial scope segment" });
    }
  });

  app.post("/api/boq/scope-segments/:segId/confirm", async (req, res) => {
    try {
      if (!assertApprove(req, res, "project_scope")) return;
      const segId = parseInt(req.params.segId);
      const authUser = (req as any).authUser;
      const segment = await storage.confirmProjectScopeSegment(segId, authUser?.id ?? null);
      await storage.logAudit({
        module: "project_scope", transactionId: segment.boqProjectId, action: "scope_segment_confirmed",
        userId: authUser?.id ?? null, userName: authUser?.name ?? authUser?.username ?? "unknown",
        userRole: authUser?.role ?? null,
        newValues: { segmentId: segment.id, segmentType: segment.segmentType, chainageFrom: segment.chainageFrom, chainageTo: segment.chainageTo, side: segment.side },
      } as any).catch((e: any) => console.error("scope confirm audit:", e?.message ?? e));
      // Instruction 031: confirming a revision of a linked reach re-points the
      // arrangements to the new geometry, then reconciles their bar coverage.
      if (segment.segmentType === "working_reach") {
        if ((segment as any).revisionOf != null) {
          await repointArrangementScopeLinks(Number((segment as any).revisionOf), segment.id);
        }
        await reconcileArrangementsForScopeSegments([segment.id, Number((segment as any).revisionOf ?? 0)], authUser);
      } else {
        // Newly confirmed constraint clips all linked reaches in the project.
        await reconcileLinkedArrangementsForProject(segment.boqProjectId, authUser);
      }
      res.json(segment);
    } catch (err: any) {
      const msg = String(err?.message ?? "");
      if (msg.startsWith("SEGMENT_")) return res.status(422).json({ error: msg });
      console.error("confirm scope-segment:", err);
      res.status(500).json({ error: "Failed to confirm scope segment" });
    }
  });

  app.delete("/api/boq/scope-segments/:segId", async (req, res) => {
