  const toRevisionBar = (bar: any): RevisionBar => ({
    id: Number(bar.id),
    boqProjectId: Number(bar.boqProjectId),
    boqItemId: Number(bar.boqItemId),
    chainageFrom: bar.chainageFrom != null ? Number(bar.chainageFrom) : null,
    chainageTo: bar.chainageTo != null ? Number(bar.chainageTo) : null,
    startDate: String(bar.startDate),
    endDate: String(bar.endDate),
    plannedQty: Number(bar.plannedQty ?? 0),
  });

  const isoCalendarDate = z.string().regex(/^\d{4}-\d{2}-\d{2}$/).refine((value) => {
    const parsed = new Date(`${value}T00:00:00Z`);
    return Number.isFinite(parsed.getTime()) && parsed.toISOString().slice(0, 10) === value;
  }, "Enter a valid calendar date.");
  const revisionBodySchema = z.object({
    startDate: isoCalendarDate.optional(),
    endDate: isoCalendarDate,
    reason: z.string().trim().min(1, "A revision reason is required.").max(1000),
    cascade: z.boolean().default(true),
    previewToken: z.string().length(64).optional(),
  });

  async function buildScheduleRevisionPlan(barId: number, rawBody: unknown) {
    const body = revisionBodySchema.parse(rawBody);
    const sourceLookup = await storage.getWorkProgramBar(barId);
    if (!sourceLookup) {
      const error: any = new Error("Programme bar not found.");
      error.code = "BAR_NOT_FOUND";
      throw error;
    }
    const project = await storage.getBoqProject(sourceLookup.boqProjectId);
    if (!project?.startDate) {
      const error: any = new Error("The project start date is required before calendar schedule revisions can be saved.");
      error.code = "PROJECT_START_REQUIRED";
      throw error;
    }
    const barsFull = await storage.getWorkProgramBars(sourceLookup.boqProjectId);
    // Use one project-wide snapshot for the source, candidates, token and
    // expected transaction state. Never combine a later successor read with
    // an earlier plan.
    const sourceFull = barsFull.find((bar) => bar.id === barId);
    if (!sourceFull) {
      const error: any = new Error("Programme bar not found.");
      error.code = "BAR_NOT_FOUND";
      throw error;
    }
    if (!sourceFull.startDate || !sourceFull.endDate) {
      const error: any = new Error("Set the project start date and commit this bar's calendar schedule before revising it.");
      error.code = "CALENDAR_SCHEDULE_REQUIRED";
      throw error;
    }
    const calendarBars = barsFull.filter((bar) => bar.startDate && bar.endDate);
    const evidence = await storage.getWorkProgrammeExecutionEvidence(sourceFull.boqProjectId, barsFull);
    const sourceBar = toRevisionBar(sourceFull);
    const requestedStart = body.startDate ?? sourceBar.startDate;
    const plan = planScheduleRevision({
      sourceBar,
      allProjectBars: calendarBars.map(toRevisionBar),
      evidenceMap: evidence,
      requestedStart,
      requestedEnd: body.endDate,
      cascade: body.cascade,
    });
    const sourceEvidence = evidence.get(barId) ?? { reportedQty: 0, earliestProgressDate: null, reviewRequired: false, unresolved: false };
    const fullById = new Map(barsFull.map((bar) => [bar.id, bar]));
    const expectedBars = barsFull
      .map((bar) => ({
        id: Number(bar.id),
        boqItemId: Number(bar.boqItemId),
        chainageFrom: bar.chainageFrom != null ? Number(bar.chainageFrom) : null,
        chainageTo: bar.chainageTo != null ? Number(bar.chainageTo) : null,
        startMonth: Number(bar.startMonth),
        endMonth: Number(bar.endMonth),
        startDate: bar.startDate ?? null,
        endDate: bar.endDate ?? null,
        plannedQty: Number(bar.plannedQty ?? 0),
      }))
      .sort((a, b) => a.id - b.id);
    const expectedEvidence = barsFull
      .map((bar) => {
        const row = evidence.get(bar.id) ?? { reportedQty: 0, earliestProgressDate: null, reviewRequired: false, unresolved: false };
        return {
          id: bar.id,
          reportedQty: Number(row.reportedQty ?? 0),
          earliestProgressDate: row.earliestProgressDate ?? null,
          reviewRequired: row.reviewRequired ?? false,
          unresolved: row.unresolved ?? false,
        };
      })
      .sort((a, b) => a.id - b.id);
    const previewToken = crypto.createHash("sha256").update(JSON.stringify({
      sourceBarId: barId,
      projectStartDate: project.startDate,
      requestedStart,
      requestedEnd: body.endDate,
      reason: body.reason,
      cascade: body.cascade,
      bars: expectedBars,
      evidence: expectedEvidence,
    })).digest("hex");
    const describe = (bar: RevisionBar) => {
      const full = fullById.get(bar.id);
      return {
        ...bar,
        reachLabel: full?.reachLabel ?? null,
        itemCode: full?.itemCode ?? null,
        description: full?.description ?? null,
        side: full?.side ?? null,
      };
    };
    return {
      body,
      project,
      sourceFull,
      sourceEvidence,
      evidence,
      barsFull,
      expectedBars,
      expectedEvidence,
      plan,
      preview: {
        previewToken,
        source: {
          before: describe(sourceBar),
          after: describe(plan.revisedSource),
          executionState: classifyBarExecutionState(sourceBar.plannedQty, sourceEvidence),
          actualStartDate: sourceEvidence.earliestProgressDate,
        },
        deltaDays: plan.delta,
        cascade: body.cascade,
        shifted: plan.shifted.map((bar) => ({
          before: describe(toRevisionBar(fullById.get(bar.id)!)),
          after: describe(bar),
        })),
        notShifted: plan.notShifted.map(({ bar, reason }) => ({
          bar: describe(bar),
          executionState: classifyBarExecutionState(bar.plannedQty, evidence.get(bar.id)),
          reason,
        })),
      },
    };
  }

  const sendRevisionError = (res: any, err: any) => {
    if (err instanceof z.ZodError) {
      return res.status(400).json({ error: "INVALID_REVISION", message: err.issues[0]?.message ?? "Invalid revision request." });
    }
    if (err?.code === "BAR_NOT_FOUND") return res.status(404).json({ error: err.code, message: err.message });
    if (["CALENDAR_SCHEDULE_REQUIRED", "PROJECT_START_REQUIRED"].includes(err?.code)) {
      return res.status(409).json({ error: err.code, message: err.message });
    }
    if (err?.code === "REVISION_STALE") return res.status(409).json({ error: err.code, message: err.message });
    if (/completed bar/i.test(err?.message ?? "")) {
      return res.status(409).json({ error: "BAR_COMPLETED", message: "Completed work cannot have its programme schedule revised." });
    }
    if (/start date/i.test(err?.message ?? "")) {
      return res.status(400).json({ error: "INVALID_DATE_RANGE", message: err.message });
    }
    console.error("Work programme schedule revision:", err);
    return res.status(500).json({ error: "REVISION_FAILED", message: "Failed to revise the programme schedule." });
  };

  app.post("/api/boq/programme/bars/:id/revision-preview", async (req, res) => {
    try {
      if (!assertEdit(req, res, "work_programme")) return;
      const result = await buildScheduleRevisionPlan(parseInt(req.params.id), req.body);
      // Preview is pure: no storage mutation occurs before this response.
      res.json(result.preview);
    } catch (err: any) {
      return sendRevisionError(res, err);
    }
  });

  app.post("/api/boq/programme/bars/:id/revise-schedule", async (req, res) => {
    try {
      if (!assertEdit(req, res, "work_programme")) return;
      const barId = parseInt(req.params.id);
      // Recompute immediately before the transaction; never trust a stale
      // client-side preview or a client-provided successor list.
      const {
        body,
        project,
        sourceFull,
        barsFull,
        expectedBars,
        expectedEvidence,
        plan,
        preview,
      } = await buildScheduleRevisionPlan(barId, req.body);
      if (!body.previewToken || body.previewToken !== preview.previewToken) {
        const error: any = new Error("The programme changed after the preview. Review the updated cascade before confirming again.");
        error.code = "REVISION_STALE";
        throw error;
      }
      const projectStart = project.startDate!;
      const sourceStartMonth = dateToMonthIndexCal(plan.revisedSource.startDate, projectStart);
      const sourceEndMonth = finishDateInputToIdx(plan.revisedSource.endDate, projectStart);
      if (!Number.isFinite(sourceStartMonth) || !Number.isFinite(sourceEndMonth)) {
        return res.status(400).json({ error: "INVALID_DATE_RANGE", message: "The revised calendar dates are invalid." });
      }

      const revisionId = crypto.randomUUID();
      const createdAt = new Date().toISOString();
      const authUser = (req as any).authUser;
      const actorId = authUser?.id ?? null;
      const actorName = currentUserName(req) ?? authUser?.username ?? null;
      const sourceHistory = {
        type: "schedule_revision",
        revisionId,
        barId,
        originalStartDate: sourceFull.startDate,
        originalEndDate: sourceFull.endDate,
        revisedStartDate: plan.revisedSource.startDate,
        revisedEndDate: plan.revisedSource.endDate,
        delta: plan.delta,
        reason: body.reason,
        cascadeApplied: body.cascade,
        actorId,
        actorName,
        createdAt,
      };
      const fullById = new Map(barsFull.map((bar) => [bar.id, bar]));
      const shifted = plan.shifted.map((bar) => {
        const current = fullById.get(bar.id)!;
        return {
          id: bar.id,
          expectedStartDate: current.startDate!,
          expectedEndDate: current.endDate!,
          startDate: bar.startDate,
          endDate: bar.endDate,
          startMonth: dateToMonthIndexCal(bar.startDate, projectStart),
          endMonth: finishDateInputToIdx(bar.endDate, projectStart),
          historyEntry: {
            type: "cascade_shift",
            revisionId: crypto.randomUUID(),
            sourceRevisionId: revisionId,
            sourceBarId: barId,
            barId: bar.id,
            originalStartDate: current.startDate,
            originalEndDate: current.endDate,
            shiftedStartDate: bar.startDate,
            shiftedEndDate: bar.endDate,
            delta: plan.delta,
            actorId,
            actorName,
            createdAt,
          },
        };
      });
      await storage.commitWorkProgrammeScheduleRevision({
        projectId: sourceFull.boqProjectId,
        expectedProjectStart: project.startDate!,
        requestedStart: body.startDate ?? sourceFull.startDate!,
        requestedEnd: body.endDate,
        cascade: body.cascade,
        expectedBars,
        expectedEvidence,
        source: {
          id: barId,
          expectedStartDate: sourceFull.startDate!,
          expectedEndDate: sourceFull.endDate!,
          startDate: plan.revisedSource.startDate,
          endDate: plan.revisedSource.endDate,
          startMonth: sourceStartMonth,
          endMonth: sourceEndMonth,
          historyEntry: sourceHistory,
        },
        shifted,
      });
      await storage.logAudit({
        module: "work_programme",
        transactionId: barId,
        action: "schedule_revision",
        userId: actorId,
        userName: actorName ?? "unknown",
        userRole: authUser?.isAdmin ? "admin" : (authUser?.role ?? null),
        oldValues: { startDate: sourceFull.startDate, endDate: sourceFull.endDate },
        newValues: {
          startDate: plan.revisedSource.startDate,
          endDate: plan.revisedSource.endDate,
          cascade: body.cascade,
          shiftedBarIds: plan.shifted.map((bar) => bar.id),
          notShiftedBarIds: plan.notShifted.map(({ bar }) => bar.id),
        },
        reason: body.reason,
      });
      res.json({ success: true, revisionId, ...preview });
    } catch (err: any) {
      return sendRevisionError(res, err);
    }
  });

  app.get("/api/boq/projects/:id/programme-status", async (req, res) => {
    try {
      if (!assertViewEither(req, res, "qto_boq", "work_programme", "work_programme_review")) return;
      const projectId = parseInt(req.params.id);
      const bars = await storage.getWorkProgramBars(projectId);
      const evidence = await storage.getWorkProgrammeExecutionEvidence(projectId, bars);
      const today = new Date().toISOString().slice(0, 10);
      const barsByItem = new Map<number, any[]>();
      for (const bar of bars) {
        if (bar.scheduled === false || bar.planningMode === "not_plannable_without_input") continue;
        const list = barsByItem.get(bar.boqItemId) ?? [];
        list.push(bar);
        barsByItem.set(bar.boqItemId, list);
      }
      const items = await storage.getBoqItems(projectId);
      res.json(items.map((item) => {
        const active = barsByItem.get(item.id) ?? [];
        const dated = active.filter((bar) => bar.startDate && bar.endDate).map(toRevisionBar);
        const status = active.length === 0
          ? "not_programmed"
          : dated.length === 0
            ? "planned"
            : deriveItemStatus(dated, evidence, today);
        const relevant = active.find((bar) =>
          classifyBarExecutionState(Number(bar.plannedQty ?? 0), evidence.get(bar.id)) !== "completed",
        ) ?? active[0] ?? null;
        return {
          boqItemId: item.id,
          status,
          relevantBarId: relevant?.id ?? null,
        };
      }));
    } catch (err) {
      console.error("GET /api/boq/projects/:id/programme-status:", err);
      res.status(500).json({ error: "Failed to derive programme status." });
    }
  });

  // ── Instruction 029 Part C: server-side chainage-overlap guard ─────────────
  // Two stretches of the SAME BOQ item may not genuinely overlap in chainage.
  // Touching boundaries (split-at-midpoint) are fine; strict interior overlap
  // blocks the save. Runs on create AND on chainage edits — not just Auto Sequence.
  const CH_OVERLAP_EPS = 0.0005; // 0.5 m — matches shared validateStretches
  /**
   * WP-02 applies this one guard to every direct schedule writer.  Revisions
   * have their own controlled route; this guard is deliberately not used there.
   */
  async function directScheduleMutationBlock(
    projectId: number,
    affectedBars: any[] = [],
  ): Promise<{ status: number; error: string; message: string } | null> {
    const project = await storage.getBoqProject(projectId);
    if (!project) return { status: 404, error: "BOQ_PROJECT_NOT_FOUND", message: "BOQ project not found" };
    if (project.programmeBaselinePublishedAt) {
      return {
        status: 409,
        error: "SCHEDULE_REVISION_REQUIRED",
        message: "Published programme dates can only be changed through Revise Schedule.",
      };
    }
    if (!affectedBars.length) return null;
    const evidence = await storage.getWorkProgrammeExecutionEvidence(projectId, affectedBars);
    const outcomes = await storage.getProgrammeBarOutcomeEventCounts(affectedBars.map((bar) => bar.id));
    const keyedValue = (source: any, id: number) => {
      if (source instanceof Map) return source.get(id);
      if (Array.isArray(source)) {
        return source.find((row) => Number(row?.barId ?? row?.id) === id);
      }
      return source?.[id] ?? source?.[String(id)];
    };
    if (affectedBars.some((bar) => !canDirectlyEditSchedule({
      programmeBaselinePublishedAt: null,
      evidence: keyedValue(evidence, bar.id),
      hasOutcomeEvents: Number(keyedValue(outcomes, bar.id) ?? 0) > 0,
    }))) {
      return {
        status: 409,
        error: "SCHEDULE_REVISION_REQUIRED",
        message: "Bars with recorded execution evidence can only be changed through Revise Schedule.",
      };
    }
    return null;
  }

  function sendDirectScheduleMutationBlock(
    res: Response,
    block: { status: number; error: string; message: string } | null,
  ): boolean {
    if (!block) return false;
    res.status(block.status).json({ error: block.error, message: block.message });
    return true;
  }
  class DirectScheduleMutationBlockedError extends Error {
    readonly code = "SCHEDULE_REVISION_REQUIRED";
    constructor(readonly block: { status: number; error: string; message: string }) {
      super(block.message);
    }
  }

  // 029B Part D: the single-bar create/PATCH guard shares the same side-aware
  // corridor policy as validateStretches(). Distinct corridors (LHS vs RHS,
  // shoulder L/R, …) may share chainage; full_width/both_sides/same-side still
  // conflict; a null side on either bar with overlapping chainage surfaces a
  // "side must be confirmed" result rather than a silent accept or a false
  // duplicate.
  async function findChainageOverlapConflict(
    boqProjectId: number,
    boqItemId: number,
    chainageFrom: unknown,
    chainageTo: unknown,
    excludeBarId?: number,
    candidateSide?: string | null,
  ): Promise<{ conflictBar: any; kind: "overlap" | "side_confirm" } | null> {
    const cf = Number(chainageFrom), ct = Number(chainageTo);
    if (!Number.isFinite(cf) || !Number.isFinite(ct)) return null; // no chainage → nothing to check
    const candSide = isBarSide(candidateSide) ? candidateSide : null;
    const siblings = (await storage.getWorkProgramBars(boqProjectId)) as any[];
    for (const b of siblings) {
      if (b.boqItemId !== boqItemId) continue;
      if (excludeBarId != null && b.id === excludeBarId) continue;
      const bf = Number(b.chainageFrom), bt = Number(b.chainageTo);
      if (!Number.isFinite(bf) || !Number.isFinite(bt)) continue;
      if (Math.min(ct, bt) - Math.max(cf, bf) <= CH_OVERLAP_EPS) continue; // interval math unchanged
      const sibSide = isBarSide(b.side) ? b.side : null;
      if (areSidesDistinctCorridors(candSide, sibSide)) continue; // e.g. LHS vs RHS — not an overlap
      if (candSide == null || sibSide == null) return { conflictBar: b, kind: "side_confirm" };
      return { conflictBar: b, kind: "overlap" };
    }
    return null;
  }

  app.post("/api/boq/projects/:id/programme", async (req, res) => {
    try {
      if (!assertEdit(req, res, "work_programme")) return;
      const boqProjectId = parseInt(req.params.id);
      if (sendDirectScheduleMutationBlock(res, await directScheduleMutationBlock(boqProjectId))) return;
      const data = { ...req.body, boqProjectId };
      if (!data.boqItemId || !data.startMonth || !data.endMonth) {
        return res.status(400).json({ error: "boqItemId, startMonth, endMonth are required" });
      }
      if (data.endMonth < data.startMonth) {
        return res.status(400).json({ error: "endMonth must be >= startMonth" });
      }
      const conflict = await findChainageOverlapConflict(
        boqProjectId, Number(data.boqItemId), data.chainageFrom, data.chainageTo,
        undefined, data.side ?? null);
      if (conflict) {
        if (conflict.kind === "side_confirm") {
          return res.status(400).json({
            error: "SIDE_CONFIRM_REQUIRED",
            message: `Chainage Km ${data.chainageFrom}–${data.chainageTo} overlaps stretch "${conflict.conflictBar.reachLabel ?? "unnamed"}" (Km ${conflict.conflictBar.chainageFrom}–${conflict.conflictBar.chainageTo}) of the same BOQ item — side must be confirmed on both bars before overlapping chainage stretches can be saved`,
          });
        }
        return res.status(400).json({
          error: "CHAINAGE_OVERLAP",
          message: `Chainage Km ${data.chainageFrom}–${data.chainageTo} overlaps existing stretch "${conflict.conflictBar.reachLabel ?? "unnamed"}" (Km ${conflict.conflictBar.chainageFrom}–${conflict.conflictBar.chainageTo}) of the same BOQ item on the same side`,
        });
      }
      const bar = await storage.upsertWorkProgramBar(data);
      res.status(201).json(bar);
    } catch (err) {
      console.error("POST /api/boq/projects/:id/programme:", err);
      res.status(500).json({ error: "Failed to create work programme bar" });
    }
  });

  app.post("/api/boq/projects/:id/programme/bulk", async (req, res) => {
    try {
      if (!assertEdit(req, res, "work_programme")) return;
      const boqProjectId = parseInt(req.params.id);
      if (sendDirectScheduleMutationBlock(res, await directScheduleMutationBlock(boqProjectId))) return;
      const { bars } = req.body as { bars: Array<Record<string, any>> };
      if (!Array.isArray(bars) || bars.length === 0) {
        return res.status(400).json({ error: "bars array is required and must not be empty" });
      }
      let created = 0;
      for (const b of bars) {
        if (!b.boqItemId || b.startMonth == null || b.endMonth == null) continue;
        if (b.endMonth < b.startMonth) continue;
        await storage.upsertWorkProgramBar({ ...b, boqProjectId } as any);
        created++;
      }
      res.status(201).json({ created });
    } catch (err) {
      console.error("POST /api/boq/projects/:id/programme/bulk:", err);
      res.status(500).json({ error: "Failed to bulk-create programme bars" });
    }
  });

  app.patch("/api/boq/programme/bars/:id", async (req, res) => {
    try {
      if (!assertEdit(req, res, "work_programme")) return;
      const barId = parseInt(req.params.id);
      const scheduleFields = [
        "startDate", "endDate", "startMonth", "endMonth",
        "durationMode", "durationDays", "durationSource", "isDurationOverride",
      ];
      if (scheduleFields.some((field) => Object.prototype.hasOwnProperty.call(req.body ?? {}, field))) {
        const existing = await storage.getWorkProgramBar(barId);
        if (!existing) return res.status(404).json({ error: "Bar not found" });
        if (sendDirectScheduleMutationBlock(res, await directScheduleMutationBlock(existing.boqProjectId, [existing]))) return;
      }
      // 030A invariant: a manual length override always carries a reason.
      if (req.body?.lengthOverrideM != null && !(req.body?.lengthOverrideReason ?? "").toString().trim()) {
        const existing = (await storage.getWorkProgramBar?.(barId)) ?? null;
        if (!(existing as any)?.lengthOverrideReason) {
          return res.status(400).json({
            error: "LENGTH_OVERRIDE_REASON_REQUIRED",
            message: "Overriding the chainage-derived length requires a reason (e.g. curved alignment, service road).",
          });
        }
      }
      // Instruction 029 Part C / 029B Part D: chainage OR side edits are
      // validated against sibling stretches of the same BOQ item — same-side
      // (or side-unconfirmed) overlap blocks the save; distinct corridors
      // (LHS vs RHS etc.) are allowed to share chainage.
      if (req.body?.chainageFrom !== undefined || req.body?.chainageTo !== undefined || req.body?.side !== undefined) {
        const existing = (await storage.getWorkProgramBar?.(barId)) ?? null;
        if (existing) {
          const cf = req.body.chainageFrom !== undefined ? req.body.chainageFrom : (existing as any).chainageFrom;
          const ct = req.body.chainageTo !== undefined ? req.body.chainageTo : (existing as any).chainageTo;
          const side = req.body.side !== undefined ? req.body.side : (existing as any).side;
          const conflict = await findChainageOverlapConflict(
            (existing as any).boqProjectId, (existing as any).boqItemId, cf, ct, barId, side ?? null);
          if (conflict) {
            if (conflict.kind === "side_confirm") {
              return res.status(400).json({
                error: "SIDE_CONFIRM_REQUIRED",
                message: `Chainage Km ${cf}–${ct} overlaps stretch "${conflict.conflictBar.reachLabel ?? "unnamed"}" (Km ${conflict.conflictBar.chainageFrom}–${conflict.conflictBar.chainageTo}) of the same BOQ item — side must be confirmed on both bars before overlapping chainage stretches can be saved`,
              });
            }
            return res.status(400).json({
              error: "CHAINAGE_OVERLAP",
              message: `Chainage Km ${cf}–${ct} overlaps stretch "${conflict.conflictBar.reachLabel ?? "unnamed"}" (Km ${conflict.conflictBar.chainageFrom}–${conflict.conflictBar.chainageTo}) of the same BOQ item on the same side`,
            });
          }
        }
      }
      const updated = await storage.updateWorkProgramBar(barId, req.body);
      if (!updated) return res.status(404).json({ error: "Bar not found" });
      res.json(updated);
    } catch (err) {
      console.error("PATCH /api/boq/programme/bars/:id:", err);
      res.status(500).json({ error: "Failed to update bar" });
    }
  });

  // ── Instruction 030A Part C point 8-10: deletion protection ────────────────
  // Ordinary deletion is BLOCKED when the bar has linked submitted DPR progress
  // (same reconcile-or-block philosophy Batch 029 built for arrangement-linked
  // bars). An authorised exceptional deletion (?force=true + reason, PM/Admin)
  // marks the affected entries "Programme Link Missing / Review Required",
  // lets the FK's SET NULL clear programmeBarId, and writes an audit record.
  app.delete("/api/boq/programme/bars/:id", async (req, res) => {
    try {
      if (!assertDelete(req, res, "work_programme")) return;
      const barId = parseInt(req.params.id);
      const bar = await storage.getWorkProgramBar?.(barId);
      if (!bar) return res.status(404).json({ error: "Bar not found" });
      if (sendDirectScheduleMutationBlock(
        res,
        await directScheduleMutationBlock((bar as any).boqProjectId, [bar]),
      )) return;
      const linkCounts = await storage.getSubmittedProgressLinkCounts([barId]);
      const linkedCount = linkCounts.get(barId) ?? 0;
      if (linkedCount > 0) {
        const force = req.query.force === "true" || req.body?.force === true;
        const reason = (req.body?.reason ?? req.query.reason ?? "").toString().trim();
        if (!force) {
          return res.status(409).json({
            error: "DPR_PROGRESS_LINKED",
            linkedProgressCount: linkedCount,
            message: `This bar has ${linkedCount} submitted DPR progress entr${linkedCount === 1 ? "y" : "ies"} linked to it. Ordinary deletion is blocked — reconcile the programme instead, or use an authorised exceptional deletion with a reason.`,
          });
        }
        // Exceptional path requires delete permission on the BOQ section + reason.
        if (!assertDeleteOrCancel(req, res, "work_programme")) return;
        if (!reason) {
          return res.status(400).json({ error: "REASON_REQUIRED", message: "An exceptional deletion of a DPR-linked bar requires a reason." });
        }
        const affectedIds = await storage.markProgressLinksReviewRequired(barId);
        await storage.deleteWorkProgramBar(barId); // FK ON DELETE SET NULL clears programmeBarId
        await storage.logAudit({
          module: "work_programme",
          transactionId: barId,
          action: "delete",
          userId: (req as any).authUser?.id ?? null,
          userName: currentUserName(req) ?? "unknown",
          userRole: (req as any).authUser?.isAdmin ? "admin" : ((req as any).authUser?.role ?? null),
          oldValues: bar ? { previousBarId: barId, reachLabel: (bar as any).reachLabel, chainageFrom: (bar as any).chainageFrom, chainageTo: (bar as any).chainageTo, side: (bar as any).side, boqItemId: (bar as any).boqItemId } : { previousBarId: barId },
          newValues: { affectedProgressEntryIds: affectedIds, markedReviewRequired: affectedIds.length },
          reason,
        });
        return res.json({ ok: true, exceptional: true, affectedProgressEntryIds: affectedIds });
      }
      await storage.deleteWorkProgramBar(barId);
      res.json({ ok: true });
    } catch (err) {
      console.error("DELETE /api/boq/programme/bars/:id:", err);
      res.status(500).json({ error: "Failed to delete bar" });
    }
  });

  // ── Instruction 030A Part A point 1: PM/Admin bulk side confirmation ──────
  // Reviewed batch action to set existing null-side bars to an explicit side.
  // Never an automatic migration — the user picks the bars and the side.
  app.post("/api/boq/projects/:id/programme/bulk-side", async (req, res) => {
    try {
      if (!assertEdit(req, res, "work_programme")) return;
      const boqProjectId = parseInt(req.params.id);
      const side = req.body?.side;
      const barIds: number[] = Array.isArray(req.body?.barIds)
        ? (req.body.barIds as any[]).map(Number).filter(Number.isFinite)
        : [];
      if (!isBarSide(side) || !["full_width", "lhs", "rhs", "both_sides"].includes(side)) {
        return res.status(400).json({ error: "INVALID_SIDE", message: "Bulk confirmation supports Full Width, LHS, RHS or Both Sides." });
      }
      if (barIds.length === 0) return res.status(400).json({ error: "NO_BARS", message: "Select at least one bar." });
      const bars = await storage.getWorkProgramBars(boqProjectId);
      const eligible = new Set(bars.filter(b => barIds.includes(b.id)).map(b => b.id));
      let updated = 0;
      for (const id of barIds) {
        if (!eligible.has(id)) continue; // never touch bars of another project
        await storage.updateWorkProgramBar(id, { side } as any);
        updated++;
      }
      await storage.logAudit({
        module: "work_programme",
        transactionId: boqProjectId,
        action: "edit",
        userId: (req as any).authUser?.id ?? null,
        userName: currentUserName(req) ?? "unknown",
        userRole: (req as any).authUser?.isAdmin ? "admin" : ((req as any).authUser?.role ?? null),
        newValues: { bulkSide: side, barIds: barIds.filter(id => eligible.has(id)) },
        reason: "030A bulk side confirmation",
      });
      res.json({ updated });
    } catch (err) {
      console.error("POST bulk-side:", err);
      res.status(500).json({ error: "Failed to set bar sides" });
    }
  });

  // ── Instruction 030A Part B point 7: split a bar by side (PM/Admin) ────────
  // preview=true returns the proposed quantity allocation plus linked
  // arrangements / DPR progress so the user confirms with full context.
  // Commit TRANSFORMS the original bar in place into the first side (its id —
  // and therefore every arrangement allocation and DPR progress link — is
  // preserved; nothing is deleted) and inserts the remaining sides as new bars.
  app.post("/api/boq/programme/bars/:id/split-by-side", async (req, res) => {
    try {
      if (!assertEdit(req, res, "work_programme")) return;
      const barId = parseInt(req.params.id);
      const bar = await storage.getWorkProgramBar?.(barId);
      if (!bar) return res.status(404).json({ error: "Bar not found" });
      const parts: Array<{ side: string; qtyShare?: number }> = Array.isArray(req.body?.parts) ? req.body.parts : [];
      if (parts.length < 2) return res.status(400).json({ error: "At least two side parts are required to split" });
      for (const p of parts) {
        if (!isBarSide(p.side)) return res.status(400).json({ error: `Invalid side "${p.side}"` });
      }
      // Quantity allocation: explicit shares must sum to 1; default = equal split.
      const explicit = parts.every(p => p.qtyShare != null && Number(p.qtyShare) > 0);
      const shares = explicit ? parts.map(p => Number(p.qtyShare)) : parts.map(() => 1 / parts.length);
      const shareSum = shares.reduce((a, b) => a + b, 0);
      if (explicit && Math.abs(shareSum - 1) > 0.001) {
        return res.status(400).json({ error: "QTY_SHARES_INVALID", message: `Quantity shares must sum to 100% (got ${(shareSum * 100).toFixed(1)}%)` });
      }
      const totalQty = Number((bar as any).plannedQty ?? 0);
      const allocation = parts.map((p, i) => ({ side: p.side, qty: +(totalQty * shares[i] / shareSum * (explicit ? 1 : 1)).toFixed(3) }));

      const [linkCounts, allocRows] = await Promise.all([
        storage.getSubmittedProgressLinkCounts([barId]),
        storage.getActiveAllocationsForBar(barId),
      ]);
      const context = {
        linkedDprProgressCount: linkCounts.get(barId) ?? 0,
        linkedArrangementIds: Array.from(new Set((allocRows as any[]).map(a => a.arrangementId))),
      };
      if (req.body?.preview === true) {
        return res.json({ preview: true, allocation, ...context, note: "The original bar becomes the first side (all arrangement and DPR links stay on it); the remaining sides are created as new bars." });
      }
      // Commit: in-place transform + inserts.
      if (sendDirectScheduleMutationBlock(
        res,
        await directScheduleMutationBlock((bar as any).boqProjectId, [bar]),
      )) return;
      const first = allocation[0];
      await storage.updateWorkProgramBar(barId, { side: first.side, plannedQty: first.qty } as any);
      const createdBars: any[] = [];
      for (const part of allocation.slice(1)) {
        const nb = await storage.upsertWorkProgramBar({
          boqProjectId: (bar as any).boqProjectId,
          boqItemId: (bar as any).boqItemId,
          reachLabel: (bar as any).reachLabel,
          chainageFrom: (bar as any).chainageFrom,
          chainageTo: (bar as any).chainageTo,
          startMonth: (bar as any).startMonth,
          endMonth: (bar as any).endMonth,
          plannedQty: part.qty,
          source: "manual",
          side: part.side,
          plannedWidthM: (bar as any).plannedWidthM ?? null,
          plannedThicknessMm: (bar as any).plannedThicknessMm ?? null,
          ...(((bar as any).sequenceOrder != null) ? { sequenceOrder: (bar as any).sequenceOrder } : {}),
        } as any);
        createdBars.push(nb);
      }
      await storage.logAudit({
        module: "work_programme",
        transactionId: barId,
        action: "edit",
        userId: (req as any).authUser?.id ?? null,
        userName: currentUserName(req) ?? "unknown",
        userRole: (req as any).authUser?.isAdmin ? "admin" : ((req as any).authUser?.role ?? null),
        oldValues: { side: (bar as any).side ?? null, plannedQty: totalQty },
        newValues: { splitInto: allocation, newBarIds: createdBars.map(b => b.id) },
        reason: "030A split bar by side",
      });
      res.json({ ok: true, allocation, updatedBarId: barId, newBarIds: createdBars.map(b => b.id), ...context });
    } catch (err) {
      console.error("POST split-by-side:", err);
      res.status(500).json({ error: "Failed to split bar" });
    }
  });

  // DPR programme-bar outcome events are append-only. Corrections are recorded
  // as a new event; there intentionally are no PATCH or DELETE routes.
  const outcomeInputSchema = z.object({
    programmeBarId: z.coerce.number().int().positive(),
    eventDate: z.string().regex(/^\d{4}-\d{2}-\d{2}$/, "eventDate must be YYYY-MM-DD"),
    outcome: z.enum(PROGRAMME_BAR_OUTCOMES),
    reason: z.enum(PROGRAMME_BAR_OUTCOME_REASONS).optional().nullable(),
    reasonOther: z.string().trim().max(2000).optional().nullable(),
    rescheduledDate: z.string().regex(/^\d{4}-\d{2}-\d{2}$/).optional().nullable(),
    actualQuantity: z.coerce.number().finite().nonnegative().optional().nullable(),
    actualUom: z.string().trim().max(64).optional().nullable(),
    remarks: z.string().trim().max(5000).optional().nullable(),
  });

  async function assertOutcomeProjectScope(req: any, res: any, projectId: number): Promise<boolean> {
    const project = await storage.getBoqProject(projectId);
    if (!project) {
      res.status(404).json({ message: "BOQ project not found" });
      return false;
    }
    const permitted = await getPermittedSiteNames(req);
    if (permitted !== null) {
      const site = (await storage.getSites()).find((candidate) => candidate.id === project.siteId);
      if (!site || !siteMatchesPermitted(site.name, permitted)) {
        res.status(403).json({ message: "You do not have access to this project's site." });
        return false;
      }
    }
    return true;
  }

  function assertOutcomeManagerAuthority(req: any, res: any): boolean {
    const user = req.authUser;
    if (!user) {
      res.status(401).json({ message: "Authentication required" });
      return false;
    }
    const role = String(user.role ?? "").trim().toLowerCase().replace(/[\s-]+/g, "_");
    const permitted = !!user.isAdmin || !!user.isOwner ||
      ["manager", "pm", "project_manager"].includes(role);
    if (!permitted) {
      res.status(403).json({ message: "Manager, PM, Admin or Owner authority is required to set arrangement status." });
      return false;
    }
    return true;
  }

  app.post("/api/dpr/programme-bar-outcomes", async (req, res) => {
    try {
      if (!assertOutcomeManagerAuthority(req, res)) return;
      const parsed = outcomeInputSchema.safeParse(req.body);
      if (!parsed.success) return res.status(400).json({ message: parsed.error.issues[0]?.message ?? "Invalid outcome event" });
      const input = parsed.data;
      const bar = await storage.getWorkProgramBar(input.programmeBarId);
      if (!bar) return res.status(404).json({ message: "Programme bar not found" });
      if (!(await assertOutcomeProjectScope(req, res, bar.boqProjectId))) return;
      const reasonOther = input.reasonOther?.trim() || null;
      const rescheduledDate = input.rescheduledDate || null;
      const actualUom = input.actualUom?.trim() || null;
      const tupleError = programmeBarOutcomeInputError({ ...input, reasonOther, rescheduledDate, actualUom });
      if (tupleError) return res.status(400).json({ message: tupleError });
      const [event] = await db.insert(programmeBarOutcomeEvents).values({
        programmeBarId: input.programmeBarId, eventDate: input.eventDate, outcome: input.outcome, reason: input.reason ?? "",
        reasonOther, rescheduledDate, actualQuantity: input.actualQuantity ?? null, actualUom,
        remarks: input.remarks?.trim() || null, createdBy: req.authUser?.id ?? null,
      }).returning();
      res.status(201).json(event);
    } catch (err) {
      console.error("POST /api/dpr/programme-bar-outcomes:", err);
      res.status(500).json({ message: "Failed to record programme-bar outcome" });
    }
  });

  app.get("/api/dpr/programme-bar-outcomes", async (req, res) => {
