  // ── Instruction 030A Part C point 12-13: programme bars for the DPR picker ──
  // Returns bars for a BOQ item with reach/side/dates/planned qty, reported
  // quantity so far, remaining, arrangement context (Part D), and execution
  // status inputs — a structured selector, not a list of IDs.
  app.get("/api/dpr/programme-bars", async (req, res) => {
    try {
      if (!assertView(req, res, "site_dprs")) return;
      const boqProjectId = parseInt(String(req.query.projectId));
      const boqItemId = parseInt(String(req.query.boqItemId));
      if (!Number.isFinite(boqProjectId) || !Number.isFinite(boqItemId)) {
        return res.status(400).json({ error: "projectId and boqItemId are required" });
      }
      if (!(await assertOutcomeProjectScope(req, res, boqProjectId))) return;
      const allBars = await storage.getWorkProgramBars(boqProjectId);
      const itemBars = allBars.filter(b => b.boqItemId === boqItemId && (b as any).scheduled !== false);
      const barIds = itemBars.map(b => b.id);
       const [reported, allocRows, sideEntries, outcomeRows] = await Promise.all([
        storage.getReportedQtyByBar(barIds),
        storage.getArrangementProgrammeAllocationsForProject(boqProjectId),
        storage.getProgressSideEntriesByBar(barIds),
        barIds.length ? db.select().from(programmeBarOutcomeEvents)
          .where(drizzleInArray(programmeBarOutcomeEvents.programmeBarId, barIds))
          .orderBy(desc(programmeBarOutcomeEvents.eventDate), desc(programmeBarOutcomeEvents.createdAt), desc(programmeBarOutcomeEvents.id)) : Promise.resolve([]),
      ]);
       const outcomesByBar = new Map<number, any[]>();
       outcomeRows.forEach((event: any) => outcomesByBar.set(event.programmeBarId, [...(outcomesByBar.get(event.programmeBarId) ?? []), event]));
      // Approved arrangement context per bar (Part D) — executing agency shown,
      // never inferred from the DPR author.
      const arrangementByBar = new Map<number, any>();
      for (const al of allocRows as any[]) {
        if (al.arrangementStatus === "approved" && barIds.includes(al.programmeBarId)) {
          arrangementByBar.set(al.programmeBarId, al);
        }
      }
      const arrIds = Array.from(new Set(Array.from(arrangementByBar.values()).map((a: any) => a.arrangementId)));
      const arrangements = await Promise.all(arrIds.map(id => storage.getEarthworkArrangementById(id)));
      const arrById = new Map(arrangements.filter(Boolean).map(a => [a!.id, a!]));
      res.json(itemBars.map(b => {
        const alloc = arrangementByBar.get(b.id);
        const arr = alloc ? arrById.get(alloc.arrangementId) : null;
        const reportedReviewRequired = reported.reviewRequiredBarIds?.has(b.id) ?? false;
        const reportedQtyUnresolved = reported.unresolvedBarIds?.has(b.id) ?? false;
        const reportedQty = reportedQtyUnresolved ? null : (reported.get(b.id) ?? 0);
        return {
          id: b.id,
          reachLabel: (b as any).reachLabel,
          chainageFrom: (b as any).chainageFrom,
          chainageTo: (b as any).chainageTo,
          side: (b as any).side ?? null,
          plannedWidthM: (b as any).plannedWidthM ?? null,
          plannedThicknessMm: (b as any).plannedThicknessMm ?? null,
          lengthOverrideM: (b as any).lengthOverrideM ?? null,
          calculatedLengthM: ((b as any).chainageFrom != null && (b as any).chainageTo != null)
            ? Math.max(0, ((b as any).chainageTo - (b as any).chainageFrom)) * 1000
            : null,
          startDate: (b as any).startDate,
          endDate: (b as any).endDate,
          sequenceOrder: (b as any).sequenceOrder ?? null,
          plannedQty: b.plannedQty,
          reportedQty,
          remainingQty: reportedQty == null ? null : Math.max(0, b.plannedQty - reportedQty),
          reportedQtyReviewRequired: reportedReviewRequired,
          reportedQtyUnresolved,
          // Batch 1 Part E: shared quantity, SEPARATE side coverage — which
          // chainage each carriageway side has actually executed so far.
          sideCoverage: barSideCoverage(
            { side: (b as any).side ?? null, chainageFrom: (b as any).chainageFrom ?? null, chainageTo: (b as any).chainageTo ?? null },
            sideEntries.get(b.id) ?? [],
          ),
          unit: (b as any).unit ?? null,
          arrangement: arr ? {
            id: arr.id,
            mode: (arr as any).arrangementType ?? (arr as any).mode ?? null,
            agency: (arr as any).agencyName ?? (arr as any).partyName ?? null,
            status: (arr as any).status ?? null,
          } : null,
           latestOutcome: outcomesByBar.get(b.id)?.[0] ?? null,
           outcomeHistory: outcomesByBar.get(b.id) ?? [],
        };
      }));
    } catch (err) {
      console.error("GET /api/dpr/programme-bars:", err);
      res.status(500).json({ error: "Failed to load programme bars" });
    }
  });

  // ── Clean road-style bars from structure items ────────────────────────────
  // Deletes auto-sequence and auto-generate bars that were incorrectly placed on
  // BOQ items that are structure-planned. An item is treated as structure-planned
  // when ANY of the following is true:
  //   - planningWorkType === "structure" (explicit or classifier-set)
  //   - it already has at least one source = "structure_import" bar
  //   - its BOQ category/section name matches a known structure section
  //     (Culverts, Bridges, Minor/Major Bridges, Drainage and Protection Works,
  //     Retaining Walls)
  //   - its description matches structure-context keywords (bearing, POT, PTFE,
  //     tar paper, expansion joint, drainage spout, weep hole, bridge numbering,
  //     bridge painting, approach slab, abutment, pier, substructure,
  //     superstructure, filter media behind abutment, wing wall, head wall,
  //     retaining wall, foundation excavation)
  // Structure-location (imported) bars are always preserved. Genuine manual bars
  // (source="manual" with a custom, non-auto-generated label) are NEVER deleted
  // silently — they are returned as `needsConfirmation` and only removed when the
  // caller re-POSTs with their ids in `confirmBarIds`.
  app.post("/api/boq/projects/:id/programme/clean-structure-bars", async (req, res) => {
    try {
      if (!assertDelete(req, res, "work_programme")) return;
      const boqProjectId = parseInt(req.params.id);
      const confirmBarIds: number[] = Array.isArray(req.body?.confirmBarIds)
        ? (req.body.confirmBarIds as any[]).map((x) => Number(x)).filter((n) => Number.isFinite(n))
        : [];
      const items = await storage.getBoqItems(boqProjectId);
      const bars  = await storage.getWorkProgramBars(boqProjectId);

      // Items that have at least one imported structure-location bar are implicitly
      // structure-planned even if planningWorkType was never set manually.
      const structureImportItemIds = new Set(
        (bars as any[])
          .filter((b) => b.source === "structure_import")
          .map((b) => b.boqItemId),
      );

      const structureItemIds = new Set([
        ...(items as any[])
          .filter((it) => isStructureOrLocationScheduledItem(it, { hasStructureImportBar: structureImportItemIds.has(it.id) }))
          .map((it) => it.id),
        ...structureImportItemIds,
      ]);

      if (structureItemIds.size === 0) {
        return res.json({ deleted: 0, needsConfirmation: [], message: "No structure-planned BOQ items found (no structure_import bars, no matching category/keywords)" });
      }

      // Regex that matches labels auto-generated by the planning engine.
      // Legacy bars created before the source column was populated often have
      // source="manual" but carry one of these auto-generated label values.
      const AUTO_LABEL_RE = /^(Full Length|Structures|Bridges|Reach \d+|Struct\. Front \d+|Bridge Grp \d+)$/;

      const toDelete: any[] = [];
      const needsConfirmation: any[] = [];

      for (const b of bars as any[]) {
        if (!structureItemIds.has(b.boqItemId)) continue;
        if (b.planningMode === "structure_location") continue; // always keep imported bars
        // Auto-sequence / auto-generate bars
        if (b.source === "auto-sequence" || b.source === "auto_generate") { toDelete.push(b); continue; }
        // Null source = legacy bar created before source column existed
        if (!b.source) { toDelete.push(b); continue; }
        // source="manual" but carrying an auto-generated label → legacy stray bar
        if (b.source === "manual" && AUTO_LABEL_RE.test(b.reachLabel ?? "")) { toDelete.push(b); continue; }
        // Genuine manual bar on a structure item — never delete silently.
        if (b.source === "manual") {
          if (confirmBarIds.includes(b.id)) {
            toDelete.push(b);
          } else {
            needsConfirmation.push({ id: b.id, boqItemId: b.boqItemId, reachLabel: b.reachLabel, startMonth: b.startMonth, endMonth: b.endMonth, plannedQty: b.plannedQty });
          }
        }
      }

      // A request with no deletion candidate is a read-only discovery response
      // (notably the manual-bar confirmation preview), so leave it available.
      // Guard only immediately before an actual cleanup commit.
      if (toDelete.length > 0 && sendDirectScheduleMutationBlock(
        res,
        await directScheduleMutationBlock(boqProjectId, toDelete),
      )) return;

      // 030A: never delete a bar with linked submitted DPR progress — even in a
      // bulk cleanup. Report them instead of silently destroying the linkage.
      const cleanLinkCounts = await storage.getSubmittedProgressLinkCounts(toDelete.map(b => b.id));
      const blockedByDpr = toDelete.filter(b => (cleanLinkCounts.get(b.id) ?? 0) > 0);
      const deletable = toDelete.filter(b => (cleanLinkCounts.get(b.id) ?? 0) === 0);

      let deleted = 0;
      for (const b of deletable) {
        await storage.deleteWorkProgramBar(b.id);
        deleted++;
      }

      const messageParts: string[] = [];
      messageParts.push(deleted ? `Removed ${deleted} road-style bar(s) from structure items` : "No stray auto-generated bars found on structure items");
      if (needsConfirmation.length) {
        messageParts.push(`${needsConfirmation.length} manually-created bar(s) on structure items need confirmation before deletion`);
      }
      if (blockedByDpr.length) {
        messageParts.push(`${blockedByDpr.length} bar(s) kept — linked submitted DPR progress`);
      }

      res.json({
        deleted,
        needsConfirmation,
        blockedByDpr: blockedByDpr.map(b => ({ id: b.id, reachLabel: b.reachLabel, linkedProgress: cleanLinkCounts.get(b.id) ?? 0 })),
        message: messageParts.join("; "),
      });
    } catch (err) {
      console.error("POST /api/boq/projects/:id/programme/clean-structure-bars:", err);
      res.status(500).json({ error: "Failed to clean structure bars" });
    }
  });

