      const idsParam = req.query["ids[]"] ?? req.query["ids"];
      const rawIds = Array.isArray(idsParam) ? idsParam : (idsParam ? [idsParam] : []);
      const ids = rawIds.map(Number).filter(n => !isNaN(n) && n > 0);
