  // ── BOM helper functions ────────────────────────────────────────────────────
  // Items that physically CONSUME no key material (demolition / removal / milling).
  // These must never demand cement/RMC/bitumen/aggregate, regardless of the words
  // (e.g. "Dismantling structures ... RCC", "Dismantling of pavements ... Concrete").
  function isNonConsumingItem(desc: string): boolean {
    return /\bdismantl|\bdemolit|\bdemolish|\bremoving\b|\bremoval\b|\bbreaking\b|\bscarif|\bmilling\b/i.test(desc);
  }

  function isMaterialDrivingLayerItem(item: any): boolean {
    const lc = item.layerConfig as LayerConfig | null;
    const desc = String(item.description ?? "").toLowerCase();
    const cat = String(item.workCategory ?? "").toLowerCase();
    if (isNonConsumingItem(desc)) return false; // demolition/removal → no key material
    if (lc?.layerType && lc.layerType !== "none") return true;
    return (
      /\bgsb\b|granular\s*sub[-\s]*base|wet\s*mix|\bwmm\b|dbm|dense\s*bituminous|bituminous\s*concrete|\bbc\b|bituminous\s*macadam|\bbm\b|sdbc|wearing\s*coat|prime\s*coat|tack\s*coat|\bpcc\b|\brcc\b|\bpqc\b|\bdlc\b|cement\s*concrete|plain\s*cement\s*concrete|reinforced\s*cement\s*concrete|pavement\s*quality\s*concrete|dry\s*lean\s*concrete|concrete\s*of\s*grade/i.test(desc) ||
      /subbase|base|bituminous|concrete/i.test(cat)
    );
  }

  function isSimpleDirectMaterialItem(item: any): boolean {
    const desc = String(item.description ?? "").toLowerCase();
    return /filter\s*media|stone\s*spalls|stone\s*pitching|boulder|pipe|np3|np4|hdpe|bearing|expansion\s*joint|joint\s*sealant|sealant|dowel|plastic\s*sheath|geotextile|separation\s*membrane|sign\s*board|stud|marker|reflector|kerb|railing|crash\s*barrier|anchor|anchorage/i.test(desc);
  }

  function isRawSdbAggregateName(name: string): boolean {
    const s = String(name ?? "").toLowerCase();
    return (
      /\d+(\.\d+)?\s*mm.*\d+(\.\d+)?\s*mm/.test(s) ||
      /below\s*\d+(\.\d+)?\s*mm/.test(s) ||
      /\d+(\.\d+)?\s*mm\s*and\s*below/.test(s) ||
      /percent|per\s*cent|gradation|graded\s*aggregate|coarse\s*graded|fine\s*graded/i.test(s)
    );
  }

  function detectConcreteGrade(text: string): string | null {
    const s = String(text ?? "").toUpperCase();
    // Accept "M15", "M-15", "M 15", "M -15", "GRADE M-25" etc. (dash/space tolerant)
    const m = s.match(/\bM[\s-]*([0-9]{2,3})\b/);
    return m ? `M${m[1]}` : null;
  }

  function isConcreteLayerOrItem(item: any): boolean {
    const lc = item.layerConfig as LayerConfig | null;
    const desc = String(item.description ?? "").toLowerCase();
    if (lc?.layerType === "concrete") return true;
    if (lc?.layerType === "bituminous") return false;
    if (isNonConsumingItem(desc)) return false;     // dismantling RCC/PQC → not a concrete pour
    if (/bitumin/i.test(desc)) return false;          // "bituminous concrete" is bituminous, not RCC
    return /\bpcc\b|\brcc\b|\bpqc\b|\bdlc\b|plain\s*cement\s*concrete|reinforced\s*cement\s*concrete|dry\s*lean\s*concrete|pavement\s*quality\s*concrete|cement\s*concrete|concrete\s*of\s*grade|grade\s*m\s*-?\s*\d{2}/i.test(desc);
  }

  function isBituminousLayerOrItem(item: any): boolean {
    const lc = item.layerConfig as LayerConfig | null;
    const desc = String(item.description ?? "").toLowerCase();
    if (lc?.layerType === "bituminous") return true;
    if (isNonConsumingItem(desc)) return false;     // dismantling bituminous layer → not a laying item
    return /dbm|dense\s*bituminous|bituminous\s*concrete|\bbc\b|bituminous\s*macadam|\bbm\b|sdbc|wearing\s*coat/i.test(desc);
  }

  // Synthesize a LayerConfig from the deterministic work-type classifier (Patch 14)
  // when an item has no manually-saved layerConfig. This unlocks the existing P2
  // derivation so concrete hits the RMC mix designs and bituminous hits the Master
  // mix templates automatically — instead of falling straight to "setup required".
  function synthLayerConfigFromWorkType(item: any): LayerConfig | null {
    const desc = String(item.description ?? "");
    const unit = String(item.unit ?? "");
    if (isNonConsumingItem(desc.toLowerCase())) return null;

    const wt = classifyWorkType(desc, unit);
    if (!wt) return null;

    const d = desc.toLowerCase();
    const thM = desc.match(/([0-9]+(?:\.[0-9]+)?)\s*mm/i);
    const detectedThk = thM ? parseFloat(thM[1]) : null;
    const srM = desc.match(/([0-9]+(?:\.[0-9]+)?)\s*kg\s*(?:per|\/)?\s*(?:sqm|sq\.?\s*m|m2|m²)/i);
    const detectedRate = srM ? parseFloat(srM[1]) : null;

    switch (wt) {
      case "earthwork":
        return { layerType: "earthwork" };
      case "gsb":
        return { layerType: "granular", mixType: "GSB", granularSource: "quarry" };
      case "wmm":
        return { layerType: "granular", mixType: "WMM", granularSource: "quarry" };
      case "prime_coat":
        return { layerType: "spray_coat", mixType: "PRIME", coverageRateKgPerSqm: detectedRate ?? 1.0, coverageMaterialName: "Primer (Bitumen Emulsion)" };
      case "tack_coat":
        return { layerType: "spray_coat", mixType: "TACK", coverageRateKgPerSqm: detectedRate ?? 0.3, coverageMaterialName: "Tack Coat (Bitumen Emulsion)" };
      case "bituminous_base":
        return {
          layerType: "bituminous",
          mixType: /\bbm\b|bituminous\s*macadam/i.test(d) && !/dense/i.test(d) ? "BM" : "DBM",
          thicknessMm: detectedThk ?? 75,
          densityTPerCum: 2.35,
        };
      case "bituminous_wearing":
        return {
          layerType: "bituminous",
          mixType: /sdbc|semi[-\s]*dense/i.test(d) ? "SDBC" : "BC",
          thicknessMm: detectedThk ?? 40,
          densityTPerCum: 2.4,
        };
      case "pcc":
      case "rcc":
      case "pqc":
      case "dlc": {
        // Only real volumetric concrete pours demand RMC. Count/lump-sum items
        // (toll booths = Nos, buildings = LS/Sqm) and pipe-laying items must NOT.
        const uNorm = unit.toUpperCase().replace(/[^A-Z0-9]/g, "");
        const isVolumetric = /^(CUM|CUB|M3|CU)$/.test(uNorm) || /cu\.?\s*m|cubic/i.test(unit);
        if (!isVolumetric) return null;
        if (/\bpipe|np\d|hume|hdpe/i.test(d)) return null;
        return {
          layerType: "concrete",
          mixType: wt === "dlc" ? "DLC" : wt === "pqc" ? "PQC" : null,
        };
      }
      case "drain_masonry":
      default:
        return null;
    }
  }

  // Composite bituminous layer parser — detects items like "40mm BC + 25mm mastic asphalt"
  // and returns each sub-layer so materials are derived independently and then combined.
  // Only applies to area-based (Sqm) items; CUM/MT items use the template directly.
  function parseCompositeLayers(
    desc: string, unit: string,
  ): Array<{thicknessMm: number; mixType: string; density: number}> | null {
    const uNorm = unit.toUpperCase().replace(/[^A-Z0-9]/g, "");
    if (!/^(SQM|M2|SQMT|SQM)/.test(uNorm)) return null;
    const d = desc.toLowerCase();
    const found: Array<{thicknessMm: number; mixType: string; density: number}> = [];
    const tryExtract = (typePattern: string, mixType: string, density: number) => {
      const rx = new RegExp(
        `(\\d+)\\s*mm\\s*(?:thick\\s*)?(?:layer\\s*of\\s*)?(?:${typePattern})`, "i",
      );
      const m = d.match(rx);
      if (m) {
        const thk = parseInt(m[1], 10);
        if (thk > 0 && thk < 200 && !found.find(f => f.mixType === mixType)) {
          found.push({ thicknessMm: thk, mixType, density });
        }
      }
    };
    tryExtract("mastic", "MA", 2.30);
    tryExtract("\\bbc\\b|bituminous\\s*concrete", "BC", 2.40);
    tryExtract("sdbc|semi.?dense\\s*bituminous", "SDBC", 2.40);
    tryExtract("dense\\s*bituminous|\\bdbm\\b", "DBM", 2.35);
    tryExtract("\\bbm\\b|bituminous\\s*macadam", "BM", 2.35);
    return found.length > 1 ? found : null;
  }

  // Shared BOM expansion — resolves each BOQ item to its best material list using the
  // P1→P4 source priority. Used by BOTH /bom and /shortage-check so the two endpoints
  // can never drift apart. (Previously /shortage-check referenced an `expandedItems`
  // that only existed inside /bom → ReferenceError → empty Procurement Intelligence.)
  async function computeProjectBom(projectId: number) {
      const [allBoqItems, bars, project, allMaterials, rmcDesigns, allMixTemplates] = await Promise.all([
        storage.getBoqItemsWithRecipes(projectId),
        storage.getWorkProgramBars(projectId),
        storage.getBoqProject(projectId),
        storage.getPlantMaterials(), // for mix template component name resolution
        storage.getRmcMixDesigns(), // concrete materials source (RMC module)
        storage.getMixTemplates(),  // bituminous standard templates (Masters/HMP)
      ]);

      // Filter to items included in planning (excluded items stay in BOQ for billing only)
      const items = allBoqItems.filter(it => it.includedInPlanning !== false);

      // Build materialId → name map for resolving mix template component names
      const matNameById = new Map(allMaterials.map(m => [m.id, m.name]));

      // Collect unique mix template IDs referenced by layerConfigs
      const mixTemplateIds = new Set<number>();
      for (const item of items) {
        const lc = (item as any).layerConfig as LayerConfig | null;
        if (lc?.mixTemplateId) mixTemplateIds.add(Number(lc.mixTemplateId));
      }

      // Fetch mix-template links for this project (fallback for bituminous items without a direct mixTemplateId)
      const mixLinks = await storage.getBoqMixLinks(projectId);
      const mixTypeToTemplateId = new Map<string, number>();
      for (const link of mixLinks) {
        if (link.mixTemplateId) {
          // Index both the raw key and its normalised form so lookups succeed
          // regardless of whether links were saved as "BC" or "Bituminous Concrete".
          const raw = link.mixType.toUpperCase();
          const normalised = normaliseMixType(link.mixType);
          mixTypeToTemplateId.set(raw, link.mixTemplateId);
          if (normalised !== raw) mixTypeToTemplateId.set(normalised, link.mixTemplateId);
        }
      }
      // Also add link template IDs to the fetch set
      for (const tmplId of mixTypeToTemplateId.values()) mixTemplateIds.add(tmplId);

      // Concrete: index RMC mix designs by grade (active only) for concrete material derivation.
      const gradeToDesign = new Map<string, typeof rmcDesigns[number]>();
      for (const d of rmcDesigns) {
        if ((d as any).isActive === 0) continue;
        // Normalise "M 25" / "M-25" → "M25" so detected grades match the RMC entry.
        const g = String(d.grade ?? "").toUpperCase().replace(/[\s-]/g, "");
        if (g && !gradeToDesign.has(g)) gradeToDesign.set(g, d);
      }

      // Pre-add ALL master template IDs so mixTemplateMap gets component data for every
      // template before we decide which one wins for each mix type.
      for (const t of allMixTemplates) mixTemplateIds.add(t.id);

      // (Cross-type "first bituminous template" fallback removed — Patch 40.
      //  Items with no matching mix type now fall back to the built-in IRC default
      //  for their exact type inside deriveMaterialsFromLayerConfig.)

      // Fetch mix template data and resolve component material names in parallel
      const mixTemplateMap = new Map<number, {
        bitumenPercent: number | null;
        ldoNorm: number | null;
        binderGrade: string | null;
        densityTPerCum: number | null;
        components: Array<{ materialName: string; percent: number | null }>;
      }>();
      await Promise.all([...mixTemplateIds].map(async (mtId) => {
        const mt = await storage.getMixTemplateWithComponents(mtId);
        if (mt) {
          mixTemplateMap.set(mtId, {
            bitumenPercent: mt.template.bitumenPercent ?? null,
            ldoNorm: mt.template.ldoNorm ?? 6,
            binderGrade: (mt.template as any).binderGrade ?? null,
            densityTPerCum: (mt.template as any).densityTPerCum ?? null,
            components: mt.components.map(c => ({
              materialName: matNameById.get(c.materialId) ?? `Material #${c.materialId}`,
              percent: c.percent ?? null,
            })),
          });
        }
      }));

      // Bituminous: index STANDARD mix templates in Masters/HMP as fallback when no project
      // link exists for a mix type. "Usable" templates (components with actual percent values)
      // always beat stubs (all-null percent). This prevents a stub DBM template from
      // blocking a fully-filled DBM template with the same mixType key.
      const tmplUsableScore = (tmplId: number) =>
        (mixTemplateMap.get(tmplId)?.components ?? []).filter(c => (c.percent ?? 0) > 0).length;

      for (const t of allMixTemplates) {
        const raw = String(t.mixType ?? "").toUpperCase();
        const normalised = normaliseMixType(t.mixType ?? "");
        for (const key of Array.from(new Set([raw, normalised].filter(Boolean)))) {
          const existing = mixTypeToTemplateId.get(key);
          if (!existing) {
            mixTypeToTemplateId.set(key, t.id);
          } else if (tmplUsableScore(t.id) > tmplUsableScore(existing)) {
            // Upgrade: new candidate has more filled-in component percentages
            mixTypeToTemplateId.set(key, t.id);
          }
        }
      }

      const barItemIds = new Set(bars.map(b => b.boqItemId));

      // For each item resolve the best possible material list using source priority:
      //   P1 — manual (non-auto) rows for non-layer items
      //   P2 — layerConfig derivation (bituminous JMF / granular / spray coat / concrete mix design)
      //   P3 — setup warning if major layer item has no usable template
      //   P4 — cleaned SDB rows for simple direct-material items
      const expandedItems = items.map(item => {
        const savedLc = (item as any).layerConfig as LayerConfig | null;
        // Trust a manually-saved layer config; otherwise synthesize from the work-type classifier.
        const lc: LayerConfig | null =
          savedLc && savedLc.layerType && savedLc.layerType !== "none"
            ? savedLc
            : synthLayerConfigFromWorkType(item);
        const manualMaterials = item.materials.filter((m: any) => !m.isAuto);
        const materialDriving = isMaterialDrivingLayerItem(item);
        const simpleDirect = isSimpleDirectMaterialItem(item);
        const concreteGrade = detectConcreteGrade((item as any).description ?? "");

        // P1: manual materials trusted only when not a major material-driving layer item
        if (manualMaterials.length > 0 && !materialDriving) {
          return { ...item, materials: manualMaterials, materialSetupWarning: null, isProgrammed: barItemIds.has(item.id) };
        }

        // P2: layerConfig derivation
        if (lc && lc.layerType && lc.layerType !== "none") {
          let resolvedMixTemplateId: number | null = lc.mixTemplateId ?? null;

          if (!resolvedMixTemplateId && lc.layerType === "bituminous" && lc.mixType) {
            resolvedMixTemplateId =
              mixTypeToTemplateId.get(lc.mixType.toUpperCase()) ??
              mixTypeToTemplateId.get(normaliseMixType(lc.mixType)) ??
              null;
          }
          if (!resolvedMixTemplateId && lc.layerType === "bituminous" && (item as any).workCategory) {
            const cat = (item as any).workCategory as string;
            resolvedMixTemplateId =
              mixTypeToTemplateId.get(cat.toUpperCase()) ??
              mixTypeToTemplateId.get(normaliseMixType(cat)) ??
              null;
          }
          // NOTE: no cross-type fallback here. If no template matches this item's exact
          // mix type (BC/DBM/SDBC/BM), we intentionally leave it unresolved so the engine
          // falls back to the built-in IRC default for THAT mix type — never borrowing a
          // different type's template (which caused BC to show DBM's grade/aggregates).
          // Concrete/RMC — prefer the user's RMC module mix design (by grade), then
          // fall back to the deterministic standard design so concrete demand never
          // silently blanks out. lc.mixType carries DLC/PQC when the description has
          // no explicit M-grade.
          const concreteKey = String(concreteGrade ?? (lc as any).mixType ?? "").toUpperCase().replace(/[\s-]/g, "");
          const concreteDesign =
            lc.layerType === "concrete" && concreteKey
              ? (gradeToDesign.get(concreteKey) ?? STANDARD_CONCRETE_DESIGNS[concreteKey] ?? null)
              : null;

          // Emulsion — derive the spraying rate from the BOQ description when the layer
          // config has no explicit coverage rate (emulsion demand = rate kg/sqm × area).
          let effLc = lc;
          if (lc.layerType === "spray_coat" && !(lc.coverageRateKgPerSqm && lc.coverageRateKgPerSqm > 0)) {
            const rm = String((item as any).description ?? "").match(/([0-9]+(?:\.[0-9]+)?)\s*kg\s*(?:per|\/)?\s*(?:sqm|sq\.?\s*m|m2|m²|square\s*met)/i);
            if (rm) effLc = { ...lc, coverageRateKgPerSqm: parseFloat(rm[1]) };
          }

          const mixTemplate = resolvedMixTemplateId ? mixTemplateMap.get(resolvedMixTemplateId) : null;

          // Grade from description wins over template grade.
          // "premixed with bituminous binder of VG-30" → always → "Bitumen VG-30"
          // regardless of which VG grade the mapped template happens to have saved.
          const descBinderGrade = (() => {
            const d = String((item as any).description ?? "");
            if (/vg\s*-?\s*40|vg40/i.test(d)) return "VG-40";
            if (/vg\s*-?\s*30|vg30/i.test(d)) return "VG-30";
            if (/vg\s*-?\s*10|vg10/i.test(d)) return "VG-10";
            return null;
          })();

          // Composite item detection — e.g. "40mm BC and 25mm mastic asphalt".
          // We derive materials for each sub-layer using its own template, then combine.
          const compositeLayers =
            effLc?.layerType === "bituminous"
              ? parseCompositeLayers(String((item as any).description ?? ""), item.unit)
              : null;

          let derived: ReturnType<typeof deriveMaterialsFromLayerConfig>;
          if (compositeLayers && compositeLayers.length > 0) {
            // Normalise raw SDB/template aggregate names to IRC standard names before
            // combining sub-layer rows, so "10/12MM" from a BC template merges with
            // "10mm Aggregate" produced by the MA IRC default (and vice versa for 6mm/dust).
            const normaliseCompKey = (name: string): string => {
              const n = name.trim();
              if (/^20\s*mm$/i.test(n)) return "20mm Aggregate";
              if (/^10\/12\s*mm$|^10\s*mm\s*chips?$|^12\.?5\s*mm$/i.test(n)) return "10mm Aggregate";
              if (/^6\s*mm\s*(down|agg|chips?)?$|^6\.?3\s*mm$/i.test(n)) return "6mm Aggregate";
              if (/^dust$|^stone\s*dust$|^crusher\s*dust$|^aggregate\s*dust$/i.test(n)) return "Stone Dust";
              return n;
            };
            const combinedMap = new Map<string, { materialName: string; uom: string; qtyPerBoqUnit: number; isAuto: boolean; applicationNote?: string }>();
            for (const cl of compositeLayers) {
              const subTmplId =
                mixTypeToTemplateId.get(cl.mixType) ??
                mixTypeToTemplateId.get(normaliseMixType(cl.mixType)) ??
                null;
              const subTmpl = subTmplId ? mixTemplateMap.get(subTmplId) : null;
              const subLc: LayerConfig = {
                layerType: "bituminous",
                mixType: cl.mixType,
                thicknessMm: cl.thicknessMm,
                densityTPerCum: cl.density,
              };
              // For composite sub-layers, don't force the item-level description grade onto
              // sub-layers whose templates already specify their own binder grade (e.g. MA
              // uses VG-40 per template while BC uses VG-30 per template). Only fall back to
              // descBinderGrade when the sub-layer's template has no grade of its own.
              const subDescBinderGrade = subTmpl?.binderGrade?.trim()
                ? null
                : descBinderGrade;
              const subDerived = deriveMaterialsFromLayerConfig(
                subLc, item.unit, subTmpl ?? undefined, null, { descBinderGrade: subDescBinderGrade },
              );
              for (const dr of subDerived) {
                // Use normalised key so template names ("10/12MM", "DUST") collapse with
                // IRC generic names ("10mm Aggregate", "Stone Dust") from other sub-layers.
                const normName = normaliseCompKey(dr.materialName);
                const ex = combinedMap.get(normName);
                if (ex) { ex.qtyPerBoqUnit += dr.qtyPerBoqUnit; }
                else combinedMap.set(normName, { ...dr, materialName: normName });
              }
            }
            derived = [...combinedMap.values()] as ReturnType<typeof deriveMaterialsFromLayerConfig>;
            // Build composite label e.g. "BC+MA" from sub-layer mix types (sorted to keep canonical order)
            (item as any).__compositeLabel = compositeLayers.map(cl => cl.mixType).join("+");
          } else {
            derived = deriveMaterialsFromLayerConfig(
              effLc,
              (item as any).canonicalUnit ?? item.unit,
              mixTemplate ?? undefined,
              concreteDesign
                ? {
                    grade: concreteDesign.grade,
                    cementContent: concreteDesign.cementContent,
                    admixtureName: concreteDesign.admixtureName,
                    admixtureDosage: concreteDesign.admixtureDosage,
                    componentProportions: concreteDesign.componentProportions as any,
                  }
                : null,
              { descBinderGrade },
            );
          }

          // --- BITUMEN BOM DIAGNOSTIC (Patch 34) ---
          if (effLc?.layerType === "bituminous") {
            console.log("[BITUMEN BOM]", JSON.stringify({
              item: `${item.itemCode ?? ""} ${item.description?.slice(0, 40)}`,
              unit: item.unit,
              composite: compositeLayers ? compositeLayers.map(c => `${c.thicknessMm}mm ${c.mixType}`) : null,
              descBinderGrade,
              resolvedTemplate: mixTemplate
                ? {
                    binderGrade: (mixTemplate as any).binderGrade ?? null,
                    bitumenPercent: (mixTemplate as any).bitumenPercent ?? null,
                    componentCount: (mixTemplate as any).components?.length ?? 0,
                  }
                : "NO TEMPLATE RESOLVED",
              derivedRows: derived.map((d: any) => ({ name: d.materialName, qtyPerBoqUnit: d.qtyPerBoqUnit })),
            }, null, 2));
          }
          // --- END DIAGNOSTIC ---

          const derivedSupplyType: "direct" | "plant" | undefined =
            lc.layerType === "granular" && lc.granularSource !== "plant" ? "direct"
            : lc.layerType === "granular" && lc.granularSource === "plant" ? "plant"
            : lc.layerType === "bituminous" ? "plant"
            : lc.layerType === "spray_coat" ? "direct"
            : lc.layerType === "concrete" ? "plant"
            : undefined;

          if (derived.length > 0) {
            const derivedRows = derived.map(dm => ({
              materialName: dm.materialName,
              uom: dm.uom,
              qtyPerBoqUnit: dm.qtyPerBoqUnit,
              wastagePct: 0,
              isClientSupplied: false,
              isAuto: true as const,
              supplyType: derivedSupplyType,
              // Cut-to-fill: earthwork layer-config rows route to the arrangement flow
              isEarthworkBulkRequirement: dm.isEarthworkBulkRequirement ?? false,
            }));

            // HMP hours correction for CUM/SQM bituminous items.
            // The HMP outputs in MT, so when the BOQ unit is SQM or CUM the saved
            // qtyPerBoqUnit falls back to a flat norm (0.00833 hrs/unit) that ignores
            // density and thickness. Correct it here: total MT of mix per BOQ unit
            // (sum of all auto MT material rows) ÷ HMP outputPerHr.
            let correctedEquipment = item.equipment as typeof item.equipment;
            if (lc?.layerType === "bituminous") {
              const boqUnitNorm = (item.unit ?? "").toUpperCase().replace(/[^A-Z0-9]/g, "");
              const isAlreadyMtUnit = boqUnitNorm === "MT" || boqUnitNorm === "T";
              if (!isAlreadyMtUnit) {
                const totalMtPerBoqUnit = derived.reduce(
                  (sum: number, d: any) => (d.uom === "MT" ? sum + d.qtyPerBoqUnit : sum), 0,
                );
                if (totalMtPerBoqUnit > 0) {
                  correctedEquipment = (item.equipment as any[]).map((eq: any) => {
                    if (!/hot[\s-]?mix[\s-]?plant|hmp\b/i.test(eq.equipmentName ?? "")) return eq;
                    try {
                      const outs = typeof eq.standardOutputs === "string"
                        ? JSON.parse(eq.standardOutputs)
                        : eq.standardOutputs;
                      const mtOut = Array.isArray(outs)
                        ? outs.find((o: any) => String(o.unit ?? "").toUpperCase() === "MT")
                        : null;
                      if (mtOut?.outputPerHr > 0) {
                        const corrected = totalMtPerBoqUnit / mtOut.outputPerHr;
                        console.log(
                          `[HMP HRS FIX] ${item.itemCode} unit=${item.unit} totalMtPerBoqUnit=${totalMtPerBoqUnit.toFixed(4)} ` +
                          `outputPerHr=${mtOut.outputPerHr} old=${eq.qtyPerBoqUnit?.toFixed(5)} new=${corrected.toFixed(5)}`,
                        );
                        return { ...eq, qtyPerBoqUnit: corrected };
                      }
                    } catch { /* keep original if parse fails */ }
                    return eq;
                  });
                }
              }
            }

            return {
              ...item,
              equipment: correctedEquipment,
              materials: derivedRows.map(dm => ({
                id: 0,
                boqItemId: item.id,
                ...dm,
                sortOrder: 0,
                createdAt: null,
              })),
              derivedKeyMaterials: derivedRows,
              materialSetupWarning: null,
              isProgrammed: barItemIds.has(item.id),
              compositeLabel: (item as any).__compositeLabel ?? undefined,
            };
          }

          // P3: layer exists but no usable template — emit warning, no raw SDB fractions
          if (materialDriving) {
            return {
              ...item,
              materials: [],
              materialSetupWarning:
                lc.layerType === "bituminous"
                  ? "Mix template/JMF required for bituminous material demand"
                  : lc.layerType === "concrete"
                  ? `Concrete/RMC mix design required${concreteGrade ? ` for ${concreteGrade}` : ""}`
                  : "Material setup required for this layer item",
              isProgrammed: barItemIds.has(item.id),
            };
          }
        }

        // P3 (no layerConfig): major layer item identified by description/category.
        // Only quantity-driven layer/pour items warrant a warning — count/lump-sum
        // structures (toll booths = Nos, buildings = LS/Each) are not RMC-driven.
        const p3UNorm = String(item.unit ?? "").toUpperCase().replace(/[^A-Z0-9]/g, "");
        const p3IsVolUnit  = /^(CUM|CUB|M3|CU)$/.test(p3UNorm);
        const p3IsAreaUnit = /^(SQM|SM|M2|MT|TON|T)$/.test(p3UNorm);
        if (materialDriving && !simpleDirect && (p3IsVolUnit || p3IsAreaUnit)) {
          return {
            ...item,
            materials: [],
            materialSetupWarning: isConcreteLayerOrItem(item)
              ? `Concrete/RMC mix design required${concreteGrade ? ` for ${concreteGrade}` : ""}`
              : isBituminousLayerOrItem(item)
              ? "Mix template/JMF required for bituminous material demand"
              : "Layer/mix setup required for material demand",
            isProgrammed: barItemIds.has(item.id),
          };
        }

        // P4: simple direct-material or non-layer items — strip raw SDB gradation rows
        const cleanedRows = item.materials.filter((m: any) => {
          if (!m.materialName) return false;
          if (isRawSdbAggregateName(m.materialName) && !simpleDirect) return false;
          return true;
        });
        return { ...item, materials: cleanedRows, materialSetupWarning: null, isProgrammed: barItemIds.has(item.id) };
      });

      return { items, bars, project, expandedItems, excludedCount: allBoqItems.length - items.length };
  }

  // BOM demand for the whole project
  app.get("/api/boq/projects/:id/bom", async (req, res) => {
    try {
      if (!assertView(req, res, "work_programme_review")) return;
      const projectId = parseInt(req.params.id);
      const [{ items, bars, project, expandedItems, excludedCount }, projectArrangementsRaw, projectBarAllocations] = await Promise.all([
        computeProjectBom(projectId),
        storage.getEarthworkArrangements(projectId), // Instruction 025: client demand calc needs these
        storage.getArrangementProgrammeAllocationsForProject(projectId), // Instruction 026: bar-level phasing
      ]);
      // Instruction 026 §9: attach bar allocations so client + engine can phase per bar.
      const allocsByArrangement = new Map<number, Array<{ programmeBarId: number; boqItemId: number; qty: number }>>();
      for (const al of projectBarAllocations) {
        if (!allocsByArrangement.has(al.arrangementId)) allocsByArrangement.set(al.arrangementId, []);
        allocsByArrangement.get(al.arrangementId)!.push({ programmeBarId: al.programmeBarId, boqItemId: al.boqItemId, qty: Number(al.allocatedQty) || 0 });
      }
      const projectArrangements = projectArrangementsRaw.map(a => ({ ...a, programmeAllocations: allocsByArrangement.get(a.id) ?? [] }));
      const barItemIds = new Set(bars.map(b => b.boqItemId));
      const hasRecipes = expandedItems.some(it => it.materials.length > 0 || it.equipment.length > 0 || it.labour.length > 0);
      console.log(`[BOM] project=${projectId} items=${items.length} bars=${bars.length} hasRecipes=${hasRecipes} excluded=${excludedCount}`);
      res.json({
        items: expandedItems,
        bars,
        earthworkArrangements: projectArrangements,
        roadLengthKm: project?.roadLengthKm ?? 0,
        unprogrammedItemIds: items.filter(it => !barItemIds.has(it.id)).map(it => it.id),
        hasBars: bars.length > 0,
        hasItems: items.length > 0,
        hasRecipes,
        _excludedCount: excludedCount,
      });
    } catch (err) {
      console.error("GET /api/boq/projects/:id/bom:", err);
      res.status(500).json({ error: "Failed to fetch BOM data" });
    }
  });

  // Material shortage intelligence — compares WP demand vs current stock.
  // Task #1240: extended to be time-phased (month-by-month, not just a single
  // total-qty comparison) and to net out material already covered by pending
  // PI/IRN procurement, without altering the existing PI/IRN schemas/workflow.
  app.get("/api/boq/projects/:id/shortage-check", async (req, res) => {
    try {
      if (!assertView(req, res, "work_programme_review")) return;
      const projectId = parseInt(req.params.id);
      const project = await storage.getBoqProject(projectId);
      if (!project) return res.status(404).json({ error: "Project not found" });

      // ── Horizon: server-authoritative — client sends mode + optional customDate ─
      const horizonModeParam = (req.query.horizonMode as string | undefined) ?? "current_month";
      const customDateParam = req.query.customDate as string | undefined;

      const [{ expandedItems, bars }, allStockBalances, allMaterialsRaw, allIndents, allIrns, materialMappings, allEarthworkArrangementsRaw, allBarAllocations] = await Promise.all([
        computeProjectBom(projectId),
        storage.getStockBalances(),
        storage.getAllPlantMaterials(),          // active + inactive — partitioned below
        storage.getPurchaseIndents(),
        storage.getInternalRequisitions(),
        storage.getMaterialMappings(projectId),
        storage.getEarthworkArrangements(projectId), // Instruction 023
        storage.getArrangementProgrammeAllocationsForProject(projectId), // Instruction 026
      ]);
      // Instruction 026 §9: attach programme-bar allocations for bar-level phasing.
      const allocsByArrId = new Map<number, Array<{ programmeBarId: number; boqItemId: number; qty: number }>>();
      for (const al of allBarAllocations) {
        if (!allocsByArrId.has(al.arrangementId)) allocsByArrId.set(al.arrangementId, []);
        allocsByArrId.get(al.arrangementId)!.push({ programmeBarId: al.programmeBarId, boqItemId: al.boqItemId, qty: Number(al.allocatedQty) || 0 });
      }
      const allEarthworkArrangements = allEarthworkArrangementsRaw.map(a => ({ ...a, programmeAllocations: allocsByArrId.get(a.id) ?? [] }));
      // Cut-to-fill by contract: BOQ item id → description lookup for detecting
      // rows whose earthwork is contractually sourced from roadway excavation.
      const boqItemDescById = new Map<number, string>();
      // PROCUREMENT CORRECTION Part D: id → operational SHORT NAME for the
      // "BOQ Work Item(s)" column. Priority: saved itemName → shared
      // short-name fallback → (client falls back to description last).
      const boqItemShortNameById = new Map<number, string>();
      for (const it of expandedItems as Array<{ id: number; description?: string | null; itemName?: string | null; itemCode?: string | null }>) {
        boqItemDescById.set(it.id, String(it.description ?? ""));
        const short = (it.itemName && String(it.itemName).trim()) || sharedShortItemName(it.description ?? "");
        boqItemShortNameById.set(it.id, short || String(it.description ?? ""));
      }
      // Cut-to-fill: batch-load current qty of any linked excavation BOQ items so
      // arrangement summaries can report cut-available vs fill-required.
      const excavationSourceIds = [...new Set(
        allEarthworkArrangements
          .map(a => (a as any).sourceExcavationBoqItemId as number | null)
          .filter((id): id is number => id != null)
      )];
      const cutQtyByBoqItemId = new Map<number, number>();
      if (excavationSourceIds.length > 0) {
        const cutRows = await db.select({ id: boqItems.id, currentQty: boqItems.currentQty })
          .from(boqItems).where(drizzleInArray(boqItems.id, excavationSourceIds));
        for (const r of cutRows) cutQtyByBoqItemId.set(r.id, Number(r.currentQty ?? 0));
      }

      // Partition: active only for resolution maps and stock lookup; inactive for diagnostics
      const allMaterials = allMaterialsRaw.filter(m => m.isActive === 1);
      const inactiveMaterials = allMaterialsRaw.filter(m => m.isActive !== 1);

      // Instruction 021: preload all active UOM conversion profiles, grouped by materialId
      const allConvProfiles = await storage.getAllMaterialUomConversions();
      const convProfilesByMaterialId = new Map<number, typeof allConvProfiles>();
      for (const p of allConvProfiles) {
        const arr = convProfilesByMaterialId.get(p.materialId) ?? [];
        arr.push(p);
        convProfilesByMaterialId.set(p.materialId, arr);
      }

      // ── materialId → HLC stock (partyId IS NULL) and elsewhere stock ────────
      // v2: keyed by materialId, NOT by name string.
      const hlcStockById = new Map<number, number>();      // partyId IS NULL
      const elsewhereStockById = new Map<number, number>(); // partyId IS NOT NULL
      for (const sb of allStockBalances) {
        if (!sb.materialId) continue;
        // Instruction 020 §7: parse as Number — numeric columns may arrive as strings via pg driver
        const bal = Number(sb.balance ?? 0);
        if (sb.partyId == null) {
          hlcStockById.set(sb.materialId, (hlcStockById.get(sb.materialId) ?? 0) + bal);
        } else {
          elsewhereStockById.set(sb.materialId, (elsewhereStockById.get(sb.materialId) ?? 0) + bal);
        }
      }

      // ── Confirmed incoming purchase — only ORDERED / PURCHASED items ─────────
      // Rule: orderedQty > 0 (set by placeOrderIndent) OR purchaseStatus ∈ {ORDERED, PURCHASED}
      // AND outstanding unreceived balance > 0. Keyed by item.materialId.
      const COMMITTED_PI_STATUSES = new Set(["ordered", "purchased"]); // lowercase
      const confirmedPiById = new Map<number, number>();
      for (const pi of allIndents) {
        if (pi.status === "rejected" || pi.status === "closed" || pi.status === "cancelled") continue;
        for (const item of pi.items ?? []) {
          const mid = (item as any).materialId as number | undefined | null;
          if (!mid) continue;
          const statusLc = (item.purchaseStatus ?? "").toLowerCase();
          // Instruction 020 §7: parse all quantities as Number — DB numeric columns may arrive as strings
          const ordQty = (item as any).orderedQty != null ? Number((item as any).orderedQty) : null;
          const isCommitted = COMMITTED_PI_STATUSES.has(statusLc) || (ordQty != null && ordQty > 0);
          if (!isCommitted) continue;
          const purchased = Number((item as any).totalPurchasedQty ?? 0);
          const committed = (ordQty ?? Number(item.approvedQty ?? item.qty ?? 0)) - purchased;
          if (committed <= 0) continue;
          confirmedPiById.set(mid, (confirmedPiById.get(mid) ?? 0) + committed);
        }
      }

      // ── Material master lookups ──────────────────────────────────────────────
      const materialIdByName = new Map<string, number>();
      for (const mat of allMaterials) {
        materialIdByName.set(mat.name.trim().toLowerCase(), mat.id);
      }

      // ── Instruction 019B §3: collision-aware alias/name resolution maps ─────────
      // Map.set() silently overwrites — we detect collisions instead.
      // resolvedAliasToId: normalized key → materialId  (exactly 1 candidate)
      // ambiguousByKey:    normalized key → candidates  (2+ candidates, cannot auto-resolve)
      type MatCandidate = { id: number; name: string; category: string | null; defaultUom: string | null };
      const keyToCandidates = new Map<string, MatCandidate[]>();
      for (const mat of allMaterials) {
        const aliasesRaw: string[] = (() => {
          try { return JSON.parse(mat.aliases ?? "[]"); } catch { return []; }
        })();
        const keys = new Set<string>([
          normalizeMaterialLabel(mat.name),
          ...aliasesRaw.map(a => normalizeMaterialLabel(a)).filter(Boolean),
        ]);
        for (const key of keys) {
          if (!key) continue;
          if (!keyToCandidates.has(key)) keyToCandidates.set(key, []);
          const cands = keyToCandidates.get(key)!;
          if (!cands.some(c => c.id === mat.id)) {
            cands.push({ id: mat.id, name: mat.name, category: mat.category ?? null, defaultUom: mat.defaultUom ?? null });
          }
        }
      }
      const resolvedAliasToId = new Map<string, number>();
      const ambiguousByKey = new Map<string, MatCandidate[]>();
      for (const [key, candidates] of keyToCandidates) {
        if (candidates.length === 1) resolvedAliasToId.set(key, candidates[0].id);
        else                          ambiguousByKey.set(key, candidates);
      }

      // ── Inactive material diagnostic map (Instruction 020 §1) ────────────────
      // Distinguishes "inactive_material" from "no_match" when auto-resolution fails.
      const inactiveKeyToName = new Map<string, string>();
      for (const mat of inactiveMaterials) {
        const normKey = normalizeMaterialLabel(mat.name);
        if (normKey) inactiveKeyToName.set(normKey, mat.name);
        const aliasesRaw: string[] = (() => { try { return JSON.parse(mat.aliases ?? "[]"); } catch { return []; } })();
        for (const alias of aliasesRaw) {
          const aKey = normalizeMaterialLabel(alias);
          if (aKey && !inactiveKeyToName.has(aKey)) inactiveKeyToName.set(aKey, mat.name);
        }
      }

      // ── Confirmed internal incoming — stores_verified IRN items with balance ─
      // Primary key: item.materialId (canonical FK). Name fallback ONLY when materialId is null.
      const confirmedIrnById = new Map<number, number>();
      for (const irn of allIrns) {
        if (irn.status !== "stores_verified") continue;
        for (const item of irn.items ?? []) {
          if (item.itemStatus !== "partially_issued" && item.itemStatus !== "pending") continue;
          const balance = (item.procureQty ?? item.qty) - (item.actualIssuedQty ?? 0);
          if (balance <= 0) continue;
          const directMid = (item as any).materialId as number | null | undefined;
          if (directMid) {
            // Canonical path: materialId present on item — use directly
            confirmedIrnById.set(directMid, (confirmedIrnById.get(directMid) ?? 0) + balance);
          } else {
            // Fallback: resolve by name (for legacy IRN items without materialId)
            const key = item.material?.trim().toLowerCase() ?? "";
            if (key) {
              const mid = materialIdByName.get(key);
              if (mid) confirmedIrnById.set(mid, (confirmedIrnById.get(mid) ?? 0) + balance);
            }
          }
        }
      }

      // ── Mapping table: BOM label → materialId + full mapping for conversion lookup ─
      // Project-specific mapping wins over global (null boqProjectId) mapping.
      const labelToMaterialId = new Map<string, number>();
      const labelToMapping = new Map<string, typeof materialMappings[0]>();
      // Load globals first (lower priority)
      for (const m of materialMappings) {
        if (m.boqProjectId == null) {
          labelToMaterialId.set(m.materialLabel, m.materialId);
          labelToMapping.set(m.materialLabel, m);
        }
      }
      // Project-specific overrides (higher priority — overwrite globals)
      for (const m of materialMappings) {
        if (m.boqProjectId != null) {
          labelToMaterialId.set(m.materialLabel, m.materialId);
          labelToMapping.set(m.materialLabel, m);
        }
      }

      // ── (a) Demand calculation ────────────────────────────────────────────────
      const demand = expandedItems.length && bars.length
        // Instruction 025: active execution arrangements reduce HLC demand
        ? calculateBomDemand(expandedItems as any, bars, project.totalMonths ?? 12, { arrangements: allEarthworkArrangements as any })
        : { materials: [], equipment: [], labour: [] };

      // ── (b) Collect all programme-month indexes ───────────────────────────────
      const allProgrammeMonths = demand.materials.flatMap(r => Object.keys(r.monthlyQty).map(Number));

      // ── (c) maxProgrammeMonth — must be declared before currentMonth ──────────
      // Fallback to project.totalMonths to avoid the circular dependency that
      // would occur if we used currentMonth as fallback (it isn't declared yet).
      const maxProgrammeMonth = allProgrammeMonths.length
        ? Math.max(...allProgrammeMonths)
        : (project.totalMonths ?? 12);

      // ── (d-e) Current project month ───────────────────────────────────────────
      // Returns 0 before programme start, contained bucket during, maxProgrammeMonth after.
      // No Math.max(1, ...) — before-start must yield 0 (Instruction 019A §2).
      const pStartDate = project.startDate ?? null;
      let currentMonth = 0;
      if (pStartDate) {
        const rawCurrent = dateToMonthIndex(new Date(), pStartDate);
        currentMonth = dateToMonthBucket(rawCurrent, maxProgrammeMonth);
      }

      // Helper: format a Date as YYYY-MM-DD ISO date string
      const toISODate = (d: Date): string => d.toISOString().split("T")[0];
      // Helper: end of programme month N = start of month N+1 minus 1 day
      const endOfProgMonth = (idx: number): string | null => {
        if (!pStartDate) return null;
        const startOfNext = monthIndexToDate(idx + 1, pStartDate);
        return toISODate(new Date(startOfNext.getTime() - 86_400_000));
      };

      type ResolvedHorizon = { horizonMonthIndex: number; resolvedHorizonDate: string | null };
      const resolveHorizon = (): ResolvedHorizon => {
        const mode = horizonModeParam as string;
        if (!pStartDate) {
          // No start date — always entire programme
          return { horizonMonthIndex: maxProgrammeMonth, resolvedHorizonDate: null };
        }
        switch (mode) {
          case "current_month": {
            const idx = Math.min(currentMonth, maxProgrammeMonth);
            return { horizonMonthIndex: idx, resolvedHorizonDate: endOfProgMonth(idx) };
          }
          case "next_30_days": {
            const cutoff = new Date(Date.now() + 30 * 24 * 60 * 60 * 1000);
            const rawIdx = dateToMonthIndex(cutoff, pStartDate);
            const idx = dateToMonthBucket(rawIdx, maxProgrammeMonth);
            return { horizonMonthIndex: idx, resolvedHorizonDate: toISODate(cutoff) };
          }
          case "next_programme_month": {
            const idx = Math.min(currentMonth + 1, maxProgrammeMonth);
            return { horizonMonthIndex: idx, resolvedHorizonDate: endOfProgMonth(idx) };
          }
          case "custom": {
            if (customDateParam) {
              const cutoff = new Date(customDateParam);
              const rawIdx = dateToMonthIndex(cutoff, pStartDate);
              const idx = dateToMonthBucket(rawIdx, maxProgrammeMonth);
              return { horizonMonthIndex: idx, resolvedHorizonDate: customDateParam };
            }
            // No custom date provided — fall through to entire_programme
            return { horizonMonthIndex: maxProgrammeMonth, resolvedHorizonDate: null };
          }
          case "entire_programme":
          default:
            return { horizonMonthIndex: maxProgrammeMonth, resolvedHorizonDate: null };
        }
      };

      const { horizonMonthIndex, resolvedHorizonDate } = resolveHorizon();

      // ── Build shortage rows (019B §4 + §7) ───────────────────────────────────
      const shortageRows = demand.materials.map(matRow => {
        // Resolve canonical materialId — strict precedence (019B §4):
        // 1. Saved BOQ-material mapping (project-specific > global)
        // 2. Exact approved alias or exact normalized canonical name (collision-aware)
        // No substring / loose auto-resolution.
        const labelKey = matRow.materialName.trim().toLowerCase();
        const normLabel = normalizeMaterialLabel(matRow.materialName);

        const savedMapping = labelToMapping.get(matRow.materialName) ?? labelToMapping.get(labelKey);
        const mappedId: number | null = savedMapping?.materialId ?? null;

        // Auto-resolve by exact alias or normalized name (only when no saved mapping)
        const rawAliasOrNameMatchId: number | null = mappedId == null
          ? (resolvedAliasToId.get(normLabel) ?? materialIdByName.get(labelKey) ?? null)
          : null;

        // ── Instruction 021 §1: UOM compatibility check for auto-resolved material ─
        // Material identity is preserved even when UOM conversion is not yet configured.
        // uomIncompatible = true only sets resolutionReason → "uom_incompatible" →
        // procurementStatus → "uom_resolution_required"; it no longer suppresses materialId.
        let aliasOrNameMatchId: number | null = rawAliasOrNameMatchId;
        let uomIncompatible = false;
        let autoConvFactor: number = 1;
        let autoConvMode: string | null = null;
        let autoConvBasis: string | null = null;
        let autoConvProfileId: number | null = null;
        let resolutionDiagnostic: { inactiveMaterialName?: string; bomUom?: string; masterUom?: string | null; materialName?: string; message?: string; action?: string } = {};

        if (rawAliasOrNameMatchId != null && matRow.uom) {
          const candidateMat = allMaterials.find(m => m.id === rawAliasOrNameMatchId);
          if (candidateMat) {
            const matProfiles = convProfilesByMaterialId.get(rawAliasOrNameMatchId) ?? [];
            const uomCheck = checkMappingUomCompatibility(matRow.uom, candidateMat, matProfiles);
            if (!uomCheck.compatible) {
              uomIncompatible = true;
              // 021: Do NOT suppress aliasOrNameMatchId — material identity still resolves.
              // The "uom_resolution_required" procurementStatus will block stock comparison.
              resolutionDiagnostic = {
                bomUom: matRow.uom,
                masterUom: candidateMat.defaultUom ?? null,
                materialName: candidateMat.name,
              };
            } else {
              autoConvFactor = uomCheck.conversionFactor ?? 1;
              autoConvMode = uomCheck.mode;
              autoConvBasis = uomCheck.basis;
              autoConvProfileId = uomCheck.conversionProfileId ?? null;
            }
          }
        }

        // Ambiguity — only when no saved mapping, no alias/name match, and not UOM-blocked
        const ambiguousCandidates: MatCandidate[] | null =
          (mappedId == null && aliasOrNameMatchId == null && !uomIncompatible)
            ? (ambiguousByKey.get(normLabel) ?? null)
            : null;
        const materialMappingAmbiguous = ambiguousCandidates != null && ambiguousCandidates.length > 0;

        const resolvedId: number | null = mappedId ?? aliasOrNameMatchId ?? null;
        // Unresolved: no saved mapping, alias/name blocked (UOM or not found), or ambiguous
        const materialMappingUnresolved = resolvedId == null;

        // ── Resolution reason (Instruction 020 §1) ──────────────────────────────
        let resolutionReason: ResolutionReason;
        if (mappedId != null) {
          resolutionReason = "saved_mapping";
        } else if (uomIncompatible) {
          resolutionReason = "uom_incompatible";
        } else if (aliasOrNameMatchId != null) {
          resolutionReason = "alias_resolved";
        } else if (materialMappingAmbiguous) {
          resolutionReason = "ambiguous";
        } else {
          // Distinguish inactive_material from no_match for targeted UI guidance
          const inactiveName = inactiveKeyToName.get(normLabel) ?? inactiveKeyToName.get(labelKey) ?? null;
          if (inactiveName) {
            resolutionReason = "inactive_material";
            resolutionDiagnostic = { inactiveMaterialName: inactiveName };
          } else {
            resolutionReason = "no_match";
            resolutionDiagnostic = { message: "No canonical material match was found.", action: "Review Material Master" };
          }
        }

        // ── 021 §12-13: Conversion factor and planning-UOM normalization ──────
        // Precedence: (1) saved mapping factor, (2) auto-resolved profile/bulk-density factor.
        // Factor meaning: 1 BOQ unit × convFactor = 1 stock unit  (e.g. 1 Cum × 2.20 = 2.20 MT).
        // Approach: keep demand in planning/BOQ UOM; convert stock DOWN to planning UOM (÷ factor).
        // This shows shortfall in the user's BOQ unit; add procurementEquivalentQty for stock UOM.
        const convFactor: number = savedMapping?.conversionFactorUsed ?? autoConvFactor;
        const convMode: string | null = savedMapping?.conversionMode ?? autoConvMode;
        const convSourceUom: string | null = savedMapping?.sourceUom ?? (convFactor !== 1 ? matRow.uom : null);
        const convProfileId: number | null = (savedMapping as any)?.conversionProfileId ?? autoConvProfileId;
        const resolvedMat = resolvedId != null ? allMaterials.find(m => m.id === resolvedId) : null;
        const canonicalUom: string | null = resolvedMat?.defaultUom ?? null;
        let conversionBasis: string | null = autoConvBasis ?? null;
        if (convFactor !== 1 && convSourceUom && canonicalUom && !conversionBasis) {
          conversionBasis = convMode === "bulk_density"
            ? `Bulk density: 1 ${convSourceUom} = ${convFactor} ${canonicalUom}`
            : `1 ${convSourceUom} = ${convFactor} ${canonicalUom}`;
        }

        // Demand stays in BOQ/planning UOM (no scaling).
        const scaledMatRow = matRow;

        // Stock is stored in canonical/stock UOM; divide by convFactor to get planning UOM coverage.
        // When uomIncompatible and no conversion found (uomBlocked), zero out stock so we don't
        // compare incompatible units (the UOM-resolution-required status will be shown instead).
        const uomBlocked = uomIncompatible && convFactor === 1;
        const invFactor = convFactor !== 1 ? 1 / convFactor : 1;
        const hlcRecordedStock = resolvedId != null && !uomBlocked
          ? Math.round((hlcStockById.get(resolvedId) ?? 0) * invFactor * 1000) / 1000
          : 0;
        const stockWithOtherParties = resolvedId != null && !uomBlocked
          ? Math.round((elsewhereStockById.get(resolvedId) ?? 0) * invFactor * 1000) / 1000
          : 0;
        const confirmedIncomingPurchase = resolvedId != null && !uomBlocked
          ? Math.round((confirmedPiById.get(resolvedId) ?? 0) * invFactor * 1000) / 1000
          : 0;
        const confirmedInternalIncoming = resolvedId != null && !uomBlocked
          ? Math.round((confirmedIrnById.get(resolvedId) ?? 0) * invFactor * 1000) / 1000
          : 0;
        const stockMatched = resolvedId != null && (hlcRecordedStock > 0 || stockWithOtherParties > 0);

        // sourceBoqItemId: non-null only when all breakdown entries trace to a single BOQ item
        const distinctBoqItemIds: number[] = [...new Set<number>(
          ((matRow as any).breakdown as Array<{ boqItemId?: number | null }> ?? [])
            .map(bd => bd.boqItemId)
            .filter((id): id is number => id != null)
        )];
        const sourceBoqItemId = distinctBoqItemIds.length === 1 ? distinctBoqItemIds[0] : null;
        const matProgrammingStatus = (matRow as any).programmingStatus as
          | "fully_programmed" | "partly_programmed" | "not_programmed" | undefined;
        const hasProgrammeBars = matProgrammingStatus !== "not_programmed";

        // Instruction 023: earthwork bulk detection from BOM row flag
        const isEarthworkBulkRequirement = !!(matRow as any).isEarthworkBulkRequirement;
        // Instruction 028A: category-generic arrangement marker stamped by the engine
        // (bituminous rows whose source items carry EFFECTIVE bituminous arrangements),
        // OR any non-cancelled bituminous arrangement on a source item — proposed
        // (draft/submitted/returned) arrangements must surface context in Procurement
        // even though they have no demand effect yet.
        const isBituminousArrangedRow = (matRow as any).arrangementWorkCategory === "bituminous"
          || (!(matRow as any).isEarthworkBulkRequirement && allEarthworkArrangements.some(a => {
            if (a.status === "cancelled" || a.status === "rejected") return false;
            if ((a as any).workCategory !== "bituminous") return false;
            if (a.boqItemId != null && distinctBoqItemIds.includes(a.boqItemId)) return true;
            const allocs = a.boqItemAllocations as Array<{ boqItemId: number }> | null;
            return Array.isArray(allocs) && allocs.some(al => distinctBoqItemIds.includes(al.boqItemId));
          }));
        const hasArrangementContext = isEarthworkBulkRequirement || isBituminousArrangedRow;
        // 028A §3/§7: company-retained fraction from engine's split — forwarded, never recalculated.
        const rowArrHlcQty = (matRow as any).arrangementHlcQty as number | undefined;
        const arrangementCompanyFraction = isBituminousArrangedRow && rowArrHlcQty != null && matRow.totalQty > 0
          ? Math.max(0, Math.min(1, rowArrHlcQty / matRow.totalQty))
          : undefined;

        // Cut-to-fill by contract: any source BOQ item whose description ties the
        // earthwork to roadway excavation (never borrow) → UI pre-selects the cut source.
        const contractCutToFill = isEarthworkBulkRequirement && distinctBoqItemIds.some(id =>
          isContractCutToFillDescription(boqItemDescById.get(id)),
        );

        const enrichedMatRow = { ...scaledMatRow, materialId: resolvedId, sourceBoqItemId };
        const shortageRow = computeShortageRow(
          enrichedMatRow,
          hlcRecordedStock,
          stockMatched,
          confirmedIncomingPurchase,
          currentMonth,
          stockWithOtherParties,
          {
            horizonMonthIndex,
            projectStartDate: project.startDate ?? null,
            hlcRecordedStock,
            stockWithOtherParties,
            confirmedIncomingPurchase,
            confirmedInternalIncoming,
            isProgrammed: hasProgrammeBars,
            materialMappingUnresolved,
            programmingStatus: matProgrammingStatus,
            programmedTotalDemand: (scaledMatRow as any).programmedTotalDemand as number | undefined,
            unprogrammedDemand: (scaledMatRow as any).unprogrammedDemand as number | undefined,
            sourceBoqItemIds: distinctBoqItemIds,
            resolutionReason,  // Instruction 020 §3: drives procurementStatus in planningEngine
            isEarthworkBulkRequirement, // Instruction 023
            requiresClassification: !!(matRow as any).requiresClassification, // Instruction 024
            ...(arrangementCompanyFraction != null ? { arrangementCompanyFraction } : {}), // 028A §3
          },
        );

        // Instruction 023/024: attach arrangement summaries for earthwork rows.
        // Use ALL distinctBoqItemIds (not just sourceBoqItemId) so multi-source rows
        // (e.g. Embankment Reach 1 + Reach 2 + Shoulder → "Earth / Borrow Soil") also
        // show their arrangements.
        let earthworkArrangementSummaries: import("@shared/planningEngine").EarthworkArrangementSummary[] | undefined;
        if (hasArrangementContext && distinctBoqItemIds.length > 0) {
          const rawArrs = allEarthworkArrangements.filter(a => {
            if (a.status === "cancelled") return false;
            // Single-BOQ arrangement
            if (a.boqItemId != null && distinctBoqItemIds.includes(a.boqItemId)) return true;
            // Multi-BOQ arrangement (boqItemAllocations JSONB)
            const allocs = a.boqItemAllocations as Array<{ boqItemId: number; qty: number }> | null;
            if (Array.isArray(allocs) && allocs.some(al => distinctBoqItemIds.includes(al.boqItemId))) return true;
            return false;
          });
          earthworkArrangementSummaries = rawArrs.map(a => {
            const allocQty = Number(a.allocatedQty ?? 0);
            const rate = a.agreedRate != null ? Number(a.agreedRate) : null;
            return {
              id: a.id,
              arrangementType: a.arrangementType,
              status: a.status,
              agencyName: a.agencyName ?? null,
              allocatedQty: allocQty,
              uom: a.uom,
              agreedRate: rate,
              tripRates: a.tripRates ?? null,
              billingTerms: a.billingTerms ?? null,
              estimatedValue: rate != null ? Math.round(allocQty * rate) : null,
              plannedDailyOutput: a.plannedDailyOutput != null ? Number(a.plannedDailyOutput) : null,
              mobilisationDate: (a as any).mobilisationDate ?? null,
              plannedStartDate: a.plannedStartDate ?? null,
              actualStartDate: (a as any).actualStartDate ?? null,
              targetCompletionDate: a.targetCompletionDate ?? null,
              reachLabel: a.reachLabel ?? null,
              components: (a.components as Record<string, string> | null) ?? null,
              completedQty: 0,      // progress loaded lazily by detail route
              recentDailyOutput: 0,
              lastEntryDate: null,
              daysSinceLastEntry: null,
              boqItemAllocations: (a.boqItemAllocations as Array<{ boqItemId: number; qty: number }> | null) ?? null,
              boqItemId: a.boqItemId ?? null,
              sourceExcavationBoqItemId: (a as any).sourceExcavationBoqItemId ?? null,
              cutAvailableQty: (a as any).sourceExcavationBoqItemId != null
                ? (cutQtyByBoqItemId.get((a as any).sourceExcavationBoqItemId) ?? null)
                : null,
              // Instruction 026: bar linkage state for Work Programme / Procurement display
              programmeAllocations: (a as any).programmeAllocations ?? [],
              barLinkedQty: ((a as any).programmeAllocations ?? []).reduce((s: number, al: any) => s + (Number(al.qty) || 0), 0),
              pendingRevision: (a as any).pendingRevision ?? null,
            };
          });
        }

        // Instruction 026 §15: timing source — bar-level programme vs legacy BOQ-level.
        let arrangementTimingSource: "bar_level" | "boq_level_legacy" | undefined;
        if (hasArrangementContext && earthworkArrangementSummaries?.length) {
          const activeArrs = earthworkArrangementSummaries.filter(a =>
            ["approved", "mobilisation_pending", "in_progress", "on_hold"].includes(String(a.status)));
          if (activeArrs.length > 0) {
            const anyLegacy = activeArrs.some(a => {
              const linked = (a as any).barLinkedQty ?? 0;
              return Number(a.allocatedQty) - linked > 0.001;
            });
            arrangementTimingSource = anyLegacy ? "boq_level_legacy" : "bar_level";
          }
        }

        // 021 §13: procurement equivalent — shortfall in stock/canonical UOM (e.g. MT)
        // = planning shortfall × convFactor. Shown alongside planning shortfall in UI.
        const procurementEquivalentQty = convFactor !== 1 && !uomBlocked
          ? Math.round(shortageRow.actionableShortfall * convFactor * 1000) / 1000
          : null;
        const procurementEquivalentUom = convFactor !== 1 && !uomBlocked ? canonicalUom : null;

        return {
          ...shortageRow,
          // PROCUREMENT CORRECTION Part D/E: contributing BOQ items resolved to
          // short names. Per-item contributed quantities are NOT invented —
          // only ids + names until the engine provides a real breakdown.
          sourceBoqItems: distinctBoqItemIds.map(id => ({
            id,
            name: boqItemShortNameById.get(id) ?? `BOQ #${id}`,
          })),
          ...(materialMappingAmbiguous ? { materialMappingAmbiguous: true, ambiguousCandidates } : {}),
          resolvedVia: mappedId ? "mapping" as const : (aliasOrNameMatchId ? "alias" as const : null),
          ...(conversionBasis ? { conversionBasis, canonicalUom, conversionProfileId: convProfileId } : {}),
          ...(procurementEquivalentQty != null ? { procurementEquivalentQty, procurementEquivalentUom } : {}),
          ...(Object.keys(resolutionDiagnostic).length > 0 ? { resolutionDiagnostic } : {}),
          // Instruction 023/024: earthwork arrangement context
          // isEarthworkBulkRequirement = arrangement flow (already classified as earthwork).
          // requiresClassification    = classification flow (gravel/moorum not yet routed).
          // Both need earthworkBoqItemId/earthworkSourceBoqItemIds so EarthworkControl can
          // find the BOQ item to classify or manage arrangements.
          ...(isEarthworkBulkRequirement ? {
            earthworkBoqItemId: sourceBoqItemId,  // null for multi-source rows (use sourceBoqItemIds)
            earthworkSourceBoqItemIds: distinctBoqItemIds,  // always present for earthwork rows
            earthworkArrangements: earthworkArrangementSummaries ?? [],
            ...(contractCutToFill ? { contractCutToFill: true } : {}),
            // Instruction 025 §12: physical vs outsourced vs HLC split for the row
            ...((matRow as any).arrangementOutsourcedQty != null ? {
              arrangementOutsourcedQty: (matRow as any).arrangementOutsourcedQty,
              arrangementHlcQty: (matRow as any).arrangementHlcQty,
            } : {}),
            // Instruction 026 §15: whether exclusion timing follows the programme bars
            ...(arrangementTimingSource ? { arrangementTimingSource } : {}),
          } : {}),
          // Instruction 028A §14: category-generic arrangement fields. Earthwork rows keep
          // every legacy field above untouched; bituminous rows get the same context under
          // generic names so Procurement can present execution effects without guessing.
          ...(hasArrangementContext ? {
            workCategory: isBituminousArrangedRow ? "bituminous" as const : "earthwork" as const,
            executionArrangements: earthworkArrangementSummaries ?? [],
            arrangementSourceBoqItemIds: distinctBoqItemIds,
            ...(arrangementTimingSource ? { arrangementTimingSource } : {}),
            ...((matRow as any).arrangementOutsourcedQty != null ? {
              arrangementAgencyQty: (matRow as any).arrangementOutsourcedQty,
              arrangementCompanyQty: (matRow as any).arrangementHlcQty,
              // legacy aliases retained for existing consumers
              arrangementOutsourcedQty: (matRow as any).arrangementOutsourcedQty,
              arrangementHlcQty: (matRow as any).arrangementHlcQty,
            } : {}),
            // Row-scoped mapping warnings (project-level list stays on the response root)
            rowMappingWarnings: ((demand as any).mappingWarnings ?? []).filter(
              (w: any) => distinctBoqItemIds.includes(w.boqItemId),
            ),
          } : {}),
          ...(shortageRow.requiresClassification && !isEarthworkBulkRequirement && distinctBoqItemIds.length > 0 ? {
            // Classification-required rows are gravel/moorum (isEarthworkBulkRequirement = false),
            // so the earthwork block above did not fire. Attach BOQ item identity here so
            // EarthworkControl can invoke the bulk-classification endpoint.
            earthworkBoqItemId: distinctBoqItemIds.length === 1 ? distinctBoqItemIds[0] : null,
            earthworkSourceBoqItemIds: distinctBoqItemIds,
          } : {}),
        };
      });

      // Sort: unresolved/ambiguous first, then by actionableShortfall desc, then totalDemand desc
      shortageRows.sort((a, b) => {
        const aTop = (a as any).materialMappingUnresolved || (a as any).materialMappingAmbiguous;
        const bTop = (b as any).materialMappingUnresolved || (b as any).materialMappingAmbiguous;
        if (aTop !== bTop) return aTop ? -1 : 1;
        return (b.actionableShortfall - a.actionableShortfall) || (b.totalDemand - a.totalDemand);
      });

      // Instruction 019C §2: derive programme relation from actual dates, not clamped
      // currentMonth (which cannot distinguish "in last month" from "after programme end").
      // pStartDate and maxProgrammeMonth are already defined above; no horizon math touched.
      let programmeRelation: "before_start" | "within_programme" | "after_end" = "within_programme";
      if (pStartDate) {
        const today = new Date();
        const progStart = new Date(pStartDate);
        // Programme end = first day of the month AFTER the last programme month.
        // e.g. starts Jan 1, maxProgrammeMonth=6 → end = Jul 1 → Jun 30 is within_programme.
        const progEnd = new Date(progStart);
        progEnd.setMonth(progEnd.getMonth() + maxProgrammeMonth);
        if (today < progStart) {
          programmeRelation = "before_start";
        } else if (today >= progEnd) {
          programmeRelation = "after_end";
        }
        // else: within_programme (default, covers today in the final month)
      }

      res.json({
        projectId,
        projectName: project.name,
        projectStartDate: project.startDate ?? null,
        rows: shortageRows,
        hasBars: bars.length > 0,
        hasRecipes: expandedItems.some(it => it.materials.length > 0),
        currentMonth,
        horizonMonthIndex,
        maxProgrammeMonth,
        selectedHorizonMode: horizonModeParam,
        resolvedHorizonDate,
        resolvedProgrammeMonthIndex: horizonMonthIndex,
        programmeRelation,
        // Instruction 025 §13: why demand numbers changed (arrangement exclusions)
        demandAdjustments: (demand as any).demandAdjustments ?? [],
        arrangementOverlaps: (demand as any).arrangementOverlaps ?? [],
        // Instruction 028 §22: non-company components with no recipe resource to exclude
        mappingWarnings: (demand as any).mappingWarnings ?? [],
      });
    } catch (err) {
      console.error("GET /api/boq/projects/:id/shortage-check:", err);
      // Return a structured, safe error — no stack traces or secrets exposed to the client.
      const detail = err instanceof Error ? err.message : String(err);
      res.status(500).json({ error: "Failed to compute shortage check", detail });
    }
  });

  // ── Instruction 023: Earthwork Arrangement routes ──────────────────────────

  /** List all earthwork arrangements for a project. */
  app.get("/api/boq/projects/:id/earthwork-arrangements", async (req, res) => {
    try {
      if (!assertViewEither(req, res, "work_programme", "work_programme_review")) return;
      const projectId = parseInt(req.params.id);
      const rows = await storage.getEarthworkArrangements(projectId);
      res.json(rows);
    } catch (err) {
      console.error("GET /api/boq/projects/:id/earthwork-arrangements:", err);
      res.status(500).json({ error: "Failed to fetch earthwork arrangements" });
    }
  });

  /** List earthwork arrangements for a specific BOQ item. */
  app.get("/api/boq/projects/:id/earthwork-arrangements/item/:itemId", async (req, res) => {
    try {
      if (!assertViewEither(req, res, "work_programme", "work_programme_review")) return;
      const projectId = parseInt(req.params.id);
      const boqItemId = parseInt(req.params.itemId);
      const rows = await storage.getEarthworkArrangementsForItem(projectId, boqItemId);
      const itemIds = Array.from(new Set(rows.flatMap((row) => [
        row.boqItemId,
        row.sourceExcavationBoqItemId,
        ...(Array.isArray(row.boqItemAllocations)
          ? (row.boqItemAllocations as Array<{ boqItemId?: number | null }>).map((allocation) => allocation?.boqItemId ?? null)
          : []),
      ]).filter((id): id is number => id != null)));
      const itemRows = await Promise.all(itemIds.map((id) => storage.getBoqItem(id)));
      const itemLabels = new Map(
        itemRows
          .filter((item): item is NonNullable<typeof item> => item != null)
          .map((item) => [item.id, boqItemDisplayName(item)]),
      );
      res.json(rows.map((row) => {
        const destinationIds = row.boqItemId != null
          ? [row.boqItemId]
          : Array.isArray(row.boqItemAllocations)
            ? (row.boqItemAllocations as Array<{ boqItemId?: number | null }>)
                .map((allocation) => allocation?.boqItemId)
                .filter((id): id is number => id != null)
            : [];
        return {
          ...row,
          sourceExcavationBoqItemLabel: row.sourceExcavationBoqItemId != null
            ? itemLabels.get(row.sourceExcavationBoqItemId) ?? null
            : null,
          destinationBoqItemLabels: destinationIds
            .map((id) => itemLabels.get(id))
            .filter((label): label is string => !!label),
        };
      }));
    } catch (err) {
      console.error("GET /api/boq/projects/:id/earthwork-arrangements/item/:itemId:", err);
      res.status(500).json({ error: "Failed to fetch earthwork arrangements" });
    }
  });

  /** Create a new earthwork arrangement. */
  /**
   * Instruction 031 B3 — validate an arrangement's authoritative Scope linkage.
   * scopeSegmentIds must be an array of IDs of CONFIRMED working_reach records
   * belonging to the arrangement's project. Draft/superseded records and
   * constraint types (no_scope / temporary_block / withdrawn) are never linkable.
   * Returns the normalised (deduped, numeric) id list, or null when empty.
   */
  async function validateArrangementScopeSegments(
    projectId: number,
    raw: unknown,
  ): Promise<{ ok: true; ids: number[] | null } | { ok: false; status: number; body: unknown }> {
    if (raw == null) return { ok: true, ids: null };
    if (!Array.isArray(raw)) {
      return { ok: false, status: 400, body: { error: "INVALID_SCOPE_SEGMENTS", message: "scopeSegmentIds must be an array of scope segment IDs." } };
    }
    const ids = Array.from(new Set(raw.map(Number)));
    if (ids.length === 0) return { ok: true, ids: null };
    if (ids.some(n => !Number.isInteger(n) || n <= 0)) {
      return { ok: false, status: 400, body: { error: "INVALID_SCOPE_SEGMENTS", message: "scopeSegmentIds must contain positive integer segment IDs." } };
    }
    const segs = await storage.getProjectScopeSegments(projectId) as any[];
    const byId = new Map(segs.map(s => [Number(s.id), s]));
    for (const segId of ids) {
      const seg = byId.get(segId);
      if (!seg) {
        return { ok: false, status: 400, body: { error: "SCOPE_SEGMENT_NOT_FOUND", message: `Scope segment ${segId} does not belong to this project.` } };
      }
      if (seg.segmentType !== "working_reach") {
        return { ok: false, status: 400, body: { error: "SCOPE_SEGMENT_NOT_LINKABLE", message: `Scope segment ${segId} is a ${seg.segmentType} constraint — only working reaches can be linked to an arrangement.` } };
      }
      if ((seg.status ?? "confirmed") !== "confirmed") {
        return { ok: false, status: 400, body: { error: "SCOPE_SEGMENT_NOT_CONFIRMED", message: `Scope segment ${segId} is ${seg.status} — only confirmed working reaches can be linked.` } };
      }
    }
    return { ok: true, ids };
  }

  async function validateReusedExcavationSource(
    projectId: number,
    arrangementType: unknown,
    sourceRaw: unknown,
    destinationBoqItemIds: number[],
  ): Promise<
    { ok: true; sourceId: number | null } |
    { ok: false; status: number; body: { error: string; message: string } }
  > {
    const sourceId = sourceRaw == null || sourceRaw === "" ? null : Number(sourceRaw);
    if (arrangementType !== "reused_excavated") {
      // Never leave a legacy cut source attached after changing away from reuse.
      return { ok: true, sourceId: null };
    }
    if (sourceId != null && (!Number.isInteger(sourceId) || sourceId <= 0)) {
      return {
        ok: false,
        status: 400,
        body: {
          error: "INVALID_REUSED_EXCAVATION_SOURCE",
          message: "sourceExcavationBoqItemId must be a positive BOQ item ID.",
        },
      };
    }
    const uniqueDestinations = Array.from(new Set(destinationBoqItemIds.map(Number).filter(Number.isFinite)));
    const issue = reusedExcavationConfigurationIssue({
      id: 0,
      status: "draft",
      arrangementType: "reused_excavated",
      boqProjectId: projectId,
      boqItemId: uniqueDestinations.length === 1 ? uniqueDestinations[0] : null,
      boqItemAllocations: uniqueDestinations.length > 1
        ? uniqueDestinations.map((boqItemId) => ({ boqItemId }))
        : null,
      sourceExcavationBoqItemId: sourceId,
    });
    if (issue) {
      return {
        ok: false,
        status: 400,
        body: { error: "INVALID_REUSED_EXCAVATION_SOURCE", message: issue },
      };
    }
    const [sourceItem] = await db.select({
      id: boqItems.id,
      description: boqItems.description,
      unit: boqItems.unit,
    })
      .from(boqItems)
      .where(and(eq(boqItems.id, sourceId!), eq(boqItems.boqProjectId, projectId)));
    if (!sourceItem) {
      return {
        ok: false,
        status: 400,
        body: {
          error: "INVALID_REUSED_EXCAVATION_SOURCE",
          message: "The source excavation BOQ item must belong to this BOQ project.",
        },
      };
    }
    if (classifyWorkType(sourceItem.description ?? "", sourceItem.unit ?? "") !== "roadway_excavation") {
      return {
        ok: false,
        status: 400,
        body: {
          error: "INVALID_REUSED_EXCAVATION_SOURCE",
          message: "The source BOQ item must be classified as roadway excavation.",
        },
      };
    }
    return { ok: true, sourceId };
  }

  async function assertCutFillProjectAccess(req: any, res: any, projectId: number, write = false): Promise<boolean> {
    if (!assertAuthed(req, res) || !(write ? assertEdit(req, res, "work_programme_review") : assertView(req, res, "work_programme_review"))) return false;
    const [project] = await db.select({ id: boqProjectsTable.id, siteId: boqProjectsTable.siteId })
      .from(boqProjectsTable).where(eq(boqProjectsTable.id, projectId));
    if (!project) { res.status(404).json({ message: "BOQ project not found" }); return false; }
    const permitted = await getPermittedSiteNames(req);
    if (permitted !== null && project.siteId != null) {
      const site = (await storage.getSites()).find((x: any) => Number(x.id) === Number(project.siteId));
      if (!site || !siteMatchesPermitted((site as any).name, permitted)) {
        res.status(403).json({ message: "Access denied for this site" }); return false;
      }
    }
    if (write && !req.authUser?.isAdmin && !["manager", "pm", "project_manager"].includes(String(req.authUser?.role ?? "").toLowerCase())) {
      res.status(403).json({ message: "Only a Project Manager or Admin can change cut/fill reconciliation settings." }); return false;
    }
    return true;
  }

  app.get("/api/boq/projects/:id/cut-fill-reconciliation", async (req, res) => {
    const projectId = Number(req.params.id);
    if (!await assertCutFillProjectAccess(req, res, projectId)) return;
    const [project] = await db.select({ activationDate: boqProjectsTable.cutFillReconciliationActivatedOn })
      .from(boqProjectsTable).where(eq(boqProjectsTable.id, projectId));
    const openings = await db.execute(sql`SELECT * FROM cut_fill_opening_balances WHERE boq_project_id = ${projectId} ORDER BY source_excavation_boq_item_id`);
    res.json({ activationDate: project?.activationDate ?? null, openingBalances: (openings.rows as any[]).map(x => ({
      id: x.id, boqProjectId: x.boq_project_id, sourceExcavationBoqItemId: x.source_excavation_boq_item_id,
      quantity: Number(x.quantity), uom: x.uom, remarks: x.remarks, confirmedAt: x.confirmed_at,
      confirmedByUserId: x.confirmed_by_user_id,
    })) });
  });

  app.put("/api/boq/projects/:id/cut-fill-reconciliation/activation", async (req, res) => {
    const projectId = Number(req.params.id);
    if (!await assertCutFillProjectAccess(req, res, projectId, true)) return;
    const activationDate = req.body?.activationDate;
    if (activationDate != null && (typeof activationDate !== "string" || !/^\d{4}-\d{2}-\d{2}$/.test(activationDate))) {
      return res.status(400).json({ message: "activationDate must be YYYY-MM-DD or null." });
    }
    await db.update(boqProjectsTable).set({ cutFillReconciliationActivatedOn: activationDate ?? null })
      .where(eq(boqProjectsTable.id, projectId));
    await (storage as any).logAudit({ module: "cut_fill_reconciliation", transactionId: projectId, action: "activation_updated", userId: req.authUser?.id, userName: currentUserName(req), newValues: { activationDate: activationDate ?? null } });
    res.json({ activationDate: activationDate ?? null });
  });

  app.put("/api/boq/projects/:id/cut-fill-opening-balances/:sourceBoqItemId", async (req, res) => {
    const projectId = Number(req.params.id), sourceBoqItemId = Number(req.params.sourceBoqItemId), quantity = Number(req.body?.quantity);
    if (!await assertCutFillProjectAccess(req, res, projectId, true)) return;
    if (!Number.isInteger(sourceBoqItemId) || sourceBoqItemId <= 0 || !Number.isFinite(quantity) || quantity < 0) {
      return res.status(400).json({ message: "A source BOQ item and non-negative quantity are required." });
    }
    const [sourceItem] = await db.select({ description: boqItems.description, unit: boqItems.unit })
      .from(boqItems).where(and(eq(boqItems.id, sourceBoqItemId), eq(boqItems.boqProjectId, projectId)));
    if (!sourceItem || classifyWorkType(sourceItem.description ?? "", sourceItem.unit ?? "") !== "roadway_excavation") {
      return res.status(400).json({ message: "Opening balance source must be a roadway excavation BOQ item in this project." });
    }
    const result = await db.execute(sql`
      INSERT INTO cut_fill_opening_balances (boq_project_id, source_excavation_boq_item_id, quantity, uom, remarks, confirmed_by_user_id, updated_at)
      VALUES (${projectId}, ${sourceBoqItemId}, ${quantity}, 'CUM', ${typeof req.body?.remarks === "string" ? req.body.remarks.trim() : null}, ${req.authUser?.id ?? null}, NOW())
      ON CONFLICT (boq_project_id, source_excavation_boq_item_id)
      DO UPDATE SET quantity = EXCLUDED.quantity, remarks = EXCLUDED.remarks, confirmed_by_user_id = EXCLUDED.confirmed_by_user_id, confirmed_at = NOW(), updated_at = NOW()
      RETURNING *
    `);
    await (storage as any).logAudit({ module: "cut_fill_opening_balance", transactionId: sourceBoqItemId, action: "upsert", userId: req.authUser?.id, userName: currentUserName(req), newValues: result.rows[0] });
    res.json(result.rows[0]);
  });

  app.get("/api/boq/projects/:id/cut-fill-sources", async (req, res) => {
    const projectId = Number(req.params.id);
    if (!await assertCutFillProjectAccess(req, res, projectId)) return;
    const rows = await db.execute(sql`
      SELECT p.id, p.entry_key AS "entryKey", p.boq_item_id AS "boqItemId", p.activity, p.uom,
        b.description AS "sourceItemDescription", p.reusable_qty AS "reusableQty", d.date,
        COALESCE((SELECT SUM(c.quantity) FROM cut_fill_consumptions c JOIN progress_entries fp ON fp.id = c.fill_progress_entry_id JOIN dprs fd ON fd.id = fp.dpr_id
          WHERE c.source_progress_entry_id = p.id AND fd.dpr_status = 'submitted' AND COALESCE(fd.is_superseded,false)=false AND COALESCE(fd.is_deleted,false)=false AND COALESCE(fd.is_cancelled,false)=false),0) AS "consumedQty"
      FROM progress_entries p JOIN dprs d ON d.id = p.dpr_id JOIN boq_items b ON b.id = p.boq_item_id JOIN boq_projects bp ON bp.id = d.boq_project_id
      WHERE d.boq_project_id = ${projectId} AND d.dpr_status = 'submitted' AND COALESCE(d.is_superseded,false)=false AND COALESCE(d.is_deleted,false)=false AND COALESCE(d.is_cancelled,false)=false
        AND bp.cut_fill_reconciliation_activated_on IS NOT NULL AND d.date >= bp.cut_fill_reconciliation_activated_on
        AND p.material_outcome IS NOT NULL
      ORDER BY d.date, p.id
    `);
    res.json({ sources: (rows.rows as any[]).map(r => ({ ...r, availableQty: Math.max(0, Number(r.reusableQty ?? 0) - Number(r.consumedQty ?? 0)) })) });
  });

  app.post("/api/boq/projects/:id/earthwork-arrangements", async (req, res) => {
    try {
      if (!assertAuthed(req, res)) return;
      if (!assertEdit(req, res, "work_programme")) return;

      // ── Schema readiness guard ────────────────────────────────────────────
      if (!earthworkSchemaReady) {
        return res.status(503).json({
          error: "EARTHWORK_SCHEMA_NOT_READY",
          message: "Earthwork database setup has not completed yet. Please wait a moment and retry.",
        });
      }

      const projectId = parseInt(req.params.id);
      const user = (req as any).authUser ?? (req as any).user;
      const body = req.body ?? {};
      const tripRatesResult = arrangementTripRatesSchema.safeParse(body.tripRates ?? null);
      const termsResult = arrangementBillingTermsSchema.nullable().safeParse(body.billingTerms ?? null);
      if (!termsResult.success) return res.status(400).json({ error: "INVALID_BILLING_TERMS", message: termsResult.error.issues[0].message });
      if (!tripRatesResult.success) return res.status(400).json({
        error: "INVALID_TRIP_RATES", message: tripRatesResult.error.issues[0].message,
      });
      // Capture the scope read before any arrangement validation. The create
      // transaction rechecks this token after taking the project mutex, so a
      // correction committed while this request was validating cannot result
      // in a stale arrangement insert.
      const scopeVersionToken = await storage.getProjectScopeVersionToken(projectId);

      const { materialLabel, arrangementType } = body;
      // saveIntent: "draft" = Save Draft; "submit" = Submit for Approval (single request, no second PATCH)
      const saveIntent: "draft" | "submit" = body.saveIntent === "submit" ? "submit" : "draft";
      // boqItemAllocations supersedes boqItemId for multi-source arrangements
      const boqItemAllocationsRaw = body.boqItemAllocations as Array<{ boqItemId: number; qty: number }> | undefined;
      const singleBoqItemId: number | null = body.boqItemId ? Number(body.boqItemId) : null;

      // ── Typed validation ──────────────────────────────────────────────────
      if (!materialLabel || !String(materialLabel).trim()) {
        return res.status(400).json({ error: "VALIDATION_FAILED", message: "materialLabel is required." });
      }

      const allocatedQtyNum = Number(body.allocatedQty);
      if (body.allocatedQty == null || isNaN(allocatedQtyNum) || allocatedQtyNum <= 0) {
        return res.status(400).json({
          error: "INVALID_ALLOCATED_QUANTITY",
          message: "Allocated quantity must be a positive number.",
        });
      }

      // Date format guard (YYYY-MM-DD or null)
      const dateRe = /^\d{4}-\d{2}-\d{2}$/;
      const plannedStart = body.plannedStartDate ?? null;
      const targetEnd = body.targetCompletionDate ?? null;
      if (plannedStart && !dateRe.test(plannedStart))
        return res.status(400).json({ error: "INVALID_DATE_RANGE", message: "plannedStartDate must be YYYY-MM-DD" });
      if (targetEnd && !dateRe.test(targetEnd))
        return res.status(400).json({ error: "INVALID_DATE_RANGE", message: "targetCompletionDate must be YYYY-MM-DD" });
      if (plannedStart && targetEnd && targetEnd < plannedStart)
        return res.status(400).json({ error: "INVALID_DATE_RANGE", message: "targetCompletionDate cannot precede plannedStartDate" });

      // ── Instruction 031 B3: authoritative Scope linkage (validated first —
      // a reach-linked arrangement is exempt from the raw-chainage guard below,
      // because its internal no-scope/withdrawn intervals are clipped by the
      // eligibility engine instead of blocking the whole selection).
      const scopeCheckResult = await validateArrangementScopeSegments(projectId, body.scopeSegmentIds);
      if (!scopeCheckResult.ok) return res.status(scopeCheckResult.status).json(scopeCheckResult.body);
      const scopeSegmentIdsValue = scopeCheckResult.ids;

      // ── Instruction 032 Part M (light): block arrangements over permanently
      // excluded / withdrawn scope, unless the record is historical (the
      // arrangement's chainage predates the withdrawal's effective date via
      // evaluateDprScope's date gate). Temporary blocks do NOT block — the
      // arrangement may be preparation for after the block lifts.
      if (scopeSegmentIdsValue == null) {
        const arrChF = body.chainageFrom != null ? Number(body.chainageFrom) : null;
        const arrChT = body.chainageTo != null ? Number(body.chainageTo) : null;
        if (arrChF != null && arrChT != null && Number.isFinite(arrChF) && Number.isFinite(arrChT) && arrChT > arrChF) {
          const rawSegs = await storage.getProjectScopeSegments(projectId);
          const segs: ScopeSegmentLike[] = (rawSegs as any[]).map(x => ({
            id: x.id, segmentType: x.segmentType, chainageFrom: Number(x.chainageFrom), chainageTo: Number(x.chainageTo),
            side: x.side, status: x.status, applicability: x.applicability,
            categoryIds: safeIdList(x.categoryIds),
            itemIds: safeIdList(x.itemIds),
            effectiveFrom: x.effectiveFrom, effectiveTo: x.effectiveTo, label: x.label, reason: x.reason,
          }));
          if (segs.some(s => s.segmentType === "working_reach" && (s.status ?? "confirmed") === "confirmed")) {
            const arrItemId = singleBoqItemId ?? ((Array.isArray(boqItemAllocationsRaw) && boqItemAllocationsRaw[0]?.boqItemId) || null);
            const arrItem: any = arrItemId ? await storage.getBoqItem(Number(arrItemId)) : null;
            const scopeCheck = evaluateDprScope(segs, {
              boqItemId: arrItemId != null ? Number(arrItemId) : null,
              categoryId: arrItem?.categoryId ?? null,
              isLinear: true,
              side: body.side ?? null,
              chainageFromKm: arrChF,
              chainageToKm: arrChT,
              dprDate: plannedStart ?? null,
            });
            if (scopeCheck.status === "no_scope" || scopeCheck.status === "withdrawn") {
              return res.status(422).json({
                error: "SCOPE_BLOCKED",
                message: `This chainage is outside the project's executable scope (${scopeCheck.status === "withdrawn" ? "withdrawn" : "no scope"}). ${scopeCheck.message ?? ""}`.trim(),
              });
            }
          }
        }
      }

      // Submit-specific validation — arrangement type must be confirmed before submitting
      if (saveIntent === "submit" && (!arrangementType || arrangementType === "not_decided")) {
        return res.status(400).json({
          error: "SUBMIT_VALIDATION_FAILED",
          message: "Arrangement type must be selected before submitting for approval. 'Not Decided' is only valid for drafts.",
        });
      }

      // ── Instruction 028 §35 — category validation ─────────────────────────
      const workCategory: string = body.workCategory ?? "earthwork";
      if (!isValidWorkCategory(workCategory)) {
        return res.status(400).json({ error: "INVALID_WORK_CATEGORY", message: `Unsupported work category '${workCategory}'. Supported: earthwork, bituminous.` });
      }
      if (arrangementType && arrangementType !== "not_decided" && !isArrangementTypeAllowed(workCategory, arrangementType)) {
        return res.status(400).json({ error: "INVALID_ARRANGEMENT_TYPE", message: `Arrangement type '${arrangementType}' is not valid for ${workCategory} works.` });
      }
      const badKeys = invalidComponentKeys(workCategory, body.components ?? null);
      if (badKeys.length > 0) {
        return res.status(400).json({ error: "INVALID_COMPONENT_KEYS", message: `Component keys not allowed for ${workCategory}: ${badKeys.join(", ")}` });
      }
      const bituminousItemType = body.bituminousItemType ?? null;
      if (bituminousItemType != null && !isValidBituminousItemType(bituminousItemType)) {
        return res.status(400).json({ error: "INVALID_BITUMINOUS_ITEM_TYPE", message: `Unknown bituminous item type '${bituminousItemType}'.` });
      }
      if (workCategory !== "bituminous" && bituminousItemType != null) {
        return res.status(400).json({ error: "INVALID_BITUMINOUS_ITEM_TYPE", message: "bituminousItemType applies only to bituminous arrangements." });
      }
      // 028A §13 (Part D safe fallback): Shared responsibility is not yet carried through
      // demand proration, so NEW Shared components are blocked outright — a stored split
      // would silently behave as 100% company-retained. Existing stored records are preserved.
      if (body.components && typeof body.components === "object") {
        const sharedKeys = Object.entries(body.components as Record<string, string>).filter(([, v]) => v === "shared").map(([k]) => k);
        if (sharedKeys.length > 0) {
          return res.status(400).json({ error: "SHARED_NOT_AVAILABLE", message: `Shared responsibility percentage entry is not yet available (component${sharedKeys.length > 1 ? "s" : ""} '${sharedKeys.join("', '")}'). Choose Company, Agency or Client for now.` });
        }
      }

      // Agency required for outsourced types (category-driven)
      const needsAgency = workCategory === "bituminous"
        ? (getCategoryDescriptor("bituminous").outsourcedTypes.has(arrangementType) || arrangementType === "partly_outsourced")
        : ["fully_outsourced_composite","vendor_material_delivered","hlc_source_outsourced_execution","partly_outsourced"].includes(arrangementType);
      if (needsAgency && !body.agencyName?.trim()) {
        return res.status(400).json({ error: "AGENCY_REQUIRED", message: "Agency / Vendor name is required for outsourced arrangements." });
      }

      // ── Instruction 028 §35 — category eligibility vs linked BOQ item(s) ──
      // A bituminous arrangement may only be raised against items that resolve
      // to the bituminous category (auto-detected or manual override); and an
      // earthwork arrangement must never target a bituminous-classified item.
      {
        const sourceItemIds: number[] = boqItemAllocationsRaw && Array.isArray(boqItemAllocationsRaw)
          ? boqItemAllocationsRaw.filter(a => a.boqItemId && Number(a.qty) > 0).map(a => Number(a.boqItemId))
          : (singleBoqItemId ? [singleBoqItemId] : []);
        for (const itemId of sourceItemIds) {
          const [srcItem] = await db.select({
            description: boqItems.description, unit: boqItems.unit,
            itemWorkCategory: boqItems.workCategory,
            bulkMaterialClassification: boqItems.bulkMaterialClassification,
          }).from(boqItems).where(eq(boqItems.id, itemId));
          if (!srcItem) continue; // existence is validated by the allocation guard below
          const resolved = executionArrangementCategoryForItem({
            description: srcItem.description ?? "", unit: srcItem.unit ?? "",
            workCategory: srcItem.itemWorkCategory,
            bulkMaterialClassification: srcItem.bulkMaterialClassification,
          } as any);
          if (workCategory === "bituminous" && resolved !== "bituminous") {
            return res.status(400).json({
              error: "CATEGORY_ITEM_MISMATCH",
              message: `BOQ item ${itemId} is not classified as bituminous — a bituminous arrangement cannot be raised against it. Use the manual classification override if the auto-detection is wrong.`,
            });
          }
          if (workCategory === "earthwork" && resolved === "bituminous") {
            return res.status(400).json({
              error: "CATEGORY_ITEM_MISMATCH",
              message: `BOQ item ${itemId} is classified as bituminous — raise a bituminous arrangement instead of an earthwork one.`,
            });
          }
        }
      }

      // ── Linkage guard: every arrangement must be tied to a BOQ source ─────
      // An arrangement with no boqItemId and no boqItemAllocations is an orphan —
      // it bypasses the per-item over-allocation guard and becomes unattributable.
      const hasMultiSource = boqItemAllocationsRaw && Array.isArray(boqItemAllocationsRaw)
        && boqItemAllocationsRaw.some(a => a.boqItemId && Number(a.qty) > 0);
      const hasSingleSource = !!singleBoqItemId;
      if (!hasSingleSource && !hasMultiSource) {
        return res.status(400).json({
          error: "BOQ_SOURCE_REQUIRED",
          message: "An earthwork arrangement must be linked to at least one BOQ item. Provide boqItemId or a non-empty boqItemAllocations array.",
        });
      }
      if (hasSingleSource && hasMultiSource) {
        return res.status(400).json({
          error: "AMBIGUOUS_BOQ_SOURCE",
          message: "Provide either boqItemId (single-source) or boqItemAllocations (multi-source), not both.",
        });
      }

      // ── Multi-BOQ over-allocation guard ───────────────────────────────────
      const effectiveAllocations: Array<{ boqItemId: number; qty: number }> = [];

      if (boqItemAllocationsRaw && Array.isArray(boqItemAllocationsRaw) && boqItemAllocationsRaw.length > 0) {
        // Multi-source: validate each source individually
        // Uses getAllocatedQtyForBoqItem which checks BOTH direct (boq_item_id) and
        // JSONB split (boq_item_allocations) allocations — prevents double-counting.
        for (const alloc of boqItemAllocationsRaw) {
          if (!alloc.boqItemId || Number(alloc.qty) <= 0) continue;
          const [boqItem] = await db.select({ currentQty: boqItems.currentQty, description: boqItems.description })
            .from(boqItems).where(eq(boqItems.id, Number(alloc.boqItemId)));
          if (!boqItem) {
            return res.status(400).json({ error: "BOQ_ITEM_NOT_FOUND", message: `BOQ item ${alloc.boqItemId} not found.` });
          }
          const alreadyAllocated = await storage.getAllocatedQtyForBoqItem(projectId, Number(alloc.boqItemId));
          const boqQty = Number(boqItem.currentQty ?? 0);
          if (alreadyAllocated + Number(alloc.qty) > boqQty + 0.001) {
            return res.status(400).json({
              error: "ALLOCATION_EXCEEDS_REMAINING_QUANTITY",
              message: `Allocation for "${boqItem.description}" (${(alreadyAllocated + Number(alloc.qty)).toFixed(2)} CUM) would exceed BOQ quantity (${boqQty} CUM). Already allocated: ${alreadyAllocated.toFixed(2)} CUM across all arrangements.`,
            });
          }
          effectiveAllocations.push({ boqItemId: Number(alloc.boqItemId), qty: Number(alloc.qty) });
        }

        // ── Allocation total must match allocatedQty for multi-source ──────
        const allocSum = effectiveAllocations.reduce((s, a) => s + a.qty, 0);
        if (Math.abs(allocSum - allocatedQtyNum) > 0.01) {
          return res.status(400).json({
            error: "ALLOCATION_TOTAL_MISMATCH",
            message: `allocatedQty (${allocatedQtyNum}) must equal the sum of boqItemAllocations (${allocSum.toFixed(2)} CUM). Please correct the per-source split.`,
          });
        }
      } else if (singleBoqItemId) {
        // Single-source: also use getAllocatedQtyForBoqItem to catch cross-allocation leakage
        const [boqItem] = await db.select({ currentQty: boqItems.currentQty, description: boqItems.description })
          .from(boqItems).where(eq(boqItems.id, singleBoqItemId));
        if (boqItem) {
          const alreadyAllocated = await storage.getAllocatedQtyForBoqItem(projectId, singleBoqItemId);
          const boqQty = Number(boqItem.currentQty ?? 0);
          if (alreadyAllocated + allocatedQtyNum > boqQty + 0.001) {
            return res.status(400).json({
              error: "ALLOCATION_EXCEEDS_REMAINING_QUANTITY",
              message: `Allocated quantity (${(alreadyAllocated + allocatedQtyNum).toFixed(2)} CUM) would exceed BOQ quantity (${boqQty} CUM). Already allocated: ${alreadyAllocated.toFixed(2)} CUM.`,
            });
          }
        }
        effectiveAllocations.push({ boqItemId: singleBoqItemId, qty: allocatedQtyNum });
      }

      const primaryBoqItemId = effectiveAllocations.length === 1
        ? effectiveAllocations[0].boqItemId
        : (effectiveAllocations.length > 1 ? null : singleBoqItemId);
      const reuseSourceCheck = await validateReusedExcavationSource(
        projectId,
        arrangementType ?? "not_decided",
        body.sourceExcavationBoqItemId,
        effectiveAllocations.map((allocation) => allocation.boqItemId),
      );
      if (!reuseSourceCheck.ok) {
        return res.status(reuseSourceCheck.status).json(reuseSourceCheck.body);
      }

      // Determine final status from saveIntent
      const finalStatus = saveIntent === "submit" ? "submitted" : "draft";
      const submittedAtValue = saveIntent === "submit" ? new Date() : null;

      const row = await storage.createEarthworkArrangement({
        boqProjectId: projectId,
        boqItemId: primaryBoqItemId,
        boqItemAllocations: effectiveAllocations.length > 1 ? effectiveAllocations : null,
        materialLabel: String(materialLabel).trim(),
        workCategory,
        bituminousItemType: workCategory === "bituminous" ? bituminousItemType : null,
        arrangementType: arrangementType ?? "not_decided",
        status: finalStatus,
        submittedAt: submittedAtValue,
        allocatedQty: allocatedQtyNum,
        uom: body.uom ?? "CUM",
        agencyName: body.agencyName?.trim() || null,
        workDescription: body.workDescription?.trim() || null,
        reachLabel: body.reachLabel?.trim() || null,
        chainageFrom: body.chainageFrom != null ? Number(body.chainageFrom) : null,
        chainageTo: body.chainageTo != null ? Number(body.chainageTo) : null,
        scopeSegmentIds: scopeSegmentIdsValue,
        tripRates: tripRatesResult.data,
        billingTerms: termsResult.data,
        agreedRate: body.agreedRate != null ? Number(body.agreedRate) : null,
        borrowSource: body.borrowSource?.trim() || null,
        avgLeadKm: body.avgLeadKm != null ? Number(body.avgLeadKm) : null,
        mobilisationDate: body.mobilisationDate ?? null,
        plannedStartDate: plannedStart,
        targetCompletionDate: targetEnd,
        plannedDailyOutput: body.plannedDailyOutput != null ? Number(body.plannedDailyOutput) : null,
        workingHoursPerShift: body.workingHoursPerShift != null ? Number(body.workingHoursPerShift) : null,
        numExcavators: body.numExcavators != null ? Number(body.numExcavators) : null,
        excavatorType: body.excavatorType?.trim() || null,
        numTippers: body.numTippers != null ? Number(body.numTippers) : null,
        tipperCapacityCum: body.tipperCapacityCum != null ? Number(body.tipperCapacityCum) : null,
        dieselResponsibility: body.dieselResponsibility ?? null,
        components: body.components ?? null,
        inclusions: body.inclusions?.trim() || null,
        exclusions: body.exclusions?.trim() || null,
        notes: body.notes?.trim() || null,
        sourceExcavationBoqItemId: reuseSourceCheck.sourceId,
        preparedByUserId: user?.id ?? null,
      }, scopeVersionToken);

      await (storage as any).logAudit({ userName: user?.fullName ?? "Unknown", userRole: user?.role ?? null,
        module: "earthwork_arrangements",
        transactionId: Number(row.id),
        action: "create",
        userId: user?.id ?? null,
        newValues: row,
      }).catch(() => {});

      res.status(201).json(row);
    } catch (err: any) {
      console.error("POST /api/boq/projects/:id/earthwork-arrangements:", err);
      const errMsg = String(err?.message ?? "");
      if (err?.code === "SCOPE_CHANGED_DURING_PLANNING"
        || (ScopeChangedDuringPlanningError && err instanceof ScopeChangedDuringPlanningError)) {
        return res.status(409).json({
          code: "SCOPE_CHANGED_DURING_PLANNING",
          message: err.message,
        });
      }
      // Schema errors — return actionable column/table name
      if (errMsg.includes("relation") || errMsg.includes("does not exist") || errMsg.includes("column")) {
        const colMatch = errMsg.match(/column "([^"]+)"/);
        const tableMatch = errMsg.match(/relation "([^"]+)"/);
        const detail = colMatch
          ? `Missing column: ${colMatch[1]}.`
          : tableMatch ? `Missing table: ${tableMatch[1]}.`
          : "Schema check needed.";
        return res.status(503).json({
          error: "EARTHWORK_SCHEMA_NOT_READY",
          message: `Earthwork database setup is incomplete. ${detail} The server will retry setup on next restart.`,
        });
      }
      // Unknown error — log with correlation ID; do not blame required fields
      const correlationId = Date.now().toString(36) + Math.random().toString(36).slice(2, 6);
      console.error(`[earthwork-save-error:${correlationId}]`, err);
      res.status(500).json({
        error: "ARRANGEMENT_SAVE_FAILED",
        message: `An unexpected error occurred while saving the arrangement. (ref: ${correlationId})`,
      });
    }
  });

  /** Get a single earthwork arrangement with progress data. */
  app.get("/api/earthwork-arrangements/:id", async (req, res) => {
    try {
      if (!assertAuthed(req, res)) return;
      const id = parseInt(req.params.id);
      const arr = await storage.getEarthworkArrangementById(id);
      if (!arr) return res.status(404).json({ error: "Arrangement not found" });
      const progress = await (storage as any).getArrangementProgress(id);
      res.json({ ...arr, progress });
    } catch (err) {
      console.error("GET /api/earthwork-arrangements/:id:", err);
      res.status(500).json({ error: "Failed to fetch arrangement" });
    }
  });

  /**
   * Read-only, live arrangement evidence. It intentionally derives from the
   * current valid DPR/trip records each request rather than persisting a
   * classification or commercial quantity.
   */
  app.get("/api/earthwork-arrangements/:id/execution-evidence", async (req, res) => {
    try {
      if (!assertAuthed(req, res) || !assertViewEither(req, res, "work_programme", "work_programme_review")) return;
      const id = Number(req.params.id);
      if (!Number.isInteger(id) || id <= 0) return res.status(400).json({ message: "A valid arrangement id is required" });
      const arrangement = await storage.getEarthworkArrangementById(id);
      if (!arrangement) return res.status(404).json({ message: "Arrangement not found" });
      if (!(await assertOutcomeProjectScope(req, res, arrangement.boqProjectId))) return;
      const bars = await storage.getArrangementExecutionEvidence(id);
      res.json({
        arrangementId: arrangement.id,
        boqProjectId: arrangement.boqProjectId,
