  app.get("/api/snl/search", async (req, res) => {
    try {
      if (!assertViewEither(req, res, "norms_library", "qto_boq", "work_programme_review")) return;
      const q = (req.query.q as string) || "";
      const category = req.query.category as string | undefined;
