async function assertOutcomeProjectScope(req: any, res: any, projectId: number): Promise<boolean> {
    const project = await storage.getBoqProject(projectId);
    if (!project) {
      res.status(404).json({ message: "BOQ project not found" });
      return false;
    }
    const permitted = await getPermittedSiteNames(req);
    if (permitted !== null) {
      const site = (await storage.getSites()).find((candidate) => candidate.id === project.siteId);
      if (!site || !siteMatchesPermitted(site.name, permitted)) {
        res.status(403).json({ message: "You do not have access to this project's site." });
        return false;
      }
    }
    return true;
  }

function assertOutcomeManagerAuthority(req: any, res: any): boolean {
    const user = req.authUser;
    if (!user) {
      res.status(401).json({ message: "Authentication required" });
      return false;
    }
    const role = String(user.role ?? "").trim().toLowerCase().replace(/[\s-]+/g, "_");
    const permitted = !!user.isAdmin || !!user.isOwner ||
      ["manager", "pm", "project_manager"].includes(role);
    if (!permitted) {
      res.status(403).json({ message: "Manager, PM, Admin or Owner authority is required to set arrangement status." });
      return false;
    }
    return true;
  }

async function assertCutFillProjectAccess(req: any, res: any, projectId: number, write = false): Promise<boolean> {
    if (!assertAuthed(req, res) || !(write ? assertEdit(req, res, "work_programme_review") : assertView(req, res, "work_programme_review"))) return false;
    const [project] = await db.select({ id: boqProjectsTable.id, siteId: boqProjectsTable.siteId })
      .from(boqProjectsTable).where(eq(boqProjectsTable.id, projectId));
    if (!project) { res.status(404).json({ message: "BOQ project not found" }); return false; }
    const permitted = await getPermittedSiteNames(req);
    if (permitted !== null && project.siteId != null) {
      const site = (await storage.getSites()).find((x: any) => Number(x.id) === Number(project.siteId));
      if (!site || !siteMatchesPermitted((site as any).name, permitted)) {
        res.status(403).json({ message: "Access denied for this site" }); return false;
      }
    }
    if (write && !req.authUser?.isAdmin && !["manager", "pm", "project_manager"].includes(String(req.authUser?.role ?? "").toLowerCase())) {
      res.status(403).json({ message: "Only a Project Manager or Admin can change cut/fill reconciliation settings." }); return false;
    }
    return true;
  }

export function registerSiteRequirementRoutes(app: Express) {
  app.post("/api/site-requirements", requireAuth, async (req: any, res) => {
    try {
      const body = req.body;
      if (!body.date) return res.status(400).json({ error: "date is required" });
      const row = await storage.createSiteRequirement({
        date: body.date,
        siteId: body.siteId ? parseInt(String(body.siteId)) : null,
        // Always use server-side session for identity — never trust client-supplied values
        submittedBy: req.authUser.id,
        submittedByName: req.authUser.fullName,
        plannedWork: body.plannedWork ?? null,
        materials: body.materials ?? null,
        equipment: body.equipment ?? null,
        labour: body.labour ?? null,
        immediateRequirements: body.immediateRequirements ?? null,
      });
      res.json(row);
    } catch (err: any) {
      console.error("POST /api/site-requirements error:", err);
      res.status(500).json({ error: err.message });
    }
  });

  app.get("/api/site-requirements", requireAuth, async (req: any, res) => {
    const t0 = Date.now();
    try {
      const canReview = req.authUser.isAdmin || req.authUser.isOwner || req.authPermissions?.site_dprs?.approve;
      const filters: any = {};
      if (req.query.dateFrom) filters.dateFrom = req.query.dateFrom as string;
      if (req.query.dateTo)   filters.dateTo   = req.query.dateTo as string;
      if (req.query.siteId)   filters.siteId   = parseInt(req.query.siteId as string);
      if (req.query.status)   filters.status   = req.query.status as string;
      // Non-admin/manager see only their own submissions
      if (!canReview) {
        filters.submittedBy = req.authUser.id;
      }
      const rows = await storage.listSiteRequirements(filters);
      const dur = Date.now() - t0;
      if (dur > 200 || process.env.NODE_ENV !== "production") {
        console.log(`[perf] GET /api/site-requirements → ${rows.length} rows in ${dur}ms`);
      }
      res.json(rows);
    } catch (err: any) {
      console.error("GET /api/site-requirements error:", err);
      res.status(500).json({ error: err.message });
    }
  });

  app.get("/api/site-requirements/:id", requireAuth, async (req: any, res) => {
    try {
      const row = await storage.getSiteRequirement(parseInt(req.params.id));
      if (!row) return res.status(404).json({ error: "Not found" });
      const canReview = req.authUser.isAdmin || req.authUser.isOwner || req.authPermissions?.site_dprs?.approve;
      const isCreator = row.submittedBy === req.authUser.id;
      if (!canReview && !isCreator) {
        return res.status(403).json({ error: "Access denied" });
      }
      res.json(row);
    } catch (err: any) {
      res.status(500).json({ error: err.message });
    }
  });

  app.patch("/api/site-requirements/:id/status", requireAuth, async (req: any, res) => {
    try {
      const { status, pmRemarks } = req.body;
      if (!status) return res.status(400).json({ error: "status is required" });
      if (isRequirementDecision(status)) {
        if (!assertApprove(req, res, "site_dprs")) return;
        const existing = await storage.getSiteRequirement(parseInt(req.params.id));
        if (!existing) return res.status(404).json({ error: "Not found" });
        const blocked = requirementApprovalBlock(req.authUser, existing.submittedBy);
        if (blocked) return res.status(403).json({ error: blocked });
      } else {
        // Non-approval allocation/status transitions retain their existing gate.
        const role = req.session?.role ?? "engineer";
        if (role !== "admin" && role !== "manager") {
          return res.status(403).json({ error: "Only managers or admins can update status" });
        }
      }
      const row = await storage.updateSiteRequirementStatus(parseInt(req.params.id), {
        status,
        pmRemarks,
        reviewedBy: req.authUser.id,
      });
      res.json(row);
    } catch (err: any) {
      res.status(500).json({ error: err.message });
    }
  });

  // PATCH /api/site-requirements/:id/allocation — PM/manager sets per-section allocation status
  app.patch("/api/site-requirements/:id/allocation", requireAuth, async (req: any, res) => {
    try {
      const role = req.session?.role ?? "engineer";
      if (role !== "admin" && role !== "manager") {
        return res.status(403).json({ error: "Only managers or admins can update allocation" });
      }
      // 06J: whitelist section-level fields only — this endpoint must never
      // write outcome/carry-forward/item-array keys (forgery + wipe protection).
      const ALLOWED = ["materials", "materialsRemark", "equipment", "equipmentRemark", "labour", "labourRemark", "immediate", "immediateRemark"] as const;
      const data: Record<string, any> = {
        updatedByName: req.session?.username ?? null,
        updatedAt: new Date().toISOString(),
      };
      for (const k of ALLOWED) if (k in req.body) data[k] = req.body[k];
      const row = await storage.updateSiteRequirementAllocation(parseInt(req.params.id), data);
      res.json(row);
    } catch (err: any) {
      res.status(500).json({ error: err.message });
    }
  });

  // PATCH /api/site-requirements/:id/item-status — PM/Store/Equipment updates per-item allocation status
  app.patch("/api/site-requirements/:id/item-status", requireAuth, async (req: any, res) => {
    try {
      const u = req.authUser;
      const perms = req.authPermissions ?? {};
      const isManagerOrAdmin = !!(u?.isAdmin || u?.isOwner || req.session?.role === "manager");
      const canStores    = isManagerOrAdmin || !!(perms["stores_inventory"]?.create);
      const canEquipment = isManagerOrAdmin || !!(perms["plant_equipment"]?.create);
      const canLabour    = isManagerOrAdmin || !!(perms["labour_management"]?.create);

      const { category, itemIndex, lineKey, status, expectedBy, remarks,
        fulfilmentType, arrangementId, agencyNameSnapshot, exceptionReason } = req.body;
      if (!category || itemIndex === undefined || itemIndex === null) {
        return res.status(400).json({ error: "category and itemIndex are required" });
      }
      // 06F: optional daily fulfilment context — validated by the shared seam.
      const fv = validateFulfilment({ fulfilmentType, arrangementId, agencyNameSnapshot, exceptionReason });
      if (!fv.ok) {
        return res.status(400).json({ error: fv.message, code: fv.code });
      }
      const allowed = ["materials", "equipment", "labour", "immediate"];
      if (!allowed.includes(category)) {
        return res.status(400).json({ error: "Invalid category" });
      }

      // Per-category permission check
      if (category === "materials" && !canStores) {
        return res.status(403).json({ error: "Updating material allocation requires Stores & Inventory access" });
      }
      if (category === "equipment" && !canEquipment) {
        return res.status(403).json({ error: "Updating equipment allocation requires Equipment & Fleet access" });
      }
      if (category === "labour" && !canLabour) {
        return res.status(403).json({ error: "Updating labour allocation requires Labour Management access" });
      }
      if (category === "immediate" && !(isManagerOrAdmin || canStores || canEquipment)) {
        return res.status(403).json({ error: "Updating immediate requirements requires Stores, Equipment, or PM access" });
      }

      // 06F: authoritative line identity — validate the target line against the
      // requirement's OWN stored lines. Clients cannot invent lineKeys or write
      // out-of-range indexes; the server derives the canonical (lineKey, index).
      const reqId = parseInt(req.params.id);
      const reqRow = await storage.getSiteRequirement(reqId);
      if (!reqRow) return res.status(404).json({ error: "Not found" });
      const lines: any[] =
        category === "materials" ? ((reqRow.materials as any[]) ?? [])
        : category === "equipment" ? ((reqRow.equipment as any[]) ?? [])
        : category === "labour" ? ((reqRow.labour as any[]) ?? [])
        : ((reqRow.immediateRequirements as any[]) ?? []);
      const idxNum = Number(itemIndex);
      const clientKey = typeof lineKey === "string" && lineKey ? lineKey : null;
      let resolvedIndex: number;
      let resolvedKey: string | null;
      if (clientKey) {
        const at = lines.findIndex((l: any) => l?.lineKey === clientKey);
        if (at < 0) return res.status(400).json({ error: "lineKey does not match any line in this category", code: "UNKNOWN_LINE_KEY" });
        resolvedIndex = at;           // authoritative current position
        resolvedKey = clientKey;
      } else {
        if (!Number.isInteger(idxNum) || idxNum < 0 || idxNum >= lines.length) {
          return res.status(400).json({ error: "itemIndex out of range for this category", code: "INVALID_ITEM_INDEX" });
        }
        resolvedIndex = idxNum;
        // Legacy caller on a keyed line: adopt the line's own key so the
        // allocation stays attached to the line, not the position.
        resolvedKey = typeof lines[idxNum]?.lineKey === "string" && lines[idxNum].lineKey ? lines[idxNum].lineKey : null;
      }

      // 06F: an 'arrangement' fulfilment must reference a real, operational
      // arrangement compatible with this requirement's planned BOQ item.
      // Reading only — the arrangement itself is never modified here.
      let agencySnapshotFinal = fv.value.agencyNameSnapshot;
      if (fv.value.fulfilmentType === "arrangement") {
        const [arrRow] = await db.select().from(earthworkArrangementsTable)
          .where(eq(earthworkArrangementsTable.id, fv.value.arrangementId!));
        if (!arrRow) return res.status(400).json({ error: "Arrangement not found", code: "ARRANGEMENT_NOT_FOUND" });
        const okStatuses = ["approved", "mobilisation_pending", "in_progress", "on_hold"];
        if (!okStatuses.includes(arrRow.status as string)) {
          return res.status(400).json({ error: `Arrangement is ${arrRow.status} — not available for daily allocation`, code: "ARRANGEMENT_NOT_OPERATIONAL" });
        }
        const plannedItemId = (reqRow.plannedWork as any)?.boqItemId ?? null;
        if (plannedItemId != null) {
          const itemAllocs = (arrRow.boqItemAllocations as Array<{ boqItemId: number }> | null) ?? null;
          const covers = arrRow.boqItemId != null
            ? arrRow.boqItemId === plannedItemId
            : Array.isArray(itemAllocs) && itemAllocs.some((x) => x?.boqItemId === plannedItemId);
          if (!covers) {
            return res.status(400).json({ error: "Arrangement does not cover this requirement's BOQ item", code: "ARRANGEMENT_INCOMPATIBLE" });
          }
        }
        // Snapshot the agency name from the arrangement itself (authoritative).
        agencySnapshotFinal = (arrRow.agencyName as string | null) ?? agencySnapshotFinal;
      }

      const row = await storage.updateSiteRequirementItemStatus(reqId, category, resolvedIndex, {
        lineKey: resolvedKey,
        status: status ?? null,
        expectedBy: expectedBy ?? null,
        remarks: remarks ?? null,
        fulfilmentType: fv.value.fulfilmentType,
        arrangementId: fv.value.arrangementId,
        agencyNameSnapshot: agencySnapshotFinal,
        exceptionReason: fv.value.exceptionReason,
        updatedBy: req.session?.username ?? null,
      });
      if (!row) return res.status(404).json({ error: "Not found" });
      res.json(row);
    } catch (err: any) {
      res.status(500).json({ error: err.message });
    }
  });

  // PATCH /api/site-requirements/:id/readiness — engineer confirms morning readiness
  // Readiness confirmation is a morning site-check action (not an approval/allocation action).
  // Any authenticated user may save readiness — the separate allocation/status endpoints
  // remain gated to managers/admins only.
  app.patch("/api/site-requirements/:id/readiness", requireAuth, async (req: any, res) => {
    try {
      const existing = await storage.getSiteRequirement(parseInt(req.params.id));
      if (!existing) return res.status(404).json({ error: "Not found" });
      const { materialStatus, equipmentStatus, labourStatus, immediateStatus, remarks } = req.body;
      const hasShortage = [materialStatus, equipmentStatus, labourStatus, immediateStatus].some(
        s => s === "partly_available" || s === "not_available" || s === "shortage"
      );
      const confirmation = {
        materialStatus: materialStatus ?? null,
        equipmentStatus: equipmentStatus ?? null,
        labourStatus: labourStatus ?? null,
        immediateStatus: immediateStatus ?? null,
        remarks: remarks ?? null,
        confirmedAt: new Date().toISOString(),
        confirmedByName: req.session?.username ?? null,
      };
      const row = await storage.updateSiteRequirementReadiness(parseInt(req.params.id), {
        readinessConfirmation: confirmation,
        readinessStatus: hasShortage ? "confirmed_with_shortage" : "confirmed_ok",
      });
      res.json(row);
    } catch (err: any) {
      res.status(500).json({ error: err.message });
    }
  });

  // ── 06J: execution outcome + carry forward ─────────────────────────────────

  // GET /api/site-requirements/:id/execution-summary — planned vs executed
  // (submitted DPR billable progress) for the plan's BOQ item. PM/Admin only.
  app.get("/api/site-requirements/:id/execution-summary", requireAuth, async (req: any, res) => {
    try {
      const role = req.session?.role ?? "engineer";
      if (role !== "admin" && role !== "manager") {
        return res.status(403).json({ error: "Only managers or admins can review outcomes" });
      }
      const plan = await storage.getSiteRequirement(parseInt(req.params.id));
      if (!plan) return res.status(404).json({ error: "Not found" });
      const pw: any = plan.plannedWork ?? {};
      const boqItemId = pw.boqItemId != null ? Number(pw.boqItemId) : null;
      let dprExists = false;
      let executedByUom: Array<{ uom: string; qty: number; entryCount: number }> = [];
      let creditApplied = true;
      if (boqItemId != null && plan.siteId != null) {
        const sites = await storage.getSites();
        const siteName = sites.find((s: any) => s.id === plan.siteId)?.name;
        if (siteName) {
          const r = await storage.getExecutedProgressForPlan({
            site: siteName,
            date: plan.date,
            boqItemId,
            programmeBarId: pw.programmeBarId != null ? Number(pw.programmeBarId) : null,
          });
          dprExists = r.dprExists;
          executedByUom = r.executedByUom;
          creditApplied = r.creditApplied;
        }
      }
      const comparison = computeExecutionComparison({
        plannedQty: pw.plannedQty != null ? Number(pw.plannedQty) : null,
        plannedUom: pw.plannedUom ?? null,
        executedByUom,
        dprExists,
        creditApplied,
      });
      res.json(comparison);
    } catch (err: any) {
      res.status(500).json({ error: err.message });
    }
  });

  // POST /api/site-requirements/:id/outcome — PM/Admin records the execution
  // outcome and (optionally) carries unexecuted work forward to a NEW plan.
  // JSONB-only persistence; never creates a DPR; never mutates arrangements.
  app.post("/api/site-requirements/:id/outcome", requireAuth, async (req: any, res) => {
    try {
      const role = req.session?.role ?? "engineer";
      if (role !== "admin" && role !== "manager") {
        return res.status(403).json({ error: "Only managers or admins can record work outcomes" });
      }
      const plan = await storage.getSiteRequirement(parseInt(req.params.id));
      if (!plan) return res.status(404).json({ error: "Not found" });

      // 06J-HF: business day in site-local time (Asia/Kolkata), NOT the UTC
      // calendar date — the UI's local "today" and the server must agree.
      const todayStr = businessToday();
      // Lifecycle rule enforced server-side, not just hidden in the UI:
      // outcomes are recorded only for plans whose target date has passed.
      if (!(plan.date < todayStr)) {
        return res.status(400).json({ error: "Work outcome can only be recorded after the plan's target date has passed.", code: "PLAN_DATE_NOT_PASSED" });
      }
      const input = {
        outcome: req.body.outcome,
        reason: req.body.reason ?? null,
        remarks: req.body.remarks ?? null,
        carryForward: req.body.carryForward ?? null,
      };
      const v = validateOutcomeInput(input as any, plan.date, todayStr);
      if (!v.ok) return res.status(400).json({ error: v.message, code: v.code });

      const wantsCarry = input.carryForward && input.carryForward.mode !== "none";
      // Atomic: row lock on the old plan prevents concurrent duplicate clones;
      // an existing carriedForwardTo link is preserved on outcome edits.
      const result = await storage.recordSiteRequirementOutcome(plan.id, {
        outcomeInput: input as any,
        byName: req.session?.username ?? null,
        byId: req.session?.userId ?? null,
        carry: wantsCarry
          ? {
              targetDate: resolveCarryTargetDate(input.carryForward!, todayStr),
              carryQty: input.carryForward!.carryQty != null ? Number(input.carryForward!.carryQty) : null,
            }
          : null,
        buildCarryForwardPlan,
        buildOutcomeRecord,
      });
      if (!result.ok && result.code === "NOT_FOUND") return res.status(404).json({ error: "Not found" });
      if (!result.ok && result.code === "ALREADY_CARRIED_FORWARD") {
        return res.status(409).json({
          error: `Already carried forward to ${result.link.date}.`,
          code: "ALREADY_CARRIED_FORWARD",
          link: result.link,
        });
      }
      if (!result.ok) return res.status(500).json({ error: "Unexpected outcome state" });
      res.json({ updated: result.updated, newPlan: result.newPlan });
    } catch (err: any) {
      res.status(500).json({ error: err.message });
    }
  });

  // ── Helper: is this requirement already acted upon by PM/store/mechanical? ──
  function isActedUpon(row: any): boolean {
    const actionedStatuses = ["approved", "arranged", "sent_store", "sent_purchase", "sent_plant"];
    if (actionedStatuses.includes(row.status)) return true;
    const alloc = row.allocationStatus;
    if (!alloc) return false;
    if (alloc.materials || alloc.equipment || alloc.labour || alloc.immediate) return true;
    const anyItemActed = (arr: any[]) => Array.isArray(arr) && arr.some((x: any) => !!x?.status);
    return anyItemActed(alloc.materialItems) || anyItemActed(alloc.equipmentItems) ||
      anyItemActed(alloc.labourItems) || anyItemActed(alloc.immediateItems);
  }

  // PUT /api/site-requirements/:id — direct content update (owner if not acted upon, or PM/admin)
  app.put("/api/site-requirements/:id", requireAuth, async (req: any, res) => {
    try {
      const id = parseInt(req.params.id);
      const isManagerOrAdmin = req.authUser.isAdmin || req.authUser.isOwner;
      const row = await storage.getSiteRequirement(id);
      if (!row) return res.status(404).json({ error: "Not found" });

      if (!isManagerOrAdmin) {
        if (row.submittedBy !== req.authUser.id) {
          return res.status(403).json({ error: "Access denied" });
        }
        const acted = isActedUpon(row);
        const hasApprovedOneTime =
          row.revisionStatus === "revision_approved" && !row.revisionOneTimeUsed;
        if (acted && !hasApprovedOneTime) {
          return res.status(403).json({ error: "This requirement has been acted upon. Request a revision first." });
        }
      }

      const body = req.body;
      const updated = await storage.updateSiteRequirementContent(id, {
        plannedWork: body.plannedWork ?? null,
        materials: body.materials ?? null,
        equipment: body.equipment ?? null,
        labour: body.labour ?? null,
        immediateRequirements: body.immediateRequirements ?? null,
      });
      res.json(updated);
    } catch (err: any) {
      res.status(500).json({ error: err.message });
    }
  });

  // POST /api/site-requirements/:id/revision-request — engineer requests a revision
  app.post("/api/site-requirements/:id/revision-request", requireAuth, async (req: any, res) => {
    try {
      const id = parseInt(req.params.id);
      const row = await storage.getSiteRequirement(id);
      if (!row) return res.status(404).json({ error: "Not found" });
      if (row.submittedBy !== req.authUser.id) {
        return res.status(403).json({ error: "You can only request revision for your own submissions" });
      }
      if (row.revisionStatus === "revision_requested") {
        return res.status(409).json({ error: "Revision already requested and pending approval" });
      }
      const { reason } = req.body;
      if (!reason?.trim()) return res.status(400).json({ error: "reason is required" });
      const updated = await storage.requestSiteRequirementRevision(id, reason.trim());
      res.json(updated);
    } catch (err: any) {
      res.status(500).json({ error: err.message });
    }
  });

  // PATCH /api/site-requirements/:id/revision-approve — PM/admin approves revision
  app.patch("/api/site-requirements/:id/revision-approve", requireAuth, async (req: any, res) => {
    try {
      if (!assertApprove(req, res, "site_dprs")) return;
      const id = parseInt(req.params.id);
      const row = await storage.getSiteRequirement(id);
      if (!row) return res.status(404).json({ error: "Not found" });
      if (row.revisionStatus !== "revision_requested") {
        return res.status(409).json({ error: "No pending revision request for this requirement" });
      }
      // Requests remain creator-only; no name/role inference for historical rows.
      const blocked = requirementApprovalBlock(req.authUser, row.submittedBy);
      if (blocked) return res.status(403).json({ error: blocked });
      const { remarks } = req.body;
      const updated = await storage.approveSiteRequirementRevision(
        id, req.authUser.id, remarks ?? ""
      );
      res.json(updated);
    } catch (err: any) {
      res.status(500).json({ error: err.message });
    }
  });

  // PATCH /api/site-requirements/:id/revision-reject — PM/admin rejects revision
  app.patch("/api/site-requirements/:id/revision-reject", requireAuth, async (req: any, res) => {
    try {
      if (!assertApprove(req, res, "site_dprs")) return;
      const id = parseInt(req.params.id);
      const row = await storage.getSiteRequirement(id);
      if (!row) return res.status(404).json({ error: "Not found" });
      const blocked = requirementApprovalBlock(req.authUser, row.submittedBy);
      if (blocked) return res.status(403).json({ error: blocked });
      const { remarks } = req.body;
      const updated = await storage.rejectSiteRequirementRevision(id, remarks ?? "");
      res.json(updated);
    } catch (err: any) {
      res.status(500).json({ error: err.message });
    }
  });
}

export function canPropagateDuplicateMapping(
  source: { description: string; unit: string | null; mappedBy: string | null; isAutoMapped: boolean; confidenceScore: number | null },
  target: { description: string; unit: string | null },
): boolean {
  const deterministicSource = source.isAutoMapped &&
    (source.mappedBy === "rule" || (source.mappedBy === "auto" && Number(source.confidenceScore) === 1));
  return deterministicSource &&
    boqIdentitySignature(source.description, source.unit) === boqIdentitySignature(target.description, target.unit);
}

export function assertValidDieselSourceForQuantity(quantity: number, dieselSource: unknown): void {
  if (quantity > 0 && dieselSource !== "plant_stock" && dieselSource !== "direct_purchase" && dieselSource !== "contractor") {
    throw new InvalidDieselSourceError(dieselSource);
  }
}

export function assertValidStockTransferQuantity(quantity: number): void {
  if (!Number.isFinite(quantity) || quantity <= 0) {
    throw new InvalidStockTransferQuantityError(quantity);
  }
}

export function assertValidDieselPhysicalStock(materialName: string | null | undefined, physicalQty: number): void {
  if (/^(diesel|hsd)$/i.test((materialName ?? "").trim()) && (!Number.isFinite(physicalQty) || physicalQty < 0)) {
    throw new InvalidDieselPhysicalStockError(physicalQty);
  }
}

export function assertNonnegativeDieselLedgerNet(data: {
  materialName: string | null | undefined;
  materialId: number;
  partyId: number | null;
  totalIn: number;
  totalOut: number;
  balance: number;
}): void {
  if (!/^(diesel|hsd)$/i.test((data.materialName ?? "").trim()) || data.balance >= 0) return;
  throw new InsufficientPlantStockError({
    material: data.materialName!,
    source: "ledger_reconciliation",
    materialId: data.materialId,
    partyId: data.partyId,
    requestedQty: data.totalOut,
    availableQty: data.totalIn,
    shortageQty: Math.round(-data.balance * 1e6) / 1e6,
  });
}

canonicaliseContractor = (raw: string): string => {
        const upper = raw.toUpperCase().trim().replace(/\s+/g, " ");
        return aliasToCanonical.get(upper) || upper;
      }

assertRows = (value: unknown, table: any, tableName: string, fields: readonly string[]): any[] => {
      if (value === undefined) return [];
      if (!Array.isArray(value)) throw new Error(`${tableName} must be an array`);

      const allowed = new Set(fields);
      const ids = new Set<number>();
      return value.map((raw, index) => {
        if (!raw || typeof raw !== "object" || Array.isArray(raw)) {
          throw new Error(`${tableName}[${index}] must be an object`);
        }
        const row = raw as Record<string, any>;
        const unknown = Object.keys(row).filter((key) => !allowed.has(key));
        if (unknown.length > 0) {
          throw new Error(`${tableName}[${index}] has unsupported field(s): ${unknown.join(", ")}`);
        }
        if (!Number.isSafeInteger(row.id) || row.id < 1) {
          throw new Error(`${tableName}[${index}] requires a positive integer id for a safe retry`);
        }
        if (ids.has(row.id)) throw new Error(`${tableName} contains duplicate id ${row.id}`);
        ids.add(row.id);
        return convertTimestampStrings(row, table);
      });
    }

assertCurrent = (planned: {
        id: number;
        expectedStartDate: string;
        expectedEndDate: string;
      }) => {
        const current = byId.get(planned.id)!;
        if (current.startDate !== planned.expectedStartDate || current.endDate !== planned.expectedEndDate) {
          throw stale();
        }
        return current;
      }

export function registerVendorMasterRoutes(app: Express, permittedSites: (req: Request) => Promise<string[] | null>) {
  const canView = (req: Request, res: Response) => assertView(req, res, "master_parties");
  const canManage = (req: Request, res: Response) => !!req.authUser?.isOwner || assertAdmin(req, res);
  const isSensitive = (req: Request) => !!(req.authUser?.isAdmin || req.authUser?.isOwner);
  async function visibleVendorIds(req: Request): Promise<Set<number> | null> {
    const allowed = await permittedSites(req);
    if (allowed === null) return null;
    const siteRows = await db.select({ id: sites.id, name: sites.name }).from(sites);
    const byId = new Map(siteRows.map(s => [s.id, s.name]));
    const visible = (s: string | null | undefined) => !!s && siteMatchesPermitted(s, allowed);
    const ids = new Set<number>();
    const bills = await db.select({ vendorId: vendorBills.vendorId, siteId: vendorBills.siteId, siteName: vendorBillItems.siteName }).from(vendorBills)
      .leftJoin(vendorBillItems, eq(vendorBillItems.billId, vendorBills.id));
    for (const b of bills) if (b.vendorId && visible(b.siteName || (b.siteId ? byId.get(b.siteId) : null))) ids.add(b.vendorId);
    const indents = await db.select({ vendorId: purchaseIndentItems.vendorId, siteId: purchaseIndents.siteId }).from(purchaseIndentItems)
      .innerJoin(purchaseIndents, eq(purchaseIndents.id, purchaseIndentItems.indentId));
    for (const p of indents) if (p.vendorId && visible(p.siteId ? byId.get(p.siteId) : null)) ids.add(p.vendorId);
    const trips = await db.select({ site: siteMaterialTrips.site, supplierId: siteMaterialTrips.supplierVendorId, materialId: siteMaterialTrips.materialSourceVendorId }).from(siteMaterialTrips);
    for (const t of trips) if (visible(t.site)) {
      if (t.supplierId) ids.add(t.supplierId);
      if (t.materialId) ids.add(t.materialId);
    }
    return ids;
  }

  app.get("/api/vendor-master", async (req, res) => {
    if (!canView(req, res)) return;
    try {
      const permitted = await visibleVendorIds(req);
      res.json((await db.select().from(vendors).orderBy(vendors.name))
        .filter(v => permitted === null || permitted.has(v.id)).map(v => publicVendor(v, isSensitive(req))));
    } catch (e) { error(res, e); }
  });
  app.post("/api/vendor-master", async (req, res) => {
    if (!canManage(req, res)) return;
    try {
      const input = fields.parse(req.body);
      const [saved] = await db.insert(vendors).values(input).returning();
      res.status(201).json(saved);
    } catch (e) { error(res, e); }
  });
  app.patch("/api/vendor-master/:id", async (req, res) => {
    if (!canManage(req, res)) return;
    try {
      const input = fields.partial().parse(req.body);
      if (!Object.keys(input).length) return res.status(400).json({ message: "No fields supplied" });
      const [saved] = await db.update(vendors).set({ ...input, updatedAt: new Date() }).where(eq(vendors.id, Number(req.params.id))).returning();
      if (!saved) return res.status(404).json({ message: "Vendor not found" });
      res.json(saved);
    } catch (e) { error(res, e); }
  });

  app.get("/api/vendor-master/review", async (req, res) => {
    if (!canManage(req, res)) return;
    try {
      const master = await db.select({ id: vendors.id, name: vendors.name }).from(vendors);
      const aliases = await db.select().from(vendorAliases);
      const proposals = [];
      for (const role of reviewRoles) {
        const { table, name, id, fk } = roles[role];
        const rows = role === "indents"
          ? (await db.select({
            id: purchaseIndentItems.id, name: purchaseIndentItems.vendor,
            procurementRoute: purchaseIndentItems.procurementRoute,
            catalogProcurementRoute: plantMaterials.procurementRoute,
          }).from(purchaseIndentItems)
            .leftJoin(plantMaterials, eq(plantMaterials.id, purchaseIndentItems.materialId))
            .where(isNull(purchaseIndentItems.vendorId))).filter(bulkReviewItem)
          : await db.select({ id, name }).from(table).where(isNull(fk));
        const grouped = new Map<string, number[]>();
        for (const row of rows) {
          if (!row.name?.trim()) continue;
          grouped.set(row.name, [...(grouped.get(row.name) || []), row.id]);
        }
        for (const [name, ids] of Array.from(grouped)) {
          proposals.push({ role, name, count: ids.length, ids: ids.sort((a: number,b: number) => a-b), ...proposeVendorMatch(name, master, aliases) });
        }
      }
      res.json(proposals);
    } catch (e) { error(res, e); }
  });
  app.post("/api/vendor-master/review/confirm", async (req, res) => {
    if (!canManage(req, res)) return;
    try {
      const input = z.object({
        role: z.enum(["bills", "rates", "indents", "transport", "materialSource"]),
        name: z.string().min(1),
        ids: z.array(z.number().int().positive()).min(1),
        vendorId: z.number().int().positive().optional(),
        newVendor: fields.optional(),
      }).refine(v => !!v.vendorId !== !!v.newVendor, "Select an existing vendor OR create a new one").parse(req.body);
      const { table, name, id, fk } = roles[input.role];
      const result = await db.transaction(async tx => {
        // Lock matching rows: a stale review cannot silently link a changed name or an already-linked row.
        const current = input.role === "indents"
          ? (await tx.select({
            id: purchaseIndentItems.id,
            procurementRoute: purchaseIndentItems.procurementRoute,
            catalogProcurementRoute: plantMaterials.procurementRoute,
          }).from(purchaseIndentItems)
            .leftJoin(plantMaterials, eq(plantMaterials.id, purchaseIndentItems.materialId))
            .where(and(eq(purchaseIndentItems.vendor, input.name), isNull(purchaseIndentItems.vendorId)))
            .for("update", { of: purchaseIndentItems })).filter(bulkReviewItem)
          : await tx.select({ id }).from(table).where(and(eq(name, input.name), isNull(fk))).for("update");
        if (!sameReviewIds(current.map(r => r.id), input.ids))
          return { conflict: true as const };
        let vendorId = input.vendorId;
        if (vendorId) {
          const [target] = await tx.select({ id: vendors.id, isActive: vendors.isActive }).from(vendors).where(eq(vendors.id, vendorId));
          if (!target?.isActive) return { missing: true as const };
        } else {
          const [created] = await tx.insert(vendors).values(input.newVendor!).returning({ id: vendors.id });
          vendorId = created.id;
        }
        const columnKey = input.role === "transport" ? "supplierVendorId"
          : input.role === "materialSource" ? "materialSourceVendorId" : "vendorId";
        // Never update by name alone: a new matching row may arrive after the
        // locked snapshot was read. Only the explicitly reviewed IDs can move.
        const updated = await tx.update(table).set({ [columnKey]: vendorId })
          .where(and(inArray(id, input.ids), eq(name, input.name), isNull(fk))).returning({ id });
        if (!sameReviewIds(updated.map(row => row.id), input.ids)) throw new Error("Vendor review changed during confirmation");
        return { vendorId, linked: updated.length };
      });
      if ("conflict" in result) return res.status(409).json({ message: "Review is stale. Refresh proposals and confirm again." });
      if ("missing" in result) return res.status(404).json({ message: "Active vendor not found" });
      res.json(result);
    } catch (e) { error(res, e); }
  });

  app.get("/api/vendor-master/:id/activity", async (req, res) => {
    if (!canView(req, res)) return;
    try {
      const vendorId = Number(req.params.id);
      const [vendor] = await db.select().from(vendors).where(eq(vendors.id, vendorId));
      if (!vendor) return res.status(404).json({ message: "Vendor not found" });
      const visible = await visibleVendorIds(req);
      if (visible !== null && !visible.has(vendorId)) return res.status(403).json({ message: "Vendor has no activity in your permitted sites" });
      const allowed = await permittedSites(req);
      const siteRows = await db.select({ id: sites.id, name: sites.name }).from(sites);
      const byId = new Map(siteRows.map(s => [s.id, s.name]));
      const grouped = new Map<string, Record<string, number>>();
      const add = (site: string | null | undefined, kind: string) => {
        const label = site || "Unassigned site";
        if (allowed !== null && (!site || !siteMatchesPermitted(site, allowed))) return;
        const counts = grouped.get(label) || { equipment: 0, material: 0, transport: 0, labour: 0 };
        counts[kind]++;
        grouped.set(label, counts);
      };
      const billRows = await db.select({ itemId: vendorBillItems.id, siteName: vendorBillItems.siteName, siteId: vendorBills.siteId, billType: vendorBills.billType, category: vendorBillItems.category })
        .from(vendorBills).leftJoin(vendorBillItems, eq(vendorBillItems.billId, vendorBills.id)).where(eq(vendorBills.vendorId, vendorId));
      for (const b of billRows) {
        if (!b.itemId) continue;
        add(b.siteName || (b.siteId ? byId.get(b.siteId) : null), activityKind(b.category, b.billType));
      }
      const piRows = await db.select({ siteId: purchaseIndents.siteId }).from(purchaseIndentItems)
        .innerJoin(purchaseIndents, eq(purchaseIndents.id, purchaseIndentItems.indentId)).where(eq(purchaseIndentItems.vendorId, vendorId));
      for (const p of piRows) add(p.siteId ? byId.get(p.siteId) : null, "material");
      const trips = await db.select({ site: siteMaterialTrips.site, supplierId: siteMaterialTrips.supplierVendorId, materialId: siteMaterialTrips.materialSourceVendorId })
        .from(siteMaterialTrips).where(eq(siteMaterialTrips.supplierVendorId, vendorId));
      for (const t of trips) add(t.site, "transport");
      const materials = await db.select({ site: siteMaterialTrips.site }).from(siteMaterialTrips).where(eq(siteMaterialTrips.materialSourceVendorId, vendorId));
      for (const t of materials) add(t.site, "material");
      // Rate cards have no site field; they are not represented as site activity.
      res.json({ vendor: publicVendor(vendor, isSensitive(req)), sites: Array.from(grouped).map(([site, counts]) => ({ site, ...counts })) });
    } catch (e) { error(res, e); }
  });
}

export function cancelledEffectiveFromAsOf(
  arrangement: ArrangementStatusAsOfInput,
  asOf: string | null | undefined,
): string | null {
  if (!isValidArrangementEffectiveDate(asOf) || !Array.isArray(arrangement.revisionHistory)) return null;
  const dates = arrangement.revisionHistory
    .filter((event: any) =>
      event?.eventType === "status_change"
      && event?.status === "cancelled"
      && isValidArrangementEffectiveDate(event?.effectiveFrom)
      && event.effectiveFrom <= asOf)
    .map((event: any) => event.effectiveFrom as string)
    .sort();
  return arrangementStatusAsOf(arrangement, asOf) === "cancelled"
    ? dates[dates.length - 1] ?? null
    : null;
}

export function canonicalizeUnit(raw: string): string {
  if (!raw || !raw.trim()) return raw ?? "";
  // Step 0: strip leading "Per" / "per" prefix (e.g. "Per 1 Sqm" → "1 Sqm", "Per Sqm" → "Sqm")
  let s = raw.trim().replace(/^[Pp][Ee][Rr]\s+/i, "").trim();
  // Step 1: strip leading numeric quantity prefix (e.g. "1 Cum" → "Cum", "1.00 " → "")
  const dePrefix = s.replace(/^\d+(\.\d+)?\s*/i, "").trim();
  if (!dePrefix) return raw.trim();
  // Step 2: collapse punctuation and spaces for map key lookup
  const key = dePrefix.replace(/[\s.]/g, "").toUpperCase();
  // Step 3: canonical lookup, step 4: fall back to de-prefixed original
  return CANONICAL_UNIT_MAP[key] ?? dePrefix;
}

export function assertValidEquipmentStatus(input: {
  usageStatus?: unknown;
  usageStatusReason?: unknown;
}, dprEntry = false): void {
  const error = equipmentStatusInputError(input, dprEntry);
  if (error) throw new Error(error);
}

export function canonMaterialName(name: string): string {
  return (name || "")
    .toUpperCase()
    .replace(/AGGREGATES?/g, "")
    .replace(/MATERIAL/g, "")
    .replace(/[^A-Z0-9]/g, "")
    .trim();
}

function canonResourceKey(name: string): string {
  return name.trim().toUpperCase().replace(/\s+/g, " ");
}

function canonEquipmentKey(name: string): string {
  return equipmentBaseName(name).toUpperCase().replace(/\s+/g, " ");
}

export function canDirectlyEditSchedule(input: {
  programmeBaselinePublishedAt: Date | string | null | undefined;
  evidence: BarEvidence | null | undefined;
  hasOutcomeEvents: boolean;
}): boolean {
  if (input.programmeBaselinePublishedAt != null || input.hasOutcomeEvents) return false;
  return !input.evidence
    || (Number(input.evidence.reportedQty ?? 0) <= 0 && !input.evidence.earliestProgressDate);
}

export function requirementApprovalBlock(
  actor: { id: number; isOwner?: boolean },
  submittedBy: number | null | undefined,
): string | null {
  if (!Number.isInteger(submittedBy) || Number(submittedBy) <= 0) {
    return "Approval is unavailable because this requirement's creator is unknown.";
  }
  if (submittedBy === actor.id && actor.isOwner !== true) {
    return "You cannot approve or reject a requirement you created.";
  }
  return null;
}

export function canLinkTripArrangement(arrangement: ArrangementStatusAsOfInput, tripDate: string | null | undefined) {
  return isValidArrangementEffectiveDate(tripDate)
    && isArrangementOperationalAsOf(arrangement, tripDate, APPLICABLE_ARRANGEMENT_STATUSES);
}

export function canonicalizeMachineType(name: string): string {
  return name.replace(/\s+PLANT\s+INTERCARTING/gi, '').replace(/\s+INTERCARTING/gi, '').replace(/\s+PLANT$/i, '').replace(/-PLANT$/i, '').replace(/-SITE$/i, '').replace(/-\d+(\s+.*)?$/i, '').replace(/-[A-Z][A-Z\s]+$/i, '').trim();
}

export function canonicalMachineName(description: string): string {
  const rawName = description.split(/\s*-\s*/)[0]?.trim() || "EQUIPMENT";
  return canonicalizeMachineType(stripSourceSuffix(rawName)).toUpperCase().replace(/\s+/g, "_");
}

export function canonicalTransportName(description: string): string {
  const upper = stripSourceSuffix(description.trim().toUpperCase());
  const viaMatch = upper.match(/\bVIA\s+(.+)/);
  if (viaMatch) return canonicalizeMachineType(viaMatch[1].trim()).toUpperCase().replace(/\s+/g, "_");
  const mobilMatch = upper.match(/^MOBILIZATION:\s*(.+?)(?:\s*\(.*)?$/);
  if (mobilMatch) return canonicalizeMachineType(mobilMatch[1].trim()).toUpperCase().replace(/\s+/g, "_");
  const stripped = upper.replace(/\s*-\s*(HOURLY HIRE|DAILY HIRE|TRIP BASED|MONTHLY HIRE|TIME\/METER|MOBILIZATION|TRANSPORT).*$/i, "").trim();
  return canonicalizeMachineType(stripped).toUpperCase().replace(/\s+/g, "_");
}

export function canonicalMatName(description: string): string {
  return stripSourceSuffix(description.trim().toUpperCase()).replace(/\s+/g, "_");
}
